    static func taggedProjectedJSON(_ original:Data) throws -> Data? {
        guard let ordinary=try JSONSerialization.jsonObject(with:original) as? [String:Any] else { return nil }
        var counts:[String:Int]=[:],shapeSet:Set<[String]>=[]
