    static func expandedTaggedJSON(_ encoded:Data) throws -> Data {
        guard let root=try JSONSerialization.jsonObject(with:encoded) as? [String:Any],
              Set(root.keys) == ["format","stringTable","objectShapes","context"],root["format"] as? String == treeFormat,
              let table=root["stringTable"] as? [String],Set(table).count == table.count,
              let shapes=root["objectShapes"] as? [[String]],Set(shapes).count == shapes.count,
              shapes.allSatisfy({ Set($0).count == $0.count }),let current=root["context"] else { throw CocoaError(.coderReadCorrupt) }
        func integer(_ value:Any)->Int? {
            guard let n=value as? NSNumber,CFGetTypeID(n) != CFBooleanGetTypeID(),n.doubleValue.isFinite,
                  n.doubleValue.rounded(.towardZero) == n.doubleValue,n.doubleValue >= 0,
                  n.doubleValue < Double(Int.max) else { return nil }
