struct RuntimeExampleConfiguration: Sendable {
    let libraryURL: URL
    let allowProposed: Bool
    let retrievalEnabled: Bool
    var expectedSHA256: String? = nil
    var excludedBlueprints: Set<String> = []
    var excludedIDs: Set<String> = []
    /// Diagnostic assistance only. nil uses automatic selection; [] selects none.
    var manualReferenceIDs: [String]? = nil
    /// Bounded semantic routing adds worked examples; current source and saved
    /// operation guards retain all authority. Disabled until paired qualification.
    var semanticRetrievalEnabled: Bool = false
    var semanticIndexURL: URL? = nil
    var expectedSemanticSHA256: String? = nil
    var compactRoutingEnabled: Bool = false
    var compactRoutingURL: URL? = nil
    var expectedCompactRoutingSHA256: String? = nil
    /// Reversible internal candidate: outline purposes/source ownership before
    /// asking for a textual correction. Both OFF/ON use the same staging.
    var usesStagedOutline: Bool = true
#if DEBUG
    @TaskLocal static var testConfiguration: Self? = nil
#endif
    static var current: Self? {
#if DEBUG
        if let testConfiguration { return testConfiguration }
        let environment = ProcessInfo.processInfo.environment
        if environment["SPEAKIT_RUNTIME_EXAMPLES"] == "0" { return nil }
        if environment["SPEAKIT_RUNTIME_EXAMPLES"] == "1",
           let path = environment["SPEAKIT_RUNTIME_LIBRARY"] {
            return Self(libraryURL: URL(fileURLWithPath: path),
                    allowProposed: environment["SPEAKIT_RUNTIME_ALLOW_PROPOSED"] == "1",
                    retrievalEnabled: environment["SPEAKIT_RUNTIME_RETRIEVAL"] != "0",
                    expectedSHA256: environment["SPEAKIT_RUNTIME_LIBRARY_SHA256"])
        }
#endif
        return bundled
    }
    /// Shipping configuration, separate from a developer harness's explicit
    /// environment/test override. Tests can inspect the actual bundled bank
    /// without enabling live generation in unrelated repository fixtures.
    static var bundled: Self? {
#if SPEAKIT_RUNTIME_FULL_BANK
        // Build 21 personal trial: search the complete development bank.
        // Proposed records remain unapproved; every result still passes the
        // source-grounding and operation-authorization guards.
        guard let library = Bundle.main.url(forResource: "runtime-library", withExtension: "sqlite") else { return nil }
        return Self(libraryURL: library, allowProposed: true, retrievalEnabled: true,
            expectedSHA256: "ea60fc340160eb9e98f00c04e775e421ae4a4bf24e476dc474bfb4ed88c8b56b")
#else
        return nil
#endif
    }
}

struct RuntimeWorkedExample: Decodable, Sendable {
    struct Input: Decodable, Sendable { let utterance: String }
    struct Approval: Decodable, Sendable { let production_eligible: Bool }
    struct Provenance: Decodable, Sendable { let blueprint: String }
    let id: String
    let input: Input
    let approval: Approval
    let provenance: Provenance
    let ruleIDs: Set<String>
    // Preserve the complete worked solution/context as JSON, not a copied answer.
    let payload: String

    init(from decoder: Decoder) throws {
        let value = try RuntimeJSON(from: decoder)
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        let data = try encoder.encode(value)
        guard let object = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath,
                debugDescription: "Worked example must be an object"))
        }
        id = object["id"] as? String ?? ""
        let inputObject = object["input"] as? [String: Any] ?? [:]
        input = Input(utterance: inputObject["utterance"] as? String ?? "")
        let approvalObject = object["approval"] as? [String: Any] ?? [:]
        approval = Approval(production_eligible: approvalObject["production_eligible"] as? Bool ?? false)
        let provenanceObject = object["provenance"] as? [String: Any] ?? [:]
        provenance = Provenance(blueprint: provenanceObject["blueprint"] as? String ?? "")
        ruleIDs = Set(object["rule_ids"] as? [String] ?? [])
        payload = String(decoding: data, as: UTF8.self)
    }
}

indirect enum RuntimeJSON: Codable, Sendable {
    case object([String: RuntimeJSON]), array([RuntimeJSON]), string(String), number(Double), boolean(Bool), null
    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .null }
        else if let v = try? c.decode(Bool.self) { self = .boolean(v) }
        else if let v = try? c.decode(String.self) { self = .string(v) }
        else if let v = try? c.decode(Double.self) { self = .number(v) }
        else if let v = try? c.decode([String: RuntimeJSON].self) { self = .object(v) }
        else { self = .array(try c.decode([RuntimeJSON].self)) }
    }
    func encode(to encoder: Encoder) throws {
        var c = encoder.singleValueContainer()
        switch self {
        case .object(let v): try c.encode(v)
        case .array(let v): try c.encode(v)
        case .string(let v): try c.encode(v)
        case .number(let v): try c.encode(v)
        case .boolean(let v): try c.encode(v)
        case .null: try c.encodeNil()
        }
    }
}

actor RuntimeExampleLibrary {
    static let shared = RuntimeExampleLibrary()
#if DEBUG
    @TaskLocal static var developmentObserver: (@Sendable (String) -> Void)? = nil
#endif
    private var cache: (URL, String?, [RuntimeWorkedExample])?
    private var database: (URL, String?, RuntimeReferenceStore)?
    /// Verify the large immutable bundle on a background actor before the
    /// first capture. Cache the read-only handle; never retain the bank in RAM.
    func prepare(configuration: RuntimeExampleConfiguration) throws {
        guard configuration.retrievalEnabled, configuration.libraryURL.pathExtension == "sqlite" else { return }
        guard configuration.expectedSHA256 != nil || configuration.allowProposed else {
            throw RuntimeReferenceStore.Failure.unpinned
        }
        if let cached = database, cached.0 == configuration.libraryURL,
           cached.1 == configuration.expectedSHA256 {
            cached.2.prepareSemantic(configuration: configuration)
            cached.2.prepareCompactRouting(configuration: configuration)
#if DEBUG
            Self.developmentObserver?("reference prepare state=cached verification=retained")
#endif
            return
        }
        let store = try RuntimeReferenceStore(url: configuration.libraryURL,
            expectedSHA256: configuration.expectedSHA256, allowUnpinnedPrototype: configuration.allowProposed)
        store.prepareSemantic(configuration: configuration)
        store.prepareCompactRouting(configuration: configuration)
        database = (configuration.libraryURL, configuration.expectedSHA256, store)
#if DEBUG
        Self.developmentObserver?("reference prepare state=opened verification=passed")
#endif
    }
    func select(_ source: String, configuration: RuntimeExampleConfiguration) throws -> [RuntimeWorkedExample] {
        let start = ContinuousClock.now
        var eligibleConfiguration = configuration
        // Explicit exact-record disputes, retained in the review registry. The
        // source bank stays intact; known disputed answers never enter prompts.
        eligibleConfiguration.excludedIDs.formUnion(["SIR1-506751", "SIR1-509711", "SIR1-034355"])
        let result = try selectRecords(source, configuration: eligibleConfiguration)
#if DEBUG
        let duration = start.duration(to: .now)
        let seconds = Double(duration.components.seconds) + Double(duration.components.attoseconds) / 1e18
        Self.developmentObserver?("retrieval seconds=\(seconds) pool=\(database?.2.recordCount ?? cache?.2.count ?? 0) eligibleApproved=\(database?.2.approvedCount ?? 0) selected=\(result.map(\.id).joined(separator: ","))")
#endif
        return result
    }
    private func selectRecords(_ source: String, configuration: RuntimeExampleConfiguration) throws -> [RuntimeWorkedExample] {
        guard configuration.retrievalEnabled else { return [] }
        // Trust is checked on every configuration, before either cache. A bank
        // opened for an unpinned trial cannot become trusted by staying warm.
        guard configuration.expectedSHA256 != nil || configuration.allowProposed else {
            throw RuntimeReferenceStore.Failure.unpinned
        }
        if configuration.libraryURL.pathExtension == "sqlite" {
            let store: RuntimeReferenceStore
            if let cached = database, cached.0 == configuration.libraryURL,
               cached.1 == configuration.expectedSHA256 { store = cached.2 }
            else {
                store = try RuntimeReferenceStore(url: configuration.libraryURL,
                    expectedSHA256: configuration.expectedSHA256,
                    allowUnpinnedPrototype: configuration.allowProposed)
                database = (configuration.libraryURL, configuration.expectedSHA256, store)
            }
            do { return try store.select(source, configuration: configuration) }
            catch {
                guard RuntimeReferenceStore.requiresFreshConnection(after:error) else { throw error }
                // A failed cached connection cannot poison every later capture.
                // Discard it and retry once through the same full digest check;
                // changed/missing assets and a second failure still decline.
                database=nil
                guard !Task.isCancelled else { throw error }
#if DEBUG
                Self.developmentObserver?("reference database recovery state=reopening attempts=1 verification=required")
#endif
                let replacement=try RuntimeReferenceStore(url:configuration.libraryURL,
                    expectedSHA256:configuration.expectedSHA256,
                    allowUnpinnedPrototype:configuration.allowProposed)
                database=(configuration.libraryURL,configuration.expectedSHA256,replacement)
                do {
                    let records=try replacement.select(source,configuration:configuration)
#if DEBUG
                    Self.developmentObserver?("reference database recovery state=reopened attempts=1 verification=passed selection=complete")
#endif
                    return records
                } catch { database=nil;throw error }
            }
        }
        let rows: [RuntimeWorkedExample]
        if let cached = cache, cached.0 == configuration.libraryURL, cached.1 == configuration.expectedSHA256 { rows = cached.2 }
        else {
            let attributes = try FileManager.default.attributesOfItem(atPath: configuration.libraryURL.path)
            guard let size = attributes[.size] as? NSNumber, size.intValue <= 8_000_000 else { return [] }
            let data = try Data(contentsOf: configuration.libraryURL, options: .mappedIfSafe)
            // JSON is a bounded delivery format. SQLite queries the complete bank.
            guard data.count <= 8_000_000 else { return [] }
            if let expected = configuration.expectedSHA256 {
                let digest = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
                guard digest == expected else { return [] }
            } else if !configuration.allowProposed { return [] }
            rows = try JSONDecoder().decode([RuntimeWorkedExample].self, from: data)
            cache = (configuration.libraryURL, configuration.expectedSHA256, rows)
        }
        let eligible = rows.filter { !configuration.excludedBlueprints.contains($0.provenance.blueprint)
            && configuration.excludedBlueprints.isDisjoint(with: $0.ruleIDs)
            && !configuration.excludedIDs.contains($0.id)
            && (configuration.allowProposed || $0.approval.production_eligible) }
        if let ids = configuration.manualReferenceIDs {
            return ids.prefix(6).compactMap { id in eligible.first { $0.id == id } }
        }
        return Self.select(source, rows: eligible, allowProposed: configuration.allowProposed)
    }
    static func words(_ text: String) -> Set<String> {
        Set(text.lowercased().components(separatedBy: CharacterSet.alphanumerics.inverted).filter { !$0.isEmpty })
    }
    static func select(_ source: String, rows: [RuntimeWorkedExample], allowProposed: Bool) -> [RuntimeWorkedExample] {
        let query = words(source)
        let signals: Set<String> = ["mom", "dad", "brother", "sister", "partner", "mother", "father", "instead", "not", "said", "packing", "inventory", "buy", "change", "tomorrow"]
        var ranked: [(RuntimeWorkedExample, Int)] = []
        for row in rows where allowProposed || row.approval.production_eligible {
            let common = words(row.input.utterance).intersection(query)
            let signalCount = common.intersection(signals).count
            let score = common.count + signalCount * 3
            if score > 1 { ranked.append((row, score)) }
        }
        ranked.sort { a, b in
            if a.1 == b.1 { return a.0.id < b.0.id }
            return a.1 > b.1
        }
        var blueprints = Set<String>()
        return Array(ranked.compactMap { pair in
            blueprints.insert(pair.0.provenance.blueprint).inserted ? pair.0 : nil
        }.prefix(6))
    }
}

enum RuntimeProposalGuard {
    // Exact current-source grounding, including punctuation, negation and Unicode.
    // All source characters must be accounted for, not merely a set of words.
    static func covers(_ source: String, quotes: [String]) -> Bool {
        var covered = Set<Int>()
        let characters = Array(source)
        for quote in quotes {
            guard !quote.isEmpty else { return false }
            var search = source.startIndex
            var found = false
            while search < source.endIndex,
                  let range = source.range(of: quote, range: search..<source.endIndex) {
                let start = source.distance(from: source.startIndex, to: range.lowerBound)
                let end = source.distance(from: source.startIndex, to: range.upperBound)
                if (start..<end).allSatisfy({ !covered.contains($0) }) {
                    covered.formUnion(start..<end)
                    found = true
                    break
                }
                search = range.upperBound
            }
            guard found else { return false }
        }
        return characters.indices.allSatisfy { covered.contains($0) || characters[$0].isWhitespace || characters[$0].isPunctuation }
    }
}

/// Complete current-source speech acts for ordinary captures. This does not
/// approve an old parser confidence score: every unit must fit a whole grammar,
/// preserve literal membership, and contain no quotation, correction, condition
/// or saved change. Other confident inputs still consult worked examples.
/// A complete CURRENT purchase and its adjacent explicit non-completion
/// state share one intention. The status supplies no saved target, mutation,
/// date, contact or permission. Ambiguous/plural antecedents and any residual
/// intention decline this compact ownership constraint.
/// A complete explicitly retained, uncommitted possible project owns Memory.
/// The proof reads every unit of this bounded current frame; no model tag,
/// generated wording or reference fact can license an action or future alert.
/// Complete current conditional physical action with an explicit refusal
/// of app weather monitoring. Its condition and only action are read together;
/// the source authorizes a date-only task, never an automatic weather service.
/// A complete booked-event context owns a BEFORE deadline for the one
/// current ticket-download task. Departure is not a chosen task execution
/// time and cannot authorize an alert. Every original context unit survives.
enum RuntimeCurrentEventDeadline {
    struct Reading { let action:String;let organization:OrganizedThought }
    static func read(_ source:String,referenceDate:Date,calendar:Calendar) -> Reading? {
        let units=RuntimeIndexedSource(source).units.map { $0.text.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!;"))) }
        guard units.count == 7,QuotedSpeechScope.ranges(in:source).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(source),
              CaptureOperationDetector.partitionWithOwnership(source).operations.isEmpty else { return nil }
        func fields(_ text:String,_ pattern:String)->[String]? {
            guard let regex=NSRegularExpression.speakItCached("(?i)^"+pattern+"$"),
                  let match=regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)) else { return nil }
            return (1..<match.numberOfRanges).compactMap { Range(match.range(at:$0),in:text).map { String(text[$0]) } }
        }
        func matches(_ text:String,_ pattern:String)->Bool { fields(text,pattern) != nil }
        guard matches(units[0],#"Right,\s+about\s+the\s+trip"#),
              let event=fields(units[1],#"The\s+(train|ferry|bus|coach)\s+is\s+booked\s+for\s+(.+),\s+leaving\s+at\s+(.+)"#),event.count == 3,
              matches(units[2],#"I\s+have\s+the\s+booking\s+already,\s+so\s+I\s+am\s+not\s+buying\s+another\s+ticket"#),
              matches(units[3],#"I\s+need\s+to\s+download\s+the\s+actual\s+ticket\s+before\s+the\s+"#+NSRegularExpression.escapedPattern(for:event[0])+#"\s+leaves"#),
              matches(units[4],#"The\s+email\s+with\s+a\s+list\s+of\s+journey\s+options\s+is\s+not\s+the\s+ticket"#),
              matches(units[5],#"use\s+the\s+attachment\s+in\s+the\s+confirmation"#),
              matches(units[6],#"I\s+know\s+I\s+always\s+say\s+I\s+will\s+have\s+a\s+signal\s+at\s+the\s+station,\s+but\s+I\s+would\s+rather\s+not\s+depend\s+on\s+that"#) else { return nil }
        let weekdays = #"(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)"#
        let months = #"(?:january|february|march|april|may|june|july|august|september|october|november|december)"#
        let day = #"(?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|thirtieth|(?:twenty|thirty)[ -](?:first|second|third|fourth|fifth|sixth|seventh|eighth|ninth))"#
        let clock = #"(?:[0-9]{1,2}(?::[0-9]{2})?|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)(?:\s*(?:am|pm|a\.m\.|p\.m\.|o['’]clock))?(?:\s+in\s+the\s+(?:morning|afternoon|evening))?"#
        guard matches(event[1],"(?:"+weekdays+#",?\s+)?"#+months+#"\s+"#+day+#"(?:,?\s+[0-9]{4})?"#),
              matches(event[2],clock) else { return nil }
        let departure=ThoughtOrganizer.organize("Finish preparations by "+event[1]+" at "+event[2],referenceDate:referenceDate,calendar:calendar)
        guard !departure.needsClarification,departure.state == .resolved,
              let instant=departure.dueDate,let date=departure.temporalIntent.day,
              departure.temporalIntent.kind == .exactDateTime,departure.temporalIntent.time != nil,
              departure.temporalIntent.timeZoneBehavior == .deviceLocal,
              departure.reminderDate == nil,departure.reminderDelivery == .none,
              departure.locationIntent == nil,departure.recurrenceRule == nil else { return nil }
        let temporal=TemporalIntent(kind:.dateOnly,day:date,timeZoneIdentifier:departure.temporalIntent.timeZoneIdentifier,
            timeZoneBehavior:.deviceLocal,sourceText:units[1]+". "+units[3]+".")
        let organization=OrganizedThought(itemType:.task,category:.general,priority:.normal,personName:nil,
            dueDate:calendar.startOfDay(for:instant),reminderDate:nil,reminderDelivery:.none,
            recurrenceRule:nil,needsClarification:false,temporalIntent:temporal,state:.resolved)
        return .init(action:"Download the actual ticket before the "+event[0]+" leaves at "+event[2]+" on "+event[1]+".",organization:organization)
    }
}

enum RuntimeCurrentConditionalWatering {
    struct Reading { let action:String;let organization:OrganizedThought }
    static func read(_ source:String,referenceDate:Date,calendar:Calendar) -> Reading? {
        let units=RuntimeIndexedSource(source).units.map { $0.text.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!;"))) }
        guard units.count == 5,QuotedSpeechScope.ranges(in:source).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(source),
              CaptureOperationDetector.partitionWithOwnership(source).operations.isEmpty else { return nil }
        func matches(_ text:String,_ pattern:String)->Bool {
            text.range(of:"(?i)^"+pattern+"$",options:.regularExpression) != nil
        }
        let pattern = #"(?i)^If\s+it\s+rains\s+before\s+tomorrow\s+morning,\s+skip\s+watering\s+(the\s+(?:parsley|mint|basil|rosemary|plants|seedlings))$"#
        guard let regex=NSRegularExpression.speakItCached(pattern),
              let match=regex.firstMatch(in:units[0],range:NSRange(units[0].startIndex...,in:units[0])),
              let objectRange=Range(match.range(at:1),in:units[0]),
              matches(units[1],#"Otherwise\s+water\s+it\s+tomorrow"#),
              matches(units[2],#"Keep\s+that\s+conditional\s+rather\s+than\s+treating\s+it\s+as\s+certain\s+that\s+rain\s+will\s+happen"#),
              matches(units[3],#"I\s+am\s+not\s+asking\s+the\s+app\s+to\s+monitor\s+the\s+weather"#),
              matches(units[4],#"I\s+can\s+check\s+it"#) else { return nil }
        let object=String(units[0][objectRange])
        let base=ThoughtOrganizer.organize("Water "+object+" tomorrow",referenceDate:referenceDate,calendar:calendar)
        guard base.itemType == .task,!base.needsClarification,base.state == .resolved,
              let tomorrow=calendar.date(byAdding:.day,value:1,to:referenceDate),
              base.temporalIntent.kind == .dateOnly,base.temporalIntent.time == nil,
              base.temporalIntent.day == CalendarDay(from:tomorrow,calendar:calendar),
              base.dueDate == calendar.startOfDay(for:tomorrow),base.reminderDate == nil,
              base.reminderDelivery == .none,base.locationIntent == nil,
              base.recurrenceRule == nil,base.personName == nil else { return nil }
        // Both exact source sentences remain visible, including the negative
        // branch. The remaining source context is preserved as owned evidence.
        return .init(action:units[0]+". "+units[1]+".",organization:base)
    }
}

enum RuntimeRetainedUncommittedIdea {
    static func read(_ source:String) -> Bool {
        let units=RuntimeIndexedSource(source).units.map { $0.text.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!"))) }
        guard units.count == 3,QuotedSpeechScope.ranges(in:source).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(source),
              CaptureOperationDetector.partitionWithOwnership(source).operations.isEmpty else { return false }
        func matches(_ text:String,_ pattern:String)->Bool {
            text.range(of:"(?i)^"+pattern+"$",options:.regularExpression) != nil
        }
        // Closed positive design activity and complete nominal objects. An
        // extra command, commitment, condition or date cannot fit any slot.
        let root = #"I\s+was\s+thinking\s+of\s+(?:painting|drawing|sketching|designing|making)\s+(?:(?:little|small|large|new|colored|colourful|colorful)\s+){0,2}(?:picture\s+)?(?:labels|signs|pictures|diagrams)\s+for\s+the\s+(?:plants|pots|rooms|shelves)(?:\s+rather\s+than\s+writing\s+their\s+names)?"#
        let design = matches(units[0],root)
            && matches(units[1],#"That\s+could\s+be\s+a\s+(?:nice\s+)?(?:small\s+)?project,?\s+but\s+it\s+is\s+still\s+an\s+idea"#)
            && matches(units[2],#"I\s+have\s+not\s+decided\s+to\s+spend\s+a\s+weekend\s+on\s+it"#)
        // An explicitly saved possible series is still an idea. The finite
        // every-visit phrase describes the possible project; the complete
        // last sentence expressly declines a recurring reminder.
        let series = matches(units[0],#"There\s+is\s+an\s+idea\s+I\s+want\s+to\s+keep\s+separately,\s+though:\s+photograph\s+the\s+same\s+(?:station\s+platform|garden\s+fence|park\s+gate)\s+from\s+the\s+same\s+spot\s+every\s+time\s+I\s+visit"#)
            && matches(units[1],#"It\s+might\s+make\s+an\s+interesting\s+series\s+over\s+a\s+year"#)
            && matches(units[2],#"I\s+am\s+not\s+setting\s+up\s+a\s+recurring\s+reminder\s+for\s+it,\s+just\s+saving\s+the\s+possible\s+project"#)
        return design || series
    }
}

enum RuntimeCurrentPurchaseStatus {
    static func read(_ units:RuntimeIndexedSource) -> Bool {
        guard !Task.isCancelled,units.units.count == 2,
              QuotedSpeechScope.ranges(in:units.source).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(units.source),
              CaptureOperationDetector.partitionWithOwnership(units.source).operations.isEmpty else { return false }
        func body(_ value:String)->String {
            value.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!")))
        }
        let purchase=body(units.units[0].text),status=body(units.units[1].text)
        guard status.range(of:#"(?i)^(?:I\s+have\s+not|I\s+haven['’]t)\s+(?:bought|purchased)\s+it\s+yet$"#,options:.regularExpression) != nil,
              let regex=NSRegularExpression.speakItCached(#"(?i)^(?:buy|purchase)\s+(?:(?:one|1|a|an|the)\s+)?([\p{L}\p{M} -]+)$"#),
              let match=regex.firstMatch(in:purchase,range:NSRange(purchase.startIndex...,in:purchase)),
              let range=Range(match.range(at:1),in:purchase) else { return false }
        let object=String(purchase[range])
        // Positive full noun-phrase evidence; an unavailable tagger or unknown
        // suffix grants no license. The small household grammar is local to
        // this proof and does not broaden the ordinary short-capture reader.
        let words=object.lowercased().split(whereSeparator:{$0.isWhitespace}).map(String.init)
        let heads:Set<String>=["mug","cup","bowl","plate","glass","jug","bottle","tray","bucket"]
        let modifiers:Set<String>=["replacement","spare","new","old","small","large","red","blue","green","white","black","ceramic","glass","plastic","metal","wooden","wide","narrow","handle","handled"]
        let household=(1...5).contains(words.count) && heads.contains(words.last ?? "")
            && words.dropLast().allSatisfy({modifiers.contains($0)})
        guard object.count <= 120,!object.contains("--"),
              ShoppingGroupParser.namesOneProduct(object) || RuntimeCurrentNominalProof.read(object) || household else { return false }
        // The singular "it" must have one current object. Explicit lists and
        // plural objects are never collapsed, even when all words are nominal.
        guard !(words.last ?? "").hasSuffix("s"),
              ActionabilityReader.read(purchase).belongsOnToday else { return false }
        return true
    }
}

enum RuntimeShortSourceCertificate {
    static func isDisfluencyOnly(_ source:String) -> Bool {
        let filler = #"(?:um|uh|er|hmm|hm|yeah|like|okay|ok|right|basically|really|you\s+know)"#
        return source.range(of:"(?i)^\\s*"+filler+"(?:[\\s,]+"+filler+")*[.!?]*\\s*$",options:.regularExpression) != nil
    }
    private static func exact(_ text:String,_ pattern:String) -> [String]? {
        guard let regex=NSRegularExpression.speakItCached("(?i)^(?:"+pattern+")$"),
              let m=regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)) else { return nil }
        return (1..<m.numberOfRanges).map { Range(m.range(at:$0),in:text).map { String(text[$0]) } ?? "" }
    }
    private static func nominal(_ text:String, in context:String? = nil) -> Bool {
        if RuntimeCurrentNominalProof.read(text) { return true }
        let heads:Set<String>=["app","apps","proposal","proposals","invoice","invoices","refund","refunds","plant","plants","drawer","drawers","cabinet","cabinets","shelf","shelves","planner","planners","planning"]
        let modifiers:Set<String>=["weekly","daily","monthly","planning","spare","blue","red","green","small","large","old","new","upper","lower","front","back"]
        guard text.range(of:#"^[\p{L}\p{M} -]+$"#,options:.regularExpression) != nil,!text.contains("--") else { return false }
        var words=text.lowercased().split(whereSeparator:{$0.isWhitespace}).map(String.init)
        if ["a","an","the"].contains(words.first ?? "") { words.removeFirst() }
        guard text.count <= 120,(1...5).contains(words.count) else { return false }
        if heads.contains(words.last ?? ""),words.dropLast().allSatisfy({ modifiers.contains($0) || heads.contains($0) }) { return true }
        if ShoppingGroupParser.namesOneProduct(text) { return true }
        // A detached noun can be tagged as an imperative (for example milk).
        // Read only this exact, uniquely located argument in its complete
        // current speech act. Every argument token must remain nominal; an
        // unknown tail, second predicate or conjunction grants no permission.
        guard let context,let range=context.range(of:text),
              context.range(of:text,range:range.upperBound..<context.endIndex) == nil else { return false }
        let tokens=SentenceContextCache.context(for:context).tokens(in:range)
        let literal=text.split(whereSeparator: { $0.isWhitespace }).joined(separator:" ")
        guard tokens.first?.range.lowerBound == range.lowerBound,
              tokens.last?.range.upperBound == range.upperBound,
              tokens.map(\.text).joined(separator:" ").caseInsensitiveCompare(literal) == .orderedSame,
              tokens.last?.lexicalClass == .noun else { return false }
        return tokens.enumerated().allSatisfy { index,token in
            token.lexicalClass == .noun || token.lexicalClass == .adjective
                || (index == 0 && token.lexicalClass == .determiner && ["a","an","the"].contains(token.text.lowercased()))
        }
    }
    private static func person(_ text:String) -> String? {
        guard RuntimeRecipientReplacement.literalRecipient(text),
              text.range(of:#"\b(?:and|or|but|then|also|if|unless|not|never|no|actually|instead|today|tomorrow|tonight)\b|[,;:.!?\"“”]"#,options:[.regularExpression,.caseInsensitive]) == nil,
              case let .person(named)=PersonMentionResolver.followUpTarget(in:"Call "+text),
              named.label.caseInsensitiveCompare(text) == .orderedSame else { return nil }
        return text
    }
    private static func ideaComplement(_ text:String) -> Bool {
        if nominal(text) { return true }
        // One reflexive playback purpose belongs to the proposed object. It
        // introduces no user commitment. Unknown verbal/finite continuations
        // still reconcile rather than borrowing an "idea" prefix as approval.
        guard let f=exact(text,#"(.+?)\s+to\s+(?:read|speak|play)\s+itself\s+(?:back|aloud)(?:\s+to\s+me)?"#),nominal(f[0]) else { return false }
        return true
    }
    private static func reminderTopic(_ text:String) -> Bool {
        if nominal(text) { return true }
        // The complete prepositional topic of an explicit reminder is retained
        // literally. One lexical head needs no installed noun-tagging asset;
        // pronouns and incomplete/conditional/repair tails prove no target.
        guard let words=exact(text,#"(?:(?:the|a|an|my|our)\s+)?([\p{L}\p{M}]+(?:-[\p{L}\p{M}]+)*)"#) else { return false }
        let unresolved:Set<String>=["it","this","that","these","those","him","her","them","me","you","us","there","here","somewhere","something","anything","everything","nothing","today","tomorrow","tonight","later","if","unless","not","never","no","actually","instead","and","or","but","then","also"]
        return !unresolved.contains(words[0].lowercased())
    }
    private struct Frame { let kind:ItemType;let person:String?;let action:String;let clock:String;let alert:Bool }
    private static func frame(_ original:String, additionalPhysicalActions:Bool = false) -> Frame? {
        let body=original.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!?")))
        // An explicit uncommitted idea owns its entire complement. A later
        // current self-commitment or independent clause cannot borrow that scope.
        if let idea=exact(body,#"(?:i\s+(?:have|had)|i['’]ve\s+got)\s+an?\s+idea\s+(?:for|to|about)\s+(.+)"#) ?? exact(body,#"(?:an?\s+)?idea\s*:\s*(.+)"#),
           ideaComplement(idea[0]) {
            return .init(kind:.idea,person:nil,action:body,clock:"",alert:false)
        }
        if let fact=exact(body,#"(?:remember\s+that\s+)?(.+?)\s+(?:likes|prefers)\s+(.+)"#),let named=person(fact[0]),nominal(fact[1],in:body) {
            return .init(kind:.note,person:named,action:body,clock:"",alert:false)
        }
        if let fact=exact(body,#"(.+?)\s+is\s+(?:in|on|under|inside)\s+(.+)"#),nominal(fact[0],in:body),nominal(fact[1],in:body) {
            return .init(kind:.note,person:nil,action:body,clock:"",alert:false)
        }
        // Complete literal clock syntax must be valid before the resolver
        // runs: an invalid hour cannot become a day-only/default-time alert.
        let timePattern = #"(?:(?:0?[1-9]|1[0-2])(?::[0-5][0-9])?\s+(?:AM|PM)|(?:[01]?[0-9]|2[0-3])(?::[0-5][0-9])?)"#
        let clockPattern = #"(?:today|tomorrow|(?:on\s+)?(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday))(?:\s+at\s+"# + timePattern + #")?"#
        if let topic=exact(body,"remind\\s+me\\s+about\\s+(.+?)\\s+("+clockPattern+")"),reminderTopic(topic[0]) {
            // A dated reminder about a topic does not imply a call, visit,
            // contact identity or spoken clock. The current organizer supplies
            // the existing date-only/default-alert policy below.
            return .init(kind:.task,person:nil,action:body,clock:topic[1],alert:true)
        }
        var action=body,clock="",alert=false
        if let f=exact(action,"remind\\s+me\\s+("+clockPattern+")\\s+to\\s+(.+)") { clock=f[0];action=f[1];alert=true }
        else if let f=exact(action,#"remind\s+me\s+to\s+(.+)"#) { action=f[0];alert=true }
        else if let f=exact(action,#"i\s+(?:need|have)\s+to\s+(.+)"#) { action=f[0] }
        if clock.isEmpty,let f=exact(action,"("+clockPattern+")[, ]+(.+)") { clock=f[0];action=f[1] }
        if clock.isEmpty,let f=exact(action,"(.+?)\\s+("+clockPattern+")") { action=f[0];clock=f[1] }
        action=action.replacingOccurrences(of:#"(?i)^please\s+"#,with:"",options:.regularExpression)
        if let f=exact(action,#"(call|phone|ask|email|text|message)\s+(.+?)(?:\s+about\s+(.+))?"#),f[2].isEmpty || nominal(f[2],in:action) {
            if let recipient=person(f[1]) {
                return .init(kind:.personFollowUp,person:recipient,action:action,clock:clock,alert:alert)
            }
            // A complete described endpoint remains literal wording. It grants
            // no address-book identity or communication side effect.
            if (nominal(f[1],in:action) || PersonMentionResolver.isLiteralServiceDescription(f[1])),
               case let .described(label)=PersonMentionResolver.followUpTarget(in:"Call "+f[1]),
               label.caseInsensitiveCompare(f[1]) == .orderedSame {
                return .init(kind:.task,person:nil,action:action,clock:clock,alert:alert)
            }
        }
        if let f=exact(action,#"(?:buy|purchase)\s+(.+)"#),nominal(f[0],in:action) {
            // Adjacent known products are still a list, not one compound.
            // The ordinary certificate cannot collapse their membership.
            guard !ShoppingGroupParser.namesOnlyProducts(f[0]) || ShoppingGroupParser.namesOneProduct(f[0]) else { return nil }
            return .init(kind:.shopping,person:nil,action:action,clock:clock,alert:alert)
        }
        if let f=exact(action,#"pay\s+(.+)"#),
           nominal(f[0],in:action) || PersonMentionResolver.isLiteralServiceDescription(f[0]) {
            // A complete current payment errand names its literal object or
            // service. It authorizes a task, not contact resolution or money
            // movement. Unknown tails still need whole-source reconciliation.
            return .init(kind:.task,person:nil,action:action,clock:clock,alert:alert)
        }
        if let f=exact(action,#"(?:water|clean|wash|check|repair|fix|dust|test|measure|polish|sort)\s+(.+)"#),nominal(f[0],in:action) {
            return .init(kind:.task,person:nil,action:action,clock:clock,alert:alert)
        }
        if additionalPhysicalActions,
           let f=exact(action,#"(?:inspect|trim|trace|photograph)\s+(.+)"#),nominal(f[0],in:action) {
            return .init(kind:.task,person:nil,action:action,clock:clock,alert:alert)
        }
        return nil
    }
    /// This supplies only a purpose proved by the complete current frame.
    /// No source is shortened, no metadata is borrowed, and later ownership,
    /// corrections and saving still pass the whole-capture validator.
    static func purpose(_ source:String) -> ItemType? {
        guard !Task.isCancelled,QuotedSpeechScope.ranges(in:source).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(source),
              CaptureOperationDetector.partitionWithOwnership(source).operations.isEmpty else { return nil }
        return frame(source,additionalPhysicalActions:true)?.kind
    }
    static func interpret(_ source:String,referenceDate:Date,calendar:Calendar) -> ThoughtExtractionResult? {
        guard !Task.isCancelled,!source.isEmpty,source.count<=500,
              QuotedSpeechScope.ranges(in:source).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(source),
              CaptureOperationDetector.partitionWithOwnership(source).operations.isEmpty else { return nil }
        if isDisfluencyOnly(source) {
            let held=RuntimeSourceInterpreter.recoverableReview(source),old=held.items[0]
            return .init(items:[.init(sourceQuote:source,rawQuote:source,wasRepaired:false,analysisText:source,suggestedTitle:source,
                organization:old.organization,confidence:0,needsReview:true,sourceUnitIDs:Set(SourceUnitLedger(source).words.indices))],method:.rules)
        }
        let units=RuntimeIndexedSource(source),ledger=SourceUnitLedger(source)
        guard (1...2).contains(units.units.count) else { return nil }
        var items:[ExtractedThought]=[]
        for unit in units.units {
            guard let current=frame(unit.text) else { return nil }
            // A complete untimed "remind me to" speech act supplies a task,
            // not a guessed interruption clock. The positive whole frame has
            // already proved all its words and excludes trigger/condition tails.
            // Read that exact action and require its complete resolved metadata.
            let readingText = current.alert && current.clock.isEmpty ? current.action : unit.text
            let reading=ThoughtOrganizer.organize(readingText,referenceDate:referenceDate,calendar:calendar)
            guard !reading.needsClarification,reading.locationIntent==nil,reading.recurrenceRule==nil else { return nil }
            let memory = current.kind == .idea || current.kind == .note
            if !memory {
                guard ActionabilityReader.read(unit.text).belongsOnToday,reading.itemType.isActionable,reading.state == .resolved else { return nil }
                if current.alert,!current.clock.isEmpty {
                    guard reading.reminderDate != nil,reading.reminderDelivery == .notification else { return nil }
                } else if !current.alert {
                    guard reading.reminderDate == nil,reading.reminderDelivery == .none else { return nil }
                }
                if current.clock.isEmpty {
                    guard reading.dueDate==nil,reading.reminderDate==nil,reading.temporalIntent == .none else { return nil }
                } else {
                    // Complete clock syntax above owns this slot; the existing
                    // temporal resolver remains authoritative for its local zone.
                    let clockReading=ThoughtOrganizer.organize("Check the task "+current.clock,referenceDate:referenceDate,calendar:calendar)
                    let hasClock = current.clock.range(of:#"(?i)\bat\b"#,options:.regularExpression) != nil
                    guard clockReading.dueDate != nil,reading.dueDate==clockReading.dueDate,
                          !hasClock || (clockReading.temporalIntent.time != nil && reading.temporalIntent.time == clockReading.temporalIntent.time),
                          !clockReading.needsClarification,clockReading.locationIntent==nil,clockReading.recurrenceRule==nil else { return nil }
                }
            }
            let org=OrganizedThought(itemType:current.kind,category:memory ? (current.kind == .idea ? .ideas : current.person == nil ? .general : .people) : reading.category,
                priority:memory ? .normal : reading.priority,personName:current.person,dueDate:memory ? nil : reading.dueDate,
                reminderDate:memory ? nil : reading.reminderDate,reminderDelivery:memory ? .none : reading.reminderDelivery,
                recurrenceRule:nil,needsClarification:false,temporalIntent:memory ? .none : reading.temporalIntent,state:.resolved)
            items.append(.init(sourceQuote:unit.text,rawQuote:unit.text,wasRepaired:false,analysisText:unit.text,
                suggestedTitle:ThoughtTitleFormatter.polished(unit.text,itemType:current.kind,personName:current.person),organization:org,
                confidence:1,needsReview:false,sourceUnitIDs:ledger.ids(in:unit.range)))
        }
        guard RuntimeProposalGuard.covers(source,quotes:items.map(\.sourceQuote)),items.reduce(into:Set<Int>()) { $0.formUnion($1.sourceUnitIDs) } == Set(ledger.words.indices) else { return nil }
        return .init(items:items,method:.rules)
    }
}

/// A bounded, complete-source reading for ordinary independent clauses. This
/// does not accept the parser's confidence, proposed destinations or titles.
/// Every literal occurrence must independently prove a current speech act;
/// one unknown clause declines the WHOLE certificate. Corrections, saved-item
/// operations and dependent/conditional clauses retain their existing readers.
enum RuntimeCompleteLiteralCertificate {
    private struct Piece { let range: Range<String.Index>; let text: String }
    private struct Reading { let body: String; let organization: OrganizedThought }
    private static let repair = #"(?i)\b(?:actually|instead|correction|wait|on\s+second\s+thought|never\s+mind|no\s+wait|make\s+that|withdraw|reschedule|replace)\b"#
    private static let dependent = #"(?i)\b(?:if|unless|when|whenever|once|until|before|after|otherwise|provided|assuming)\b"#
    private static let ownLead = #"(?:(?:I|we)\s+(?:(?:need|have|ought)\s+to|should|must|will)\s+|(?:I|we)['’]ll\s+|(?:please\s+)?remind\s+me\s+to\s+)"#

    private static func exact(_ text: String, _ pattern: String) -> [String]? {
        guard let regex = NSRegularExpression.speakItCached("(?i)^(?:" + pattern + ")$"),
              let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) else { return nil }
        return (1..<match.numberOfRanges).map { Range(match.range(at: $0), in: text).map { String(text[$0]) } ?? "" }
    }
    private static func body(_ text: String) -> String {
        text.trimmingCharacters(in: .whitespacesAndNewlines.union(CharacterSet(charactersIn: ".!?")))
            .replacingOccurrences(of: #"(?i)^,?\s*(?:and\s+)?(?=(?:I|we)\b|(?:please\s+)?remind\s+me\b)"#,
                with: "", options: .regularExpression)
    }
    private static func communicationMatrix(_ text: String) -> Bool {
        ClauseScope.read(text).act == .communicating
            || ActionabilityReader.actionBody(body(text)).range(
                of: #"(?i)^(?:call|phone|ask|tell|say|email|text|message|notify|inform)\b"#,
                options: .regularExpression) != nil
    }
    /// Only an explicit new matrix act can open a run-on seam. The first
    /// clause must speak directly: a reported/message complement cannot use
    /// an inner 'and I need to' to manufacture the phone owner's obligation.
    private static func pieces(_ source: String) -> [Piece]? {
        let units = RuntimeIndexedSource(source)
        guard !units.units.isEmpty, units.units.count <= 64 else { return nil }
        let seam = #"(?i)(?:,\s*(?:and\s+)?|\s+and\s+)(?="# + ownLead + ")"
        guard let regex = NSRegularExpression.speakItCached(seam) else { return nil }
        var result: [Piece] = []
        for unit in units.units {
            var start = unit.range.lowerBound
            for match in regex.matches(in: source, range: NSRange(unit.range, in: source)) {
                guard let boundary = Range(match.range, in: source), boundary.lowerBound > start,
                      !QuotedSpeechScope.protects(boundary, in: source) else { continue }
                let prefix = body(String(source[start..<boundary.lowerBound]))
                guard ClauseScope.read(prefix).act == .direct,
                      !communicationMatrix(prefix) else { continue }
                result.append(.init(range: start..<boundary.lowerBound,
                    text: String(source[start..<boundary.lowerBound])))
                // Keep the connector in the literal quote and source ledger.
                // Only the reading projection peels this proved matrix seam.
                start = boundary.lowerBound
            }
            result.append(.init(range: start..<unit.range.upperBound,
                text: String(source[start..<unit.range.upperBound])))
        }
        return result.count <= 64 ? result : nil
    }
    private static func nominalSubject(_ text: String) -> Bool {
        if ["I", "we", "he", "she", "they", "it", "this", "that"].contains(where: { $0.caseInsensitiveCompare(text) == .orderedSame }) { return true }
        if RuntimeCurrentNominalProof.read(text) { return true }
        if let fields = exact(text, #"(?:my|our|his|her|their|its)\s+(.+)"#), RuntimeCurrentNominalProof.read(fields[0]) { return true }
        guard text.first?.isUppercase == true,
              RuntimeRecipientReplacement.literalRecipient(text),
              case let .person(named) = PersonMentionResolver.followUpTarget(in: "Call " + text) else { return false }
        return named.label.caseInsensitiveCompare(text) == .orderedSame
    }
    private static func memoryKind(_ text: String) -> ItemType? {
        guard !QuotedSpeechScope.hasUnclosedQuote(text) else { return nil }
        if let retained = ActionabilityReader.explicitCaptureRetentionKind(text),
           !RuntimeAccountOwnership.hasCurrentActForReference(text) { return retained }
        if RuntimeRetainedUncommittedIdea.read(text),
           !RuntimeAccountOwnership.hasCurrentActForReference(text) { return .idea }
        let scope = ClauseScope.read(text)
        if scope.act == .reporting, scope.complement?.isEmpty == false,
           !RuntimeAccountOwnership.hasCurrentActForReference(text) { return .note }
        guard QuotedSpeechScope.ranges(in: text).isEmpty,
              // These separators introduce a new clause or an unproved list;
              // neither can borrow a preceding finite subject as permission.
              text.range(of: #"(?i)[,;:]|\b(?:and|or|but|then|also|plus|so|because|although|while|by|via)\b"#, options: .regularExpression) == nil else { return nil }
        let finite = #"(?:is|are|was|were|am|has|have|had|contains|costs|weighs|measures|fits|likes|prefers|opens|closes|offers|lives|works|leaks|seems|looks|smells|sounds|made|built|drew|found|saw|broke|felt|took|went|gave|[\p{L}]+ed)"#
        guard let fields = exact(text, "(.+?)\\s+(" + finite + #")(?:\s+(.*))?"#),
              nominalSubject(fields[0]),
              !fields[2].isEmpty || ["leaks", "opens", "closes", "smells", "broke", "cracked", "arrived", "closed", "opened", "faded"].contains(fields[1].lowercased()),
              !RuntimeAccountOwnership.hasCurrentActForReference(text),
              !ActionabilityReader.read(text).belongsOnToday else { return nil }
        return .note
    }
    private static func reading(_ original: String, referenceDate: Date, calendar: Calendar) -> Reading? {
        let text = body(original)
        guard !text.isEmpty,
              !original.trimmingCharacters(in: .whitespacesAndNewlines).hasSuffix("?"),
              !ClauseScope.read(text).deniesComplement,
              !RuleBasedThoughtExtractor.shouldKeepAsOneSafetyItem(text),
              text.range(of: #"(?i)^(?:I|we)\s+(?:should|must|would|could|may|might)\s+have\b"#, options: .regularExpression) == nil else { return nil }
        // Preserve the existing positive short grammar, including its exact
        // clock and recipient checks. Its narrow meaning is not broadened.
        if !text.contains(","),
           let short = RuntimeShortSourceCertificate.interpret(text, referenceDate: referenceDate, calendar: calendar),
           short.items.count == 1, let item = short.items.first, !item.needsReview {
            return .init(body: text, organization: item.organization)
        }
        if let kind = memoryKind(text) {
            let factual = ThoughtOrganizer.organize(text, referenceDate: referenceDate, calendar: calendar)
            let memoryType = kind == .note && factual.itemType == .idea ? ItemType.idea : kind
            let subjects = PersonMentionResolver.mentions(in: text).filter { $0.role == .subject }
            let person = memoryType == .note && ClauseScope.read(text).act == .direct
                && subjects.count == 1 && factual.personName == subjects.first?.label ? factual.personName : nil
            return .init(body: text, organization: .init(itemType: memoryType,
                category: memoryType == .idea ? .ideas : person == nil ? .general : .people, priority: .normal, personName: person,
                dueDate: nil, reminderDate: nil, reminderDelivery: .none, recurrenceRule: nil,
                needsClarification: false, temporalIntent: .none, state: .resolved))
        }
        // An explicitly causal fact explains this action; it is not a second
        // task or a source of the action's clock. Both complete clauses must
        // independently prove their roles. Unknown or executive reasons decline.
        if let because = text.range(of: #"(?i)\s+because\s+"#, options: .regularExpression),
           text.range(of: #"(?i)\s+because\s+"#, options: .regularExpression,
               range: because.upperBound..<text.endIndex) == nil,
           QuotedSpeechScope.ranges(in: text).isEmpty,
           let action = reading(String(text[..<because.lowerBound]), referenceDate: referenceDate, calendar: calendar),
           action.organization.itemType.isActionable,
           memoryKind(String(text[because.upperBound...])) == .note {
            return .init(body: text, organization: action.organization)
        }
        guard QuotedSpeechScope.ranges(in: text).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(text),
              !communicationMatrix(text),
              text.range(of: dependent, options: .regularExpression) == nil,
              text.range(of: #"(?i)[,;:]|\b(?:and|or|but|then|also|plus|because|although|while|not|never|don't|do\s+not)\b"#, options: .regularExpression) == nil,
              ClauseScope.read(text).act != .reporting else { return nil }
        let explicitOwn = text.range(of: "(?i)^" + ownLead, options: .regularExpression) != nil
        let imperative = text.range(of: #"(?i)^(?:please\s+)?(?:"# + ActionabilityReader.actionVerb
            + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\s+\S"#, options: .regularExpression) != nil
        guard explicitOwn || imperative else { return nil }
        let action = ActionabilityReader.actionBody(text)
        // A first-person obligation proves ownership even for an unfamiliar
        // physical verb, but cannot turn intellectual retention into an errand.
        guard action.range(of: #"(?i)^(?:know|understand|think|consider|remember|save|keep|retain|preserve|record)\b"#, options: .regularExpression) == nil,
              // A noun-headed factual subject such as 'Call records are ...'
              // is not an imperative merely because its first word is a verb.
              // More complex finite message/reference complements retain the
              // existing whole-source interpreter rather than borrowing this
              // ordinary complete-predicate certificate.
              action.range(of: #"(?i)\b(?:is|are|am|was|were|has|have|had|contains|costs|weighs|measures|fits|likes|prefers|opens|closes|offers|lives|works|leaks|seems|looks|smells|sounds)\b"#, options: .regularExpression) == nil,
              ActionabilityReader.read(text).belongsOnToday else { return nil }
        let knownHead = action.range(of: #"(?i)^(?:"# + ActionabilityReader.actionVerb
            + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\s+\S"#, options: .regularExpression) != nil
        if !knownHead {
            guard explicitOwn,
                  let predicate = exact(action, #"([\p{L}]+)\s+(.+)"#),
                  !["be", "been", "being", "have", "has", "had"].contains(predicate[0].lowercased()),
                  RuntimeShortSourceCertificate.purpose("Check " + predicate[1]) == .task else { return nil }
        }
        var organized = ThoughtOrganizer.organize(text, referenceDate: referenceDate, calendar: calendar)
        if ReminderPhrasing.requestsReminder(text), organized.reminderDate == nil,
           organized.temporalIntent == .none, organized.locationIntent == nil,
           organized.recurrenceRule == nil,
           text.range(of: #"(?i)^(?:please\s+)?remind\s+me\s+to\s+"#, options: .regularExpression) != nil {
            // No trigger was supplied: preserve the clear action without
            // inventing a notification. The complete executable body must
            // itself resolve; unknown adjuncts still decline below.
            organized = ThoughtOrganizer.organize(action, referenceDate: referenceDate, calendar: calendar)
        }
        guard organized.itemType.isActionable, !organized.needsClarification,
              organized.state == .resolved, organized.locationIntent == nil,
              organized.recurrenceRule == nil else { return nil }
        return .init(body: text, organization: organized)
    }
    /// A past copular state has a descriptive calendar adjunct, not an
    /// instruction scheduled for that day. Require the whole finite state;
    /// dated event nouns and completed event predicates retain their existing
    /// metadata. This proof never comes from a proposed row's destination.
    private static func pastStateCalendarContext(_ original: String) -> String? {
        let text = body(original)
        guard memoryKind(text) == .note,
              let fields = exact(text, #"(.+?)\s+(?:was|were)\s+(.+?)\s+(on\s+"#
                + SelfCorrectionResolver.datePattern + #")"#),
              nominalSubject(fields[0]) else { return nil }
        // Reuse the established asset-independent copular quality grammar.
        // The exact whole finite source frame above owns this predicate and
        // calendar adjunct; neither detached nor unavailable tags authorize it.
        guard RuntimeIndependentFramePlan.descriptiveCopularQuality(fields[1]) else { return nil }
        return fields[2]
    }
    private static func withoutContextTiming(_ value: OrganizedThought) -> OrganizedThought {
        .init(itemType: value.itemType, category: value.category, priority: value.priority,
            personName: value.personName, dueDate: nil, reminderDate: nil,
            reminderDelivery: .none, recurrenceRule: value.recurrenceRule,
            needsClarification: value.needsClarification, temporalIntent: .none,
            locationIntent: value.locationIntent, state: value.state)
    }
    private static func sameTemporalMeaning(_ left: TemporalIntent, _ right: TemporalIntent) -> Bool {
        var left = left, right = right
        left.sourceText = nil; right.sourceText = nil
        return left == right
    }
    /// The only timing disagreement this certificate can correct is the
    /// already proved descriptive state adjunct. Its exact resolved calendar
    /// must account for every old timing field, while all other semantics agree.
    private static func ownsContextTiming(_ item: ExtractedThought, old: OrganizedThought,
                                         referenceDate: Date, calendar: Calendar) -> Bool {
        let current = item.organization
        guard current.temporalIntent == .none, current.dueDate == nil,
              current.reminderDate == nil, current.reminderDelivery == .none,
              old.reminderDate == nil, old.reminderDelivery == .none,
              old.recurrenceRule == nil, old.locationIntent == nil,
              !old.temporalIntent.isUserEdited,
              old.temporalIntent.kind == .dateOnly,
              withoutContextTiming(old) == current else { return false }
        let text = body(item.sourceQuote)
        let context: String?
        if current.itemType == .note {
            context = pastStateCalendarContext(text)
        } else if current.itemType.isActionable,
                  let because = text.range(of: #"(?i)\s+because\s+"#, options: .regularExpression),
                  text.range(of: #"(?i)\s+because\s+"#, options: .regularExpression,
                    range: because.upperBound..<text.endIndex) == nil {
            // reading(_:) already independently proved the executable left
            // clause and the complete factual reason before constructing this
            // literal item. The date belongs only to that whole finite reason.
            context = pastStateCalendarContext(String(text[because.upperBound...]))
        } else { context = nil }
        guard let context else { return false }
        guard let timing = ThoughtOrganizer.dateOnlyContextTiming(context,
            referenceDate: referenceDate, calendar: calendar) else { return false }
        return sameTemporalMeaning(old.temporalIntent, timing.intent)
            && (old.dueDate == nil || old.dueDate == timing.dueDate)
    }
    /// Bind a processed quote to the actual occurrence IDs it claims. Repeated
    /// words elsewhere and a merely equal title cannot satisfy this ownership.
    private static func ownsOriginalQuote(_ item: ExtractedThought, ledger: SourceUnitLedger) -> Bool {
        guard let first = item.sourceUnitIDs.min(), let last = item.sourceUnitIDs.max(),
              first >= 0, last < ledger.words.count,
              item.sourceUnitIDs == Set(first...last) else { return false }
        let lower = first == 0 ? ledger.source.startIndex : ledger.words[first - 1].range.upperBound
        let upper = last + 1 == ledger.words.count ? ledger.source.endIndex : ledger.words[last + 1].range.lowerBound
        guard let occurrence = ledger.source.range(of: item.rawQuote, range: lower..<upper)
        else { return false }
        return ledger.ids(in: occurrence) == item.sourceUnitIDs
    }
    /// A literal proof may settle an otherwise held reading, but it cannot
    /// replace preprocessing or a richer source-owned parser result. Neither
    /// parser confidence nor a single broad raw predicate proves that a list,
    /// normalized clock, calendar alias, named person or event was preserved.
    private static func aligned(_ literal: ThoughtExtractionResult,
                                with rules: ThoughtExtractionResult,
                                source: String, referenceDate: Date,
                                calendar: Calendar) -> ThoughtExtractionResult? {
        guard rules.operations.isEmpty, !rules.items.isEmpty,
              literal.items.count >= rules.items.count,
              rules.items.allSatisfy({ !$0.wasRepaired }) else { return nil }
        let ledger = SourceUnitLedger(source)
        let allIDs = Set(ledger.words.indices)
        guard rules.items.allSatisfy({ ownsOriginalQuote($0, ledger: ledger) }) else { return nil }
        let processedIDs = rules.items.reduce(into: Set<Int>()) { $0.formUnion($1.sourceUnitIDs) }
        // Rules consume coordinating 'and' while splitting. The complete
        // literal proof retains that exact connector on a positively proved
        // new own matrix; no omitted content word can use this exception.
        let seamIDs = Set(literal.items.compactMap { item -> Int? in
            guard item.rawQuote.range(of: #"(?i)^\s*,?\s*and\s+(?="# + ownLead + #")"#,
                options: .regularExpression) != nil,
                  let first = item.sourceUnitIDs.min(), ledger.words[first].text == "and"
            else { return nil }
            return first
        })
        guard allIDs.subtracting(processedIDs).isSubset(of: seamIDs) else { return nil }
        var titles: [Int: String] = [:]
        var analyses: [Int: String] = [:]
        var groups: [Int: String] = [:]
        for item in rules.items {
            guard !item.sourceUnitIDs.isEmpty, item.sourceUnitIDs.isSubset(of: allIDs) else { return nil }
            let owners = literal.items.indices.filter {
                item.sourceUnitIDs.isSubset(of: literal.items[$0].sourceUnitIDs)
            }
            let old = item.organization
            let resolved = !item.needsReview && !old.needsClarification && old.state == .resolved
            let hasMetadata = old.personName != nil || old.dueDate != nil || old.reminderDate != nil
                || old.reminderDelivery != .none || old.recurrenceRule != nil
                || old.locationIntent != nil || old.temporalIntent != .none
            // Only an untyped, metadata-free whole review can be partitioned
            // by newly proved independent matrices. A typed or settled row
            // must have one exact current occurrence owner.
            guard owners.count == 1 || (!resolved && !hasMetadata && old.itemType == .unclear) else { return nil }
            guard let owner = owners.first, owners.count == 1 else { continue }
            let current = literal.items[owner].organization
            if resolved {
                guard old == current || ownsContextTiming(literal.items[owner], old: old,
                    referenceDate: referenceDate, calendar: calendar) else { return nil }
                // Preserve established display framing only after complete
                // source ownership and every semantic field agree. Titles
                // supply no authority for type, metadata or review waiver.
                titles[owner] = item.suggestedTitle ?? ThoughtTitleFormatter.polished(
                    item.analysisText, itemType: old.itemType, personName: old.personName)
                // Preserve canonical analysis and grouping after semantic
                // agreement, just as established display framing is retained.
                analyses[owner] = item.analysisText
                if let group = item.shoppingGroup { groups[owner] = group }
            } else {
                // A generic literal predicate cannot supply a missing object
                // or decide that a single untyped review was meaningful.
                guard old.state.gap != .ambiguousObject,
                      !(old.itemType == .unclear && literal.items.count == rules.items.count),
                      old.itemType == .unclear || old.itemType == current.itemType,
                      old.personName == nil || old.personName == current.personName,
                      old.dueDate == nil || old.dueDate == current.dueDate,
                      old.reminderDate == nil || old.reminderDate == current.reminderDate,
                      old.reminderDelivery == .none || old.reminderDelivery == current.reminderDelivery,
                      old.recurrenceRule == nil || old.recurrenceRule == current.recurrenceRule,
                      old.locationIntent == nil || old.locationIntent == current.locationIntent,
                      old.temporalIntent == .none || old.temporalIntent == current.temporalIntent else { return nil }
            }
        }
        let items = literal.items.enumerated().map { index, item in
            ExtractedThought(sourceQuote: item.sourceQuote, rawQuote: item.rawQuote,
                wasRepaired: item.wasRepaired, analysisText: analyses[index] ?? item.analysisText,
                suggestedTitle: titles[index] ?? item.suggestedTitle,
                organization: item.organization, confidence: item.confidence,
                needsReview: item.needsReview, sourceUnitIDs: item.sourceUnitIDs,
                shoppingGroup: item.shoppingGroup ?? groups[index])
        }
        return .init(items: items, method: literal.method)
    }
    static func interpret(_ source: String, referenceDate: Date, calendar: Calendar,
                          rules: ThoughtExtractionResult? = nil) -> ThoughtExtractionResult? {
        if let corrected = calendarRepair(source, referenceDate: referenceDate, calendar: calendar) {
            let previous: ThoughtExtractionResult
            if let rules { previous = rules }
            else {
                let reading = RuleBasedThoughtExtractor.process(source, referenceDate: referenceDate, calendar: calendar)
                previous = .init(items: reading.items, operations: reading.operations, method: .rules)
            }
            guard !previous.items.contains(where: {
                $0.organization.state.gap == .ambiguousObject
                    || ($0.needsReview && $0.organization.itemType == .unclear)
            }) else { return nil }
            return corrected
        }
        if let rules, let arrival = arrivalReminder(source, rules: rules) { return arrival }
        if let shopping = RuleBasedThoughtExtractor.literalPurchasePlan(source,
            referenceDate: referenceDate, calendar: calendar)
            ?? RuleBasedThoughtExtractor.pastTripShoppingPlan(source,
                referenceDate: referenceDate, calendar: calendar)
            ?? RuleBasedThoughtExtractor.literalPackingPlan(source,
                referenceDate: referenceDate, calendar: calendar), rules == nil || rules == shopping {
            return shopping
        }
        guard !Task.isCancelled, !source.isEmpty, source.count <= 12_000,
              source.range(of: repair, options: .regularExpression) == nil,
              // Honorific/place abbreviations require the established rules
              // sentence reader. An indexed stop at 'dr.' must not authorize
              // a second imperative beginning with a person's surname.
              source.range(of: #"(?i)\b(?:dr|mr|mrs|ms|prof|st|sr|jr|vs|etc)\."#, options: .regularExpression) == nil,
              !QuotedSpeechScope.hasUnclosedQuote(source),
              CaptureOperationDetector.partitionWithOwnership(source).operations.isEmpty,
              let pieces = pieces(source) else { return nil }
        let ledger = SourceUnitLedger(source)
        var items: [ExtractedThought] = [], claimed = Set<Int>()
        for piece in pieces {
            guard let current = reading(piece.text, referenceDate: referenceDate, calendar: calendar) else { return nil }
            let ids = ledger.ids(in: piece.range)
            guard !ids.isEmpty, claimed.isDisjoint(with: ids) else { return nil }
            claimed.formUnion(ids)
            items.append(.init(sourceQuote: piece.text, rawQuote: piece.text, wasRepaired: false,
                analysisText: piece.text, suggestedTitle: ThoughtTitleFormatter.polished(current.body,
                    itemType: current.organization.itemType, personName: current.organization.personName),
                organization: current.organization, confidence: 1, needsReview: false, sourceUnitIDs: ids))
        }
        guard claimed == Set(ledger.words.indices),
              RuntimeProposalGuard.covers(source, quotes: items.map(\.sourceQuote)) else { return nil }
        let processed: ThoughtExtractionResult
        if let rules { processed = rules }
        else {
            let result = RuleBasedThoughtExtractor.process(source,
                referenceDate: referenceDate, calendar: calendar)
            processed = .init(items: result.items, operations: result.operations, method: .rules)
        }
        return aligned(.init(items: items, method: .rules), with: processed, source: source,
            referenceDate: referenceDate, calendar: calendar)
    }
    /// The reminder act, own arrival condition and explicit action form one
    /// literal envelope. Named-place support remains a downstream live blocker.
    /// This never certifies third-party arrivals or adds a geographic match.
    static func arrivalReminder(_ source: String, rules: ThoughtExtractionResult) -> ThoughtExtractionResult? {
        guard rules.operations.isEmpty, rules.items.count == 1,
              source.range(of: #"(?i)^\s*(?:(?:please\s+)?remind\s+me\s*,?\s*)?(?:when|once|as\s+soon\s+as|next\s+time)\s+(?:I|we)\b"#,
                           options: .regularExpression) != nil,
              QuotedSpeechScope.ranges(in: source).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(source),
              ReminderPhrasing.requestsReminder(source),
              let action = LocationIntentParser.actionBody(in: source),
              ActionabilityReader.read(action).belongsOnToday,
              let item = rules.items.first, !item.wasRepaired, !item.needsReview,
              item.rawQuote == source, item.sourceQuote == source,
              item.sourceUnitIDs == Set(SourceUnitLedger(source).words.indices),
              item.organization.locationIntent != nil,
              item.organization.itemType.isActionable,
              !item.organization.needsClarification, item.organization.state == .resolved else { return nil }
        return rules
    }

    /// The repair reader proves an exact single calendar-slot replacement,
    /// including every deleted occurrence. Re-read only its complete final
    /// source; the old first clock cannot donate metadata to the new action.
    static func calendarRepair(_ source: String, referenceDate: Date, calendar: Calendar) -> ThoughtExtractionResult? {
        guard !Task.isCancelled, source.count <= 2_000,
              source.range(of: repair, options: .regularExpression) != nil else { return nil }
        let corrected = SelfCorrectionResolver.resolved(source)
        guard corrected != source,
              SelfCorrectionResolver.calendarFrameRepairIDs(input: source, output: corrected) != nil,
              corrected.range(of: repair, options: .regularExpression) == nil,
              CaptureOperationDetector.partitionWithOwnership(corrected).operations.isEmpty,
              ActionabilityReader.read(corrected).belongsOnToday else { return nil }
        // The exact repair reader already proved this one complete calendar
        // frame and its unchanged executable tail. Read that final frame
        // directly, including its literal reminder delimiter comma; ordinary
        // comma/list frames remain outside the complete-literal certificate.
        let organization = ThoughtOrganizer.organize(corrected, referenceDate: referenceDate, calendar: calendar)
        guard organization.itemType.isActionable, !organization.needsClarification,
              organization.state == .resolved, organization.locationIntent == nil,
              organization.recurrenceRule == nil, organization.dueDate != nil,
              organization.temporalIntent.kind == .dateOnly || organization.temporalIntent.kind == .exactDateTime else { return nil }
        return .init(items: [.init(sourceQuote: corrected, rawQuote: source, wasRepaired: true,
            analysisText: corrected, suggestedTitle: ThoughtTitleFormatter.polished(corrected,
                itemType: organization.itemType, personName: organization.personName), organization: organization,
            confidence: 1, needsReview: false, sourceUnitIDs: Set(SourceUnitLedger(source).words.indices))], method: .rules)
    }
}

enum RuntimeExampleInterpreter {
#if DEBUG
    @TaskLocal static var testInterpretation: ThoughtExtractionResult? = nil
#endif
    static func interpret(_ source: String, referenceDate: Date, calendar: Calendar,
                          context: RuntimeCaptureContext, configuration: RuntimeExampleConfiguration,
                          rules: ThoughtExtractionResult,ruleTrace: RuntimeRuleTrace? = nil,
                          contextProvider: (@MainActor @Sendable () -> RuntimeCaptureContext)? = nil) async -> ThoughtExtractionResult? {
        if let nominal = RuleBasedThoughtExtractor.currentNominalStatusPlan(source,
            referenceDate: referenceDate, calendar: calendar, rules: rules) {
            return nominal
        }
#if DEBUG
        if let testInterpretation { return testInterpretation }
#endif
        if rules.operations.isEmpty,
           let literal = RuntimeCompleteLiteralCertificate.interpret(source,
            referenceDate: referenceDate, calendar: calendar, rules: rules) {
            return literal
        }
        if rules.operations.isEmpty, let reference = RuntimeExplicitReferenceScope.interpret(source) {
            return reference
        }
        if let ordinary=RuntimeShortSourceCertificate.interpret(source,referenceDate:referenceDate,calendar:calendar) {
#if DEBUG
            RuntimeExampleLibrary.developmentObserver?("short source contract consumed=no-references complete-current-frames=true")
#endif
            return ordinary
        }
        // These explicit current-source graphs need no worked answer. Resolve
        // them identically with retrieval OFF and ON, before opening an index.
        if let decision = RuntimeExplicitDecisionCertificate.interpret(source) { return decision }
        if let narrative = RuntimeIndependentFramePlan.coherentNarrative(source) { return narrative }
        var permitsAccountOwnership = false
#if canImport(FoundationModels)
        if #available(iOS 26.4, *) {
            permitsAccountOwnership = configuration.usesStagedOutline && RuntimeAccountOwnership.scoped(source)
        }
#endif
        if RuntimeIndependentFramePlan.hasUnprovedAccount(source), !permitsAccountOwnership {
            return RuntimeSourceInterpreter.recoverableReview(source)
        }
        if let composed = RuntimeIndependentFramePlan.interpret(source,examples:[],
            referenceDate:referenceDate,calendar:calendar,configuration:configuration) {
            return composed
        }
        if !RuntimeIndependentFramePlan.containsAccountDeclaration(source),!Task.isCancelled,
           let certified = RuntimeDiscourseCertificate.validate(rules,trace:ruleTrace,
            source:source,referenceDate:referenceDate,calendar:calendar) {
#if DEBUG
            RuntimeExampleLibrary.developmentObserver?("source certificate consumed=no-references identity-lineage=true complete-meaning=true")
#endif
            return certified
        }
        // A protected literal call has no ownership/correction/list problem.
        // Keep it fast on every phone; complex/confident readings still retrieve.
        if rules.operations.isEmpty, rules.items.count == 1,
           !rules.items[0].needsReview,
           source.range(of: #"^(?i)(?:please\s+)?(?:call|phone)\s+(?:my\s+)?(?:mom|mum|dad|mother|father|grandma|grandpa|brother|sister)(?:\s+(?:today|tomorrow|tonight))?[.!]?$"#,
                        options: .regularExpression) != nil { return rules }
        // Current-source certificates above cannot consume saved context.
        // Load one complete value snapshot only when interpretation needs it.
        let currentContext: RuntimeCaptureContext
        if let contextProvider { currentContext = await contextProvider() }
        else { currentContext = context }
#if canImport(FoundationModels)
        if #available(iOS 26.4, *),
           SystemLanguageModel.default.availability == .available,
           SystemLanguageModel.default.supportsLocale(.current) {
            let work = Task<ThoughtExtractionResult?, Never> {
                let examples: [RuntimeWorkedExample]
                do { examples = try await RuntimeExampleLibrary.shared.select(source, configuration: configuration) }
                catch { return RuntimeSourceInterpreter.recoverableReview(source) }
                if let local = RuntimeSourceInterpreter.interpret(source, referenceDate: referenceDate,
                    calendar: calendar, context: currentContext, examples: examples, configuration:configuration) { return local }
                if RuntimeIndependentFramePlan.containsAccountDeclaration(source) {
                    // One bounded ownership call may validate the complete literal
                    // account. Failed/unavailable ownership remains recoverable;
                    // it never falls through to another generative interpretation.
                    if configuration.usesStagedOutline, RuntimeAccountOwnership.scoped(source),
                       let account = await RuntimeAccountOwnership.interpret(source,
                        referenceDate:referenceDate, calendar:calendar, context:currentContext,
                        rules:rules, examples:examples) { return account }
                    return RuntimeSourceInterpreter.recoverableReview(source)
                }
                return await RuntimeFoundationInterpreter.interpret(source, referenceDate: referenceDate,
                    calendar: calendar, context: currentContext, configuration: configuration, rules: rules,
                    preselectedExamples: examples, ruleTrace:ruleTrace)
            }
            let deadline = Task {
                do { try await Task.sleep(for: .seconds(20)) } catch { return }
#if DEBUG
                RuntimeFoundationInterpreter.developmentObserver?("call cancellation phase=runtime reason=deadline deadlineSeconds=20")
#endif
                work.cancel()
            }
            return await withTaskCancellationHandler {
                defer { deadline.cancel() }
                let result = await work.value
                if work.isCancelled, rules.operations.isEmpty {
                    return RuntimeFoundationInterpreter.recoverableReview(source)
                }
                return result
            } onCancel: {
#if DEBUG
                RuntimeFoundationInterpreter.developmentObserver?("call cancellation phase=runtime reason=caller")
#endif
                work.cancel()
            }
        }
#endif
        // The same source-grounded local interpreter is available on iOS 17+.
        // Model availability changes complex interpretation capability, never
        // the original transcript or permission to guess a saved target.
        let examples = (try? await RuntimeExampleLibrary.shared.select(source, configuration: configuration)) ?? []
        let local = RuntimeSourceInterpreter.interpret(source, referenceDate: referenceDate,
            calendar: calendar, context: currentContext, examples: examples, configuration:configuration)
        if local == nil,RuntimeIndependentFramePlan.containsAccountDeclaration(source) { return RuntimeSourceInterpreter.recoverableReview(source) }
        return local
    }
}

/// Bounded local interpretation for source-declared purposes and a complete
/// saved revision. Demonstrations supply structural evidence (membership,
/// destination, atomic delta); every resulting fact comes from current source.
/// Clear lists do not require the model to echo 30 actions through a token cap.
enum RuntimeSourceInterpreter {
    static func interpret(_ source: String, referenceDate: Date, calendar: Calendar,
                          context: RuntimeCaptureContext, examples: [RuntimeWorkedExample],
                          configuration: RuntimeExampleConfiguration? = nil) -> ThoughtExtractionResult? {
        guard !Task.isCancelled else { return recoverableReview(source) }
        // Inspect the worked solutions, not merely the retriever's score. Only
        // abstract structure is consumed; example facts and IDs never flow into
        // a current item or operation. OFF uses the identical source contract.
        let structures = examples.compactMap { row -> [String: Any]? in
            guard let data = row.payload.data(using: .utf8),
                  let record = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
            return record["solution"] as? [String: Any]
        }
        let supportsMembership = structures.contains { ($0["groups"] as? [Any])?.isEmpty == false
            || (($0["new_items"] as? [Any])?.count ?? 0) > 1 }
        let supportsAtomic = structures.contains { solution in
            (solution["mutations"] as? [[String: Any]] ?? []).contains { $0["atomic"] as? Bool == true }
        }
#if DEBUG
        RuntimeExampleLibrary.developmentObserver?("local structures membership=\(supportsMembership) atomic=\(supportsAtomic) inspected=\(examples.map(\.id).joined(separator: ","))")
#endif
        if let saved = savedChangePlan(source, referenceDate: referenceDate, calendar: calendar, context: context) { return saved }
        if let revision = SavedAtomicRevision.read(source, snapshots: context.savedItems.compactMap(\.snapshot),
                referenceDate: referenceDate, calendar: calendar) {
            var request = CaptureOperationRequest(operation: .revise, polarity: .positive,
                target: revision.expected.title, sourceQuote: source, needsReview: false)
            request.savedAtomicRevision = revision
            return ThoughtExtractionResult(items: [], operations: [request], method: .rules)
        }
        if let composed = RuntimeIndependentFramePlan.interpret(source,examples:examples,
            referenceDate:referenceDate,calendar:calendar,configuration:configuration) { return composed }
        if let narrative = RuntimeIndependentFramePlan.coherentNarrative(source) { return narrative }
        if RuntimeIndependentFramePlan.hasUnprovedAccount(source)
            || RuntimeIndependentFramePlan.containsAccountDeclaration(source) { return nil }
        if let mixed = RuntimeMixedPurposeCertificate.interpret(source,examples:examples,referenceDate:referenceDate,calendar:calendar,configuration:configuration) { return mixed }
        if let replaced = RuntimeRecipientReplacement.interpret(source,examples:examples,referenceDate:referenceDate,calendar:calendar,configuration:configuration) { return replaced }
        if let repaired = RuntimeQuantityAnalogy.interpret(source, examples: examples) { return repaired }
        if let withdrawn = RuntimeCurrentWithdrawal.interpret(source,referenceDate:referenceDate,calendar:calendar) { return withdrawn }
        if let commitments = RuntimeCommitmentAnalogy.interpret(source, examples: examples,
            referenceDate: referenceDate, calendar: calendar) { return commitments }
        if let items = declaredPurposeGroups(source, referenceDate: referenceDate, calendar: calendar) {
            return ThoughtExtractionResult(items: items, method: .rules)
        }
        if let items = independentUndatedTasks(source, referenceDate: referenceDate, calendar: calendar) {
            return ThoughtExtractionResult(items: items, method: .rules)
        }
        if let replaced = RuntimeWholePlanReplacement.interpret(source,referenceDate:referenceDate,calendar:calendar) { return replaced }
        if let action = RuntimeCommunicationReading.read(source) {
            let reading = ThoughtOrganizer.organize(action.action, referenceDate: referenceDate, calendar: calendar)
            if !reading.needsClarification, reading.locationIntent == nil, reading.recurrenceRule == nil {
                let organization = OrganizedThought(itemType: .task, category: reading.category,
                    priority: reading.priority, personName: action.recipient,
                    dueDate: reading.dueDate, reminderDate: reading.reminderDate,
                    reminderDelivery: reading.reminderDelivery, recurrenceRule: nil,
                    needsClarification: false, temporalIntent: reading.temporalIntent, state: .resolved)
                return ThoughtExtractionResult(items: [.init(sourceQuote: source, rawQuote: source,
                    wasRepaired: false, analysisText: source,
                    suggestedTitle: ThoughtTitleFormatter.polished(action.action, itemType: .task),
                    organization: organization, confidence: 1, needsReview: false)], method: .rules)
            }
        }
        let clearKnowledge = source.range(of: #"(?i)^\s*(?:inventory\s*(?:only)?|questions?\s+to\s+keep\s+for\s+reference|(?:an?\s+)?idea)\s*:"#, options: .regularExpression) != nil
        let governingSource = outsideQuotations(source)
        let explicitUnadoptedQuote = governingSource.range(of: #"(?i)\b(?:haven.t\s+agreed|not\s+(?:agreeing|agreed)|not\s+my\s+(?:task|commitment))\b"#, options: .regularExpression) != nil
            && governingSource.range(of: #"(?i)\b(?:keep|preserve).{0,60}\b(?:note|quotation)\b"#, options: .regularExpression) != nil
        let positiveTail = governingSource.range(of: #"(?i)\b(?:remind\s+me|i\s+(?:(?:will|must|should)(?!\s+(?:not|never)\b)|need\s+to|have\s+to|promised)|i['’]ll)\b|(?:^|[.!?;\n])\s*(?:also\s+|and\s+)?(?:call|phone|ask|tell|email|text|message|send|buy|pack|clean|test|check|finish|return|fix|repair|book|pay|wash|count)\b"#, options: .regularExpression) != nil
        let declaredCoherentMemory = governingSource.range(of: #"(?i)^\s*(?:keep|save|preserve)(?:\s+(?:the\s+following|this)\s+as)?\s+one\s+(?:(?:connected|coherent)\s+)?(?:memory|note|account)\b"#,
                                                          options: .regularExpression) != nil
        if (clearKnowledge || explicitUnadoptedQuote || declaredCoherentMemory) && !positiveTail {
            let isIdea = source.range(of: #"(?i)^\s*(?:an?\s+)?idea\s*:"#, options: .regularExpression) != nil
            let kind: ItemType = isIdea ? .idea : .note
            let organized = OrganizedThought(itemType: kind, category: isIdea ? .ideas : .general,
                priority: .normal, personName: nil, dueDate: nil, reminderDate: nil,
                reminderDelivery: .none, recurrenceRule: nil, needsClarification: false, state: .resolved)
            return ThoughtExtractionResult(items: [.init(sourceQuote: source, rawQuote: source,
                wasRepaired: false, analysisText: source, suggestedTitle: nil,
                organization: organized, confidence: 1, needsReview: false,
                sourceUnitIDs: Set(SourceUnitLedger(source).words.indices))], method: .rules)
        }
        if source.range(of: #"(?i)^\s*pack\s+"#, options: .regularExpression) != nil,
           governingSource.range(of: #"(?i)\b(?:we\s+own|already\s+(?:own|have))\b"#, options: .regularExpression) != nil,
           governingSource.range(of: #"(?i)\b(?:do\s+not|don.t)\s+buy\b"#, options: .regularExpression) != nil,
           governingSource.range(of: #"(?i)\b(?:actually|instead|also|unless|if|remind)\b"#, options: .regularExpression) == nil,
           ThoughtOrganizer.organize(source, referenceDate: referenceDate, calendar: calendar).dueDate == nil,
           source.range(of: #"(?is)^\s*pack\s+[^.!?]+[.!]\s*we\s+(?:already\s+)?(?:own|have)\s+[^.!?]+[.!]\s*(?:do\s+not|don.t)\s+buy\s+[^.!?]+[.!]?\s*$"#, options: .regularExpression) != nil {
            let organized = OrganizedThought(itemType: .task, category: .general, priority: .normal,
                personName: nil, dueDate: nil, reminderDate: nil, reminderDelivery: .none,
                recurrenceRule: nil, needsClarification: false, state: .resolved)
            return ThoughtExtractionResult(items: [.init(sourceQuote: source, rawQuote: source,
                wasRepaired: false, analysisText: source, suggestedTitle: nil,
                organization: organized, confidence: 1, needsReview: false)], method: .rules)
        }
        return nil
    }

    /// Separate a source-owned saved edit from explicit independent new work.
    /// Unsupported saved deltas remain one visible held request, never parser
    /// fragments promoted to tasks. The original capture remains complete.
    static func savedChangePlan(_ source: String, referenceDate: Date, calendar: Calendar,
                                context: RuntimeCaptureContext) -> ThoughtExtractionResult? {
        guard source.range(of: #"(?i)^\s*(?:please\s+)?(?:change|update|revise|edit|move|reschedule|cancel|remove|turn\s+off)\b.{0,100}\bsaved\b"#,options: .regularExpression) != nil else { return nil }
        let units = RuntimeIndexedSource(source)
        let boundary = units.units.firstIndex { unit in
            unit.text.range(of: #"(?i)^\s*(?:also|separately)\s*[, :]?\s*(?:remind\s+me|call|phone|ask|tell|email|text|message|send|buy|pack|clean|test|check|finish|return|fix|repair|book|pay|wash|count)\b"#, options: .regularExpression) != nil
        } ?? units.units.count
        guard boundary > 0 else { return nil }
        let end = units.units[boundary-1].range.upperBound
        let owned = String(source[..<end]).trimmingCharacters(in: .whitespacesAndNewlines)
        var creations: [ExtractedThought] = []
        let ledger = SourceUnitLedger(source)
        for index in boundary..<units.units.count {
            let unit = units.units[index]
            let action = unit.text.replacingOccurrences(of: #"(?i)^\s*(?:also|separately)\s*[, :]?\s*"#,with: "",options: .regularExpression)
            let reading = ThoughtOrganizer.organize(action,referenceDate: referenceDate,calendar: calendar)
            // Conditional/quoted/withdrawn or coupled tails need full model
            // reconciliation, so do not claim a safe independent creation.
            guard ActionabilityReader.read(action).belongsOnToday,!reading.needsClarification,
                  action.range(of: #"(?i)\b(?:actually|instead|cancel|withdraw|if|unless|said|wrote|maybe|might|never\s+mind)\b"#,options: .regularExpression) == nil,
                  reading.locationIntent == nil,reading.recurrenceRule == nil else { return recoverableReview(source) }
            creations.append(.init(sourceQuote: unit.text,rawQuote: unit.text,wasRepaired: false,analysisText: action,
                suggestedTitle: ThoughtTitleFormatter.polished(action,itemType: reading.itemType),organization: reading,
                confidence: 1,needsReview: false,sourceUnitIDs: ledger.ids(in: unit.range)))
        }
        guard RuntimeProposalGuard.covers(source,quotes: [owned]+creations.map(\.sourceQuote)) else { return recoverableReview(source) }
        let snapshots = context.savedItems.compactMap(\.snapshot)
        var revision = SavedAtomicRevision.read(owned,snapshots: snapshots,referenceDate: referenceDate,calendar: calendar)
        revision?.captureSource = source
        let pending = revision == nil ? SavedRevisionIntent.read(owned,captureSource: source,snapshots: snapshots,
            referenceDate: referenceDate,calendar: calendar) : nil
        var request:CaptureOperationRequest
        // A saved cancellation is not a generic replacement. Preserve the
        // complete typed CURRENT operation contract (including quantity,
        // person/place and date deltas) before the repository resolves targets.
        // This grammar supplies no saved ID or permission to select a row.
        let typed=CaptureOperationDetector.partitionWithOwnership(owned)
        let alertOnly=SavedAtomicRevision.alertRemovalEvidence(owned,referenceDate:referenceDate,calendar:calendar) != nil
        if revision == nil,pending == nil,!alertOnly,typed.operations.count == 1,typed.remainder == nil,
           typed.unownedMeaningfulIDs(in:owned).isEmpty {
            request=typed.operations[0]
        } else {
            // A quoted notification-only delta with stale/missing state must
            // remain an amendment hold; it cannot become task cancellation.
            request=CaptureOperationRequest(operation:.revise,polarity:.positive,
                target:revision?.expected.title ?? pending?.targetWords,sourceQuote:owned,needsReview:revision == nil)
            request.savedAtomicRevision=revision;request.savedRevisionIntent=pending
        }
        request.captureSource = source; request.sourceUnitIDs = ledger.ids(in: source.startIndex..<end)
        request.independentCreationUnitIDs = creations.reduce(into: Set<Int>()) { $0.formUnion($1.sourceUnitIDs) }
        return .init(items: creations,operations: [request],method: .rules)
    }

    private static func outsideQuotations(_ source: String) -> String {
        var result = "", quoted = false
        for character in source {
            if character == "\"" { quoted.toggle(); result.append(" "); continue }
            if character == "“" { quoted = true; result.append(" "); continue }
            if character == "”" { quoted = false; result.append(" "); continue }
            result.append(quoted ? " " : character)
        }
        return result
    }

    /// Explicit task and reference headings own different source scopes. A
    /// mixed 30-intention capture need not regenerate every unchanged sentence.
    /// This contract requires declared counts and complete literal membership;
    /// corrections, quotations and implicit purpose changes use reconciliation.
    static func declaredPurposeGroups(_ source: String, referenceDate: Date,
                                      calendar: Calendar) -> [ExtractedThought]? {
        let number = #"(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty(?:[- ](?:one|two|three|four|five|six|seven|eight|nine))?|thirty)"#
        let heading = #"(?i)(?:^|[.!?:]\s+)(?:(?:these|the)\s+(?:next\s+)?)?("# + number
            + #")\s+(?:(?:independent|separate|distinct)\s+)?(jobs|tasks|actions|facts|notes)\b([^:;.!?]{0,100}):"#
        guard let regex = NSRegularExpression.speakItCached(heading) else { return nil }
        let matches = regex.matches(in: source, range: NSRange(source.startIndex..., in: source))
        guard matches.count >= 2 else { return nil }
        let counts = ["one":1,"two":2,"three":3,"four":4,"five":5,"six":6,"seven":7,"eight":8,"nine":9,
            "ten":10,"eleven":11,"twelve":12,"thirteen":13,"fourteen":14,"fifteen":15,"sixteen":16,
            "seventeen":17,"eighteen":18,"nineteen":19,"twenty":20,"thirty":30]
        func count(_ text: String) -> Int? {
            if let value = Int(text) { return value }
            let words = text.lowercased().split(whereSeparator: { $0 == "-" || $0 == " " }).map(String.init)
            if words.count == 2, words[0] == "twenty", let tail = counts[words[1]], (1...9).contains(tail) { return 20 + tail }
            return counts[text.lowercased()]
        }
        guard let firstRange = Range(matches[0].range, in: source) else { return nil }
        let lead = String(source[..<firstRange.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
        var total: Int?
        if !lead.isEmpty {
            let pattern = #"(?i)^\s*("# + number + #")\s+(?:separate|independent|distinct)\s+intentions\s*:?\s*$"#
            guard let declaration = NSRegularExpression.speakItCached(pattern)?.firstMatch(in: lead, range: NSRange(lead.startIndex..., in: lead)),
                  let range = Range(declaration.range(at: 1), in: lead) else { return nil }
            total = count(String(lead[range]))
        }
        let ledger = SourceUnitLedger(source)
        var items: [ExtractedThought] = [], purposes = Set<ItemType>()
        for (groupIndex, match) in matches.enumerated() {
            guard let headerRange = Range(match.range, in: source),
                  let countRange = Range(match.range(at: 1), in: source),
                  let kindRange = Range(match.range(at: 2), in: source),
                  let qualifiersRange = Range(match.range(at: 3), in: source),
                  let declared = count(String(source[countRange])), declared > 0 else { return nil }
            let kind = String(source[kindRange]).lowercased()
            let isTask = ["jobs","tasks","actions"].contains(kind)
            let qualifiers = String(source[qualifiersRange])
            guard qualifiers.range(of: #"(?i)\b(?:said|wrote|quoted|maybe|might|actually|instead|unless|if|their|your|his|her)\b|[\"“”]"#,
                                   options: .regularExpression) == nil,
                  !isTask || qualifiers.range(of: #"(?i)\bnot\b"#, options: .regularExpression) == nil else { return nil }
            let bodyEnd: String.Index
            if groupIndex + 1 < matches.count {
                guard let nextRange = Range(matches[groupIndex + 1].range, in: source) else { return nil }
                bodyEnd = nextRange.lowerBound
            } else { bodyEnd = source.endIndex }
            let bodyRange = headerRange.upperBound..<bodyEnd
            let body = String(source[bodyRange])
            guard body.range(of: #"(?i)\b(?:actually|instead|never\s+mind|cancel|remove|withdraw|unless|said|wrote|if|except|until|only\s+after|provided)\b|[\"“”]"#,
                             options: .regularExpression) == nil,
                  !isTask || body.range(of: #"(?i)\b(?:don.t|do\s+not|not\s+my|maybe|might)\b"#, options: .regularExpression) == nil else { return nil }
            var ranges: [Range<String.Index>] = [], start = bodyRange.lowerBound
            for index in source[bodyRange].indices where source[index] == ";" {
                ranges.append(start..<index); start = source.index(after: index)
            }
            ranges.append(start..<bodyEnd)
            guard ranges.count == declared else { return nil }
            let header = String(source[headerRange])
            let shared = ThoughtOrganizer.organize(header, referenceDate: referenceDate, calendar: calendar)
            let quiet = header.range(of: #"(?i)\b(?:undated|no\s+(?:timed\s+)?alerts|without\s+(?:notifications|alerts)|no\s+notifications)\b"#,
                                     options: .regularExpression) != nil
            guard !isTask || shared.locationIntent == nil && shared.recurrenceRule == nil else { return nil }
            for (entryIndex, range) in ranges.enumerated() {
                let text = String(source[range]).trimmingCharacters(in: .whitespacesAndNewlines)
                guard !text.isEmpty else { return nil }
                let quoteStart = entryIndex == 0 ? (groupIndex == 0 ? source.startIndex : headerRange.lowerBound) : range.lowerBound
                let quoteRange = quoteStart..<range.upperBound
                let quote = String(source[quoteRange]).trimmingCharacters(in: .whitespacesAndNewlines)
                let organized: OrganizedThought
                if isTask {
                    guard ActionabilityReader.read("I need to " + text).belongsOnToday else { return nil }
                    let reading = ThoughtOrganizer.organize(text, referenceDate: referenceDate, calendar: calendar)
                    guard !reading.needsClarification, reading.locationIntent == nil, reading.recurrenceRule == nil,
                          !quiet || !ReminderPhrasing.requestsReminder(text) else { return nil }
                    let communication = text.range(of: #"(?i)^(?:call|phone|ask|tell|email|text|message|send)\b"#, options: .regularExpression) != nil
                    organized = .init(itemType: .task, category: reading.category, priority: reading.priority,
                        personName: communication ? reading.personName : nil, dueDate: reading.dueDate ?? shared.dueDate,
                        reminderDate: quiet ? nil : reading.reminderDate, reminderDelivery: quiet ? .none : reading.reminderDelivery,
                        recurrenceRule: nil, needsClarification: false,
                        temporalIntent: reading.dueDate == nil && shared.dueDate != nil ? shared.temporalIntent : reading.temporalIntent,
                        state: .resolved)
                } else {
                    organized = .init(itemType: .note, category: .general, priority: .normal,
                        personName: nil, dueDate: nil, reminderDate: nil, reminderDelivery: .none,
                        recurrenceRule: nil, needsClarification: false, state: .resolved)
                }
                purposes.insert(organized.itemType)
                items.append(.init(sourceQuote: quote, rawQuote: quote, wasRepaired: false, analysisText: text,
                    suggestedTitle: ThoughtTitleFormatter.polished(text, itemType: organized.itemType),
                    organization: organized, confidence: 1, needsReview: false, sourceUnitIDs: ledger.ids(in: quoteRange)))
            }
        }
        guard purposes.contains(.task), purposes.contains(.note), total == nil || total == items.count,
              RuntimeProposalGuard.covers(source, quotes: items.map(\.sourceQuote)) else { return nil }
        return items
    }

    private static func independentUndatedTasks(_ source: String, referenceDate: Date,
                                                calendar: Calendar) -> [ExtractedThought]? {
        // A declared list owns its scope. "No alerts" does not also require
        // the word "undated"; an explicit shared day is a deadline, not an alert.
        let declaration = #"(?i)^\s*(?:(?:these|here)\s+are\s+(?:my\s+)?|i\s+(?:mean|have|need)\s+)?(?:(?:\p{L}+|\d+)(?:[- ](?:five|six|seven|eight|nine))?\s+)?(?:separate|independent|independently\s+trackable|distinct)\s+(?:\p{L}+\s+){0,3}(?:tasks|jobs|actions|intentions|preparations)\b"#
        guard let declarationRange = source.range(of: declaration, options: .regularExpression) else { return nil }
        let suffix = declarationRange.upperBound..<source.endIndex
        let headerEnd: String.Index
        if let colon = source.range(of: ":", range: suffix) {
            headerEnd = colon.upperBound
        } else if let quiet = source.range(of: #"(?i)\bno\s+(?:timed\s+)?alerts\b\s*"#,
                                          options: .regularExpression, range: suffix) {
            headerEnd = quiet.upperBound
        } else { return nil }
        let prefix = String(source[..<headerEnd])
        guard prefix.range(of: #"(?i)\b(?:said|wrote|quoted|maybe|might|actually|instead|unless|if)\b|[\"“”]"#,
                           options: .regularExpression) == nil,
              !ReminderPhrasing.requestsReminder(prefix) else { return nil }
        let quiet = prefix.range(of: #"(?i)\b(?:no\s+(?:timed\s+)?alerts|without\s+(?:notifications|alerts)|no\s+notifications)\b"#,
                                  options: .regularExpression) != nil
        let shared = ThoughtOrganizer.organize(prefix, referenceDate: referenceDate, calendar: calendar)
        guard shared.locationIntent == nil, shared.recurrenceRule == nil else { return nil }
        let bodyRange = headerEnd..<source.endIndex
        let body = String(source[bodyRange])
        // Reconcile later changes before any creation. This fast reading only
        // owns independent actions with no correction, quotation or condition.
        guard body.range(of: #"(?i)\b(?:actually|instead|never\s+mind|cancel|remove|withdraw|don.t|do\s+not|unless|said|wrote|if|except|until|only\s+after|provided)\b"#,
                         options: .regularExpression) == nil else { return nil }
        var ranges: [Range<String.Index>] = [], start = bodyRange.lowerBound
        var inQuote = false, depth = 0
        for index in source[bodyRange].indices {
            let character = source[index]
            if character == "\"" { inQuote.toggle() }
            if character == "“" { inQuote = true }; if character == "”" { inQuote = false }
            if !inQuote { if character == "(" { depth += 1 }; if character == ")" { depth = max(0, depth - 1) } }
            if character == ";", !inQuote, depth == 0 { ranges.append(start..<index); start = source.index(after: index) }
        }
        guard !inQuote, depth == 0 else { return nil }
        ranges.append(start..<source.endIndex)
        // An explicit discourse separator remains useful when ASR loses
        // punctuation. Keep its exact source in each row's provenance.
        if ranges.count == 1, let regex = NSRegularExpression.speakItCached(#"(?i)\s+next\s+job\s+"#) {
            let separators = regex.matches(in: source, range: NSRange(bodyRange, in: source))
                .compactMap { Range($0.range, in: source) }
            if !separators.isEmpty {
                ranges = []; start = headerEnd
                for separator in separators { ranges.append(start..<separator.lowerBound); start = separator.lowerBound }
                ranges.append(start..<source.endIndex)
            }
        }
        guard ranges.count > 1 else { return nil }
        let counts = ["one":1,"two":2,"three":3,"four":4,"five":5,"six":6,"seven":7,"eight":8,"nine":9,"ten":10,
            "eleven":11,"twelve":12,"thirteen":13,"fourteen":14,"fifteen":15,"sixteen":16,"seventeen":17,
            "eighteen":18,"nineteen":19,"twenty":20,"twentyfive":25,"twenty-five":25,"thirty":30]
        let declarationText = String(source[declarationRange]).lowercased()
        let leadingWords = declarationText.components(separatedBy: CharacterSet.alphanumerics.inverted)
            .prefix { $0 != "separate" && $0 != "independent" && $0 != "independently" && $0 != "distinct" }
        let numbers = leadingWords.compactMap { Int($0) ?? counts[$0] }
        let declaredCount = numbers.count == 2 && numbers[0] == 20 && (1...9).contains(numbers[1])
            ? numbers[0] + numbers[1] : numbers.first
        if let declaredCount, declaredCount != ranges.count { return nil }
        let ledger = SourceUnitLedger(source)
        var result: [ExtractedThought] = []
        for (index, range) in ranges.enumerated() {
            let action = String(source[range]).trimmingCharacters(in: .whitespacesAndNewlines)
                .replacingOccurrences(of: #"(?i)^next\s+job\s+"#, with: "", options: .regularExpression)
            guard !action.isEmpty, ActionabilityReader.read("I need to " + action).belongsOnToday else { return nil }
            let quoteRange = index == 0 ? source.startIndex..<range.upperBound : range
            let quote = String(source[quoteRange]).trimmingCharacters(in: .whitespacesAndNewlines)
            let reading = ThoughtOrganizer.organize(action, referenceDate: referenceDate, calendar: calendar)
            guard reading.locationIntent == nil, reading.recurrenceRule == nil, !reading.needsClarification,
                  !quiet || !ReminderPhrasing.requestsReminder(action) else { return nil }
            let communication = action.range(of: #"(?i)^(?:call|phone|ask|tell|email|text|message|send)\b"#, options: .regularExpression) != nil
            let due = reading.dueDate ?? shared.dueDate
            let temporal = reading.dueDate == nil && shared.dueDate != nil ? shared.temporalIntent : reading.temporalIntent
            let organized = OrganizedThought(itemType: .task, category: reading.category,
                priority: reading.priority, personName: communication ? reading.personName : nil,
                dueDate: due, reminderDate: quiet ? nil : reading.reminderDate,
                reminderDelivery: quiet ? .none : reading.reminderDelivery,
                recurrenceRule: nil, needsClarification: false, temporalIntent: temporal, state: .resolved)
            result.append(.init(sourceQuote: quote, rawQuote: quote, wasRepaired: false,
                analysisText: prefix + " " + action,
                suggestedTitle: ThoughtTitleFormatter.polished(action, itemType: .task),
                organization: organized, confidence: 1, needsReview: false,
                sourceUnitIDs: ledger.ids(in: quoteRange)))
        }
        guard RuntimeProposalGuard.covers(source, quotes: result.map(\.sourceQuote)) else { return nil }
        return result
    }

    static func recoverableReview(_ source: String) -> ThoughtExtractionResult {
        let organized = OrganizedThought(itemType: .unclear, category: .general, priority: .normal,
            personName: nil, dueDate: nil, reminderDate: nil, reminderDelivery: .none,
            recurrenceRule: nil, needsClarification: true, state: .contested(.uncertainClauseBoundary))
        return ThoughtExtractionResult(items: [.init(sourceQuote: source, rawQuote: source,
            wasRepaired: false, analysisText: source, suggestedTitle: nil,
            organization: organized, confidence: 0, needsReview: true)], method: .rules)
    }
}

/// Contacting a person is a different edge from asking that person to contact
/// someone else. This bounded reading retains the complete literal relation
/// and applies only an explicit correction of the same verb and subject.
enum RuntimeCommunicationReading {
    struct Reading { let action: String; let recipient: String; var inheritsCurrentClock: Bool = false; var isConditionalCurrentAction:Bool = false }
    static func completeRecipient(_ text: String,delimiter: String) -> Bool {
        // The relation grammar must consume the complete recipient. A named
        // person has at most two literal name tokens here; coordination or a
        // second executive clause cannot become part of that human slot.
        // Named possessive owners need the actual retained contact delimiter
        // for the existing grammar's lookahead. Match exactly the NP span;
        // no contact lookup or inferred person identity occurs.
        let contextual = text + " " + delimiter
        if let regex = NSRegularExpression.speakItCached("(?i)^(?:" + PersonMentionResolver.communicationRelationPhrasePattern + ")"),
           let match = regex.firstMatch(in:contextual,range:NSRange(contextual.startIndex...,in:contextual)),
           let range = Range(match.range,in:contextual),String(contextual[range]) == text { return true }
        let named = #"^\p{L}[\p{L}\p{M}'’-]*(?:\s+(?!(?:and|or|but|then|if|that|which|because|unless|after|before|until|about|to)\b)\p{L}[\p{L}\p{M}'’-]*)?$"#
        return RuntimeRecipientReplacement.literalRecipient(text)
            && text.range(of:named,options:[.regularExpression,.caseInsensitive]) != nil
    }
    /// The condition and its unresolved factual context remain in the
    /// complete current action. Reading the addressed predicate supplies only
    /// its literal recipient, never permission to monitor the condition.
    private static func conditionalReading(_ source:String) -> Reading? {
        guard QuotedSpeechScope.ranges(in:source).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(source),
              source.range(of:#"(?i)\b(?:actually|instead|correction|cancel|withdraw|maybe|might|said|wrote)\b"#,options:.regularExpression) == nil else { return nil }
        let body = source.replacingOccurrences(of:#"(?i)^\s*(?:near\s+the\s+end|toward\s+the\s+end|at\s+the\s+very\s+end|in\s+the\s+middle(?:\s+of\s+this\s+capture)?),\s*"#,with:"",options:.regularExpression)
        let pattern = #"(?is)^\s*((?:after|before|if|unless|when|once|until)\s+[^,;.!?]{3,160}),\s*((?:ask|tell|call|phone|email|text|message)\s+[^;.!?]+)[.!]\s*(.*)$"#
        guard let regex = NSRegularExpression.speakItCached(pattern),let m = regex.firstMatch(in:body,range:NSRange(body.startIndex...,in:body)),
              let conditionRange = Range(m.range(at:1),in:body),let actionRange = Range(m.range(at:2),in:body),let tailRange = Range(m.range(at:3),in:body) else { return nil }
        let condition = String(body[conditionRange]),action = String(body[actionRange]),tail = String(body[tailRange]).trimmingCharacters(in:.whitespacesAndNewlines)
        guard condition.split(whereSeparator: { $0.isWhitespace }).count >= 3,
              condition.range(of:#"(?i)\b(?:and|or|but|then|also|remind|alert|notify)\b"#,options:.regularExpression) == nil,
              let addressed = read(action),
              tail.isEmpty || RuntimeIndependentFramePlan.coherentNarrative("Keep one memory. " + tail) != nil else { return nil }
        return .init(action:body,recipient:addressed.recipient,isConditionalCurrentAction:true)
    }
    static func read(_ source: String) -> Reading? {
        if let conditional = conditionalReading(source) { return conditional }
        let pattern = #"(?is)^\s*(?:please\s+)?(ask|tell|call|phone|email|text|message)\s+(.+?)\s+(about|to|for)\s+([^.!?]+)[.!?]?(.*)$"#
        guard let regex = NSRegularExpression.speakItCached(pattern),
              let match = regex.firstMatch(in: source, range: NSRange(source.startIndex..., in: source)),
              let verbRange = Range(match.range(at: 1), in: source),
              let personRange = Range(match.range(at: 2), in: source),
              let relationRange = Range(match.range(at: 3), in: source),
              let subjectRange = Range(match.range(at: 4), in: source),
              let tailRange = Range(match.range(at: 5), in: source) else { return nil }
        let verb = String(source[verbRange]), person = String(source[personRange])
        let relation = String(source[relationRange]), subject = String(source[subjectRange])
        let tail = String(source[tailRange]).trimmingCharacters(in: .whitespacesAndNewlines)
        guard completeRecipient(person,delimiter:relation), !person.contains(","), !person.contains(";"), !person.contains("\""),
              source.range(of: #"(?i)\b(?:if|unless|said|wrote|maybe|might|never\s+mind|cancel)\b"#,
                           options: .regularExpression) == nil else { return nil }
        if tail.isEmpty { return Reading(action: "\(verb) \(person) \(relation) \(subject)", recipient: person) }
        // An explicit replacement can inherit the current question's object
        // and clock. The repeated noun must identify that same object; neither
        // a source-present relative nor a generic "same thing" supplies it.
        let inherited = #"(?is)^actually\s+"# + NSRegularExpression.escapedPattern(for: verb)
            + #"\s+([^;.!?]+);\s*same\s+([^;.!?]+)\.?$"#
        if relation.lowercased() == "about", QuotedSpeechScope.ranges(in:source).isEmpty,
           let regex = NSRegularExpression.speakItCached(inherited),
           let m = regex.firstMatch(in:tail,range:NSRange(tail.startIndex...,in:tail)),
           let newRange = Range(m.range(at:1),in:tail),let repeatedRange = Range(m.range(at:2),in:tail) {
            let recipient = String(tail[newRange]).trimmingCharacters(in:.whitespacesAndNewlines)
            let repeated = RuntimeRecipientReplacement.normalize(String(tail[repeatedRange]))
            let object = RuntimeRecipientReplacement.normalize(subject.replacingOccurrences(
                of:#"(?i)\s+(?:today|tomorrow|tonight)\s*$"#,with:"",options:.regularExpression))
            guard RuntimeRecipientReplacement.literalRecipient(person),RuntimeRecipientReplacement.literalRecipient(recipient),
                  completeRecipient(recipient,delimiter:relation),
                  recipient.caseInsensitiveCompare(person) != .orderedSame,
                  subject.range(of:#"(?i)\b(?:and|or|but|then|also|if|unless|before|after|until|only|actually|instead|not|never|no|every|remind|alert|notify|it|that|thing|one)\b|[;,:\"“”]"#,options:.regularExpression) == nil,
                  repeated.range(of:#"^[\p{L}\p{M}'’ -]+$"#,options:.regularExpression) != nil,
                  !Set(["it","that","thing","one","question","subject"]).contains(repeated),
                  !repeated.isEmpty,object == repeated || object.hasSuffix(" " + repeated) else { return nil }
            return Reading(action:"\(verb) \(recipient) \(relation) \(subject)",recipient:recipient,inheritsCurrentClock:true)
        }
        let correction = #"(?is)^actually\s+"# + NSRegularExpression.escapedPattern(for: verb)
            + #"\s+([^,;.!?]+),\s*not\s+([^;.!?]+);\s*(.+?)\s+is\s+still\s+the\s+subject\.?$"#
        if let regex = NSRegularExpression.speakItCached(correction),
           let m = regex.firstMatch(in: tail, range: NSRange(tail.startIndex..., in: tail)),
           let recipientRange = Range(m.range(at: 1), in: tail),
           let rejectedRange = Range(m.range(at: 2), in: tail),
           let repeatedRange = Range(m.range(at: 3), in: tail) {
            let recipient = String(tail[recipientRange]).trimmingCharacters(in: .whitespacesAndNewlines)
            guard completeRecipient(recipient,delimiter:relation),
                  QuotedSpeechScope.voiceProjection(in:subject)?.ownVoiceText.range(of:
                    #"(?i)(?:,\s*(?:and\s+)?|\s+and\s+)(?:(?:then|also|next)\s+)?(?:"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b"#,
                    options:.regularExpression) == nil,
                  String(tail[rejectedRange]).caseInsensitiveCompare(person) == .orderedSame,
                  String(tail[repeatedRange]).caseInsensitiveCompare(subject) == .orderedSame else { return nil }
            return Reading(action: "\(verb) \(recipient) \(relation) \(subject)", recipient: recipient)
        }
        // An explicit perspective statement supports the first contact edge;
        // the nested action stays in the full source/title with its own actor.
        let perspective = #"(?is)^i\s+am\s+contacting\s+"# + NSRegularExpression.escapedPattern(for: person)
            + #",\s*not\s+[^.!?]+\.?$"#
        if tail.range(of: perspective, options: .regularExpression) != nil {
            return Reading(action: "\(verb) \(person) \(relation) \(subject)", recipient: person)
        }
        return nil
    }
}

/// A current recipient correction can retain an explicitly bound document
/// and approval condition. Every unit and restatement is checked; no saved
/// identity, contact endpoint or permission is inferred from this proof.
#if canImport(FoundationModels)
@available(iOS 26.4, *)
enum RuntimeApprovalRecipientReplacement {
    struct Command {
        let verb: String; let recipient: String; let object: String
        let approver: String; let condition: String
        var action: String { "\(verb) \(recipient) \(object) \(condition)" }
    }
    struct Reading {
        let original: Command; let recipient: String
        var action: String { "\(original.verb) \(recipient) \(original.object) \(original.condition)" }
        func accepts(_ meaning: String) -> Bool {
            guard let proposed = RuntimeApprovalRecipientReplacement.command(meaning) else { return false }
            return RuntimeApprovalRecipientReplacement.same(proposed.verb,original.verb)
                && RuntimeApprovalRecipientReplacement.same(proposed.recipient,recipient)
                && RuntimeApprovalRecipientReplacement.same(proposed.object,original.object)
                && RuntimeApprovalRecipientReplacement.same(proposed.approver,original.approver)
        }
    }
    private static func same(_ a: String,_ b: String) -> Bool {
        RuntimeRecipientReplacement.normalize(a) == RuntimeRecipientReplacement.normalize(b)
    }
    private static func fields(_ text: String,_ pattern: String) -> [String]? {
        let value = text.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!?")))
        guard let regex = NSRegularExpression.speakItCached("(?i)^(?:" + pattern + ")$"),
              let match = regex.firstMatch(in:value,range:NSRange(value.startIndex...,in:value)) else { return nil }
        return (1..<match.numberOfRanges).map { Range(match.range(at:$0),in:value).map { String(value[$0]) } ?? "" }
    }
    private static func command(_ text: String) -> Command? {
        guard QuotedSpeechScope.ranges(in:text).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(text),
              let f = fields(text,#"(?:and\s+)?(email|text|message)\s+(.+?)\s+(the\s+[\p{L}\p{M}'’ -]+?)\s+((?:once|after)\s+(.+?)\s+(?:has\s+approved\s+it|approves(?:\s+it)?))"#),
              RuntimeCommunicationReading.completeRecipient(f[1],delimiter:"about"),
              RuntimeCommunicationReading.completeRecipient(f[4],delimiter:"about") else { return nil }
        let objectWords = RuntimeExampleLibrary.words(f[2])
        guard (2...12).contains(f[2].split(whereSeparator: { $0.isWhitespace }).count),
              objectWords.isDisjoint(with:RuntimeExampleLibrary.words("I we you he she they is are was were has have had will must should can could and or but then also if unless before after once until not never no remind alert notify")),
              documentObject(f[2]) else { return nil }
        return .init(verb:f[0],recipient:f[1],object:f[2],approver:f[4],condition:f[3])
    }
    private static func documentObject(_ text: String) -> Bool {
        // Complete positive nominal evidence, with a bounded document fallback
        // when optional lexical assets are unavailable. All literal values
        // still come from this capture, never a worked example.
        if RuntimeCurrentNominalProof.read(text) { return true }
        let heads: Set<String> = ["rota","sheet","report","form","document","file","letter","note","schedule","list","draft"]
        let modifiers: Set<String> = ["final","draft","spare","updated","revised","original","volunteer","inventory","staff","committee","event","budget","attendance","contact","project","monthly","annual"]
        let words = RuntimeRecipientReplacement.normalize(text).split(separator:" ").map(String.init)
        guard (1...5).contains(words.count),let head = words.last,heads.contains(head) else { return false }
        return words.dropLast().allSatisfy { modifiers.contains($0) || heads.contains($0) }
    }
    static func read(_ source: String,wholeSource: String) -> Reading? {
        guard QuotedSpeechScope.ranges(in:source).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(source) else { return nil }
        let units = RuntimeIndexedSource(source).units.map(\.text)
        guard units.count >= 3,let root = units.first.flatMap(command) else { return nil }
        let allUnits = RuntimeIndexedSource(wholeSource).units.map(\.text)
        var recipient: String?,corrections = 0,restatements = 0
        for unit in units.dropFirst() {
            if let f = fields(unit,#"(?:no,?\s+)?actually,?\s+the\s+person\s+(?:collecting|receiving)\s+the\s+([\p{L}\p{M}'’ -]+?)\s+is\s+(.+?),\s+not\s+(.+)"#) {
                guard corrections == 0,restatements == 0,same(f[2],root.recipient),!same(f[1],root.recipient),
                      RuntimeCommunicationReading.completeRecipient(f[1],delimiter:"about") else { return nil }
                let alias = RuntimeRecipientReplacement.normalize(f[0])
                func identifies(_ object: String) -> Bool {
                    let words = RuntimeRecipientReplacement.normalize(object).split(separator:" ").map(String.init)
                    let aliasWords = alias.split(separator:" ").map(String.init)
                    return aliasWords == words || (aliasWords.count == 1 && words.last == aliasWords.first)
                }
                // Count potential CURRENT antecedents before applying the
                // supported approval grammar. A second same-recipient command
                // with another condition cannot disappear from alias uniqueness.
                let recipientPattern = NSRegularExpression.escapedPattern(for:RuntimeRecipientReplacement.normalize(root.recipient))
                let aliasPattern = NSRegularExpression.escapedPattern(for:alias)
                let possibleRoot = #"(?i)^\s*(?:and\s+)?(?:email|text|message|send)\s+"# + recipientPattern + #"\s+.+\b"# + aliasPattern + #"\b"#
                let antecedents = allUnits.filter { unit in
                    let own = QuotedSpeechScope.voiceProjection(in:unit)?.ownVoiceText ?? unit
                    return RuntimeRecipientReplacement.normalize(own).range(of:possibleRoot,options:.regularExpression) != nil
                }
                guard identifies(root.object),antecedents.count == 1 else { return nil }
                recipient = f[1];corrections += 1
            } else if let f = fields(unit,#"(email|text|message)\s+(.+?)\s+(?:after|once)\s+(.+?)\s+(?:approves(?:\s+it)?|has\s+approved\s+it)"#) {
                guard corrections == 1,restatements == 0,let recipient,
                      same(f[0],root.verb),same(f[1],recipient),same(f[2],root.approver) else { return nil }
                restatements += 1
            } else {
                guard !RuntimeAccountOwnership.hasCurrentActForReference(unit) else { return nil }
                let unresolvedApproval = fields(unit,#"(she|he|they)\s+(?:has|have)\s+looked\s+at\s+it,\s+but\s+\1\s+(?:has|have)\s+not\s+said\s+it\s+is\s+approved"#) != nil
                let declinedChange = fields(unit,#"(?:I|we)\s+(?:am|are)\s+not\s+changing\s+any\s+of\s+(?:the|my|our)\s+[\p{L}\p{M}'’ -]+\s+(?:myself|ourselves)\s+in\s+this\s+recording"#) != nil
                guard unresolvedApproval || declinedChange
                    || RuntimeDiscourseCertificate.approvalContext(unit,verb:root.verb,recipient:root.recipient,object:root.object) else { return nil }
            }
        }
        guard corrections == 1,restatements == 1,let recipient else { return nil }
        return .init(original:root,recipient:recipient)
    }
}

#endif

/// Complete current nominal evidence. Installed lexical tags may prove every
/// word; without those assets a closed physical noun/modifier grammar is used.
/// Unknown tails, punctuation, conjunctions, conditions and extra predicates
/// retain the recoverable path. No literal source slots come from this grammar.
enum RuntimeCurrentNominalProof {
    private static let heads:Set<String> = ["sealant","mat","mats","vent","vents","canopy","canopies","counterweight","counterweights","rib","ribs","flange","flanges","disk","disks","disc","discs","cap","caps","beam","beams","pulley","pulleys","width","height","depth","length","weight","dimension","dimensions","balance","mask","roof","pivot","heat","cork","resin","drain","drains","hinge","hinges","handle","handles","rail","rails","wheel","wheels","axle","axles","shaft","shafts","gasket","gaskets","seal","seals","terrarium","aquarium","greenhouse","garden","fence","window","door","wall","floor","ceiling","rafter","post"]
    private static let modifiers:Set<String> = ["acrylic","existing","balance","mask","roof","pivot","heat","cork","resin","silver","gold","copper","aluminium","aluminum","iron","stone","timber","foam","canvas","linen","thermal","drainage","upper","lower","front","rear","left","right","central","outer","inner","ceramic","bronze","steel","brass","wooden","paper","glass","rubber","plastic","small","large","round","square","flat","thin","thick","spare","portable","red","blue","green"]
    static func read(_ text:String) -> Bool {
        guard text.count <= 120,text.range(of:#"^[\p{L}\p{M} -]+$"#,options:.regularExpression) != nil,!text.contains("--") else { return false }
        var words = text.lowercased().split(whereSeparator: { $0.isWhitespace }).map(String.init)
        if ["the","a","an"].contains(words.first ?? "") { words.removeFirst() }
        guard (1...5).contains(words.count),let head = words.last else { return false }
        // Reuse the existing positive nominal grammar without expanding its
        // scope for other readers. This proof has no omitted residual tokens.
        if RuntimeIndependentFramePlan.nominal(text) { return true }
        if heads.contains(head),words.dropLast().allSatisfy({ heads.contains($0) || modifiers.contains($0) }) { return true }
        if RuntimeIndependentFramePlan.nominal(head),words.dropLast().allSatisfy({ modifiers.contains($0) }) { return true }
        let tokens = SentenceContextCache.context(for:text).tokens
        guard (1...6).contains(tokens.count),tokens.last?.lexicalClass == .noun else { return false }
        return tokens.allSatisfy { token in
            token.lexicalClass == .noun || token.lexicalClass == .adjective
                || (token.lexicalClass == .determiner && ["a","an","the"].contains(token.text.lowercased()))
        }
    }
}

/// An explicit whole-plan replacement owns every retained slot and its new
/// clock. Both complete old/new commands and final adoption must be present.
/// This source proof cannot resolve a saved item, inherit an omitted object,
/// or import a reference fact.
enum RuntimeWholePlanReplacement {
    struct Reading { let action:String; let recipient:String; let clock:String }
    /// Positive noun-phrase evidence is required for every topic token. An
    /// unknown lexical tag grants no permission to hide a second imperative.
    private static func nominalTopic(_ text:String) -> Bool {
        RuntimeCurrentNominalProof.read(text)
    }

    static func read(_ source:String) -> Reading? {
        guard QuotedSpeechScope.ranges(in:source).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(source) else { return nil }
        let pattern = #"(?:make|create|add)\s+(?:a|one)\s+task\s+to\s+([^.!?;]+)[.!]\s*No,\s*replace\s+that\s+whole\s+plan:\s*([^.!?;]+)\s+instead[.!]\s*Keep\s+only\s+that\s+final\s+task;\s*no\s+timed\s+alert[.!]?\s*$"#
        guard let (range,f) = RuntimeRecipientReplacement.match(source,from:source.startIndex,pattern:pattern),range.upperBound == source.endIndex,f.count == 2 else { return nil }
        let months = #"(?:January|February|March|April|May|June|July|August|September|October|November|December)"#
        let shape = #"((?:ask|call|phone|email|text|message)\s+(.+?)\s+(?:about|for)\s+([\p{L}\p{M}'’ -]+?)\s+(?:on\s+)?((?:"# + months + #"\s+[0-9]{1,2}(?:\s+[0-9]{4})?)|today|tomorrow|tonight))"#
        func command(_ text:String) -> (String,String,String)? {
            guard let (r,fields) = RuntimeRecipientReplacement.match(text,from:text.startIndex,pattern:shape),r.upperBound == text.endIndex,fields.count == 4,
                  RuntimeRecipientReplacement.literalRecipient(fields[1]),nominalTopic(fields[2]),
                  fields[2].range(of:#"(?i)\b(?:and|or|plus|but|then|also|if|unless|before|after|until|only|actually|instead|not|never|no|every|remind|alert|notify)\b|--"#,options:.regularExpression) == nil,
                  let contact = RuntimeCommunicationReading.read(fields[0]),contact.recipient == fields[1] else { return nil }
            return (fields[0],contact.recipient,fields[3])
        }
        guard command(f[0]) != nil,let adopted = command(f[1]) else { return nil }
        return .init(action:adopted.0 + ", no timed alert",recipient:adopted.1,clock:adopted.2)
    }
    static func interpret(_ source:String,referenceDate:Date,calendar:Calendar) -> ThoughtExtractionResult? {
        guard let current = read(source),let (date,intent) = RuntimeIndependentFramePlan.clock(current.clock,referenceDate:referenceDate,calendar:calendar,source:source),
              intent.kind == .dateOnly,intent.time == nil else { return nil }
        let reading = ThoughtOrganizer.organize(current.action,referenceDate:referenceDate,calendar:calendar)
        var checkedIntent = reading.temporalIntent
        checkedIntent.sourceText = intent.sourceText // Compare all timing meaning; source phrasing may differ.
        guard reading.dueDate == date,checkedIntent == intent,!reading.needsClarification,
              reading.reminderDate == nil,reading.locationIntent == nil,reading.recurrenceRule == nil else { return nil }
        let organization = OrganizedThought(itemType:.task,category:reading.category,priority:reading.priority,personName:current.recipient,
            dueDate:date,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,needsClarification:false,temporalIntent:intent,state:.resolved)
        return .init(items:[.init(sourceQuote:source,rawQuote:source,wasRepaired:false,analysisText:source,
            suggestedTitle:current.action,organization:organization,confidence:1,needsReview:false)],method:.rules)
    }
}

/// A closed current request for N distinct tasks is routing, not another
/// intention. The anchors must still partition every current predicate/object.
enum RuntimeDeclaredTaskPartition {
    static func predicate(_ anchor:String) -> Bool {
        // The entire current predicate and object must be proved. A known
        // verb followed by unknown suffix tokens is not a complete action.
        let verbs = "(?:" + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + "|trace)"
        guard let (range,fields) = RuntimeRecipientReplacement.match(anchor,from:anchor.startIndex,
            pattern:"(" + verbs + #")\s+(.+)"#),range.upperBound == anchor.endIndex,fields.count == 2 else { return false }
        return RuntimeCurrentNominalProof.read(fields[1])
    }
    static func prefix(_ text:String,count:Int) -> Bool {
        let lead = #"(?:(?:around\s+the\s+middle|in\s+the\s+middle(?:\s+of\s+this\s+capture)?|near\s+the\s+end|toward\s+the\s+end|at\s+the\s+very\s+end),\s*)?"#
        let pattern = lead + #"(?:give\s+me|make|create|add)\s+("# + RuntimeAllocationReading.quantityPattern + #")\s+distinct\s+(?:tasks|jobs),?\s*to\s*$"#
        guard let (range,f) = RuntimeRecipientReplacement.match(text,from:text.startIndex,pattern:pattern),range.upperBound == text.endIndex,f.count == 1 else { return false }
        return count > 1 && RuntimeAllocationReading.number(f[0]) == count
    }
}

/// Complete source proof for replacing separate proposed calls with one
/// explicitly adopted joint call. It owns no address-book identity and cannot
/// accept a quoted plan, missing participant, changed topic or uncertain choice.
enum RuntimeJointCallReading {
    struct Reading { let action: String; let clock: String; let month: Int; let day: Int; let topic:String }
    static func read(_ source: String) -> Reading? {
        guard QuotedSpeechScope.ranges(in:source).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(source) else { return nil }
        let months = #"(?:January|February|March|April|May|June|July|August|September|October|November|December)"#
        let pattern = #"I\s+thought\s+of\s+separate\s+calls\s+to\s+(.+?)\s+and\s+(.+?)\s+about\s+([^.!?;]+)[.!]\s*Actually\s+make\s+it\s+one\s+call\s+with\s+both\s+of\s+them\s+together\s+on\s+("# + months
            + #"\s+([0-9]{1,2}))[.!]\s*That\s+joint\s+call\s+is\s+the\s+final\s+choice,\s*no\s+timed\s+alert[.!]?\s*$"#
        guard let (range,f) = RuntimeRecipientReplacement.match(source,from:source.startIndex,pattern:pattern),range.upperBound == source.endIndex,
              f.count == 5,let day = Int(f[4]),(1...31).contains(day),
              RuntimeRecipientReplacement.literalRecipient(f[0]),RuntimeRecipientReplacement.literalRecipient(f[1]),
              let a = RuntimeCommunicationReading.read("Call " + f[0] + " about " + f[2]),a.recipient == f[0],
              let b = RuntimeCommunicationReading.read("Call " + f[1] + " about " + f[2]),b.recipient == f[1],
              RuntimeRecipientReplacement.normalize(f[0]) != RuntimeRecipientReplacement.normalize(f[1]),
              f[2].range(of:#"^[\p{L}\p{M}'’ -]+$"#,options:.regularExpression) != nil,!f[2].contains("--"),
              f[2].range(of:#"(?i)\b(?:and|or|but|then|also|if|unless|before|after|until|only|actually|instead|not|never|no|every|remind|alert|notify|today|tomorrow|tonight)\b|[,;:\"“”]"#,options:.regularExpression) == nil else { return nil }
        let monthNames = ["january","february","march","april","may","june","july","august","september","october","november","december"]
        guard let month = f[3].split(separator:" ").first.flatMap({ monthNames.firstIndex(of:$0.lowercased()) }) else { return nil }
        return .init(action:"One joint call with \(f[0]) and \(f[1]) about \(f[2]) on \(f[3]), no timed alert",clock:f[3],month:month+1,day:day,topic:f[2])
    }
}

/// A typed allocation graph is checked against current-source owners, objects,
/// package units and quantities. Covering source IDs alone cannot prove that a
/// later quantity correction was applied to the right owner.
enum RuntimeAllocationReading {
    struct Entry: Equatable {
        var quantity: Int
        let unit: String
        let object: String
        let owner: String
    }
    static let quantityPattern = #"(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)"#
    static func number(_ text: String) -> Int? {
        Int(text) ?? ["one":1,"two":2,"three":3,"four":4,"five":5,"six":6,"seven":7,"eight":8,"nine":9,"ten":10,"eleven":11,"twelve":12][text.lowercased()]
    }
    static func normalized(_ text: String) -> String {
        text.lowercased().replacingOccurrences(of: "’", with: "'")
            .trimmingCharacters(in: CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn: ",.!")))
    }
    static func entries(_ text: String) -> [Entry]? {
        guard text.range(of: #"(?i)\b(?:actually|instead|allocation|keep|make)\b"#, options: .regularExpression) == nil else { return nil }
        let split = #"(?i),?\s+(?:and|also)\s+(?=(?:(?:buy|get|add)\s+)?"# + quantityPattern + #"\b)"#
        let separated = text.replacingOccurrences(of: split, with: "\n", options: .regularExpression).components(separatedBy: "\n")
        var result: [Entry] = []
        let pattern = #"(?i)^\s*(?:(?:buy|get|add)\s+)?("# + quantityPattern + #")\s+(\p{L}+)(?:\s+(?:of\s+)?(.+?))?\s+for\s+(.+?)\s*[.!]?\s*$"#
        guard let regex = NSRegularExpression.speakItCached(pattern) else { return nil }
        for segment in separated {
            guard let m = regex.firstMatch(in: segment, range: NSRange(segment.startIndex..., in: segment)),
                  let q = Range(m.range(at: 1), in: segment), let unitRange = Range(m.range(at: 2), in: segment),
                  let ownerRange = Range(m.range(at: 4), in: segment), let quantity = number(String(segment[q])), quantity > 0 else { return nil }
            let unit = normalized(String(segment[unitRange])), owner = normalized(String(segment[ownerRange]))
            guard !owner.contains(";"), !owner.contains(","), !owner.contains("."),
                  ["me", "myself", "us", "ourselves", "you", "yourself"].contains(owner)
                    || RuntimeCommunicationReading.read("Ask " + owner + " about the allocation")?.recipient == owner,
                  owner.range(of: #"(?i)\b(?:if|unless|tomorrow|today|after|before|actually|not)\b"#, options: .regularExpression) == nil else { return nil }
            let object: String
            if let objectRange = Range(m.range(at: 3), in: segment) { object = normalized(String(segment[objectRange])) }
            else if let prior = result.last, prior.unit == unit { object = prior.object }
            else { return nil }
            guard !object.isEmpty else { return nil }
            result.append(Entry(quantity: quantity, unit: unit, object: object, owner: owner))
        }
        return result.isEmpty ? nil : result
    }
    static func expected(_ source: String) -> [Entry]? {
        guard source.range(of: #"(?i)^\s*buy\s+"#, options: .regularExpression) != nil else { return nil }
        // A spoken replacement names the CURRENT allocation again; the added
        // allocation inherits only that current product/unit. No example fact
        // or overlapping beneficiary name can provide this binding.
        if let correction = source.range(of:#"(?i)\s+no\s+make\s+"#,options:.regularExpression) {
            guard var initial = entries(String(source[..<correction.lowerBound])),initial.count == 1 else { return nil }
            let original = initial[0]
            let tail = String(source[correction.upperBound...])
            let pattern = "(?i)^" + NSRegularExpression.escapedPattern(for:original.owner)
                + #"\s+("# + quantityPattern + #")\s+"# + NSRegularExpression.escapedPattern(for:original.unit)
                + #"\s+and\s+add\s+("# + quantityPattern + #")\s+"# + NSRegularExpression.escapedPattern(for:original.unit)
                + #"\s+for\s+(.+?)(?:\s+those\s+allocations\s+stay\s+separate)?\s*[.!]?\s*$"#
            guard let regex = NSRegularExpression.speakItCached(pattern),
                  let match = regex.firstMatch(in:tail,range:NSRange(tail.startIndex...,in:tail)),
                  let changedRange = Range(match.range(at:1),in:tail),let addedRange = Range(match.range(at:2),in:tail),
                  let ownerRange = Range(match.range(at:3),in:tail),let changed = number(String(tail[changedRange])),changed > 0,
                  let added = number(String(tail[addedRange])),added > 0,
                  let additional = entries("Buy " + String(tail[addedRange]) + " " + original.unit + " of " + original.object + " for " + String(tail[ownerRange])),
                  additional.count == 1 else { return nil }
            initial[0].quantity = changed
            return initial + additional
        }
        guard let correction = source.range(of: #"(?i)\.\s*actually\s+make\s+"#, options: .regularExpression) else {
            return entries(source)
        }
        guard var initial = entries(String(source[..<correction.lowerBound])), initial.count == 2 else { return nil }
        let tail = String(source[correction.upperBound...]).replacingOccurrences(of: "’", with: "'")
        let pattern = #"(?i)^"# + NSRegularExpression.escapedPattern(for: initial[0].owner)
            + #"'s\s+allocation\s+("# + quantityPattern + #")\s+"# + NSRegularExpression.escapedPattern(for: initial[0].unit)
            + #",\s*keep\s+"# + NSRegularExpression.escapedPattern(for: initial[1].owner)
            + #"'s\s+("# + quantityPattern + #"),\s*and\s+add\s+(.+?)\s*[.!]?\s*$"#
        guard let regex = NSRegularExpression.speakItCached(pattern),
              let m = regex.firstMatch(in: tail, range: NSRange(tail.startIndex..., in: tail)),
              let changedRange = Range(m.range(at: 1), in: tail), let keptRange = Range(m.range(at: 2), in: tail),
              let addedRange = Range(m.range(at: 3), in: tail), let changed = number(String(tail[changedRange])), changed > 0,
              number(String(tail[keptRange])) == initial[1].quantity,
              let added = entries("Buy " + String(tail[addedRange])), added.count == 1 else { return nil }
        initial[0].quantity = changed
        return initial + added
    }
}

/// Compiles a demonstrated correction into a source-slot transformation. The
/// reference's values are used to prove its before/after relation, then discarded.
/// Applying the program reads every object, recipient and quantity from CURRENT.
enum RuntimeQuantityAnalogy {
    struct Entry: Equatable {
        var quantity: Int?
        var quantityWords: String
        let unit: String
        let object: String
        let recipient: String
        var literal: String
        var contents: [String] = []
        var key: String { [normalize(unit), identity(object), identity(recipient)].joined(separator: "|") }
    }
    struct Correction {
        let target: Int
        let old: Int
        let new: Int
        let words: String
    }
    struct Graph {
        let initial: [Entry]
        let entries: [Entry]
        let corrections: [Correction]
    }
    struct Program {
        let referenceID: String
        let runtimePayloadSHA256: String
        let inputSHA256: String
        let solutionSHA256: String
        // A complete demonstrated before/after relation, not a copied RHS.
        let operation = "replace quantity at same allocation; preserve others"
    }
    static let quantity = RuntimeAllocationReading.quantityPattern
    static let units: Set<String> = ["pack","packs","carton","cartons","box","boxes","spool","spools","bottle","bottles","packet","packets","tin","tins","metre","metres","meter","meters","bag","bags","roll","rolls","set","sets"]
    static func identity(_ text: String) -> String {
        let value = RuntimeAllocationReading.normalized(text)
        return value == "me" || value == "myself" ? "user" : value
    }
    // Morphology is only for audited reference object/unit alignment. Current
    // recipient and correction-target identity never uses singularization.
    static func normalize(_ text: String) -> String {
        let clean = RuntimeAllocationReading.normalized(text)
        return clean.split(separator: " ").map { token -> String in
            let word = String(token)
            if word == "me" || word == "myself" { return "user" }
            if word == "boxes" { return "box" }
            if word.hasSuffix("s"), !word.hasSuffix("ss"), word.count > 3 { return String(word.dropLast()) }
            return word
        }.joined(separator: " ")
    }
    private static func captures(_ pattern: String, in text: String) -> [String]? {
        guard let match = NSRegularExpression.speakItCached(pattern)?.firstMatch(in: text,range: NSRange(text.startIndex...,in:text)) else { return nil }
        return (1..<match.numberOfRanges).map { index in
            Range(match.range(at:index),in:text).map { String(text[$0]) } ?? ""
        }
    }
    static func initialEntries(_ input: String) -> [Entry]? {
        var text = input.trimmingCharacters(in: .whitespacesAndNewlines)
        text = text.replacingOccurrences(of: #"(?i)^for\s+the\s+shopping,\s*"#,with:"",options:.regularExpression)
        guard let command = text.range(of: #"(?i)^(?:buy|get|purchase|put|add)\s+"#,options:.regularExpression) else { return nil }
        let verb = String(text[command]).trimmingCharacters(in:.whitespacesAndNewlines).lowercased()
        if verb == "put", text.range(of:#"(?i)\s+on\s+my\s+shopping\s+list[.!]?$"#,options:.regularExpression) == nil { return nil }
        if verb == "get", text.range(of:#"(?i)\b(?:from|in|into|out|off|back|away)\b"#,options:.regularExpression) != nil { return nil }
        text = String(text[command.upperBound...]).replacingOccurrences(of: #"(?i)\s+on\s+my\s+shopping\s+list[.!]?$"#,with:"",options:.regularExpression)
        let separated = text.replacingOccurrences(of: #"(?i),\s*(?:and\s+)?|\s+and\s+(?=(?:another\s+)?"# + quantity + #"\b)|\s+plus\s+"#,with:"\n",options:.regularExpression).components(separatedBy:"\n")
        var entries: [Entry] = []
        for raw in separated {
            let segment = raw.trimmingCharacters(in:.whitespacesAndNewlines).replacingOccurrences(of:#"(?i)^another\s+"#,with:"",options:.regularExpression)
            let ownerParts = segment.components(separatedBy:" for ")
            guard ownerParts.count <= 2 else { return nil }
            let recipient = ownerParts.count == 2 ? ownerParts[1].trimmingCharacters(in: CharacterSet.whitespacesAndNewlines.union(.punctuationCharacters)) : ""
            guard ownerParts.count == 1 || !recipient.isEmpty else { return nil }
            var objectPart = ownerParts[0].trimmingCharacters(in: CharacterSet.whitespacesAndNewlines.union(.punctuationCharacters))
            var count: Int?, countWords = "", unit = ""
            if let numberRange = objectPart.range(of: #"(?i)^"# + quantity + #"\b"#, options:.regularExpression) {
                countWords = String(objectPart[numberRange]); count = RuntimeAllocationReading.number(countWords)
                objectPart = String(objectPart[numberRange.upperBound...]).trimmingCharacters(in:.whitespaces)
                if let first = objectPart.split(separator:" ").first, units.contains(String(first).lowercased()) {
                    unit = String(first); objectPart = String(objectPart.dropFirst(first.count)).trimmingCharacters(in:.whitespaces)
                    objectPart = objectPart.replacingOccurrences(of:#"(?i)^of\s+"#,with:"",options:.regularExpression)
                }
            }
            guard let count, count > 0 else { return nil }
            if objectPart.isEmpty {
                guard !recipient.isEmpty, let prior = entries.last,
                      Set(entries.map { identity($0.object) }).count == 1 else { return nil }
                objectPart = prior.object; if unit.isEmpty { unit = prior.unit }
            }
            objectPart = objectPart.replacingOccurrences(of:#"(?i)^the\s+same\s+"#,with:"",options:.regularExpression)
            // A comma may introduce another speech act rather than another
            // commodity. This bounded program never purchases that predicate.
            guard objectPart.range(of:#"(?i)^(?:call|phone|ask|tell|email|text|message|send|pack|clean|check|finish|return|fix|repair|book|pay|wash|count|inspect|remind|add)\s+"#,options:.regularExpression) == nil else { return nil }
            guard !objectPart.isEmpty, objectPart.range(of:#"(?i)\b(?:if|unless|actually|instead|each|not|tomorrow|today|after|before|and|or|but|is|are|was|were|has|have|contains|said|wrote|asked|offered|that|which|who|possibly|perhaps)\b|[;.!?]"#,options:.regularExpression) == nil,
                  recipient.range(of:#"(?i)\b(?:if|unless|actually|instead|not|tomorrow|today|after|before|and|or|but|call|phone|ask|tell|email|text|message|send|possibly|perhaps)\b|[,;.!?]"#,options:.regularExpression) == nil else { return nil }
            let prefix = ([countWords,unit].filter { !$0.isEmpty }.joined(separator:" "))
            let literal = (prefix.isEmpty ? "" : prefix + " ") + (unit.isEmpty ? "" : "of ") + objectPart + (recipient.isEmpty ? "" : " for " + recipient)
            let entry = Entry(quantity:count,quantityWords:countWords,unit:unit,object:objectPart,recipient:recipient,literal:literal)
            guard !entries.contains(where: { $0.key == entry.key }) else { return nil }
            entries.append(entry)
        }
        return entries.isEmpty ? nil : entries
    }
    static func graph(_ source: String) -> Graph? {
        let purchase = source.range(of: #"(?i)^\s*(?:buy|purchase)\b|^\s*for\s+the\s+shopping,|^\s*put\b[^.!?]+\bon\s+my\s+shopping\s+list\b"#,options:.regularExpression) != nil
        guard purchase else { return nil }
        var eligibilityCalendar = Calendar(identifier: .gregorian)
        eligibilityCalendar.timeZone = TimeZone(secondsFromGMT: 0)!
        // This clock only asks whether a temporal/location scope exists. No
        // date from this eligibility reading can enter the current result.
        let scoped = ThoughtOrganizer.organize(source,referenceDate:Date(timeIntervalSince1970:946684800),calendar:eligibilityCalendar)
        guard scoped.temporalIntent.kind == .none, scoped.dueDate == nil, scoped.reminderDate == nil,
              scoped.recurrenceRule == nil, scoped.locationIntent == nil,
              source.range(of:#"(?i)\b(?:once|provided|only|when|until|upon|permission|approval|unless|if|after|before|without)\b"#,options:.regularExpression) == nil else { return nil }
        guard source.range(of:#"(?i)\b(?:said|wrote|saved|unless|if|tomorrow|today|remind|alert|alarm|every|after|before|maybe|might)\b|[\"“”]"#,options:.regularExpression) == nil else { return nil }
        let parts = source.replacingOccurrences(of:#"[.!]\s+"#,with:"\n",options:.regularExpression).components(separatedBy:"\n").map { $0.trimmingCharacters(in:CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!"))) }.filter { !$0.isEmpty }
        guard let first = parts.first, var entries = initialEntries(first) else { return nil }
        let initial = entries
        var corrections: [Correction] = []
        for part in parts.dropFirst() {
            if part.range(of:#"(?i)^actually\s+"#,options:.regularExpression) != nil {
                let pieces = part.components(separatedBy:";")
                let statement = pieces[0].replacingOccurrences(of:"’",with:"'")
                let object = captures(#"(?i)^actually\s+make\s+(?:the\s+)?(.+?)\s+("# + quantity + #")(?:\s+(\p{L}+))?,\s*not\s+("# + quantity + #")$"#,in:statement)
                let owner = captures(#"(?i)^actually\s+(.+?)\s+needs\s+("# + quantity + #")(?:\s+(\p{L}+))?,\s*not\s+("# + quantity + #")$"#,in:statement)
                guard let values = object ?? owner, let new = RuntimeAllocationReading.number(values[1]), let old = RuntimeAllocationReading.number(values[3]), new > 0,new != old else { return nil }
                let allocation = object != nil && values[0].range(of:#"(?i)'s\s+allocation$"#,options:.regularExpression) != nil
                let target = identity(values[0].replacingOccurrences(of:#"(?i)'s\s+allocation$"#,with:"",options:.regularExpression))
                let targets = entries.indices.filter { index in
                    if owner != nil || allocation {
                        return !entries[index].recipient.isEmpty && identity(entries[index].recipient) == target
                    }
                    return identity(entries[index].object) == target
                }
                guard targets.count == 1, let index = targets.first, entries[index].quantity == old,
                      values[2].isEmpty || normalize(values[2]) == normalize(entries[index].unit) else { return nil }
                for tail in pieces.dropFirst() {
                    let text = tail.trimmingCharacters(in:.whitespacesAndNewlines).replacingOccurrences(of:"’",with:"'")
                    if let keep = captures(#"(?i)^(?:keep\s+)?(.+?)'s\s+("# + quantity + #")\s*(?:stay|unchanged)?$"#,in:text) {
                        let untouched = entries.indices.filter { identity(entries[$0].recipient) == identity(keep[0]) }
                        guard untouched.count == 1, untouched[0] != index, entries[untouched[0]].quantity == RuntimeAllocationReading.number(keep[1]) else { return nil }
                    } else if let keep = captures(#"(?i)^(?:the\s+)?(.+?)\s+is\s+still\s+needed$"#,in:text) {
                        guard entries.indices.filter({ identity(entries[$0].object) == identity(keep[0]) && $0 != index }).count == 1 else { return nil }
                    } else { return nil }
                }
                corrections.append(.init(target:index,old:old,new:new,words:values[1]))
                let oldWords = entries[index].quantityWords
                guard entries[index].literal.hasPrefix(oldWords + " ") else { return nil }
                entries[index].literal = values[1] + entries[index].literal.dropFirst(oldWords.count)
                entries[index].quantity = new; entries[index].quantityWords = values[1]
            } else if let content = captures(#"(?i)^each\s+(\p{L}+)\s+(?:has|contains)\s+("# + quantity + #")\s+(.+)$"#,in:part) {
                let matched = entries.indices.filter { normalize(entries[$0].unit) == normalize(content[0]) && identity(entries[$0].object).range(of:#"(?<!\p{L})"# + NSRegularExpression.escapedPattern(for:identity(content[2])) + #"(?!\p{L})"#,options:.regularExpression) != nil }
                guard !matched.isEmpty, matched.allSatisfy({ entries[$0].contents.isEmpty }) else { return nil }
                for index in matched { entries[index].contents.append(part) }
            } else if part.range(of:#"(?i)^add\s+"#,options:.regularExpression) != nil, let added = initialEntries(part) {
                guard added.allSatisfy({ value in !entries.contains(where: { $0.key == value.key }) }) else { return nil }
                var appended = added
                for index in appended.indices {
                    let possible = entries.filter { !$0.contents.isEmpty && normalize($0.unit) == normalize(appended[index].unit) }
                    guard possible.allSatisfy({ identity($0.object) == identity(appended[index].object) }) else { return nil }
                    let declarations = Set(possible.flatMap(\.contents))
                    guard declarations.count <= 1 else { return nil }
                    appended[index].contents = declarations.sorted()
                }
                entries += appended
            } else if part.range(of:#"(?i)^(?:the\s+)?quantities\s+are\s+separate\s+allocations,\s*not\s+shared\s+totals$|^keep\s+the\s+(?:two\s+)?allocations\s+separate$"#,options:.regularExpression) == nil {
                return nil
            }
        }
        return .init(initial:initial,entries:entries,corrections:corrections)
    }
    private static func exactEvidence(_ value: [String:Any], source: String) -> String? {
        guard let start = value["start"] as? Int, let end = value["end"] as? Int,
              let text = value["text"] as? String, start >= 0, end >= start,
              end <= source.unicodeScalars.count else { return nil }
        let scalars = source.unicodeScalars
        let lower = scalars.index(scalars.startIndex,offsetBy:start), upper = scalars.index(scalars.startIndex,offsetBy:end)
        guard scalars[lower..<upper].elementsEqual(text.unicodeScalars), let first = source.range(of:text),
              source.range(of:text,range:first.upperBound..<source.endIndex) == nil else { return nil }
        return text
    }
    static func compile(_ example: RuntimeWorkedExample) -> Program? {
        guard example.approval.production_eligible,
              let record = try? JSONSerialization.jsonObject(with:Data(example.payload.utf8)) as? [String:Any],
              let solution = record["solution"] as? [String:Any],
              let groups = solution["groups"] as? [[String:Any]],
              let inputSHA = record["input_sha256"] as? String, inputSHA.count == 64,
              let solutionSHA = record["solution_sha256"] as? String, solutionSHA.count == 64 else { return nil }
        for group in groups where group["purpose"] as? String == "shopping" && group["destination"] as? String == "Today" {
            guard Set(group.keys).isSubset(of:["destination","entries","evidence","local_id","purpose"]),
                  let evidence = group["evidence"] as? [[String:Any]], evidence.count == 1,
                  let text = exactEvidence(evidence[0],source:example.input.utterance),
                  let graph = graph(text), graph.corrections.count == 1,
                  let answer = group["entries"] as? [[String:Any]], answer.count == graph.entries.count else { continue }
            let matches = graph.entries.indices.allSatisfy { index in
                let row = answer[index], current = graph.entries[index]
                guard Set(row.keys).isSubset(of:["text","quantity","unit","recipient","for_person"]) else { return false }
                let recipient = row["recipient"] as? String ?? row["for_person"] as? String ?? ""
                return normalize(row["text"] as? String ?? "") == normalize(current.object)
                    && identity(recipient) == identity(current.recipient)
                    && (row["quantity"] as? Int) == current.quantity
                    && (row["unit"] == nil || normalize(row["unit"] as? String ?? "") == normalize(current.unit))
            }
            guard matches else { continue }
            // Establish an actual parser discrepancy on this same evidence,
            // independent of the current query and without running the model.
            let baseline = ThoughtExtractionEngine.extractWithRules(text,permitsOperations:false)
            let observed = baseline.items.filter { !$0.needsReview && $0.organization.itemType == .shopping }.compactMap { initialEntries($0.analysisText) }.flatMap { $0 }
            guard !observed.isEmpty, observed.count == graph.initial.count,
                  observed.indices.allSatisfy({ observed[$0].key == graph.initial[$0].key && observed[$0].quantity == graph.initial[$0].quantity }),
                  observed != graph.entries else { continue }
            return .init(referenceID:example.id,runtimePayloadSHA256:SHA256.hash(data:Data(example.payload.utf8)).map { String(format:"%02x",$0) }.joined(),inputSHA256:inputSHA,solutionSHA256:solutionSHA)
        }
        return nil
    }
    static func interpret(_ source: String, examples: [RuntimeWorkedExample]) -> ThoughtExtractionResult? {
        guard let graph = graph(source), !graph.corrections.isEmpty,
              let program = examples.compactMap(compile).first else { return nil }
        let ledger = SourceUnitLedger(source)
        let organization = OrganizedThought(itemType:.shopping,category:.shopping,priority:.normal,personName:nil,
            dueDate:nil,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,needsClarification:false,state:.resolved)
        let items = graph.entries.map { entry -> ExtractedThought in
            let meaning = "Buy " + entry.literal + entry.contents.map { " (" + $0 + ")" }.joined()
            return .init(sourceQuote:source,rawQuote:source,wasRepaired:false,analysisText:meaning,
                suggestedTitle:meaning,organization:organization,confidence:1,needsReview:false,
                sourceUnitIDs:Set(ledger.words.indices))
        }
#if DEBUG
        RuntimeExampleLibrary.developmentObserver?("analogy consumed=\(program.referenceID) program=quantity-replacement runtimeReencodedPayloadSHA=\(program.runtimePayloadSHA256) inputSHA=\(program.inputSHA256) solutionSHA=\(program.solutionSHA256) corrections=\(graph.corrections.count) entries=\(items.count) current-source-bound=true")
#endif
        return .init(items:items,method:.rules)
    }
}

/// A reviewed mixed-adoption demonstration supplies a purpose constraint.
/// Inventory membership, transfer roles and clocks require separate proofs
/// from the complete current source. No example fact survives compilation.
/// Complete occurrence graphs for an adopted purchase choice and a shared
/// pending prerequisite. Unknown nouns, tails or contradictory decisions use
/// the existing interpreter; overlapping topic words cannot select a product.
enum RuntimeExplicitDecisionCertificate {
    private struct Occurrence { let range: Range<String.Index>; let action: String; let kind: ItemType; let recipient: String? }
    private static func exact(_ text: String,_ pattern: String) -> [String]? {
        guard let (r,f) = RuntimeRecipientReplacement.match(text,from:text.startIndex,pattern:pattern),r.upperBound == text.endIndex else { return nil };return f
    }
    private static func same(_ a: String,_ b: String) -> Bool {
        RuntimeRecipientReplacement.normalize(a) == RuntimeRecipientReplacement.normalize(b)
    }
    private static var person: String {
        "(?:" + PersonMentionResolver.communicationRelationPhrasePattern
            + #"|\p{L}[\p{L}\p{M}'’-]*(?:\s+(?!(?:a|an|the|my|our|your|their|his|her|and|or|but|if|then|that|about)\b)\p{L}[\p{L}\p{M}'’-]*)?)"#
    }
    private static func literalPerson(_ text: String) -> Bool {
        RuntimeRecipientReplacement.literalRecipient(text)
            && text.range(of:#"(?i)\b(?:and|or|but|if|then|that|which|because|unless|after|before|until)\b"#,options:.regularExpression) == nil
    }
    private static func nominal(_ text: String) -> Bool {
        // Extend physical-object grammar for these communication subjects;
        // modifiers remain closed so an embedded instruction is not an object.
        let expanded = text.replacingOccurrences(of:"hook-and-loop",with:"elastic",options:.caseInsensitive)
            .replacingOccurrences(of:#"(?i)\bdock\b"#,with:"display",options:.regularExpression)
            .replacingOccurrences(of:#"(?i)\bstand\b"#,with:"display",options:.regularExpression)
        if RuntimeMixedPurposeCertificate.nominal(expanded) { return true }
        guard let f = exact(expanded,#"(?:the\s+)?(?:(display|frame|panel|box)\s+)?(spacing|dimensions|measurements|layout|sketch|drawing|design|plan)"#) else { return false }
        return f.count == 2
    }
    /// The stated shorter rejection must uniquely identify the unselected
    /// alternative. A missing modifier is allowed; a conflicting one is not.
    private static func identifies(_ alias: String,_ product: String) -> Bool {
        let a = RuntimeRecipientReplacement.normalize(alias).split(separator:" ").map(String.init)
        let p = RuntimeRecipientReplacement.normalize(product).split(separator:" ").map(String.init)
        guard !a.isEmpty,a.last == p.last,Set(a).count == a.count else { return false }
        var cursor = 0
        for word in a {
            guard let i = p[cursor...].firstIndex(of:word) else { return false };cursor = i + 1
        }
        return true
    }
    private static func purchase(_ source: String) -> [Occurrence]? {
        let root = #"For\s+(the\s+(?:exhibition|workshop|trip|display|event|demonstration))\s+(?:buy|purchase)\s+either\s+([^.!?;]+?)\s+or\s+([^.!?;]+)\.\s*(?:I have decided|My decision is):\s*([^.!?;]+?),\s*(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|[0-9]{1,4})\s+(metres?|meters?|yards?|feet|centimetres?|centimeters?)\.\s*Do not buy\s+([^.!?;]+)[.!](?=\s|$)"#
        guard let (r,f) = RuntimeRecipientReplacement.match(source,from:source.startIndex,pattern:root),f.count == 7,
              nominal(f[1]),nominal(f[2]),nominal(f[3]),nominal(f[6]),!same(f[1],f[2]),
              let quantity = RuntimeAllocationReading.number(f[4]),(1...9999).contains(quantity) else { return nil }
        let selected: String,other: String
        if same(f[3],f[1]) { selected = f[1];other = f[2] }
        else if same(f[3],f[2]) { selected = f[2];other = f[1] }
        else { return nil }
        guard identifies(f[6],other),!identifies(f[6],selected) else { return nil }
        var result = [Occurrence(range:r,action:"Buy " + f[4] + " " + f[5] + " of " + selected + " for " + f[0],kind:.shopping,recipient:nil)]
        var cursor = r.upperBound
        // Additional purchases remain distinct; no omitted final member and no
        // inheritance of the selected member's measurement into its siblings.
        while cursor < source.endIndex {
            while cursor < source.endIndex,source[cursor].isWhitespace { cursor = source.index(after:cursor) }
            if cursor == source.endIndex { break }
            guard let (tail,g) = RuntimeRecipientReplacement.match(source,from:cursor,
                pattern:#"Also\s+(?:buy|purchase)\s+(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|[0-9]{1,4})\s+([^.!?;]+)[.!](?=\s|$)"#),
                  let q = RuntimeAllocationReading.number(g[0]),(1...9999).contains(q),nominal(g[1]),result.count < 30 else { return nil }
            result.append(.init(range:tail,action:"Buy " + g[0] + " " + g[1] + " for " + f[0],kind:.shopping,recipient:nil));cursor = tail.upperBound
        }
        return result
    }
    private static func prerequisite(_ source: String) -> [Occurrence]? {
        let pattern = #"After\s+("# + person + #")\s+confirms\s+(the\s+(?:dimensions|measurements|layout|design|counts)),\s*(email\s+("# + person + #")\s+([^.!?;]+?))\s+and\s*(call\s+("# + person + #")\s+about\s+([^.!?;]+?))\.\s*Both wait for that confirmation;\s*("# + person + #")\s+has only reviewed\s+(the\s+(?:sketch|drawing|plan|design))[.!]?"#
        guard let regex = NSRegularExpression.speakItCached("(?is)" + pattern),
              let match = regex.firstMatch(in:source,range:NSRange(source.startIndex...,in:source)),
              let whole = Range(match.range,in:source),whole.lowerBound == source.startIndex,whole.upperBound == source.endIndex,
              let firstActionRange = Range(match.range(at:3),in:source),
              let secondActionRange = Range(match.range(at:6),in:source),
              let noteRange = Range(match.range(at:9),in:source) else { return nil }
        let f = (1..<match.numberOfRanges).map { Range(match.range(at:$0),in:source).map { String(source[$0]) } ?? "" }
        guard f.count == 10,literalPerson(f[0]),literalPerson(f[3]),literalPerson(f[6]),
              same(f[0],f[8]),nominal(f[1]),nominal(f[4]),nominal(f[7]),nominal(f[9]),!same(f[1],f[9]) else { return nil }
        // Exact outer recipients are separate from the prerequisite's actor.
        let first = ClauseScope.read(f[2]),second = ClauseScope.read(f[5])
        // ClauseScope directActor deliberately does not label bare imperatives
        // as user. Ownership here follows the exact positive matrix email/call
        // constructions, independently recognized as current actions.
        guard first.act == .direct,second.act == .direct,
              ActionabilityReader.read(f[2]).belongsOnToday,ActionabilityReader.read(f[5]).belongsOnToday,
              first.recipient.map({ same($0,f[3]) }) == true,
              second.recipient.map({ same($0,f[6]) }) == true,
              String(source[firstActionRange.upperBound..<secondActionRange.lowerBound]).trimmingCharacters(in:.whitespacesAndNewlines).lowercased() == "and" else { return nil }
        let condition = "after " + f[0] + " confirms " + f[1]
        return [
            .init(range:source.startIndex..<firstActionRange.upperBound,action:f[2] + " " + condition,kind:.task,recipient:f[3]),
            .init(range:firstActionRange.upperBound..<noteRange.lowerBound,action:f[5] + " " + condition,kind:.task,recipient:f[6]),
            .init(range:noteRange.lowerBound..<source.endIndex,action:f[8] + " has only reviewed " + f[9] + "; " + f[1] + " confirmation pending",kind:.note,recipient:nil)
        ]
    }
    static func interpret(_ source: String) -> ThoughtExtractionResult? {
        guard !Task.isCancelled,QuotedSpeechScope.ranges(in:source).isEmpty,
              let graph = purchase(source) ?? prerequisite(source) else { return nil }
        let ledger = SourceUnitLedger(source);var seen = Set<Int>(),items: [ExtractedThought] = []
        for frame in graph {
            let raw = String(source[frame.range]),ids = ledger.ids(in:frame.range)
            guard !ids.isEmpty,seen.isDisjoint(with:ids) else { return nil };seen.formUnion(ids)
            let organization = OrganizedThought(itemType:frame.kind,category:frame.kind == .shopping ? .shopping : .general,
                priority:.normal,personName:frame.recipient,dueDate:nil,reminderDate:nil,reminderDelivery:.none,
                recurrenceRule:nil,needsClarification:false,state:.resolved)
            items.append(.init(sourceQuote:raw,rawQuote:raw,wasRepaired:false,analysisText:frame.action,suggestedTitle:frame.action,
                organization:organization,confidence:1,needsReview:false,sourceUnitIDs:ids))
        }
        guard seen == Set(ledger.words.indices),RuntimeProposalGuard.covers(source,quotes:items.map(\.rawQuote)) else { return nil }
#if DEBUG
        RuntimeExampleLibrary.developmentObserver?("source certificate consumed=no-references explicit-choice-or-shared-prerequisite completeFrames=\(items.count)")
#endif
        return .init(items:items,method:.rules)
    }
}

/// Transient current-source frames. A constructor proves only its own exact
/// occurrence; nothing is emitted until every occurrence and dependency has a
/// proof. Unknown tails decline the complete plan, never become default notes.
/// This composes unchanged meanings without recursively interpreting slices.
enum RuntimeIndependentFramePlan {
    struct Frame {
        let range: Range<String.Index>
        let meaning: String
        let organization: OrganizedThought
        var mixedProgram: RuntimeRecipientReplacement.Program? = nil
    }
    private static var person: String {
        "(?:" + PersonMentionResolver.communicationRelationPhrasePattern
            + #"|\p{L}[\p{L}\p{M}'’-]*(?:\s+(?!(?:a|an|the|my|our|your|their|his|her|and|or|but|if|then|that|about)\b)\p{L}[\p{L}\p{M}'’-]*)?)"#
    }
    private static func literalPerson(_ text: String) -> Bool {
        RuntimeRecipientReplacement.literalRecipient(text)
            && text.range(of:#"(?i)\b(?:and|or|but|if|then|that|which|because|unless|after|before|until|said|wrote|asked)\b"#,options:.regularExpression) == nil
    }
    private static func exact(_ text: String,_ pattern: String) -> [String]? {
        guard let (r,f) = RuntimeRecipientReplacement.match(text,from:text.startIndex,pattern:pattern),
              r.upperBound == text.endIndex else { return nil }; return f
    }
    private static func same(_ a: String,_ b: String) -> Bool {
        RuntimeRecipientReplacement.normalize(a) == RuntimeRecipientReplacement.normalize(b)
    }
    /// Extend the existing closed nominal proof with everyday packing and
    /// communication nouns. Arbitrary strings and hidden predicates cannot
    /// become noun phrases just because the source contains their words.
    static func nominal(_ text: String) -> Bool {
        if RuntimeMixedPurposeCertificate.nominal(text) { return true }
        let heads: Set<String> = ["prism","prisms","apron","aprons","kneepad","kneepads","blanket","blankets","gauge","gauges","bag","bags","label","labels","latch","latches","slip","slips","smell","smells","spacing","dimensions","measurements","layout","sketch","drawing","design","plan"]
        let modifiers: Set<String> = ["sail","launch","varnish","dock","stand","low-tack","edging","cloth","paper","wooden","brass","steel","red","blue","green","small","large","winter","mural","test","storage","spare","existing","portable","north","south","east","west","stencil"]
        guard text.range(of:#"^[\p{L}\p{M} -]+$"#,options:.regularExpression) != nil,!text.contains("--") else { return false }
        var words = text.lowercased().split(whereSeparator: { $0.isWhitespace }).map(String.init)
        if ["the","a","an"].contains(words.first ?? "") { words.removeFirst() }
        guard (1...5).contains(words.count),let head = words.last else { return false }
        if heads.contains(head) { return words.dropLast().allSatisfy { modifiers.contains($0) || heads.contains($0) } }
        // New modifiers may qualify an already proved physical head, but not
        // add another predicate or an unrecognized compound noun.
        return RuntimeMixedPurposeCertificate.nominal(head)
            && words.dropLast().allSatisfy { modifiers.contains($0) }
    }
    private static func memory(_ kind: ItemType = .note) -> OrganizedThought {
        .init(itemType:kind,category:kind == .idea ? .ideas : .general,priority:.normal,personName:nil,
            dueDate:nil,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,needsClarification:false,state:.resolved)
    }
    private static func task(_ recipient: String?,_ timing: (Date,TemporalIntent)?,alert: Bool) -> OrganizedThought {
        .init(itemType:.task,category:.general,priority:.normal,personName:recipient,
            dueDate:timing?.0,reminderDate:alert ? timing?.0 : nil,reminderDelivery:alert ? .notification : .none,
            recurrenceRule:nil,needsClarification:false,temporalIntent:timing?.1 ?? .none,state:.resolved)
    }
    static func clock(_ text: String,referenceDate: Date,calendar: Calendar,source: String) -> (Date,TemporalIntent)? {
        guard calendar.identifier == .gregorian else { return nil }
        if let f = exact(text,#"(today|tomorrow)(?:\s+at\s+([0-9]{1,2})(?::([0-9]{2}))?\s+(AM|PM))?"#) {
            guard let day = calendar.date(byAdding:.day,value:f[0].lowercased() == "tomorrow" ? 1 : 0,to:calendar.startOfDay(for:referenceDate)) else { return nil }
            let names = ["January","February","March","April","May","June","July","August","September","October","November","December"]
            let m = calendar.component(.month,from:day),d = calendar.component(.day,from:day),y = calendar.component(.year,from:day)
            let bound = names[m-1] + " \(d) \(y)" + (f[1].isEmpty ? "" : " at " + f[1] + (f[2].isEmpty ? "" : ":" + f[2]) + " " + f[3])
            return RuntimeMixedPurposeCertificate.clock(bound,referenceDate:referenceDate,calendar:calendar,source:source)
        }
        return RuntimeMixedPurposeCertificate.clock(text,referenceDate:referenceDate,calendar:calendar,source:source)
    }
    private static func direct(_ verb: String,_ recipient: String,_ topic: String) -> String? {
        guard literalPerson(recipient),nominal(topic) else { return nil }
        let meaning = verb + " " + recipient + " about " + topic
        let scope = ClauseScope.read(meaning)
        guard scope.act == .direct,scope.recipient.map({ same($0,recipient) }) == true,
              scope.recipientRange != nil,ActionabilityReader.read(meaning).belongsOnToday else { return nil }
        // Bare imperatives deliberately have actor.unresolved in ClauseScope.
        // Current ownership comes from this complete positive matrix grammar,
        // and provisional frames still await all-source dependency validation.
        return meaning
    }
    private static func quantified(_ text: String) -> Bool {
        let count = #"(?:one|two|three|four|five|six|seven|eight|nine|ten|[1-9][0-9]{0,3})"#
        guard let f = exact(text,"(" + count + #")\s+(.+)"#) else { return false }
        if nominal(f[1]) { return true }
        guard let container = exact(f[1],#"(?:rolls?|bags?|boxes?|cartons?|bottles?|packs?)\s+of\s+(.+)"#) else { return false }
        return nominal(container[0])
    }
    static func packingMembers(_ text: String) -> [String]? {
        guard text.range(of:#"[;:&/\n\r.!?—–()\[\]{}]"#,options:.regularExpression) == nil else { return nil }
        let members = text.replacingOccurrences(of:#"(?i),?\s+and\s+"#,with:",",options:.regularExpression)
            .split(separator:",",omittingEmptySubsequences:false).map { $0.trimmingCharacters(in:.whitespaces) }
        guard !members.isEmpty else { return nil }
        for member in members {
            if let f = exact(member,#"(?:our|my)\s+(?:already\s+owned\s+|existing\s+)?(.+)"#),nominal(f[0]) { continue }
            guard let f = exact(member,"(" + person + #")['’]s\s+(.+)"#),literalPerson(f[0]),nominal(f[1]) else { return nil }
        }
        return members
    }
    /// Declared Memory/idea may contain uncertainty, but cannot swallow another
    /// user's executive directive, a cross-frame correction or later adoption.
    private static func declaredKnowledge(_ text: String) -> Bool {
        text.range(of:#"(?i)\b(?:actually|instead|cancel|withdraw|reschedule|remind|notify|alerts?|notifications?|saved|earlier|previous|both|either|otherwise)\b|\b(?:i|we)\s+(?:will|must|should|need\s+to|have\s+to|have\s+agreed|am\s+going\s+to)\b|(?:^|[,;:]|\band\b|\bthen\b)\s*(?:call|phone|ask|tell|email|text|message|buy|purchase|pack|clean|unlock|print|return|send|fix|repair|test|check|finish|pay|book)\b"#,options:.regularExpression) == nil
            && QuotedSpeechScope.ranges(in:text).isEmpty && !QuotedSpeechScope.hasUnclosedQuote(text)
    }
    /// A heading supplies destination, not permission to hide arbitrary
    /// predicates. Every interior clause needs a descriptive finite frame.
    /// Unrecognized clauses decline; no finite command blacklist is an oracle.
    private static func descriptivePredicate(_ clause: String) -> Bool {
        guard !clause.isEmpty,!ActionabilityReader.read(clause).belongsOnToday,
              let f = exact(clause,#"(.+?)\s+(supplied|provided|made|built|drew|designed|dried|cracked|faded|broke|arrived|closed|opened|reviewed|finished|tested|owns|owned|has|had|belongs|was|were|is|are)\b(?:\s+(.*))?"#) else { return false }
        let subject = f[0],predicate = f[1].lowercased(),rest = f[2]
        let grammaticalSubject = ["i","we","he","she","they"].contains(subject.lowercased())
            || nominal(subject) || packingMembers(subject) != nil || (subject.first?.isUppercase == true && literalPerson(subject))
        guard grammaticalSubject else { return false }
        if ["supplied","provided","made","built","drew","designed","reviewed","finished","tested","owns","owned","has","had"].contains(predicate) {
            // A nominal complement cannot contain a second executive predicate.
            return nominal(rest) || packingMembers(rest) != nil
        }
        if predicate == "belongs" {
            guard let owner = exact(rest,#"to\s+(.+)"#) else { return false };return literalPerson(owner[0])
        }
        if ["dried","cracked","faded","broke","arrived","closed","opened"].contains(predicate) {
            return rest.isEmpty || exact(rest,#"(?:unevenly|evenly|slowly|quickly|overnight|yesterday|already|early|late|again|last week)"#) != nil
        }
        // Copular facts have a bounded descriptive quality, not an arbitrary
        // adoption/cancellation policy hidden behind 'we are' or 'Mom is'.
        return descriptiveCopularQuality(rest)
    }
    /// Shared closed predicate grammar for complete copular source facts.
    /// This proves only a descriptive quality, never an executable action.
    static func descriptiveCopularQuality(_ text: String) -> Bool {
        exact(text,#"(?:red|blue|green|white|black|grey|gray|uneven|even|damp|dry|wet|open|closed|missing|broken|ready|complete|unfinished|cold|warm|hot)"#) != nil
    }
    private static func descriptiveAccount(_ text: String) -> Bool {
        guard declaredKnowledge(text) else { return false }
        let clauses = text.replacingOccurrences(of:#"(?i),\s*(?:and\s+)?|\s+(?:and|then|plus|but)\s+"#,with:";",options:.regularExpression)
            .split(separator:";",omittingEmptySubsequences:false).map { $0.trimmingCharacters(in:.whitespacesAndNewlines) }
        guard !clauses.isEmpty else { return false }
        for clause in clauses {
            if let f = exact(clause,#"(?:we|I)\s+(?:do not know|don't know|are unsure|am unsure)\s+whether\s+(.+)"#) {
                // This records an unconfirmed causal proposition. It grants
                // no action, recipient, saved change or precise interruption.
                guard exact(f[0],#"(?:the\s+)?(?:heater|weather|heat|cold|rain|wind|sun|moisture)\s+caused\s+(?:it|the uneven drying|the crack|the fading|the damage)"#) != nil else { return false }
            } else if !descriptivePredicate(clause) { return false }
        }
        return true
    }
    /// Positive finite matrix grammar used when lexical assets are absent.
    /// A named/pronominal/nominal subject owns a fact or an attributed report;
    /// a bare instruction cannot borrow that subject from another clause.
    private static func finiteNarrativeClause(_ text: String, attributedFacts:Bool = false) -> Bool {
        let subject = #"(?:I|we|you|he|she|they|it|this|that|these|those|(?:the|a|an|my|our|their|his|her|its)\s+[\p{L}\p{M}'’-]+(?:\s+[\p{L}\p{M}'’-]+){0,6}|"# + person + ")"
        let finite = #"(?:is|are|was|were|am|has|have|had|did|should|made|built|drew|found|saw|broke|felt|took|went|gave|owns|belongs|[\p{L}]+ed|"# + (attributedFacts ? "came|remembers|suspects|" : "") + ClauseScope.reportingVerb + ")"
        let reportAdverb = attributedFacts ? "(?:only\\s+)?" : ""
        guard let fields = exact(text,"(" + subject + ")\\s+" + reportAdverb + "(" + finite + #")\b(.*)"#),!fields[0].isEmpty else { return false }
        let predicate = fields[1].lowercased(),rest = fields[2].trimmingCharacters(in:.whitespacesAndNewlines)
        if predicate == "did" || predicate == "should" {
            return rest.range(of:#"(?i)^(?:not|never)\s+\p{L}"#,options:.regularExpression) != nil
        }
        if (attributedFacts && ["remembers","suspects"].contains(predicate)) || predicate.range(of:"^" + ClauseScope.reportingVerb + "$",options:[.regularExpression,.caseInsensitive]) != nil {
            // Report ownership extends to its literal proposition; independent
            // user commitments/adoption are vetoed over the complete own voice.
            if attributedFacts, ["remembers","suspects"].contains(predicate),
               rest.range(of:#"(?i)\b(?:because|although|while|when|whenever|unless|until|if|after|before|then|plus|by|via)\b"#,options:.regularExpression) != nil { return false }
            return !rest.isEmpty || ["said","wrote","told"].contains(predicate)
        }
        guard !rest.isEmpty else { return false }
        // Unproved subordinate continuation cannot disappear behind an early
        // past predicate. The same closed conjunction grammar is checked for
        // every fact, rather than recognizing a growing list of commands.
        return rest.range(of:#"(?i)\b(?:because|although|while|when|whenever|unless|until|if|after|before|then|plus)\b"#,options:.regularExpression) == nil
    }
    /// These dispositions override only the broad outstanding-action heuristic
    /// inside a fully retained declared account. They never create an action
    /// or excuse an unproved physical prohibition or an outstanding obligation.
    private static func narrativeNegativeFact(_ clause: String,unit: String,body: String) -> Bool {
        if exact(clause,#"(?:I|we)\s+(?:have\s+not|haven['’]t)\s+(?:adopted|accepted|agreed\s+to|committed\s+to|said\s+yes\s+to)\s+(?:this|that)\s+(?:request|offer|proposal|suggestion)"#) != nil {
            // The actual quoted report in this same unit is the referent.
            // An unquoted 'Nori said I have not...' has no own-refusal proof.
            return !QuotedSpeechScope.ranges(in:unit).isEmpty && QuotedSpeechScope.matrixVoice(in:unit) == .reported
        }
        if let f = exact(clause,#"(?:I|we)\s+should\s+(?:not|never)\s+(?:turn|treat|present|record)\s+((?:this|that|the)\s+(?:explanation|hypothesis|guess|claim|theory|interpretation|assumption))\s+(?:into|as)\s+(?:a\s+)?(?:confirmed|verified|established|proven|certain)\s+(?:conclusion|fact|finding|truth)"#) {
            let proposition = body.range(of:#"(?i)\b(?:thinks?|believes?|suspects?|hypothesizes?|hypothesises?)\s+[^.!?;]+"#,options:.regularExpression)
            // A demonstrable preceding explanatory proposition supplies the
            // source role. A physical object or dangling 'that' cannot do so.
            return !f[0].isEmpty && proposition != nil && body.range(of:clause).map { own in
                proposition!.upperBound <= own.lowerBound
            } == true
        }
        if let f = exact(clause,#"(?:I|we)\s+did\s+(?:not|never)\s+([\p{L}]+)\s+(.+)"#),
           (nominal(f[1]) || exact(f[1],#"(?:the|a|an)\s+(?:sloped\s+|uneven\s+|wooden\s+)?(?:floor|wall|ceiling|surface)"#) != nil) {
            // Closed retrospective context and explicit non-creation together
            // distinguish missing past observations from still-owed errands.
            return body.range(of:#"(?i)\b(?:these|those|the)\s+(?:are|were)?\s*past\s+(?:events|observations|experiences)\b"#,options:.regularExpression) != nil
                && body.range(of:#"(?i)\b(?:I\s+am|we\s+are)\s+not\s+(?:giving|assigning)\s+(?:myself|ourselves)\s+(?:jobs|tasks)\b"#,options:.regularExpression) != nil
                && body.range(of:#"(?i)\b(?:still|yet|owe|owing|forgot|supposed\s+to)\b"#,options:.regularExpression) == nil
        }
        return false
    }
    /// A whole declared account can retain general narrative facts without
    /// borrowing an action from a heading. Every own-voice clause must prove
    /// a subject and finite predicate; quotations must prove a reported matrix.
    /// The complete literal account remains the saved meaning, including doubt.
    static func coherentNarrative(_ source: String, attributedFacts:Bool = false) -> ThoughtExtractionResult? {
        guard !Task.isCancelled,!QuotedSpeechScope.hasUnclosedQuote(source),
              let heading = source.range(of:#"(?i)^\s*(?:keep|save|preserve)(?:\s+(?:the\s+following|this)\s+as)?\s+one\s+(?:(?:connected|coherent)\s+)?(?:memory|note|account)(?:\s+(?:about|of)\s+[^.!?:]+)?\s*[.:]"#,options:.regularExpression) else { return nil }
        let headingText = String(source[heading])
        if let topicMarker = headingText.range(of:#"(?i)\s+(?:about|of)\s+"#,options:.regularExpression) {
            let topic = String(headingText[topicMarker.upperBound...]).trimmingCharacters(in:.whitespacesAndNewlines.union(.punctuationCharacters))
            guard exact(topic,#"[\p{L}\p{M}0-9’'-]+(?:\s+[\p{L}\p{M}0-9’'-]+){0,7}"#) != nil,
                  topic.range(of:#"(?i)\b(?:and|or|but|then|also|because|if|unless|until|after|before|I|we|you|will|must|should|today|tomorrow|tonight)\b"#,options:.regularExpression) == nil else { return nil }
        }
        let body = String(source[heading.upperBound...])
        let units = RuntimeIndexedSource(body)
        guard !units.units.isEmpty else { return nil }
        for (unitIndex,unit) in units.units.enumerated() {
            if !QuotedSpeechScope.ranges(in:unit.text).isEmpty,
               QuotedSpeechScope.matrixVoice(in:unit.text) != .reported {
#if DEBUG
                RuntimeExampleLibrary.developmentObserver?("narrative declined matrix unit=\(unitIndex)")
#endif
                return nil
            }
            guard let voice = QuotedSpeechScope.voiceProjection(in:unit.text) else { return nil }
            let text = voice.ownVoiceText
            // Prospective user acts and adoption are checked throughout the
            // own-voice proposition, including a later causal continuation.
            guard text.range(of:#"(?i)\b(?:i|we)\s+(?:(?:will|shall|must|should)(?!\s+(?:not|never)\b)|(?:need|have|want)\s+to)\b"#,options:.regularExpression) == nil,
                  text.range(of:#"(?i)\b(?:i|we)\s+(?:have\s+)?(?:now\s+)?(?:agree|agreed|accept|accepted|adopt|adopted|decide|decided|commit|committed|say\s+yes|said\s+yes)\b"#,options:.regularExpression) == nil else { return nil }
            guard let boundaries = NSRegularExpression.speakItCached(#";|,\s*(?:(?:and|but|then|plus|so)\s+)?|\s+(?:and|but|then|plus|so)\s+"#,options:.caseInsensitive) else { return nil }
            var ranges: [Range<String.Index>] = [],position = text.startIndex
            for match in boundaries.matches(in:text,range:NSRange(text.startIndex...,in:text)) {
                guard let boundary = Range(match.range,in:text) else { return nil }
                ranges.append(position..<boundary.lowerBound);position = boundary.upperBound
            }
            ranges.append(position..<text.endIndex)
            for range in ranges {
                let clause = String(text[range]).trimmingCharacters(in:.whitespacesAndNewlines.union(.punctuationCharacters))
                if clause.isEmpty { continue }
                let positiveFinite = finiteNarrativeClause(clause,attributedFacts:attributedFacts)
                let subject = positiveFinite,predicate = positiveFinite
                let today = ActionabilityReader.read(clause).belongsOnToday,reminder = ReminderPhrasing.requestsReminder(clause)
                guard !clause.contains(":"),subject,predicate,
                      (!today || narrativeNegativeFact(clause,unit:unit.text,body:body)),!reminder else {
#if DEBUG
                    RuntimeExampleLibrary.developmentObserver?("narrative declined finite unit=\(unitIndex) subject=\(subject) predicate=\(predicate) today=\(today) reminder=\(reminder)")
#endif
                    return nil
                }
                // A subject with a prospective user obligation is not a fact
                // merely because the lexical tagger missed its action verb.
                if clause.range(of:#"(?i)^(?:i|we)\s+(?:(?:will|shall|must|should)(?!\s+(?:not|never)\b)|(?:need|have|want)\s+to)\b"#,options:.regularExpression) != nil { return nil }
                if clause.range(of:#"(?i)^(?:i|we)\s+(?:have\s+)?(?:now\s+)?(?:agreed|accepted|adopted|decided|committed|said\s+yes)\b"#,options:.regularExpression) != nil { return nil }
            }
        }
        let organization = memory()
        return ThoughtExtractionResult(items:[.init(sourceQuote:source,rawQuote:source,wasRepaired:false,
            analysisText:source,suggestedTitle:nil,organization:organization,confidence:1,needsReview:false,
            sourceUnitIDs:Set(SourceUnitLedger(source).words.indices))],method:.rules)
    }
    /// Prevent an older broad heading reader from automatically accepting the
    /// exact account shapes whose interior proof failed here. Other coherent
    /// Memory paths and protected long-source certificates keep their contract.
    static func containsAccountDeclaration(_ source: String) -> Bool {
        let pattern = #"(?is)(?:^\s*|(?<=[.!?])\s+|(?<=[\n\r])\s*)(?:Save|Keep|Preserve)(?:\s+(?:the\s+following|this)\s+as)?\s+one\s+(?:(?:connected|coherent)\s+)?(?:account|note|memory)\b"#
        guard let regex = NSRegularExpression.speakItCached(pattern) else { return false }
        return regex.matches(in:source,range:NSRange(source.startIndex...,in:source)).contains { match in
            guard let range = Range(match.range,in:source) else { return false }
            return !QuotedSpeechScope.protects(range,in:source)
        }
    }
    static func hasUnprovedAccount(_ source: String) -> Bool {
        let pattern = #"(?is)(?:^\s*|(?<=[.!?])\s+|(?<=[\n\r])\s*)(?:Save|Keep|Preserve)\s+one\s+(?:(?:connected|coherent)\s+)?(?:account|note|memory)\s+(?:of|about)\s+([^.!?;:]+):\s*([^.!?]+)(?:[.!?](?=\s|$)|$)"#
        guard let regex = NSRegularExpression.speakItCached(pattern) else { return false }
        for match in regex.matches(in:source,range:NSRange(source.startIndex...,in:source)) {
            guard let range = Range(match.range,in:source),!QuotedSpeechScope.protects(range,in:source),
                  let label = Range(match.range(at:1),in:source),let body = Range(match.range(at:2),in:source) else { continue }
            if !declaredKnowledge(String(source[label])) || !descriptiveAccount(String(source[body])) { return true }
        }
        return false
    }
    private static func mixedProgram(_ examples: [RuntimeWorkedExample],configuration: RuntimeExampleConfiguration?) -> RuntimeRecipientReplacement.Program? {
        guard let cfg = configuration ?? RuntimeExampleConfiguration.current,cfg.retrievalEnabled,
              let identities = RuntimeRecipientReplacement.approvedIdentities(cfg) else { return nil }
        return examples.first(where: {
            !cfg.excludedIDs.contains($0.id) && !cfg.excludedBlueprints.contains($0.provenance.blueprint)
                && cfg.excludedBlueprints.isDisjoint(with:$0.ruleIDs)
                && RuntimeMixedPurposeCertificate.compile($0,approved:identities) != nil
        }).flatMap { RuntimeMixedPurposeCertificate.compile($0,approved:identities)?.provenance }
    }
    static func graph(_ source: String,examples: [RuntimeWorkedExample],referenceDate: Date,
                      calendar: Calendar,configuration: RuntimeExampleConfiguration?) -> [Frame]? {
        guard !Task.isCancelled,!QuotedSpeechScope.hasUnclosedQuote(source) else { return nil }
        var frames: [Frame] = [],position = source.startIndex
        func next(_ pattern: String) -> (Range<String.Index>,[String])? {
            RuntimeRecipientReplacement.match(source,from:position,pattern:pattern)
        }
        let end = #"[.!](?=\s|$)"#
        while position < source.endIndex {
            while position < source.endIndex,source[position].isWhitespace { position = source.index(after:position) }
            if position == source.endIndex { break }
            guard !Task.isCancelled else { return nil }
            let frame: Frame
            if let (r,f) = next(#"Remind me\s+(?:separately\s+)?([^.!?;]+?)\s+to\s+(call|phone|ask)\s+("# + person + #")\s+about\s+([^.!?;]+)"# + end) {
                guard let action = direct(f[1],f[2],f[3]),let timing = clock(f[0],referenceDate:referenceDate,calendar:calendar,source:String(source[r])),timing.1.kind == .exactDateTime else { return nil }
                frame = .init(range:r,meaning:action,organization:task(f[2],timing,alert:true))
            } else if let (r,f) = next(#"(?:please\s+)?(call|phone)\s+("# + person + #")\s+(today|tomorrow)(?:[.!](?=\s|$)|(?=$))"#) {
                let action = f[0] + " " + f[1],scope = ClauseScope.read(action + " " + f[2])
                guard literalPerson(f[1]),scope.act == .direct,
                      scope.recipient.map({ same($0,f[1]) }) == true,scope.recipientRange != nil,
                      let timing = clock(f[2],referenceDate:referenceDate,calendar:calendar,source:String(source[r])),
                      timing.1.kind == .dateOnly else { return nil }
                frame = .init(range:r,meaning:action + " " + f[2],organization:task(f[1],timing,alert:false))
            } else if let (r,f) = next(#"(?:Separately,?\s+|Also,?\s+)?(call|phone|ask)\s+("# + person + #")\s+about\s+([^.!?;]+?)\s+(today|tomorrow)"# + end) {
                guard let action = direct(f[0],f[1],f[2]),let timing = clock(f[3],referenceDate:referenceDate,calendar:calendar,source:String(source[r])),timing.1.kind == .dateOnly else { return nil }
                frame = .init(range:r,meaning:action + " " + f[3],organization:task(f[1],timing,alert:false))
            } else if let (r,f) = next(#"The\s+(boatyard|workshop|shop|store|office|library|museum|school|cafe)\s+closes\s+([^.!?;]+);\s*(?:that last time|that time|the closing time)\s+is only reference information"# + end) {
                guard clock(f[1],referenceDate:referenceDate,calendar:calendar,source:String(source[r])) != nil else { return nil }
                frame = .init(range:r,meaning:String(source[r]),organization:memory())
            } else if let (r,f) = next(#"(?:Save|Keep|Preserve)\s+one\s+(?:(?:connected|coherent)\s+)?(?:account|note|memory)\s+(?:of|about)\s+([^.!?;:]+):\s*([^.!?;]+)"# + end) {
                guard declaredKnowledge(f[0]),descriptiveAccount(f[1]) else { return nil }
                frame = .init(range:r,meaning:String(source[r]),organization:memory())
            } else if let (r,f) = next(#"(?:Also,?\s+|Separately,?\s+)?(?:Buy|Purchase)\s+([^.!?;]+)"# + end) {
                guard quantified(f[0]) else { return nil }
                frame = .init(range:r,meaning:"Buy " + f[0],organization:memory(.shopping))
            } else if let (r,f) = next(#"Pack\s+([^.!?;]+);\s*(?:do not|don't)\s+buy\s+(?:those|these)"# + end) {
                guard packingMembers(f[0]) != nil else { return nil }
                frame = .init(range:r,meaning:String(source[r]),organization:task(nil,nil,alert:false))
            } else if let (r,f) = next(#"(?:An?\s+)?idea for later is\s+([^.!?;]+),\s*not something I have agreed to\s+(?:build|make|do|create|start|buy)"# + end) {
                guard declaredKnowledge(f[0]) else { return nil }
                frame = .init(range:r,meaning:String(source[r]),organization:memory(.idea))
            } else if let (r,f) = next("(" + person + #")\s+(?:wrote|said),?\s*[\"“]([^\"“”]+)[\"”]\s*[.!]?\s*I\s+(?:have not said yes|have not agreed|am not adopting that)[.!]\s*(?:Save|Keep)\s+(her|his|their)\s+(?:message|note)"# + end) {
                guard literalPerson(f[0]),!f[1].trimmingCharacters(in:.whitespacesAndNewlines).isEmpty else { return nil }
                // One report/refusal/message chain owns this whole occurrence.
                // Quote recipient, conditions and clocks stay literal data.
                frame = .init(range:r,meaning:String(source[r]),organization:memory())
            } else if let proved = RuntimeMixedPurposeCertificate.readFrame(source,from:position,referenceDate:referenceDate,calendar:calendar),
                      let program = mixedProgram(examples,configuration:configuration) {
                let raw = String(source[proved.range]),meaning: String,organization: OrganizedThought
                switch proved {
                case .inventory: meaning = raw;organization = memory()
                case .offer(_,let actor,let offered): meaning = actor + " offered to " + offered + "; offer not accepted";organization = memory()
                case .own(_,let action,let date,let intent): meaning = action;organization = task(nil,(date,intent),alert:false)
                case .transfer(_,let action,_,let recipient,let date,let intent): meaning = action;organization = task(recipient,(date,intent),alert:true)
                }
                frame = .init(range:proved.range,meaning:meaning,organization:organization,mixedProgram:program)
            } else { return nil }
            frames.append(frame);position = frame.range.upperBound
        }
        guard !frames.isEmpty,RuntimeProposalGuard.covers(source,quotes:frames.map { String(source[$0.range]) }) else { return nil }
        // Construction consumed every character except whitespace, not just
        // selected slices. Every dependency-bearing tail must therefore be an
        // explicitly proved frame; an unknown withdrawal/adoption/global alert
        // policy invalidates the whole composition before executable output.
        return frames
    }
    static func interpret(_ source: String,examples: [RuntimeWorkedExample],referenceDate: Date,
                          calendar: Calendar,configuration: RuntimeExampleConfiguration? = nil) -> ThoughtExtractionResult? {
        guard let frames = graph(source,examples:examples,referenceDate:referenceDate,calendar:calendar,configuration:configuration) else { return nil }
        let ledger = SourceUnitLedger(source);var seen = Set<Int>(),items: [ExtractedThought] = []
        for frame in frames {
            let ids = ledger.ids(in:frame.range),raw = String(source[frame.range])
            guard !ids.isEmpty,seen.isDisjoint(with:ids) else { return nil };seen.formUnion(ids)
            items.append(.init(sourceQuote:raw,rawQuote:raw,wasRepaired:false,analysisText:frame.meaning,
                suggestedTitle:frame.meaning,organization:frame.organization,confidence:1,needsReview:false,sourceUnitIDs:ids))
        }
        guard seen == Set(ledger.words.indices),!Task.isCancelled else { return nil }
#if DEBUG
        for p in frames.compactMap(\.mixedProgram) {
            RuntimeExampleLibrary.developmentObserver?("analogy consumed=\(p.referenceID) program=composed-mixed-purpose-adoption runtimeReencodedPayloadSHA=\(p.runtimePayloadSHA256) inputSHA=\(p.inputSHA256) solutionSHA=\(p.solutionSHA256) current-source-bound=true")
        }
        RuntimeExampleLibrary.developmentObserver?("independent frame composition complete=\(items.count) whole-source=true")
#endif
        return .init(items:items,method:.rules)
    }
}

enum RuntimeMixedPurposeCertificate {
    struct Program { let provenance: RuntimeRecipientReplacement.Program }
    struct InventoryMember: Equatable { let quantity: Int; let phrase: String }
    enum Frame {
        case inventory(Range<String.Index>,[InventoryMember])
        case own(Range<String.Index>,String,Date,TemporalIntent)
        case transfer(Range<String.Index>,String,String,String,Date,TemporalIntent)
        case offer(Range<String.Index>,String,String)
        var range: Range<String.Index> {
            switch self { case .inventory(let r,_),.own(let r,_,_,_),.transfer(let r,_,_,_,_,_),.offer(let r,_,_): return r }
        }
        var kind: String { switch self { case .inventory:return "inventory";case .own:return "own";case .transfer:return "transfer";case .offer:return "offer" } }
    }
    private static func exact(_ text: String,_ pattern: String) -> [String]? {
        guard let (range,f) = RuntimeRecipientReplacement.match(text,from:text.startIndex,pattern:pattern),
              range.upperBound == text.endIndex else { return nil };return f
    }
    private static func same(_ a: String,_ b: String) -> Bool {
        RuntimeRecipientReplacement.normalize(a) == RuntimeRecipientReplacement.normalize(b)
    }
    private static var person: String {
        "(?:" + PersonMentionResolver.communicationRelationPhrasePattern
            + #"|\p{L}[\p{L}\p{M}'’-]*(?:\s+\p{L}[\p{L}\p{M}'’-]*)?)"#
    }
    private static let physical = #"(?:adjust|print|clean|dust|wash|test|check|finish|fix|repair|count|scan|polish|measure|sort|label|sharpen|tighten|charge|put|pack|copy)"#
    // This is a bounded nominal grammar. Unknown heads/modifiers require the
    // existing recoverable path; an optional tagger's absence grants no licence.
    private static let heads: Set<String> = ["cooler","coolers","lens","lenses","shim","shims","spacer","spacers","magnifier","magnifiers","bracket","brackets","speaker","speakers","case","cases","frame","frames","ring","rings","insert","inserts","button","buttons","bottle","bottles","clasp","clasps","sleeve","sleeves","cover","covers","runner","runners","brake","brakes","cord","cords","bead","beads","funnel","funnels","bin","bins","key","keys","map","maps","tape","braid","ruler","rulers","wrench","wrenches","cloth","cloths","battery","batteries","screw","screws","washer","washers","bolt","bolts","nut","nuts","plate","plates","panel","panels","card","cards","notebook","notebooks","pencil","pencils","pen","pens","cable","cables","socket","sockets","tool","tools","cup","cups","tray","trays","box","boxes"]
    private static let modifiers: Set<String> = ["amber","blue","red","green","yellow","white","black","grey","gray","orange","purple","clear","wooden","wood","brass","bronze","steel","metal","plastic","ceramic","glass","rubber","paper","felt","cotton","elastic","viewing","portable","spare","small","large","short","long","round","flat","square","thin","thick","new","old","empty","full","clean","dry","wet","storage","crate","tripod","finder","frost","visor","eyepiece","snap","picture","pencil","power","charging","display","measuring","safety","support","telescope","sealant"]
    static func nominal(_ text: String) -> Bool {
        guard text.count <= 120,text.range(of:#"^[\p{L}\p{M} -]+$"#,options:.regularExpression) != nil,
              !text.contains("--") else { return false }
        var words = text.lowercased().split(whereSeparator:{ $0.isWhitespace }).map(String.init)
        if ["the","a","an"].contains(words.first ?? "") { words.removeFirst() }
        guard (1...5).contains(words.count),let head = words.last,heads.contains(head) else { return false }
        return words.dropLast().allSatisfy { modifiers.contains($0) || heads.contains($0) }
    }
    static func inventoryMembers(_ text: String) -> [InventoryMember]? {
        guard text.range(of:#"[;:&/\n\r.!?—–()\[\]{}]"#,options:.regularExpression) == nil else { return nil }
        let pieces = text.replacingOccurrences(of:#"(?i),?\s+and\s+"#,with:",",options:.regularExpression)
            .split(separator:",",omittingEmptySubsequences:false).map { $0.trimmingCharacters(in:.whitespaces) }
        guard (1...30).contains(pieces.count) else { return nil }
        let numberWords = ["one":1,"two":2,"three":3,"four":4,"five":5,"six":6,"seven":7,"eight":8,"nine":9,"ten":10]
        var members: [InventoryMember] = []
        for piece in pieces {
            guard let f = exact(piece,#"(one|two|three|four|five|six|seven|eight|nine|ten|[0-9]{1,4})\s+(.+)"#),
                  let n = numberWords[f[0].lowercased()] ?? Int(f[0]),(1...9999).contains(n),nominal(f[1]) else { return nil }
            members.append(.init(quantity:n,phrase:f[1]))
        }
        return members
    }
    /// Named month/day resolution follows the existing nearest valid future
    /// day policy. A clock is exact only when explicitly present on this frame.
    static func clock(_ text: String, referenceDate: Date, calendar: Calendar, source: String)
        -> (Date,TemporalIntent)? {
        let months = ["january":1,"february":2,"march":3,"april":4,"may":5,"june":6,"july":7,"august":8,"september":9,"october":10,"november":11,"december":12]
        guard let f = exact(text,#"(january|february|march|april|may|june|july|august|september|october|november|december)\s+([0-9]{1,2})(?:st|nd|rd|th)?(?:,?\s+([0-9]{4}))?(?:\s+at\s+([0-9]{1,2})(?::([0-9]{2}))?\s+(AM|PM))?"#),
              let month = months[f[0].lowercased()],let day = Int(f[1]),(1...31).contains(day) else { return nil }
        var hour: Int? = nil,minute = 0
        if !f[3].isEmpty {
            guard let h = Int(f[3]),(1...12).contains(h),f[4].isEmpty || Int(f[4]) != nil else { return nil }
            minute = Int(f[4]) ?? 0;guard (0...59).contains(minute) else { return nil }
            hour = h % 12 + (f[5].lowercased() == "pm" ? 12 : 0)
        }
        let years: [Int]
        if f[2].isEmpty { let y = calendar.component(.year,from:referenceDate);years = Array(y...y+8) }
        else { guard let y = Int(f[2]),(1900...9999).contains(y) else { return nil };years = [y] }
        // Resolve the stated day before binding its local clock. Searching a
        // later year to evade a daylight-saving gap invents a different day.
        for y in years {
            guard let dayStart = calendar.date(from:DateComponents(year:y,month:month,day:day)),
                  calendar.component(.year,from:dayStart) == y,calendar.component(.month,from:dayStart) == month,
                  calendar.component(.day,from:dayStart) == day,
                  !f[2].isEmpty || dayStart >= calendar.startOfDay(for:referenceDate) else { continue }
            let date: Date
            if let hour {
                guard let bound = calendar.date(bySettingHour:hour,minute:minute,second:0,of:dayStart,
                    matchingPolicy:.nextTime,repeatedTimePolicy:.first,direction:.forward),
                      calendar.component(.year,from:bound) == y,calendar.component(.month,from:bound) == month,
                      calendar.component(.day,from:bound) == day,calendar.component(.hour,from:bound) == hour,
                      calendar.component(.minute,from:bound) == minute else { return nil }
                date = bound
            } else { date = calendar.startOfDay(for:dayStart) }
            return (date,.init(kind:hour == nil ? .dateOnly : .exactDateTime,
                day:.init(year:y,month:month,day:day),time:hour.map { .init(hour:$0,minute:minute) },
                timeZoneIdentifier:hour == nil ? nil : calendar.timeZone.identifier,
                timeZoneBehavior:.deviceLocal,sourceText:source))
        }
        return nil
    }
    /// Approval of the complete worked answer precedes this compilation. The
    /// offer and independently owned task are rederived from their evidence;
    /// recipient-replacement support alone does not license mixed adoption.
    static func compile(_ row: RuntimeWorkedExample, approved: [String:RuntimeRecipientReplacement.ApprovedIdentity]) -> Program? {
        guard let whole = RuntimeRecipientReplacement.compile(row,approved:approved),
              let object = try? JSONSerialization.jsonObject(with:Data(row.payload.utf8)) as? [String:Any],
              let solution = object["solution"] as? [String:Any],let items = solution["new_items"] as? [[String:Any]] else { return nil }
        var offered: String? = nil,own = false
        for item in items {
            guard let evidence = item["evidence"] as? [[String:Any]],evidence.count == 1,
                  let text = RuntimeRecipientReplacement.exactEvidence(evidence[0],source:row.input.utterance) else { continue }
            if item["accepted"] as? Bool == false {
                let pattern = #"I am trying to sort out the family visit without turning everyone else's plans into my own jobs\.\s*("# + person + #")\s+has already offered to\s+(.+?),\s*but I have not accepted that offer\.\s*Keep it as an unaccepted offer for now\."#
                guard let f = exact(text,pattern),RuntimeRecipientReplacement.literalRecipient(f[0]),
                      item["kind"] as? String == "note",item["destination"] as? String == "Memory",
                      same(item["actor"] as? String ?? "",f[0]),
                      same(item["meaning"] as? String ?? "",f[0] + " offered to " + f[1] + "; offer not accepted"),
                      let action = exact(f[1],physical + #"\s+(.+)"#),nominal(action[0]),offered == nil else { return nil }
                offered = f[0]
            } else if item["actor"] as? String == "user" {
                let pattern = #"I will\s+("# + physical + #"\s+.+?)\s+(january|february|march|april|may|june|july|august|september|october|november|december)\s+([0-9]{1,2})\.\s*That is the definite part I am taking responsibility for, rather than the job I just mentioned for (.+)\."#
                guard let f = exact(text,pattern),item["kind"] as? String == "task",item["destination"] as? String == "Today",
                      same(item["meaning"] as? String ?? "",f[0]),let timing = item["timing"] as? [String:Any],
                      timing["kind"] as? String == "dateOnly",timing["requested_alert"] as? Bool == false,
                      timing["time"] is NSNull,
                      exact(f[0],#"put\s+the\s+(.+)\s+in\s+the\s+(car|van|truck)"#).map({ nominal($0[0]) }) == true else { return nil }
                // The exact reviewed answer's sibling clock cannot propagate
                // into any current item; compilation stores no clock at all.
                own = true
            }
        }
        guard offered != nil,own else { return nil };return .init(provenance:whole)
    }
    /// Provisional proof against an exact range in the WHOLE source. Caller
    /// must reconcile all remaining frames before emitting any effects.
    static func readFrame(_ source: String,from position: String.Index,referenceDate: Date,calendar: Calendar) -> Frame? {
        guard !Task.isCancelled else { return nil }
        func next(_ pattern: String) -> (Range<String.Index>,[String])? {
            RuntimeRecipientReplacement.match(source,from:position,pattern:pattern)
        }
            let frame: Frame
            if let (r,f) = next(#"Inventory only:\s*(.+?)\s+are already in the\s+(crate|cabinet|box|cupboard|drawer|bin)\.\s*Keep those counts as reference, nothing to buy or pack[.!](?=\s|$)"#) {
                guard let members = inventoryMembers(f[0]) else { return nil };frame = .inventory(r,members)
            } else if let (r,f) = next(#"(?:My task is to|I will|I need to|I have to)\s+("# + physical + #"\s+.+?)\s+on\s+([^.!?;]+)[.!](?=\s|$)"#) {
                guard let object = exact(f[0],physical + #"\s+(.+)"#),nominal(object[0]),
                      let (date,intent) = clock(f[1],referenceDate:referenceDate,calendar:calendar,source:String(source[r])),
                      intent.kind == .dateOnly else { return nil }
                frame = .own(r,f[0] + " on " + f[1],date,intent)
            } else if let (r,f) = next(#"Remind me\s+([^.!?;]+?)\s+to return\s+("# + person + #")['’]s\s+(.+?)\s+to\s+("# + person + #");\s*("# + person + #")\s+owns it and\s+("# + person + #")\s+is only receiving it[.!](?=\s|$)"#) {
                guard f.count == 6,RuntimeRecipientReplacement.literalRecipient(f[1]),RuntimeRecipientReplacement.literalRecipient(f[3]),
                      same(f[1],f[4]),same(f[3],f[5]),!same(f[1],f[3]),nominal(f[2]),
                      let (date,intent) = clock(f[0],referenceDate:referenceDate,calendar:calendar,source:String(source[r])),
                      intent.kind == .exactDateTime else { return nil }
                frame = .transfer(r,"Return " + f[1] + "’s " + f[2] + " to " + f[3],f[1],f[3],date,intent)
            } else if let (r,f) = next("(" + person + #")\s+offered to\s+("# + physical + #"\s+.+?),\s*but I have not accepted the offer[.!](?=\s|$)"#) {
                guard RuntimeRecipientReplacement.literalRecipient(f[0]),
                      let object = exact(f[1],physical + #"\s+(.+)"#),nominal(object[0]) else { return nil }
                let clause = f[0] + " offered to " + f[1]
                let scope = ClauseScope.read(clause)
                guard scope.act == .reporting,scope.speaker.map({ same($0,f[0]) }) == true,
                      scope.actor == .other(f[0]),scope.complement.map({ same($0,"to " + f[1]) }) == true else { return nil }
                frame = .offer(r,f[0],f[1])
            } else { return nil }
        return frame
    }
    static func graph(_ source: String, referenceDate: Date, calendar: Calendar) -> [Frame]? {
        guard QuotedSpeechScope.ranges(in:source).isEmpty else { return nil }
        var frames: [Frame] = [],position = source.startIndex,kinds = Set<String>()
        while position < source.endIndex {
            while position < source.endIndex,source[position].isWhitespace { position = source.index(after:position) }
            if position == source.endIndex { break }
            guard let frame = readFrame(source,from:position,referenceDate:referenceDate,calendar:calendar) else { return nil }
            guard kinds.insert(frame.kind).inserted else { return nil };frames.append(frame);position = frame.range.upperBound
        }
        guard kinds == ["inventory","own","transfer","offer"],
              RuntimeProposalGuard.covers(source,quotes:frames.map { String(source[$0.range]) }) else { return nil }
        return frames
    }
    static func interpret(_ source: String,examples: [RuntimeWorkedExample],referenceDate: Date,
                          calendar: Calendar,configuration: RuntimeExampleConfiguration? = nil) -> ThoughtExtractionResult? {
        guard !Task.isCancelled,let graph = graph(source,referenceDate:referenceDate,calendar:calendar),
              let cfg = configuration ?? RuntimeExampleConfiguration.current,
              let approved = RuntimeRecipientReplacement.approvedIdentities(cfg),
              let program = examples.compactMap({ compile($0,approved:approved) }).first else { return nil }
        let ledger = SourceUnitLedger(source);var seen = Set<Int>(),items: [ExtractedThought] = []
        for frame in graph {
            let ids = ledger.ids(in:frame.range),raw = String(source[frame.range])
            guard !ids.isEmpty,seen.isDisjoint(with:ids) else { return nil };seen.formUnion(ids)
            let action: String,organization: OrganizedThought
            switch frame {
            case .inventory: action = raw;organization = memory()
            case .offer(_,let actor,let offered):
                action = actor + " offered to " + offered + "; offer not accepted";organization = memory()
            case .own(_,let a,let date,let intent):
                action = a;organization = .init(itemType:.task,category:.general,priority:.normal,personName:nil,
                    dueDate:date,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,needsClarification:false,temporalIntent:intent,state:.resolved)
            case .transfer(_,let a,_,let recipient,let date,let intent):
                action = a;organization = .init(itemType:.task,category:.general,priority:.normal,personName:recipient,
                    dueDate:date,reminderDate:date,reminderDelivery:.notification,recurrenceRule:nil,needsClarification:false,temporalIntent:intent,state:.resolved)
            }
            // Certified surface wording is kept intact: title transforms must
            // not remove possession, a negative adoption or a literal recipient.
            items.append(.init(sourceQuote:raw,rawQuote:raw,wasRepaired:false,analysisText:action,
                suggestedTitle:action,organization:organization,confidence:1,needsReview:false,sourceUnitIDs:ids))
        }
        guard seen == Set(ledger.words.indices),!Task.isCancelled else { return nil }
#if DEBUG
        let p = program.provenance
        RuntimeExampleLibrary.developmentObserver?("analogy consumed=\(p.referenceID) program=mixed-purpose-adoption runtimeReencodedPayloadSHA=\(p.runtimePayloadSHA256) inputSHA=\(p.inputSHA256) solutionSHA=\(p.solutionSHA256) current-source-bound=true completeFrames=\(items.count)")
#endif
        return .init(items:items,method:.rules)
    }
    private static func memory() -> OrganizedThought {
        .init(itemType:.note,category:.general,priority:.normal,personName:nil,dueDate:nil,reminderDate:nil,
            reminderDelivery:.none,recurrenceRule:nil,needsClarification:false,state:.resolved)
    }
}


/// A selected approved answer can demonstrate a direct recipient replacement.
/// Current occurrence frames independently prove the unchanged question and
/// every sibling. The program retains provenance, never reference values.
enum RuntimeRecipientReplacement {
    struct Program {
        let referenceID: String
        let runtimePayloadSHA256: String
        let inputSHA256: String
        let solutionSHA256: String
    }
    struct Replacement {
        let old: String
        let new: String
        let subject: String
        var action: String { "Ask \(new) about \(subject)" }
    }
    struct ApprovedIdentity { let input: String; let solution: String; let blueprint: String }
    private struct Frame {
        let range: Range<String.Index>
        let kind: ItemType
        let action: String
        let person: String?
    }
    static func normalize(_ value: String) -> String {
        value.lowercased().replacingOccurrences(of:"’",with:"'")
            .replacingOccurrences(of:"-",with:" ")
            .replacingOccurrences(of:#"^\s*(?:the|a|an)\s+"#,with:"",options:.regularExpression)
            .trimmingCharacters(in:.whitespacesAndNewlines.union(.punctuationCharacters))
            .replacingOccurrences(of:#"\s+"#,with:" ",options:.regularExpression)
    }
    static func match(_ source: String, from start: String.Index, pattern: String)
        -> (Range<String.Index>, [String])? {
        guard let regex = NSRegularExpression.speakItCached("(?is)" + pattern),
              let m = regex.firstMatch(in:source,range:NSRange(start..<source.endIndex,in:source)),
              let range = Range(m.range,in:source),range.lowerBound == start else { return nil }
        return (range,(1..<m.numberOfRanges).map {
            Range(m.range(at:$0),in:source).map { String(source[$0]) } ?? ""
        })
    }
    private static var contact: String {
        "(?:" + PersonMentionResolver.communicationRelationPhrasePattern
            + #"|\p{L}[\p{L}\p{M}'’-]*(?:\s+\p{L}[\p{L}\p{M}'’-]*)?)"#
    }
    static func literalRecipient(_ text: String) -> Bool {
        let words = text.lowercased().replacingOccurrences(of:"’",with:"'").split(whereSeparator: { $0.isWhitespace }).map(String.init)
        guard let first = words.first else { return false }
        let head = first.hasSuffix("'s") ? String(first.dropLast(2)) : first
        guard !Set(["i","me","we","us","you","him","her","them","he","she","they","it","this","that","someone","somebody","anyone","anybody","everyone","everybody","nobody","myself","ourselves","a","an","another","some","any","other"]).contains(head) else { return false }
        if ["his","her","their","its"].contains(first) { return false }
        if ["my","our","your","the"].contains(first) {
            let value = text + " about"
            guard let regex = NSRegularExpression.speakItCached("(?i)^(?:" + PersonMentionResolver.communicationRelationPhrasePattern + ")(?=\\s+about$)"),
                  let m = regex.firstMatch(in:value,range:NSRange(value.startIndex...,in:value)),
                  let range = Range(m.range,in:value),String(value[range]) == text else { return false }
        }
        return true
    }
    private static func safeSubject(_ text: String) -> Bool {
        !text.isEmpty && text.count <= 160
            && text.range(of:#"^[\p{L}\p{M}'’ -]+$"#,options:.regularExpression) != nil
            && text.range(of:#"(?i)\b(?:and|or|plus|also|but|yet|then|so|if|unless|when|before|after|instead|actually|not|never|saved|existing|today|tomorrow|tonight|every|monday|tuesday|wednesday|thursday|friday|saturday|sunday|january|february|march|april|may|june|july|august|september|october|november|december|remind|alert|notify)\b|(?:^|\s)-+(?:\s|$)|--|[0-9,;:.!?"“”]"#,options:.regularExpression) == nil
    }
    static func referenceReplacement(_ text: String) -> Replacement? {
        let pattern = #"(?:I\s+(?:also\s+)?(?:need|have)\s+to\s+)?ask\s+("# + contact
            + #")\s+about\s+([^.!?;]+)[.!]\s*No,\s*that\s+question\s+should\s+go\s+to\s+("# + contact
            + #"),\s*not\s+("# + contact
            + #"),\s*because\s+I\s+mixed\s+up\s+who\s+is\s+handling\s+that\s+part[.!]\s*The\s+question\s+itself\s+has\s+not\s+changed[.!]?"#
        guard let (range,f) = match(text,from:text.startIndex,pattern:pattern),range.upperBound == text.endIndex,
              f.count == 4,literalRecipient(f[0]),literalRecipient(f[2]),
              normalize(f[0]) == normalize(f[3]),normalize(f[0]) != normalize(f[2]),
              safeSubject(f[1]),QuotedSpeechScope.ranges(in:text).isEmpty else { return nil }
        return .init(old:f[0],new:f[2],subject:f[1])
    }
    static func exactEvidence(_ row: [String:Any], source: String) -> String? {
        guard Set(row.keys) == ["start","end","text"],
              let a = row["start"] as? Int,let b = row["end"] as? Int,
              let text = row["text"] as? String,a >= 0,b > a,b <= source.unicodeScalars.count else { return nil }
        let scalars = source.unicodeScalars
        let lo = scalars.index(scalars.startIndex,offsetBy:a),hi = scalars.index(scalars.startIndex,offsetBy:b)
        return scalars[lo..<hi].elementsEqual(text.unicodeScalars) ? text : nil
    }
    /// Exact review membership is a prerequisite, separate from the semantic
    /// delta proof below. It cannot turn a generated answer into approval.
    static func approvedIdentities(_ configuration: RuntimeExampleConfiguration) -> [String:ApprovedIdentity]? {
        let url = configuration.libraryURL.deletingLastPathComponent().appendingPathComponent("runtime-reference-manifest.json")
        guard let bytes = try? Data(contentsOf:url),
              SHA256.hash(data:bytes).map({ String(format:"%02x",$0) }).joined()
                == "8931002a927214dcd4e9da2c2ec0ca6fdce104416f2ab38a76308533ee8f92fd",
              let object = try? JSONSerialization.jsonObject(with:bytes) as? [String:Any],
              object["approvedCandidateSHA256"] as? String == configuration.expectedSHA256,
              let rows = object["records"] as? [[String:Any]],rows.count == 59 else { return nil }
        var result: [String:ApprovedIdentity] = [:]
        for row in rows {
            guard let id = row["id"] as? String,let input = row["input_sha256"] as? String,
                  let solution = row["solution_sha256"] as? String,let blueprint = row["blueprint"] as? String,
                  result[id] == nil else { return nil }
            result[id] = .init(input:input,solution:solution,blueprint:blueprint)
        }
        return result
    }
    static func digest(_ value: Any) -> String? {
        guard let bytes = try? JSONSerialization.data(withJSONObject:value,options:[.sortedKeys,.withoutEscapingSlashes]) else { return nil }
        return SHA256.hash(data:bytes).map { String(format:"%02x",$0) }.joined()
    }
    static func compile(_ example: RuntimeWorkedExample, approved: [String:ApprovedIdentity]) -> Program? {
        guard example.approval.production_eligible,let reviewed = approved[example.id],
              reviewed.blueprint == example.provenance.blueprint,
              let record = try? JSONSerialization.jsonObject(with:Data(example.payload.utf8)) as? [String:Any],
              let solution = record["solution"] as? [String:Any],
              Set(solution.keys) == ["clarifications","external_actions","extra_actionable_items_allowed","groups",
                 "mutations","new_items","operation_receipts","original_transcript","relationship_policy","unmentioned_saved_fields"],
              solution["external_actions"] as? String == "none",
              solution["extra_actionable_items_allowed"] as? Bool == false,
              solution["original_transcript"] as? String == "retain_exactly",
              solution["unmentioned_saved_fields"] as? String == "unchanged",
              solution["relationship_policy"] as? [String:Bool]
                == ["do_not_share_aliases_between_users":true,"invent_contact_bindings":false,"preserve_spoken_relationships":true],
              ["clarifications","mutations","operation_receipts"].allSatisfy({ (solution[$0] as? [Any])?.isEmpty == true }),
              let items = solution["new_items"] as? [[String:Any]],let groups = solution["groups"] as? [[String:Any]],
              let inputSHA = record["input_sha256"] as? String,inputSHA.count == 64,
              let solutionSHA = record["solution_sha256"] as? String,solutionSHA.count == 64,
              inputSHA == reviewed.input,solutionSHA == reviewed.solution,
              let input = record["input"],digest(input) == inputSHA,digest(solution) == solutionSHA,
              let approval = record["approval"] as? [String:Any],approval["status"] as? String == "externally_reviewed",
              let review = approval["review_evidence"] as? [String:Any],review["decision"] as? String == "approve" else { return nil }
        var coverage: [String] = []
        var replacementCount = 0
        for item in items {
            guard Set(item.keys).isSubset(of:["accepted","actor","committed","destination","evidence","kind","local_id",
                "meaning","recipient","withdrawn_recipient","timing"]),
                  let kind = item["kind"] as? String,["task","note","idea"].contains(kind),
                  item["destination"] as? String == (kind == "task" ? "Today" : "Memory"),
                  let evidence = item["evidence"] as? [[String:Any]],!evidence.isEmpty,
                  let meaning = item["meaning"] as? String,!meaning.isEmpty else { return nil }
            let quotes = evidence.compactMap { exactEvidence($0,source:example.input.utterance) }
            guard quotes.count == evidence.count else { return nil };coverage += quotes
            if item["withdrawn_recipient"] != nil {
                guard Set(item.keys) == ["destination","evidence","kind","local_id","meaning","recipient","withdrawn_recipient"],
                      kind == "task",quotes.count == 1,let delta = referenceReplacement(quotes[0]),
                      normalize(item["recipient"] as? String ?? "") == normalize(delta.new),
                      normalize(item["withdrawn_recipient"] as? String ?? "") == normalize(delta.old),
                      normalize(meaning) == normalize(delta.action) else { return nil }
                replacementCount += 1
            }
        }
        for group in groups {
            guard Set(group.keys).isSubset(of:["destination","entries","evidence","local_id","purpose"]),
                  group["destination"] as? String == "Today",group["purpose"] as? String == "shopping",
                  let entries = group["entries"] as? [[String:Any]],!entries.isEmpty,
                  let evidence = group["evidence"] as? [[String:Any]],!evidence.isEmpty else { return nil }
            let quotes = evidence.compactMap { exactEvidence($0,source:example.input.utterance) }
            guard quotes.count == evidence.count else { return nil };coverage += quotes
        }
        guard replacementCount == 1,RuntimeProposalGuard.covers(example.input.utterance,quotes:coverage) else { return nil }
        return .init(referenceID:example.id,
            runtimePayloadSHA256:SHA256.hash(data:Data(example.payload.utf8)).map { String(format:"%02x",$0) }.joined(),
            inputSHA256:inputSHA,solutionSHA256:solutionSHA)
    }
    private static func currentReplacement(_ source: String,from start: String.Index)
        -> (Range<String.Index>,Replacement)? {
        let pattern = #"I\s+first\s+thought\s+I\s+should\s+ask\s+("# + contact
            + #")\s+about\s+([^,.!?;]+),\s*but\s+it\s+should\s+be\s+("# + contact
            + #")\s+instead,\s*same\s+([^,.!?;]+)\s+question[.!](?=\s|$)"#
        guard let (range,f) = match(source,from:start,pattern:pattern),f.count == 4,
              literalRecipient(f[0]),literalRecipient(f[2]),
              normalize(f[1]) == normalize(f[3]),normalize(f[0]) != normalize(f[2]),
              safeSubject(f[1]),safeSubject(f[3]) else { return nil }
        return (range,.init(old:f[0],new:f[2],subject:f[1]))
    }
    /// Independent complete CURRENT grammar shared with proposal lowering.
    /// This reads no reference and is not a worked-example benefit.
    static func currentFrames(_ source: String) -> [(kind:ItemType,action:String,person:String?)]? {
        frames(source,requiresReplacement:false).map { $0.map { (kind:$0.kind,action:$0.action,person:$0.person) } }
    }
    private static func frames(_ source: String, requiresReplacement: Bool = true) -> [Frame]? {
        guard QuotedSpeechScope.ranges(in:source).isEmpty else { return nil }
        var position = source.startIndex,frames: [Frame] = [],corrections = 0
        func skipSpace() { while position < source.endIndex,source[position].isWhitespace { position = source.index(after:position) } }
        skipSpace()
        while position < source.endIndex {
            let start = position
            if let (range,delta) = currentReplacement(source,from:start) {
                guard corrections == 0 else { return nil };corrections += 1
                frames.append(.init(range:range,kind:.task,action:delta.action,person:delta.new));position = range.upperBound
            } else if let (range,f) = match(source,from:start,pattern:
                #"About\s+([^,.!?;]+),\s*I\s+keep\s+mixing\s+up\s+who\s+I\s+need\s+to\s+speak\s+to[.!](?=\s|$)"#) {
                guard frames.isEmpty,safeSubject(f[0]) else { return nil }
                frames.append(.init(range:range,kind:.note,action:String(source[range]),person:nil));position = range.upperBound
            } else if let (range,f) = match(source,from:start,pattern:
                "(" + contact + #")\s+has\s+([^.!?;]+);\s*that\s+is\s+a\s+fact\s+about\s+possession,\s*not\s+a\s+return\s+request[.!](?=\s|$)"#) {
                guard safeSubject(f[1]) else { return nil }
                frames.append(.init(range:range,kind:.note,action:String(source[range]),person:nil));position = range.upperBound
            } else if let (range,f) = match(source,from:start,pattern:
                #"Tell\s+(\p{L}[\p{L}\p{M}'’-]*)\s+to\s+ask\s+their\s+("# + PersonMentionResolver.communicationRelationPhrasePattern
                + #")\s+about\s+([^.!?;]+)[.!]\s*That\s+is\s+(\p{L}[\p{L}\p{M}'’-]*)['’]s\s+("# + PersonMentionResolver.communicationRelationPhrasePattern
                + #"),\s*not\s+mine;\s*I\s+am\s+contacting\s+(\p{L}[\p{L}\p{M}'’-]*)[.!](?=\s|$)"#) {
                guard f.count == 6,literalRecipient(f[0]),normalize(f[0]) == normalize(f[3]),normalize(f[0]) == normalize(f[5]),
                      normalize(f[1]) == normalize(f[4]),safeSubject(f[2]) else { return nil }
                let action = "Tell \(f[0]) to ask their \(f[1]) about \(f[2])"
                frames.append(.init(range:range,kind:.task,action:action,person:f[0]));position = range.upperBound
            } else if let (range,f) = match(source,from:start,pattern:
                #"I\s+might\s+((?:sketch|design|draft|imagine|write|make)\s+[^.!?;,]+)\s+someday,\s*with\s+no\s+commitment[.!](?=\s|$)"#) {
                guard f[0].range(of:#"(?i)\b(?:and|or|plus|also|but|yet|then|so|if|unless|instead|actually|will|must|need|remind|alert|notify)\b|(?:^|\s)-+(?:\s|$)|--|[:,"“”—–(){}\[\]]"#,options:.regularExpression) == nil else { return nil }
                frames.append(.init(range:range,kind:.idea,action:String(source[range]),person:nil));position = range.upperBound
            } else if let (range,f) = match(source,from:start,pattern:
                #"The\s+firm\s+part\s+is\s+to\s+((?:print|clean|dust|wash|test|check|finish|fix|repair|count|scan|polish|measure|sort|label|sharpen|tighten)\s+[^.!?;]+)[.!](?=\s|$)"#) {
                guard f[0].range(of:#"(?i)\b(?:and|or|plus|also|but|yet|then|so|if|unless|when|before|after|instead|actually|not|never|no|longer|saved|existing|remind|alert|notify|i|we|you|he|she|they|will|would|should|must|want|need)\b|(?:^|\s)-+(?:\s|$)|--|[:,"“”—–(){}\[\]]"#,options:.regularExpression) == nil else { return nil }
                frames.append(.init(range:range,kind:.task,action:f[0],person:nil));position = range.upperBound
            } else if let (range,_) = match(source,from:start,pattern:
                #"There\s+is\s+no\s+timed\s+alert\s+in\s+this\s+capture[.!]?\s*$"#) {
                guard let last = frames.last,last.kind == .task,last.person == nil else { return nil }
                frames[frames.count-1] = .init(range:last.range.lowerBound..<range.upperBound,
                    kind:last.kind,action:last.action,person:nil);position = range.upperBound
            } else { return nil }
            skipSpace()
        }
        guard (requiresReplacement ? corrections == 1 : corrections <= 1),!frames.isEmpty,
              RuntimeProposalGuard.covers(source,quotes:frames.map { String(source[$0.range]) }) else { return nil }
        return frames
    }
    static func ownClock(_ action: String, reading: OrganizedThought,referenceDate: Date,calendar: Calendar) -> Bool {
        let months = ["january":1,"february":2,"march":3,"april":4,"may":5,"june":6,
            "july":7,"august":8,"september":9,"october":10,"november":11,"december":12]
        let pattern = #"(?:print|clean|dust|wash|test|check|finish|fix|repair|count|scan|polish|measure|sort|label|sharpen|tighten)\s+(.+?)\s+on\s+(january|february|march|april|may|june|july|august|september|october|november|december)\s+([0-9]{1,2})(?:st|nd|rd|th)?(?:,?\s+([0-9]{4}))?"#
        if let (range,f) = match(action,from:action.startIndex,pattern:pattern),range.upperBound == action.endIndex {
            guard f.count == 4,safeSubject(f[0]),let month = months[f[1].lowercased()],let day = Int(f[2]),
                  let stored = reading.temporalIntent.day,reading.temporalIntent.kind == .dateOnly,
                  reading.temporalIntent.time == nil,stored.month == month,stored.day == day,
                  (1...12).contains(month),(1...31).contains(day) else { return false }
            let years: [Int]
            if !f[3].isEmpty {
                guard let year = Int(f[3]) else { return false };years = [year]
            } else {
                let year = calendar.component(.year,from:referenceDate);years = Array(year...year+8)
            }
            let expected = years.compactMap { year -> Date? in
                guard let date = calendar.date(from:DateComponents(year:year,month:month,day:day)),
                      calendar.component(.year,from:date) == year,calendar.component(.month,from:date) == month,
                      calendar.component(.day,from:date) == day,
                      !f[3].isEmpty || date >= calendar.startOfDay(for:referenceDate) else { return nil }
                return date
            }.first
            guard let expected,CalendarDay(from:expected,calendar:calendar) == stored,
                  reading.dueDate == calendar.startOfDay(for:expected) else { return false }
            return true
        }
        // An undated own task still needs an independent single-object
        // proof. Punctuation cannot hide a second imperative in one row.
        guard let (range,f) = match(action,from:action.startIndex,pattern:
            #"(?:print|clean|dust|wash|test|check|finish|fix|repair|count|scan|polish|measure|sort|label|sharpen|tighten)\s+(.+)"#),
              range.upperBound == action.endIndex,f.count == 1,safeSubject(f[0]) else { return false }
        return reading.dueDate == nil && reading.temporalIntent.kind == .none
            && action.range(of:#"(?i)\b(?:on|by|at|tomorrow|today|tonight|next|monday|tuesday|wednesday|thursday|friday|saturday|sunday|january|february|march|april|may|june|july|august|september|october|november|december)\b"#,options:.regularExpression) == nil
    }
    static func interpret(_ source: String, examples: [RuntimeWorkedExample],referenceDate: Date,
                          calendar: Calendar, configuration: RuntimeExampleConfiguration? = nil) -> ThoughtExtractionResult? {
        guard !Task.isCancelled,let graph = frames(source),
              let configuration = configuration ?? RuntimeExampleConfiguration.current,
              let approved = approvedIdentities(configuration),
              let program = examples.compactMap({ compile($0,approved:approved) }).first else { return nil }
        let ledger = SourceUnitLedger(source)
        var items: [ExtractedThought] = [],seen = Set<Int>()
        for frame in graph {
            let ids = ledger.ids(in:frame.range)
            guard !ids.isEmpty,seen.isDisjoint(with:ids) else { return nil };seen.formUnion(ids)
            let organization: OrganizedThought
            if frame.kind == .task {
                let reading = ThoughtOrganizer.organize(frame.action,referenceDate:referenceDate,calendar:calendar)
                guard reading.itemType.isActionable,!reading.needsClarification,
                      reading.reminderDate == nil,reading.reminderDelivery == .none,
                      reading.locationIntent == nil,reading.recurrenceRule == nil else { return nil }
                if frame.person != nil {
                    guard reading.dueDate == nil,reading.temporalIntent.kind == .none else { return nil }
                } else {
                    guard ownClock(frame.action,reading:reading,referenceDate:referenceDate,calendar:calendar) else { return nil }
                }
                organization = .init(itemType:.task,category:reading.category,priority:reading.priority,
                    personName:frame.person,dueDate:reading.dueDate,reminderDate:nil,reminderDelivery:.none,
                    recurrenceRule:nil,needsClarification:false,temporalIntent:reading.temporalIntent,state:.resolved)
            } else {
                organization = .init(itemType:frame.kind,category:frame.kind == .idea ? .ideas : .general,
                    priority:.normal,personName:nil,dueDate:nil,reminderDate:nil,reminderDelivery:.none,
                    recurrenceRule:nil,needsClarification:false,state:.resolved)
            }
            let raw = String(source[frame.range])
            items.append(.init(sourceQuote:raw,rawQuote:raw,wasRepaired:false,analysisText:frame.action,
                suggestedTitle:frame.kind == .task ? ThoughtTitleFormatter.polished(frame.action,itemType:.task) : nil,
                organization:organization,confidence:1,needsReview:false,sourceUnitIDs:ids))
        }
        guard seen == Set(ledger.words.indices),!Task.isCancelled else { return nil }
#if DEBUG
        RuntimeExampleLibrary.developmentObserver?("analogy consumed=\(program.referenceID) program=direct-recipient-replacement runtimeReencodedPayloadSHA=\(program.runtimePayloadSHA256) inputSHA=\(program.inputSHA256) solutionSHA=\(program.solutionSHA256) current-source-bound=true completeFrames=\(items.count)")
#endif
        return .init(items:items,method:.rules)
    }
}


/// A bounded proposition graph, rather than a capture-wide actionability bit.
/// Attributed language and its scoped refusal stay in Memory; an explicitly
/// adopted own task has a separate current-source span and clock. All frames
/// are reconciled before any output. A reviewed quote/refusal demonstration
/// supplies that purpose projection, never its speaker, relatives or content.
enum RuntimeCommitmentAnalogy {
    enum Kind: Equatable { case attributedQuote, recordedRequest, ownTask, separateNote }
    struct Frame {
        let kind: Kind
        let range: Range<String.Index>
        let quote: String
        let speaker: String?
        let recipient: String?
        let proposition: String
        let adopted: Bool
    }
    struct Program {
        let referenceID: String
        let runtimePayloadSHA256: String
        let inputSHA256: String
        let solutionSHA256: String
        let operation = "attributed quote with scoped explicit refusal stays Memory"
    }
    private static func match(_ pattern: String, _ source: String, from start: String.Index)
        -> (Range<String.Index>, [String])? {
        guard let regex = NSRegularExpression.speakItCached(pattern),
              let found = regex.firstMatch(in: source, range: NSRange(start..<source.endIndex,in:source)),
              let range = Range(found.range,in:source), range.lowerBound == start else { return nil }
        return (range,(1..<found.numberOfRanges).map { index in
            Range(found.range(at:index),in:source).map { String(source[$0]) } ?? ""
        })
    }
    static func graph(_ source: String) -> [Frame]? {
        var frames: [Frame] = [], position = source.startIndex
        func skipSpace() { while position < source.endIndex, source[position].isWhitespace { position = source.index(after:position) } }
        // Each refusal must immediately modify its one preceding report/quote.
        // Later adoption, an additional quoted speaker, unresolved pronouns or
        // corrections cannot pass as an already reconciled frame.
        let quoted = #"(?is)(?:([\p{L}][\p{L}'’ -]{0,100}?)\s+(?:said|wrote),?\s*|([\p{L}][\p{L}'’ -]{0,100}?)[’']s\s+note\s+was\s*)[\"“]([^\"“”]+)[\"”]\s*[;.!]?\s*I\s+(?:have\s+not\s+agreed\s+to\s+pass\s+that\s+on|am\s+not\s+adopting\s+that(?:\s+either)?)\s*[.!](?:\s*Keep\s+(?:her|his|their)\s+request\s+as\s+a\s+note,\s*not\s+a\s+job\s+for\s+me[.!])?"#
        let report = #"(?is)([\p{L}][\p{L}'’ -]{0,100}?)\s+asked\s+([\p{L}][\p{L}'’ -]{0,100}?)\s+to\s+([^.!?\"“”;]+)[.!]\s*I\s+am\s+recording\s+their\s+conversation\s+and\s+have\s+not\s+taken\s+over\s+([\p{L}][\p{L}'’ -]{0,100}?)[’']s\s+job[.!]"#
        let own = #"(?is)My\s+own\s+task\s+is\s+to\s+([^.!?\"“”;]+)[.!](?=\s|$)"#
        skipSpace()
        while position < source.endIndex {
            let start = position
            if let (range,values) = match(quoted,source,from:start) {
                let speaker = values[0].isEmpty ? values[1] : values[0]
                guard !speaker.isEmpty, !values[2].trimmingCharacters(in:.whitespacesAndNewlines).isEmpty,
                      speaker.range(of:#"(?i)\b(?:i|you|he|she|they|it|said|wrote|asked|and|or)\b"#,options:.regularExpression) == nil else { return nil }
                let recipient = RuntimeCommunicationReading.read(values[2])?.recipient
                frames.append(.init(kind:.attributedQuote,range:range,quote:String(source[range]),speaker:speaker,
                    recipient:recipient,proposition:values[2],adopted:false)); position = range.upperBound
            } else if let (range,values) = match(report,source,from:start) {
                guard values[1].trimmingCharacters(in:.whitespacesAndNewlines).caseInsensitiveCompare(
                    values[3].trimmingCharacters(in:.whitespacesAndNewlines)) == .orderedSame,
                    values[0].range(of:#"(?i)\b(?:i|you|he|she|they|it|asked|and|or)\b"#,options:.regularExpression) == nil,
                    values[1].range(of:#"(?i)\b(?:i|you|he|she|they|it|asked|and|or)\b"#,options:.regularExpression) == nil else { return nil }
                frames.append(.init(kind:.recordedRequest,range:range,quote:String(source[range]),speaker:values[0],
                    recipient:values[1],proposition:values[2],adopted:false)); position = range.upperBound
            } else if let (range,values) = match(own,source,from:start) {
                let action = values[0].trimmingCharacters(in:.whitespacesAndNewlines)
                guard ActionabilityReader.read(action).belongsOnToday,
                      action.range(of:#"(?i)\b(?:said|wrote|asked|actually|instead|maybe|might|if|unless|until|after|before|once|when|while|not|never|saved|change|remove|cancel|withdraw|that|it|them|him|her|and|or|then|also|next)\b"#,options:.regularExpression) == nil else { return nil }
                frames.append(.init(kind:.ownTask,range:range,quote:String(source[range]),speaker:nil,
                    recipient:nil,proposition:action,adopted:true)); position = range.upperBound
            } else if let (range,values) = match(#"(?is)Also\s+keep\s+this\s+separate\s+note:\s*([^.!?\"“”]+[.!?]?)\s*$"#,source,from:start) {
                guard !ActionabilityReader.read(values[0]).belongsOnToday,
                      values[0].range(of:#"(?i)\b(?:my\s+own\s+task|also\s+keep\s+this\s+separate\s+note|actually|instead|agree|agreed|adopt|adopting|will|must|promised|need\s+to|have\s+to|then|and\s+(?:call|phone|print|buy|send|tell|ask|email|text|message|pack|clean|fix|return))\b"#,options:.regularExpression) == nil else { return nil }
                frames.append(.init(kind:.separateNote,range:range,quote:String(source[range]),speaker:nil,
                    recipient:nil,proposition:values[0],adopted:false)); position = range.upperBound
            } else { return nil }
            skipSpace()
        }
        let ownedActions = frames.filter { $0.adopted }.map { $0.proposition.lowercased().trimmingCharacters(in:.whitespacesAndNewlines) }
        guard Set(ownedActions).count == ownedActions.count,
              !frames.isEmpty, frames.contains(where: { $0.kind == .attributedQuote }),
              RuntimeProposalGuard.covers(source,quotes:frames.map(\.quote)) else { return nil }
        return frames
    }
    private static func evidence(_ item: [String:Any], source: String, frame: Frame) -> Bool {
        guard let spans = item["evidence"] as? [[String:Any]], spans.count == 1,
              let start = spans[0]["start"] as? Int, let end = spans[0]["end"] as? Int,
              let text = spans[0]["text"] as? String, start >= 0, end >= start,
              end <= source.unicodeScalars.count,
              let frameStart = frame.range.lowerBound.samePosition(in:source.unicodeScalars) else { return false }
        let scalars = source.unicodeScalars
        let lower = scalars.index(scalars.startIndex,offsetBy:start), upper = scalars.index(scalars.startIndex,offsetBy:end)
        return scalars[lower..<upper].elementsEqual(text.unicodeScalars)
            && frame.quote.unicodeScalars.elementsEqual(text.unicodeScalars)
            && scalars.distance(from:scalars.startIndex,to:frameStart) == start
    }
    static func compile(_ example: RuntimeWorkedExample) -> Program? {
        guard example.approval.production_eligible,
              let record = try? JSONSerialization.jsonObject(with:Data(example.payload.utf8)) as? [String:Any],
              let solution = record["solution"] as? [String:Any],
              Set(solution.keys).isSubset(of:["clarifications","external_actions","extra_actionable_items_allowed","groups","mutations","new_items","operation_receipts","original_transcript","relationship_policy","unmentioned_saved_fields"]),
              let relationships = solution["relationship_policy"] as? [String:Bool],
              relationships == ["do_not_share_aliases_between_users":true,"invent_contact_bindings":false,"preserve_spoken_relationships":true],
              solution["unmentioned_saved_fields"] as? String == "unchanged",
              let inputSHA = record["input_sha256"] as? String,inputSHA.count == 64,
              let solutionSHA = record["solution_sha256"] as? String,solutionSHA.count == 64,
              let frames = graph(example.input.utterance),frames.count == 2,
              frames[0].kind == .attributedQuote,frames[1].kind == .separateNote,
              solution["external_actions"] as? String == "none",solution["extra_actionable_items_allowed"] as? Bool == false,
              solution["original_transcript"] as? String == "retain_exactly",
              ["mutations","groups","clarifications","operation_receipts"].allSatisfy({ (solution[$0] as? [Any])?.isEmpty == true }),
              let answer = solution["new_items"] as? [[String:Any]],answer.count == frames.count,
              Set(answer[0].keys).isSubset(of:["adopted","destination","evidence","kind","local_id","meaning","quoted_recipient","quoted_speaker","recipient_anchor"]),
              Set(answer[1].keys).isSubset(of:["destination","evidence","kind","local_id","meaning"]),
              answer.indices.allSatisfy({ answer[$0]["destination"] as? String == "Memory"
                  && answer[$0]["kind"] as? String == "note" && evidence(answer[$0],source:example.input.utterance,frame:frames[$0]) }),
              answer[0]["adopted"] as? Bool == false,answer[0]["recipient_anchor"] as? String == "quoted_speaker",
              let speaker = answer[0]["quoted_speaker"] as? String,
              speaker.caseInsensitiveCompare(frames[0].speaker ?? "") == .orderedSame,
              answer[0]["quoted_recipient"] as? String == frames[0].recipient,
              let meaning = answer[0]["meaning"] as? String,
              let recipient = frames[0].recipient,
              frames[0].proposition.range(of:"Tell " + recipient + " ",options:.caseInsensitive)?.lowerBound == frames[0].proposition.startIndex,
              let note = answer[1]["meaning"] as? String,
              note.unicodeScalars.elementsEqual(frames[1].proposition.unicodeScalars) else { return nil }
        let prefix = "Tell " + recipient + " "
        let remainder = String(frames[0].proposition.dropFirst(prefix.count)).trimmingCharacters(in:.punctuationCharacters)
        let expected = (frames[0].speaker ?? "") + " asked for " + recipient + " to be told " + remainder + "; I have not agreed"
        guard meaning.caseInsensitiveCompare(expected) == .orderedSame else { return nil }
        return .init(referenceID:example.id,
            runtimePayloadSHA256:SHA256.hash(data:Data(example.payload.utf8)).map { String(format:"%02x",$0) }.joined(),
            inputSHA256:inputSHA,solutionSHA256:solutionSHA)
    }
    private static func completeContact(_ literal: String,in source: String) -> Bool {
        guard let range = source.range(of:literal) else { return false }
        let before = String(source[..<range.lowerBound]), after = String(source[range.upperBound...])
        guard before.last?.isLetter != true, after.first?.isLetter != true,
              after.range(of:#"^[’']s\s+"#,options:.regularExpression) == nil,
              before.range(of:#"\p{L}[’']s\s*$"#,options:.regularExpression) == nil else { return false }
        return true
    }
    static func interpret(_ source: String, examples: [RuntimeWorkedExample],referenceDate: Date,
                          calendar: Calendar) -> ThoughtExtractionResult? {
        guard let frames = graph(source),let program = examples.compactMap(compile).first else { return nil }
        let ledger = SourceUnitLedger(source)
        var items: [ExtractedThought] = []
        for frame in frames {
            let organization: OrganizedThought
            if frame.adopted {
                let reading = ThoughtOrganizer.organize(frame.proposition,referenceDate:referenceDate,calendar:calendar)
                guard reading.itemType.isActionable,!reading.needsClarification,
                      reading.locationIntent == nil,reading.recurrenceRule == nil else { return nil }
                // An object owner is not the contact of an adopted task.
                // Bind contact metadata only to a current direct communication
                // predicate; retain every owner in the task's complete wording.
                let communication = frame.proposition.range(of:#"(?i)^(?:ask|tell|call|phone|email|text|message)\s+"#,options:.regularExpression) != nil
                let contact: String?
                if let direct = RuntimeCommunicationReading.read(frame.proposition) { contact = direct.recipient }
                else if communication {
                    guard let literal = reading.personName,
                          frame.proposition.range(of:#"(?i)^(?:ask|tell|call|phone|email|text|message)\s+"#
                            + NSRegularExpression.escapedPattern(for:literal) + #"(?=\s|$)"#,options:.regularExpression) != nil,
                          completeContact(literal,in:frame.proposition) else { return nil }
                    contact = literal
                } else { contact = nil }
                organization = .init(itemType:reading.itemType == .personFollowUp && contact == nil ? .task : reading.itemType,
                    category:reading.category,priority:reading.priority,personName:contact,dueDate:reading.dueDate,
                    reminderDate:reading.reminderDate,reminderDelivery:reading.reminderDelivery,
                    recurrenceRule:reading.recurrenceRule,needsClarification:reading.needsClarification,
                    temporalIntent:reading.temporalIntent,locationIntent:reading.locationIntent,state:reading.state)
            } else {
                organization = .init(itemType:.note,category:.general,priority:.normal,personName:nil,dueDate:nil,
                    reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,needsClarification:false,state:.resolved)
            }
            items.append(.init(sourceQuote:frame.quote,rawQuote:frame.quote,wasRepaired:false,
                analysisText:frame.adopted ? frame.proposition : frame.quote,
                suggestedTitle:frame.adopted ? ThoughtTitleFormatter.polished(frame.proposition,itemType:organization.itemType) : nil,
                organization:organization,confidence:1,needsReview:false,sourceUnitIDs:ledger.ids(in:frame.range)))
        }
#if DEBUG
        RuntimeExampleLibrary.developmentObserver?("analogy consumed=\(program.referenceID) program=quoted-refusal runtimeReencodedPayloadSHA=\(program.runtimePayloadSHA256) inputSHA=\(program.inputSHA256) solutionSHA=\(program.solutionSHA256) quotedFrames=\(frames.filter { $0.kind == .attributedQuote }.count) independentCurrentFrames=\(frames.filter { $0.kind != .attributedQuote }.count) current-source-bound=true")
#endif
        return .init(items:items,method:.rules)
    }
}

/// A complete CURRENT report/refusal plan can prove ownership independently
/// of the model's row tags. Every frame and source unit must reconcile first;
/// a local task prefix, quoted instruction or retrieved answer cannot admit a
/// row. These proofs retain literal arguments, never resolve objects/contacts.
enum RuntimeRecordedCommitmentCertificate {
    struct Frame {
        let evidence: [Int]
        let adopted: Bool
        let action: String
        let organization: OrganizedThought
    }
    private static func exact(_ text:String,_ pattern:String) -> [String]? {
        guard let regex=NSRegularExpression.speakItCached("(?i)^(?:"+pattern+")$"),
              let found=regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)),
              let range=Range(found.range,in:text),range == text.startIndex..<text.endIndex else { return nil }
        return (1..<found.numberOfRanges).map { Range(found.range(at:$0),in:text).map { String(text[$0]) } ?? "" }
    }
    private static func literalActor(_ text:String) -> Bool {
        let person="(?:"+PersonMentionResolver.communicationRelationPhrasePattern
            + #"|\p{L}[\p{L}\p{M}'’-]*(?:\s+\p{L}[\p{L}\p{M}'’-]*)?)"#
        return exact(text,person) != nil && RuntimeRecipientReplacement.literalRecipient(text)
            && text.range(of:#"(?i)\b(?:and|or|but|then|also|said|wrote|asked|is|are|was|were|will|must|should)\b"#,options:.regularExpression) == nil
    }
    /// The explicit self-owned task supplies the argument's role. Unknown
    /// literal object words remain unchanged; they acquire no noun identity,
    /// saved-item target, contact, location, or external-action permission.
    private static func ownTask(_ action:String,referenceDate:Date,calendar:Calendar) -> OrganizedThought? {
        if let ordinary=RuntimeShortSourceCertificate.interpret(action,referenceDate:referenceDate,calendar:calendar),
           ordinary.items.count == 1,let item=ordinary.items.first,
           item.organization.itemType.isActionable,item.organization.itemType != .shopping,
           !item.needsReview,item.organization.reminderDelivery == .none {
            return item.organization
        }
        let day = #"(?:today|tomorrow|(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+[0-9]{1,2}(?:\s+[0-9]{4})?)"#
        let clock = day + #"(?:\s+at\s+(?:0?[1-9]|1[0-2])(?::[0-5][0-9])?\s+(?:AM|PM))?"#
        guard QuotedSpeechScope.ranges(in:action).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(action),
              let fields=exact(action,#"(weigh|measure|photograph|inspect|trim|trace|water|clean|wash|check|repair|fix|dust|test|polish|sort)\s+(.+?)(?:\s+("#+clock+"))?"),
              fields[1].count <= 120,
              exact(fields[1],#"(?:(?:a|an|the|my|our)\s+)?\p{L}[\p{L}\p{M}-]*(?:\s+\p{L}[\p{L}\p{M}-]*){0,3}"#) != nil,
              !fields[1].contains("--"),
              // An unknown inflected predicate cannot be certified as a
              // literal object when lexical-class assets are unavailable.
              fields[1].split(whereSeparator: { $0.isWhitespace }).allSatisfy({ token in
                  let word=token.lowercased()
                  return !word.hasSuffix("ed") && !word.hasSuffix("ing") && !word.hasSuffix("s")
              }),
              fields[1].range(of:#"(?i)\b(?:i|we|you|he|she|they|it|that|this|them|him|her|his|their|its|and|or|but|yet|then|also|plus|so|if|unless|until|when|once|after|before|while|because|since|actually|instead|not|never|no|saved|existing|is|are|am|was|were|has|have|had|will|would|shall|should|must|can|could|may|might|need|want|to|for|from|with|without|about|at|on|by|in|every|today|tomorrow|tonight|monday|tuesday|wednesday|thursday|friday|saturday|sunday|january|february|march|april|may|june|july|august|september|october|november|december|said|wrote|asked|agreed|adopted|flew|fell|broke|"#+ActionabilityReader.actionVerb+"|"+ActionabilityReader.headOnlyImperativeVerb+#")\b"#,options:.regularExpression) == nil,
              ActionabilityReader.read(action).belongsOnToday else { return nil }
        // The entire argument must also be temporally inert. A relative
        // clock that did not fit the strict final clock cannot silently become
        // object text or lose its date. Use the existing CURRENT resolver.
        let argument=ThoughtOrganizer.organize("Check "+fields[1],referenceDate:referenceDate,calendar:calendar)
        guard argument.dueDate == nil,argument.reminderDate == nil,
              argument.temporalIntent == .none,argument.locationIntent == nil,
              argument.recurrenceRule == nil else { return nil }
        let timing:(Date,TemporalIntent)?
        if fields[2].isEmpty { timing=nil }
        else {
            guard let bound=RuntimeIndependentFramePlan.clock(fields[2],referenceDate:referenceDate,calendar:calendar,source:action) else { return nil }
            timing=bound
        }
        return .init(itemType:.task,category:.general,priority:.normal,personName:nil,
            dueDate:timing?.0,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,
            needsClarification:false,temporalIntent:timing?.1 ?? .none,state:.resolved)
    }
    static func read(_ source:String,referenceDate:Date,calendar:Calendar) -> [Frame]? {
        guard !Task.isCancelled,!QuotedSpeechScope.hasUnclosedQuote(source),
              let graph=RuntimeCommitmentAnalogy.graph(source),
              graph.contains(where: { $0.kind == .ownTask }),
              graph.allSatisfy({ $0.kind != .separateNote }) else { return nil }
        let units=RuntimeIndexedSource(source)
        var result:[Frame]=[]
        for frame in graph {
            // Indexed ranges include the inter-sentence whitespace. Prove
            // the nonwhitespace unit span, then retain the original full range.
            let ids=units.units.indices.filter { id in
                let range=units.units[id].range
                let owned=source[range].indices.filter { !source[$0].isWhitespace }
                guard let first=owned.first,let last=owned.last else { return false }
                return first >= frame.range.lowerBound && source.index(after:last) <= frame.range.upperBound
            }
            guard !ids.isEmpty,ids == Array(ids.first!...ids.last!),
                  String(source[units.units[ids.first!].range.lowerBound..<units.units[ids.last!].range.upperBound])
                    .trimmingCharacters(in:.whitespacesAndNewlines) == frame.quote.trimmingCharacters(in:.whitespacesAndNewlines) else { return nil }
            let organization:OrganizedThought
            if frame.kind == .ownTask {
                guard frame.adopted,let current=ownTask(frame.proposition,referenceDate:referenceDate,calendar:calendar) else { return nil }
                organization=current
            } else {
                guard !frame.adopted,let speaker=frame.speaker,literalActor(speaker) else { return nil }
                if frame.kind == .recordedRequest {
                    guard let recipient=frame.recipient,literalActor(recipient),
                          frame.proposition.range(of:#"[,;:\n\r]|(?i:\b(?:i|we|you|he|she|they|my|our|actually|instead|then|also|but|and|or|because|since|if|unless|until|when|once|after|before|while|will|would|must|should)\b)"#,options:.regularExpression) == nil else { return nil }
                }
                // The attributed payload stays inside its exact quote; the
                // complete following own refusal governs adoption. No date,
                // contact or operation is interpreted from that payload.
                organization = .init(itemType:.note,category:.general,priority:.normal,personName:nil,
                    dueDate:nil,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,
                    needsClarification:false,state:.resolved)
            }
            result.append(.init(evidence:ids,adopted:frame.adopted,action:frame.adopted ? frame.proposition : frame.quote,organization:organization))
        }
        guard result.flatMap(\.evidence).sorted() == Array(units.units.indices) else { return nil }
        return result
    }
}

/// A complete explicit recording denial owns its denied complement; a
/// following first-person commitment owns only the separate literal chores.
/// This bounded current-source grammar supplies no contact or saved target.
/// Every frame must be present together before any row receives admission.
enum RuntimeDeniedRequestPlan {
    struct Frame {
        let anchor:String
        let adopted:Bool
        let organization:OrganizedThought
    }
    private static func exact(_ text:String,_ pattern:String)->[String]? {
        guard let regex=NSRegularExpression.speakItCached("(?i)^(?:"+pattern+")$"),
              let match=regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)),
              let range=Range(match.range,in:text),range == text.startIndex..<text.endIndex else { return nil }
        return (1..<match.numberOfRanges).map { Range(match.range(at:$0),in:text).map { String(text[$0]) } ?? "" }
    }
    private static func physical(_ action:String,referenceDate:Date,calendar:Calendar)->OrganizedThought? {
        guard let fields=exact(action,#"(wash|clean|dust|polish|inspect|repair|fix|water|trim|sort|check)\s+(.+)"#),
              fields[1].count <= 120,!fields[1].contains("--"),
              exact(fields[1],#"(?:(?:a|an|the|my|our)\s+)?[\p{L}\p{M}-]+(?:\s+[\p{L}\p{M}-]+){0,3}"#) != nil else { return nil }
        var words=fields[1].lowercased().split(whereSeparator:{$0.isWhitespace}).map(String.init)
        if ["a","an","the","my","our"].contains(words.first ?? "") { words.removeFirst() }
        let heads:Set<String>=["window","windows","kitchen","garage","floor","floors","dish","dishes","sink","table","desk","shelf","shelves","drawer","drawers","cabinet","cabinets","plant","plants","tray","trays","bowl","bowls"]
        let modifiers:Set<String>=["front","back","upper","lower","small","large","old","new","wooden","metal","plastic","ceramic","blue","red","green"]
        let household = !words.isEmpty && heads.contains(words.last ?? "")
            && words.dropLast().allSatisfy({modifiers.contains($0)})
        guard RuntimeCurrentNominalProof.read(fields[1]) || household,
              ActionabilityReader.read(action).belongsOnToday else { return nil }
        let organized=ThoughtOrganizer.organize(action,referenceDate:referenceDate,calendar:calendar)
        guard organized.personName == nil,organized.dueDate == nil,organized.reminderDate == nil,
              organized.reminderDelivery == .none,organized.temporalIntent == .none,
              organized.locationIntent == nil,organized.recurrenceRule == nil else { return nil }
        return .init(itemType:.task,category:.general,priority:.normal,personName:nil,
            dueDate:nil,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,
            needsClarification:false,temporalIntent:.none,state:.resolved)
    }
    static func read(_ units:RuntimeIndexedSource,referenceDate:Date,calendar:Calendar)->[Frame]? {
        guard !Task.isCancelled,units.units.count == 1,
              QuotedSpeechScope.ranges(in:units.source).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(units.source),
              CaptureOperationDetector.partitionWithOwnership(units.source).operations.isEmpty else { return nil }
        let body=units.source.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!")))
        let recipient="(?:"+PersonMentionResolver.communicationRelationPhrasePattern
            + #"|\p{L}[\p{L}\p{M}'’-]*(?:\s+\p{L}[\p{L}\p{M}'’-]*)?)"#
        let owner = #"(?:her|his|their|my|our|(?:"# + recipient + #")[’']s)"#
        let denied = #"I\s+am\s+correcting\s+(?:this|the)\s+recording\s+not\s+asking\s+you\s+to\s+(?:call|phone|email|text|message)\s+("# + recipient + #")\s+and\s+(?:cancel|remove|delete)\s+"# + owner + #"\s+(?:appointment|meeting|booking|task|reminder)"#
        guard let fields=exact(body,"(" + denied + #")\s+but\s+I\s+will\s+(.+?)\s+and\s+(.+)"#),
              fields.count == 4,RuntimeRecipientReplacement.literalRecipient(fields[1]),
              let first=physical(fields[2],referenceDate:referenceDate,calendar:calendar),
              let second=physical(fields[3],referenceDate:referenceDate,calendar:calendar),
              fields[2].caseInsensitiveCompare(fields[3]) != .orderedSame else { return nil }
        // These exact nonoverlapping anchors partition the whole source. The
        // denial is retained as Memory, not an authorized saved-item change.
        let note=OrganizedThought(itemType:.note,category:.general,priority:.normal,personName:nil,
            dueDate:nil,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,
            needsClarification:false,temporalIntent:.none,state:.resolved)
        return [.init(anchor:fields[0],adopted:false,organization:note),
                .init(anchor:fields[2],adopted:true,organization:first),
                .init(anchor:fields[3],adopted:true,organization:second)]
    }
}

/// An explicit reference-only directive owns the immediately preceding factual
/// clause. It supplies Memory purpose, never an action, date or notification.
enum RuntimeExplicitReferenceScope {
    struct Pair { let fact: Int; let directive: Int }
    /// This fast certificate proves a complete calendar fact, rather than
    /// treating an arbitrary continuation after "is" or "has" as factual.
    /// Other reference material still goes through the normal capture engine.
    private static func calendarFact(_ text: String) -> Bool {
        let months = #"(?:January|February|March|April|May|June|July|August|September|October|November|December)"#
        let weekday = #"(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)"#
        let day = #"(?:[1-9]|[12][0-9]|3[01])(?:st|nd|rd|th)?"#
        let date = "(?:" + months + "(?:\\s+" + day + #"(?:,?\s+[0-9]{4})?)?|"#
            + day + "\\s+" + months + #"(?:\s+[0-9]{4})?|(?:this\s+|next\s+)?"#
            + weekday + #"|today|tomorrow|[0-9]{4}-[0-9]{2}-[0-9]{2})"#
        let predicate = #"(?:expires?|expired|ends?|ended|runs?\s+until|ran\s+until|is|was|is\s+due|was\s+due|has\s+(?:an?\s+)?(?:expiry|expiration|end|due)\s+date\s+of|has\s+an?\s+(?:expiry|expiration)\s+of)"#
        let pattern = #"(?i)^\s*((?:the|my|our|his|her|their|this|that|a|an)\s+[\p{L}\p{M}'’-]+(?:\s+[\p{L}\p{M}'’-]+){0,4})\s+"#
            + predicate + #"\s+(?:(?:on|in)\s+)?"# + date + #"[.!?]*\s*$"#
        guard let regex = NSRegularExpression.speakItCached(pattern),
              let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)),
              let subjectRange = Range(match.range(at: 1), in: text) else { return false }
        let subject = String(text[subjectRange]).replacingOccurrences(
            of: #"(?i)^(?:my|our|his|her|their|this|that)\s+"#, with: "the ", options: .regularExpression)
        if RuntimeCurrentNominalProof.read(subject) { return true }
        // Asset-free noun proof stays local to calendar references. Every
        // subject token must be nominal; unknown predicates cannot hide here.
        let heads: Set<String> = ["warranty", "policy", "card", "coverage", "pass", "subscription",
            "permit", "license", "licence", "lease", "meeting", "appointment", "session", "event",
            "booking", "reservation", "contract", "deadline"]
        let modifiers: Set<String> = ["annual", "monthly", "weekly", "temporary", "insurance",
            "membership", "parking", "travel", "training", "existing", "new", "old", "current"]
        var words = subject.lowercased().split(whereSeparator: { $0.isWhitespace }).map(String.init)
        words.removeFirst()
        guard let head = words.last, heads.contains(head) else { return false }
        return words.dropLast().allSatisfy { heads.contains($0) || modifiers.contains($0) }
    }
    static func pairs(_ units: RuntimeIndexedSource) -> [Pair] {
        guard !Task.isCancelled else { return [] }
        return units.units.indices.compactMap { index in
            guard index > 0,
                  CaptureContentScope.isReferenceOnlyDirective(units.units[index].text),
                  QuotedSpeechScope.ranges(in: units.units[index].text).isEmpty,
                  !QuotedSpeechScope.protects(units.units[index].range, in: units.source) else { return nil }
            let fact = units.units[index - 1]
            guard QuotedSpeechScope.ranges(in: fact.text).isEmpty,
                  !QuotedSpeechScope.hasUnclosedQuote(fact.text),
                  !QuotedSpeechScope.protects(fact.range, in: units.source),
                  calendarFact(fact.text) else { return nil }
            return .init(fact: index - 1, directive: index)
        }
    }
    static func interpret(_ source: String) -> ThoughtExtractionResult? {
        let units = RuntimeIndexedSource(source), links = pairs(units)
        guard units.units.count == 2, links.count == 1,
              links[0].fact == 0, links[0].directive == 1,
              CaptureOperationDetector.partitionWithOwnership(source).operations.isEmpty else { return nil }
        let organization = OrganizedThought(itemType: .note, category: .general,
            priority: .normal, personName: nil, dueDate: nil, reminderDate: nil,
            reminderDelivery: .none, recurrenceRule: nil, needsClarification: false,
            temporalIntent: .none, state: .resolved)
        return .init(items: [.init(sourceQuote: source, rawQuote: source,
            wasRepaired: false, analysisText: source, suggestedTitle: nil,
            organization: organization, confidence: 1, needsReview: false,
            sourceUnitIDs: Set(SourceUnitLedger(source).words.indices))], method: .rules)
    }
}

/// Scoped current-capture cancellation is a source dependency, not an output
/// row choice. A proposal cannot detach the withdrawal and revive its antecedent.
enum RuntimeCurrentWithdrawal {
    /// A terminal own-voice instruction not to create a task cannot authorize
    /// a creation from the same unresolved unit. This is only a veto: it never
    /// identifies or changes a saved item, and does not prove a resolved note.
    static func hasNonCreationDirective(_ text: String) -> Bool {
        guard let voice = QuotedSpeechScope.voiceProjection(in: text),
              !QuotedSpeechScope.hasUnclosedQuote(text),
              let directive = text.range(of: #"(?i)(?:^|[,;.!?]\s*|\b(?:so|and|but)\s+)(?:please\s+)?(?:do\s+not|don['’]t)\s+(?:make|create|add)\s+(?:a|an|any|the|another|new)\s+(?:(?!(?:task|job|reminder|alert|to-do)\b)[\p{L}\p{M}'’-]+\s+){0,6}(?:task|job|reminder|alert|to-do)(?:\s+(?:for|about|to)\s+[^.!?;]+)?[.!?]*\s*$"#, options: .regularExpression) else { return false }
        return voice.ownVoiceRanges.contains { $0.lowerBound <= directive.lowerBound && $0.upperBound >= directive.upperBound }
    }
    static func isDirective(_ text: String) -> Bool {
        text.range(of:#"(?i)^\s*(?:(?:wait|no|actually)[,;:]?\s+)?(?:leave\s+that\s+off|take\s+that\s+back|cancel\s+that|withdraw\s+that|never\s+mind|scratch\s+that)\s*[.!]?\s*$"#,options:.regularExpression) != nil
    }
    struct Dependency { let creation: Int; let withdrawal: Int }
    static func dependencies(_ indexed: RuntimeIndexedSource) -> [Dependency] {
        indexed.units.indices.compactMap { index in
            guard index > 0,isDirective(indexed.units[index].text),
                  !QuotedSpeechScope.protects(indexed.units[index].range,in:indexed.source),
                  !QuotedSpeechScope.protects(indexed.units[index-1].range,in:indexed.source),
                  ActionabilityReader.read(indexed.units[index-1].text).belongsOnToday else { return nil }
            return .init(creation:index-1,withdrawal:index)
        }
    }
    static func interpret(_ source: String,referenceDate: Date,calendar: Calendar) -> ThoughtExtractionResult? {
        let indexed = RuntimeIndexedSource(source),links = dependencies(indexed)
        guard indexed.units.count >= 2,links.count == 1,links[0].creation == 0,links[0].withdrawal == 1,
              indexed.units[0].text.range(of:#"(?i)^\s*add\s+(?:a|one)\s+(?:new\s+)?(?:job|task)\s+to\s+"#,options:.regularExpression) != nil,
              indexed.units[0].text.range(of:#"(?i)\b(?:and|or|then|also|if|unless|saved|existing)\b"#,options:.regularExpression) == nil else { return nil }
        let ledger = SourceUnitLedger(source)
        let cancelledRange = indexed.units[0].range.lowerBound..<indexed.units[1].range.upperBound
        let cancelled = String(source[cancelledRange]).trimmingCharacters(in:.whitespacesAndNewlines)
        let memory = OrganizedThought(itemType:.note,category:.general,priority:.normal,personName:nil,
            dueDate:nil,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,needsClarification:false,state:.resolved)
        var items: [ExtractedThought] = [.init(sourceQuote:cancelled,rawQuote:cancelled,wasRepaired:false,
            analysisText:cancelled,suggestedTitle:nil,organization:memory,confidence:1,needsReview:false,
            sourceUnitIDs:ledger.ids(in:cancelledRange))]
        for unit in indexed.units.dropFirst(2) {
            guard let prefix = unit.text.range(of:#"(?i)^\s*i\s+still\s+need\s+to\s+"#,options:.regularExpression),
                  unit.text.range(of:#"(?i)\b(?:and|or|then|also|if|unless|until|after|before|once|when|while|not|never|saved|existing|that|it|them|him|her|actually|instead)\b"#,options:.regularExpression) == nil else { return nil }
            let action = String(unit.text[prefix.upperBound...]).trimmingCharacters(in:.whitespacesAndNewlines.union(.punctuationCharacters))
            guard action.range(of:#"(?i)^(?:clean|dust|wash|weigh|test|check|finish|fix|repair|count|scan|polish|measure|sort|label|sharpen|tighten)\s+\S"#,options:.regularExpression) != nil,
                  ActionabilityReader.read(action).belongsOnToday else { return nil }
            let reading = ThoughtOrganizer.organize(action,referenceDate:referenceDate,calendar:calendar)
            guard reading.itemType == .task,reading.personName == nil,!reading.needsClarification,
                  reading.locationIntent == nil,reading.recurrenceRule == nil else { return nil }
            let organized = OrganizedThought(itemType:.task,category:reading.category,priority:reading.priority,personName:nil,
                dueDate:reading.dueDate,reminderDate:reading.reminderDate,reminderDelivery:reading.reminderDelivery,
                recurrenceRule:nil,needsClarification:false,temporalIntent:reading.temporalIntent,state:reading.state)
            items.append(.init(sourceQuote:unit.text,rawQuote:unit.text,wasRepaired:false,analysisText:action,
                suggestedTitle:ThoughtTitleFormatter.polished(action,itemType:.task),organization:organized,
                confidence:1,needsReview:false,sourceUnitIDs:ledger.ids(in:unit.range)))
        }
        guard RuntimeProposalGuard.covers(source,quotes:items.map(\.sourceQuote)) else { return nil }
        return .init(items:items,method:.rules)
    }
}

/// Spoken section labels are CURRENT source boundaries, not generated facts.
/// Only an own, explicitly labelled sequence opens this reader. A historical
/// mention or another speaker's quoted labels cannot open that sequence.
enum RuntimeSpokenIntentionLabels {
    static let ordinal = #"(?:(?:another\s+)?(?:first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|next|middle|last|final|opening|\d+(?:st|nd|rd|th))|another)"#
    static let label = ordinal + #"\s+(job|task|note|memory|idea)\b\s*:?\s+"#
    static func reading(_ text: String) -> (kind: String, body: String)? {
        guard let regex = NSRegularExpression.speakItCached("^\\s*" + label,options:.caseInsensitive),
              let match = regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)),
              let range = Range(match.range,in:text),let kind = Range(match.range(at:1),in:text) else { return nil }
        let body = String(text[range.upperBound...]).trimmingCharacters(in:.whitespacesAndNewlines)
        guard !body.isEmpty else { return nil }
        return (String(text[kind]).lowercased(),body)
    }
    static func boundaries(in source: String) -> Set<String.Index> {
        guard !QuotedSpeechScope.hasUnclosedQuote(source),let first = reading(source),
              !QuotedSpeechScope.protects(source.startIndex..<source.index(after:source.startIndex),in:source),
              ["job","task"].contains(first.kind),RuntimeFoundationActionShape.executable(first.body) else { return [] }
        let pattern = #"(?i)\b(?:"# + label
            + #"|(?:keep|save|retain|record)\s+the\s+fact\s+that\s+)"#
        guard let regex = NSRegularExpression.speakItCached(pattern) else { return [] }
        return Set(regex.matches(in:source,range:NSRange(source.startIndex...,in:source)).compactMap { match in
            guard let range = Range(match.range,in:source),range.lowerBound > source.startIndex,
                  !QuotedSpeechScope.protects(range,in:source) else { return nil }
            return range.lowerBound
        })
    }
}

/// This is a positive executable shape, separate from Today membership (which
/// includes factual events and outstanding states). It supplies no endpoints,
/// identities, timing or permission from another clause or quotation.
enum RuntimeFoundationActionShape {
    static func executable(_ text: String) -> Bool {
        let body = ActionabilityReader.actionBody(text).trimmingCharacters(in:.whitespacesAndNewlines)
        let head = #"(?i)^(?:"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b\s+\S"#
        guard body.range(of:head,options:.regularExpression) != nil,
              body.range(of:#"(?i)^(?:do|make|handle|finish|complete)\s+(?:that|it|them|both|all)\b"#,options:.regularExpression) == nil else { return false }
        return ActionabilityReader.read(text).belongsOnToday
    }
    static func body(_ text: String) -> String {
        // Explicit capture-position routing does not belong to the action's
        // object or clock. Keep all source evidence; remove only this closed
        // prefix immediately before its own executable head.
        if let marker = text.range(of:#"(?i)^\s*(?:around\s+the\s+middle|in\s+the\s+middle(?:\s+of\s+this\s+capture)?|near\s+the\s+end|toward\s+the\s+end|at\s+the\s+very\s+end),\s+(?=(?:please\s+)?(?:ask|tell|call|phone|email|text|message|buy|purchase|pack|remind\s+me|notify\s+me|alert\s+me)\b)"#,options:.regularExpression) {
            return body(String(text[marker.upperBound...]))
        }
        if let marker = text.range(of:#"(?i)^\s*(?:first|next|separately),\s+(?=(?:please\s+)?(?:ask|tell|call|phone|email|text|message|buy|purchase|pack)\b)"#,options:.regularExpression) {
            return body(String(text[marker.upperBound...]))
        }
        if let label = RuntimeSpokenIntentionLabels.reading(text) {
            if label.kind == "idea" { return "Idea: " + label.body }
            return body(label.body)
        }
        // A fact is the object of this retention directive. The complete
        // existing narrative reader checks every factual clause and declines
        // an executive continuation before this routing wrapper is supplied.
        if let frame = text.range(of:#"(?i)^\s*(?:keep|save|retain|record)\s+the\s+fact\s+that\s+"#,options:.regularExpression) {
            let fact = String(text[frame.upperBound...])
            if RuntimeIndependentFramePlan.coherentNarrative("Keep one memory. " + fact) != nil {
                return "Note: " + fact
            }
        }
        return text
    }
}

struct RuntimeIndexedSource {
    struct Unit { let range: Range<String.Index>; let text: String }
    let source: String
    let units: [Unit]
    var prompt: String {
        units.enumerated().map { "\($0.offset): \(source[$0.element.range])" }.joined(separator: "\n")
    }
    init(_ source: String) {
        self.source = source
        var result: [Unit] = [], start = source.startIndex, quoted = false, depth = 0
        let declaredBoundaries = RuntimeSpokenIntentionLabels.boundaries(in:source)
        for index in source.indices {
            if declaredBoundaries.contains(index),start < index {
                let range = start..<index
                let text = String(source[range]).trimmingCharacters(in:.whitespacesAndNewlines)
                if !text.isEmpty { result.append(Unit(range:range,text:text)) }
                start = index
            }
            let character = source[index]
            if character == "\"" { quoted.toggle() }
            if character == "“" { quoted = true }; if character == "”" { quoted = false }
            if !quoted { if character == "(" { depth += 1 }; if character == ")" { depth = max(0, depth - 1) } }
            let next = source.index(after: index)
            let sentenceEnd = !quoted && depth == 0 && ".!?".contains(character)
                && (next == source.endIndex || source[next].isWhitespace)
                && !Self.continuesFrontedCalendarClock(source, start: start, through: next)
            if !quoted, depth == 0, character == ";" || character == "\n" || sentenceEnd {
                let range = start..<next
                let text = String(source[range]).trimmingCharacters(in: .whitespacesAndNewlines)
                if !text.isEmpty { result.append(Unit(range: range, text: text)) }
                start = next
            }
        }
        if start < source.endIndex {
            let range = start..<source.endIndex
            let text = String(source[range]).trimmingCharacters(in: .whitespacesAndNewlines)
            if !text.isEmpty { result.append(Unit(range: range, text: text)) }
        }
        self.units = result
    }

    /// A clock abbreviation is internal punctuation when the existing reader
    /// proves one complete clock-and-calendar adjunct. Without that proof the
    /// period still ends the unit: "At 3 p.m. Call Mom" has two intentions.
    /// This shares the rules reader's calendar grammar rather than allowing a
    /// generated outline to turn the clock into a separate dated task.
    private static func continuesFrontedCalendarClock(_ source: String,
        start: String.Index, through end: String.Index) -> Bool {
        let prefix = source[start..<end].trimmingCharacters(in: .whitespacesAndNewlines)
        guard prefix.range(of: #"(?i)(?:a|p)\.?m\.$"#, options: .regularExpression) != nil,
              let lead = RuleBasedThoughtExtractor.leadingTemporalContext(in:
                source[start...].trimmingCharacters(in: .whitespacesAndNewlines)) else { return false }
        let normalizedPrefix = prefix.replacingOccurrences(of: #"\s+"#, with: " ",
                                                            options: .regularExpression)
        // Bind this exact stop to the complete lead. A later clock in the
        // action cannot borrow an earlier clock/calendar prefix's proof.
        return lead.lowercased().hasPrefix(normalizedPrefix.lowercased() + " on ")
    }
}

enum RuntimeAccountOwnership {
    enum Disposition: String, CaseIterable {
        case routing, fact, report, uncertainty, referenceQuestion, possibility
        case currentIntent, unresolved

        var code: String {
            switch self {
            case .routing: "R"
            case .fact: "F"
            case .report: "S"
            case .uncertainty: "U"
            case .referenceQuestion: "Q"
            case .possibility: "P"
            case .currentIntent: "A"
            case .unresolved: "X"
            }
        }
    }

    static let declaration = #"(?i)^\s*(?:keep|save|preserve)(?:\s+(?:the\s+following|this)\s+as)?\s+one\s+(?:(?:connected|coherent)\s+)?(?:memory|note|account)\b"#

    static func scoped(_ source: String) -> Bool {
        guard !QuotedSpeechScope.hasUnclosedQuote(source),
              let heading = source.range(of:declaration,options:.regularExpression),
              heading.upperBound < source.endIndex,
              !QuotedSpeechScope.protects(heading,in:source) else { return false }
        return !source[heading.upperBound...].trimmingCharacters(in:.whitespacesAndNewlines).isEmpty
    }

    private static let knowledgeObject = #"(?:memory|note|account|story|history|context|questions?|facts?|details?|possibility|uncertainties|distinctions|disagreement|relationships|observations?|contributions?)"#
    private static let determiner = #"(?:this|that|the|these|those|a|an|its|his|her|their|our|my|"# + RuntimeAllocationReading.quantityPattern + ")"
    private static var retention: String {
        #"(?i)^\s*(?:(?:I|we)\s+(?:(?:want|need)\s+to|would\s+like\s+to|am|are)\s+)?(?:keep|save|retain|preserve|record|keeping|saving|retaining|preserving)\s+"# + determiner
        + #"\s+(?:(?:unanswered|reference|connected|coherent)\s+)*"# + knowledgeObject + #"\b"#
    }
    private static var passiveRetention: String {
        #"(?i)^\s*(?:I|we)\s+(?:want|need)\s+"# + determiner + #"\s+(?:(?:unanswered|reference|connected|coherent)\s+)*"#
        + knowledgeObject + #"\s+(?:(?:to\s+be)\s+)?(?:retained|remembered|preserved|kept|recorded)\b"#
    }
    private static var cognitiveDestination: String {
        #"(?i)^\s*What\s+(?:I|we)\s+want\s+to\s+(?:find|recover|remember|revisit)\s+later\s+is\s+"#
        + determiner + #"\s+(?:(?:connected|coherent)\s+)*"# + knowledgeObject + #"\b"#
    }
    static func retainsKnowledge(_ text: String) -> Bool {
        [retention,passiveRetention,cognitiveDestination].contains { text.range(of:$0,options:.regularExpression) != nil }
    }

    private static var actionHead: String {
        "(?:" + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + ")"
    }

    /// Reverse productive spelling changes against the existing action grammar.
    /// This is a current-action veto, never a whitelist of factual predicates.
    private static func inflectedActionHead(_ text: String, gerund: Bool) -> Bool {
        guard let head = text.range(of:#"^[\p{L}]+"#,options:.regularExpression) else { return false }
        let word = String(text[head]).lowercased()
        var stems: [String] = []
        if gerund,word.hasSuffix("ing"),word.count > 3 {
            let base = String(word.dropLast(3));stems = [base,base + "e"]
            if word.hasSuffix("ying") { stems.append(String(word.dropLast(4)) + "ie") }
            if base.count > 1,base.last == base.dropLast().last { stems.append(String(base.dropLast())) }
        } else if !gerund,word.hasSuffix("ed"),word.count > 2 {
            let base = String(word.dropLast(2));stems = [base,String(word.dropLast())]
            if word.hasSuffix("ied") { stems.append(String(word.dropLast(3)) + "y") }
            if base.count > 1,base.last == base.dropLast().last { stems.append(String(base.dropLast())) }
        }
        if !gerund,["done","made","sent","paid","taken","brought","put","kept","given","written","cut","built","bought"].contains(word) { return true }
        return stems.contains { stem in
            let restored = stem + text[head.upperBound...]
            return restored.range(of:"(?i)^" + actionHead + #"\b"#,options:.regularExpression) != nil
        }
    }

    private static func hasDesiredPhysicalResult(_ text: String) -> Bool {
        guard let lead = text.range(of:#"(?i)^\s*(?:I|we)\s+(?:want|need)\s+"#,options:.regularExpression),
              let words = NSRegularExpression.speakItCached(#"[\p{L}\p{N}'’-]+"#) else { return false }
        let body = String(text[lead.upperBound...])
        let matches = words.matches(in:body,range:NSRange(body.startIndex...,in:body))
        for (index,match) in matches.enumerated() {
            guard let range = Range(match.range,in:body) else { return true }
            let word = body[range].lowercased()
            if ["who","that","which","to","by","because","when","after","before","if","unless","while","once","and","but"].contains(word), !(index == 0 && word == "that") { break }
            if index > 0,inflectedActionHead(String(body[range.lowerBound...]),gerund:false) { return true }
        }
        return false
    }

    /// A positively finite coordinated subject owns its internal commas/and.
    /// Only those separators are protected; later clauses still get inspected.
    private static func protectNominalSubjectSeparators(_ text: String) -> String {
        let finite = "(?:is|are|was|were|has|have|had|needs?|must|should|can|could)"
        let token = "(?!(?:and|but|or|" + finite + #")\b)[\p{L}\p{N}'’-]+"#
        let nominal = token + "(?:\\s+" + token + ")*"
        let pattern = "(?i)^\\s*(?:the|these|those|my|our)\\s+" + nominal
            + "(?:,\\s*" + nominal + ")+[,]?\\s+and\\s+" + nominal + "\\s+(?=" + finite + #"\b)"#
        guard let subject = text.range(of:pattern,options:.regularExpression) else { return text }
        let protected = String(text[subject]).replacingOccurrences(of:#"(?i),|\band\b"#,with:" ",options:.regularExpression)
        return protected + text[subject.upperBound...]
    }

    /// Model roles are semantic judgments. Independent current-source speech
    /// acts can veto an all-Memory map; verb-like noun-list members cannot.
    static func hasCurrentIntent(_ unit: String) -> Bool {
        hasCurrentIntent(unit,checksIndependentActions:false)
    }

    /// Reference admission also checks each complete own-voice clause with
    /// the existing action reader. A past matrix cannot hide a new promise.
    static func hasCurrentActForReference(_ unit: String) -> Bool {
        hasCurrentIntent(unit,checksIndependentActions:true)
    }

    /// Only a positively attributed report's first matrix/content comma is
    /// not an independent current-action boundary. This changes the veto's
    /// reading projection only; source words, ranges and later seams remain.
    private static func protectReportedIntroductionSeparator(_ text: String) -> String {
        guard let comma = text.firstIndex(of: ",") else { return text }
        let matrix = String(text[..<comma]).trimmingCharacters(in: .whitespacesAndNewlines)
        let afterComma = text.index(after: comma)
        let content = String(text[afterComma...])
        // Cheap shape guards keep ClauseScope off ordinary sentences. Require
        // an action-shaped report object, never a first-person adoption slot.
        guard matrix.range(of: #"(?i)\b\#(ClauseScope.reportingVerb)\s*$"#,
                           options: .regularExpression) != nil,
              content.range(of: "(?i)^\\s*(?:please\\s+)?" + actionHead + #"\b"#,
                            options: .regularExpression) != nil else { return text }
        let reading = ClauseScope.read(text)
        guard reading.act == .reporting,
              case .other = reading.actor,
              reading.speaker?.isEmpty == false,
              reading.complement?.isEmpty == false,
              reading.matrix.trimmingCharacters(in: .whitespacesAndNewlines
                .union(CharacterSet(charactersIn: ",:"))) == matrix else { return text }
        var projected = text
        projected.replaceSubrange(comma..<afterComma, with: " ")
        return projected
    }

    private static func hasCurrentIntent(_ unit: String, checksIndependentActions: Bool) -> Bool {
        guard let voice = QuotedSpeechScope.voiceProjection(in:unit) else { return true }
        for range in voice.ownVoiceRanges {
            var own = String(unit[range]).trimmingCharacters(in:.whitespacesAndNewlines.union(.punctuationCharacters))
            if let heading = own.range(of:declaration,options:.regularExpression) {
                own = String(own[heading.upperBound...])
            }
            // Conjunctions open owned continuations. A bare comma can be part
            // of a noun list, so only explicit clause connectors split there.
            let seams = #"(?i)[;:]|,\s*(?:and|but|then|also|so)\s+|,\s*(?=(?:I|we|(?:please\s+)?"# + actionHead + #")\b)|\s+(?:and|but|then|also|plus|so|because|although|while|once|by|via)\s+"#
            let projected = protectReportedIntroductionSeparator(protectNominalSubjectSeparators(own))
            let children = projected.replacingOccurrences(of:seams,with:"\n",options:.regularExpression).components(separatedBy:"\n")
            for child in children {
                let text = child.trimmingCharacters(in:.whitespacesAndNewlines.union(.punctuationCharacters))
                guard !text.isEmpty else { continue }
                let intellectualPrefixes = [retention,passiveRetention,cognitiveDestination].compactMap {
                    text.range(of:$0,options:.regularExpression)
                }
                let childRetention = !intellectualPrefixes.isEmpty
                let epistemic = #"(?i)^\s*(?:I|we)\s+should\s+(?:not|never)\s+(?:turn|treat|present|record|rewrite|restate|describe)\s+(?:this|that|the|his|her|their)\s+(?:explanation|hypothesis|guess|claim|theory|interpretation|assumption|observation)\s+(?:into|as)\s+(?:a\s+)?(?:(?:confirmed|verified|established|proven|certain|permanent|material)\s+)+(?:conclusion|fact|finding|truth|specification)\s*$"#
                let epistemicOnly = text.range(of:epistemic,options:.regularExpression) != nil
                let prospective = #"(?i)\b(?:I|we)\s+(?:will|shall|must|should|(?:need|have|want)\s+to|am\s+going\s+to|are\s+going\s+to)\b"#
                if let regex = NSRegularExpression.speakItCached(prospective) {
                    for match in regex.matches(in:text,range:NSRange(text.startIndex...,in:text)) {
                        guard let matched = Range(match.range,in:text) else { return true }
                        let ownsRetentionPrefix = intellectualPrefixes.contains { $0.lowerBound <= matched.lowerBound && $0.upperBound >= matched.upperBound }
                        if !ownsRetentionPrefix && !epistemicOnly { return true }
                    }
                }
                // This is a conservative Memory veto, not a positive action
                // certificate: unfamiliar verbs still name a current intent.
                if text.range(of:#"(?i)\b(?:I|we)['’]ll\s+|^\s*\#(ActionabilityReader.ownedNominalTaskEntryFramePattern)(?=\p{L})"#,options:.regularExpression) != nil { return true }
                let adoption = #"(?i)\b(?:I|we)\s+(?:have\s+)?(?:now\s+)?(?:agree|agreed|accept|accepted|adopt|adopted|decide|decided|commit|committed|say\s+yes|said\s+yes)\b"#
                if text.range(of:adoption,options:.regularExpression) != nil { return true }
                let inheritedPermissionDenial = own.range(of:#"(?i)^\s*(?:These|Those)\b"#,options:.regularExpression) != nil
                    && text.range(of:#"(?i)^\s*do\s+not\s+(?:resolve|request)\b"#,options:.regularExpression) != nil
                if !childRetention {
                    // A desired physical change may have a passive complement
                    // rather than 'want to'. Reuse the current action grammar
                    // for regular participles; known irregular forms stay bounded.
                    if hasDesiredPhysicalResult(text) { return true }
                    let body = ActionabilityReader.actionBody(text).trimmingCharacters(in:.whitespacesAndNewlines)
                    let currentHead = #"(?i)^(?:"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b"#
                    // A head without its quoted object, or 'do that', still
                    // owns an unresolved current directive; it cannot become
                    // an asserted fact merely because execution is declined.
                    let reading = ActionabilityReader.read(text)
                    if checksIndependentActions, reading == .actionable || reading == .outstanding { return true }
                    if !inheritedPermissionDenial && !epistemicOnly {
                        // The complete existing reader distinguishes finite
                        // compound nouns such as 'Call records were archived'
                        // from a present command and supports current Let's/
                        // responsibility frames. A bare unresolved head is
                        // still held; lexical knowledge alone never adopts it.
                        let explicitOwnedFrame = #"(?i)^\s*(?:let['’]?s\s+(?:go\s+(?:and\s+)?)?|\#(ActionabilityReader.ownedNominalTaskEntryFramePattern)(?=\p{L}))"#
                        if text.range(of:explicitOwnedFrame,options:.regularExpression) != nil, reading.belongsOnToday { return true }
                        let finiteNoun = #"(?i)^(?:"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb
                            + #")\s+(?!(?:the|a|an|my|our|your|this|that|if|whether)\b)(?:(?!(?:if|whether|when|after|before|once|who|that|which|because|i|we|he|she|they|you)\b)[\p{L}\p{N}'’-]+\s+){0,3}(?:is|are|was|were|has|have)\b"#
                        if reading != .knowledge, body.range(of:currentHead,options:.regularExpression) != nil,
                           body.range(of:finiteNoun,options:.regularExpression) == nil { return true }
                        let ownsKnowledgePrefix = [retention,passiveRetention,cognitiveDestination].contains { own.range(of:$0,options:.regularExpression) != nil }
                        if ownsKnowledgePrefix,own.range(of:#"(?i)\b(?:by|via)\s+"#,options:.regularExpression) != nil,
                           inflectedActionHead(text,gerund:true) { return true }
                    }
                }
                let interruption = #"\b(?:set\s+an?\s+alarm|alarm\s+(?:for|at)|wake\s+me|(?:set|start)\s+a\s+timer|timer\s+for)\b"#
                if ReminderPhrasing.requestsReminder(text) || ReminderPhrasing.authorizesRequest(text,pattern:interruption) { return true }
                if text.range(of:#"(?i)^\s*(?:cancel|reschedule|revise|delete|remove|change|move|complete|mark|pin|unpin)\s+(?:my|our|the|that|this)\s+(?:saved|existing|earlier|previous)\b"#,options:.regularExpression) != nil { return true }
                if text.range(of:#"(?i)^\s*(?:I|we)\s+(?:have|am\s+attending|are\s+attending)\b"#,options:.regularExpression) != nil,
                   ActionabilityReader.read(text) == .event { return true }
            }
        }
        return false
    }

    static func validate(_ dispositions: [Int:Disposition], source: String,
                         units: RuntimeIndexedSource, rules: ThoughtExtractionResult) -> ThoughtExtractionResult? {
        guard scoped(source),rules.operations.isEmpty,!Task.isCancelled,
              Set(dispositions.keys) == Set(units.units.indices),
              RuntimeProposalGuard.covers(source,quotes:units.units.map(\.text)) else { return nil }
        for index in units.units.indices {
            let text = units.units[index].text
            guard let role = dispositions[index],role != .currentIntent,role != .unresolved,
                  !hasCurrentIntent(text) else { return nil }
            switch role {
            case .routing:
                guard (index == 0 && text.range(of:declaration,options:.regularExpression) != nil) || retainsKnowledge(text) else { return nil }
            case .report:
                guard ClauseScope.read(text).act == .reporting
                    || QuotedSpeechScope.matrixVoice(in:text) == .reported else { return nil }
            case .referenceQuestion:
                guard text.range(of:#"(?i)\b(?:questions?|who|what|where|when|why|whether|which|how)\b"#,options:.regularExpression) != nil else { return nil }
            case .possibility:
                guard text.range(of:#"(?i)\b(?:idea|possible|possibility|could|might|perhaps|imagined|uncommitted|unchosen|unadopted)\b"#,options:.regularExpression) != nil else { return nil }
            case .uncertainty:
                guard text.range(of:#"(?i)\b(?:not|never|unknown|uncertain|unanswered|unsure|cannot|can't|doubt|unconfirmed|unresolved)\b"#,options:.regularExpression) != nil else { return nil }
            case .fact: break // Positive model semantic judgment; no verb whitelist.
            case .currentIntent,.unresolved: return nil
            }
        }
        let organization = OrganizedThought(itemType:.note,category:.general,priority:.normal,
            personName:nil,dueDate:nil,reminderDate:nil,reminderDelivery:.none,recurrenceRule:nil,
            needsClarification:false,temporalIntent:.none,state:.resolved)
        return .init(items:[.init(sourceQuote:source,rawQuote:source,wasRepaired:false,
            analysisText:source,suggestedTitle:nil,organization:organization,confidence:1,needsReview:false,
            sourceUnitIDs:Set(SourceUnitLedger(source).words.indices))],method:.appleIntelligence)
    }

}

#if canImport(FoundationModels)
@available(iOS 26.4, *)
extension RuntimeAccountOwnership {
    static func fixedKeySchema(_ units: RuntimeIndexedSource) throws -> GenerationSchema? {
        guard !units.units.isEmpty else { return nil }
