        let root = DynamicGenerationSchema(name:"CurrentAccountOwnership",properties:units.units.indices.map {
            .init(name:"u\($0)",description:"Semantic disposition of complete CURRENT unit u\($0), including all its continuations",schema:.init(referenceTo:"AccountDisposition"))
        })
