        let root = DynamicGenerationSchema(name:"CurrentAccountOwnership",properties:[
            .init(name:"roles",description:"Exactly one role for each CURRENT unit u0 onward in unchanged CURRENT order; never sort, omit, duplicate or combine units",schema:.init(arrayOf:.init(referenceTo:"AccountDisposition"),minimumElements:units.units.count,maximumElements:units.units.count))
