              Set(labels.keys) == Set(units.units.indices.map { "u\($0)" }) else { return nil }
        var roles: [Int:Disposition] = [:]
        for index in units.units.indices {
            guard let label = labels["u\(index)"],let role = Disposition.allCases.first(where:{ $0.code == label }) else { return nil };roles[index] = role
        }
        return roles
    }

    enum AccountDecision: String, CaseIterable {
        case retainConnectedMemory, containsIndependentCurrentIntent, unresolved
