    static func decisionSchema(_ units: RuntimeIndexedSource) throws -> GenerationSchema? {
        guard !units.units.isEmpty else { return nil }
        let verdict = DynamicGenerationSchema(name:"WholeCurrentAccountDecision",anyOf:AccountDecision.allCases.map(\.rawValue))
        let root = DynamicGenerationSchema(name:"CurrentAccountReconciliation",properties:[
