    static func decodeDecision(_ content: GeneratedContent) throws -> AccountDecision? {
        guard let value = try? JSONDecoder().decode([String:String].self,from:Data(content.jsonString.utf8)),
              Set(value.keys) == ["decision"],let name = value["decision"] else { return nil }
