@available(iOS 26.4, *)
enum RuntimeFoundationInterpreter {
#if DEBUG
    // Only a synthetic developer harness installs this observer. No app log,
    // analytics sink, shared bank or production diagnostic receives content.
    @TaskLocal static var developmentObserver: (@Sendable (String) -> Void)? = nil
#endif
    static func measuredGeneration<T>(phase:String,operation:() async throws -> T) async rethrows -> T {
#if DEBUG
        let clock=ContinuousClock(),start=ContinuousClock.now
        func observe(_ state:String) {
            let elapsed=clock.now-start,parts=elapsed.components
            let seconds=Double(parts.seconds)+Double(parts.attoseconds)/1e18
            developmentObserver?("call timing phase=\(phase) elapsedSeconds=\(seconds) completion=\(state) cancellation=\(Task.isCancelled ? "observed" : "none")")
        }
        do { let response=try await operation();observe("response-returned");return response }
        catch { observe("generation-threw");throw error }
#else
        return try await operation()
#endif
    }
#if DEBUG
    static func observedFailureReason(_ error: Error) -> String {
        if error is CancellationError { return "task-cancelled" }
        if #available(iOS 27.0, macOS 27.0, *), let failure = error as? LanguageModelError {
            switch failure {
            case .contextSizeExceeded: return "context-size-exceeded"
            case .rateLimited: return "rate-limited"
            case .guardrailViolation: return "guardrail-violation"
            case .refusal: return "model-refusal"
            case .unsupportedCapability: return "unsupported-capability"
            case .unsupportedTranscriptContent: return "unsupported-transcript-content"
            case .unsupportedGenerationGuide: return "unsupported-guide"
            case .unsupportedLanguageOrLocale: return "unsupported-locale"
            case .timeout: return "provider-timeout"
            @unknown default: return "unknown-language-model-error"
            }
        }
        // The installed 26.x runtime reports the earlier typed errors. A raw
        // NSError with the same domain is not enough to infer any enum case.
        if let failure=error as? LanguageModelSession.GenerationError {
            switch failure {
            case .exceededContextWindowSize: return "context-size-exceeded"
            case .assetsUnavailable: return "assets-unavailable"
            case .guardrailViolation: return "guardrail-violation"
            case .unsupportedGuide: return "unsupported-guide"
            case .unsupportedLanguageOrLocale: return "unsupported-locale"
            case .decodingFailure: return "decoding-failure"
            case .rateLimited: return "rate-limited"
            case .concurrentRequests: return "concurrent-requests"
            case .refusal: return "model-refusal"
            @unknown default: return "unknown-generation-error"
            }
        }
        return "unclassified-sdk-error"
    }
    static func observedErrorIdentity(_ error:Error) -> String {
        let ns=error as NSError
        var value="errorDomain=\(ns.domain.debugDescription) errorCode=\(ns.code)"
        value += " errorInfoKeys=\(ns.userInfo.keys.sorted().debugDescription)"
        if let description=ns.userInfo[NSLocalizedDescriptionKey] as? String { value += " errorDescription=\(description.debugDescription)" }
        if let description=ns.userInfo[NSDebugDescriptionErrorKey] as? String { value += " errorDebugDescription=\(description.debugDescription)" }
        if let failures=ns.userInfo[NSMultipleUnderlyingErrorsKey] as? [NSError] {
            value += " multipleUnderlyingCount=\(failures.count)"
            for (index,failure) in failures.enumerated() {
                value += " underlying\(index)Domain=\(failure.domain.debugDescription) underlying\(index)Code=\(failure.code) underlying\(index)Description=\(failure.localizedDescription.debugDescription)"
            }
        }
        if let underlying=ns.userInfo[NSUnderlyingErrorKey] as? NSError {
            value += " underlyingDomain=\(underlying.domain.debugDescription) underlyingCode=\(underlying.code)"
        } else { value += " underlying=none" }
        value += " errorTreeJSON="+observedErrorTreeJSON(ns)
        return value
    }
    /// Bounded DEBUG-only synthetic-harness evidence. Do not turn an opaque
    /// NSError code into a typed cause or publish arbitrary userInfo values.
    static func observedErrorTreeJSON(_ error:NSError)->String {
        var rows:[[String:Any]]=[],seen=Set<ObjectIdentifier>(),truncated=false
        func visit(_ node:NSError,path:String,depth:Int) {
            guard rows.count < 16,depth <= 6 else { truncated=true;return }
            let identity=ObjectIdentifier(node)
            guard seen.insert(identity).inserted else {
                rows.append(["path":path,"repeatedNode":true]);return
            }
