        let retrospectiveEvent = #"(?:before|after)\s+(?:the\s+)?(?:(?:first|last|previous|original)\s+)?(?:delivery|arrival|transport|handoff|shipment|exhibition|display|receipt|loan|inspection|installation)"#
        let pattern = #"((?:the|a|an)\s+[^,;.!?]+?)\s+was\s+(?:lent\s+(?:by|from)|loaned\s+(?:by|from)|borrowed\s+from)\s+("# + person
            + #"),\s*and\s+("# + person + #")\s+(?:remembers|recalls)\s+((?:the|a|an)\s+[^,;.!?]+?)\s+being\s+([\p{L}]+)(?:\s+"# + retrospectiveEvent + ")?"
