    /// These source-only bonds preserve complete literal context. They do not
    /// discharge a prerequisite, classify a noun, resolve a contact/object or
    /// grant a saved mutation or reminder. The ordinary final guards still run.
    private static func currentContextExact(_ text:String,_ pattern:String) -> [String]? {
        guard let regex=NSRegularExpression.speakItCached("(?i)^\\s*(?:"+pattern+")[;.!]?\\s*$"),
              let match=regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)) else { return nil }
        return (1..<match.numberOfRanges).map { Range(match.range(at:$0),in:text).map { String(text[$0]) } ?? "" }
    }
    private static var currentContextPerson:String {
        "(?:" + PersonMentionResolver.communicationRelationPhrasePattern + #"|\p{L}[\p{L}\p{M}'’-]*(?:\s+\p{L}[\p{L}\p{M}'’-]*)??)"#
    }
    /// A nominal object in an explicit finite inspection/confirmation fact can
    /// remain an opaque literal word. That gives no executable object identity.
    private static func currentFactualContextNominal(_ text:String) -> Bool {
        if RuntimeCurrentNominalProof.read(text) { return true }
        guard let fields=currentContextExact(text,#"(?:the\s+|a\s+|an\s+)?([\p{L}\p{M}][\p{L}\p{M}-]{0,63})"#) else { return false }
        return fields[0].range(of:#"(?i)^(?:I|we|you|he|she|they|it|this|that|these|those|me|us|them|him|her|and|or|but|then|also|if|unless|when|once|because|before|after|until|not|never|no|will|shall|must|should|need|want|saved|actually|instead|correction|cancel|withdraw|"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + ")$",options:.regularExpression) == nil
    }
    /// Decline nested intention labels before the generic recursive router can
    /// strip a Memory owner. A routing label supplies no semantic permission.
    private static func currentContextBody(_ original:String) -> String? {
        if let label=RuntimeSpokenIntentionLabels.reading(original) {
            guard !["note","memory","idea"].contains(label.kind),
                  RuntimeSpokenIntentionLabels.reading(label.body) == nil else { return nil }
        }
        guard original.range(of:#"(?i)^\s*(?:task|job|note|memory|idea)\s*:"#,options:.regularExpression) == nil else { return nil }
        var body=RuntimeFoundationActionShape.body(original)
        if let routing=body.range(of:#"(?i)^\s*(?:near\s+the\s+end|toward\s+the\s+end|at\s+the\s+very\s+end|in\s+the\s+middle(?:\s+of\s+this\s+capture)?),\s+(?=(?:after|before|if|unless|when|once|until)\b)"#,options:.regularExpression) { body=String(body[routing.upperBound...]) }
        return body
    }
    /// Potential antecedents are counted BEFORE full-parent proof. A second
    /// unsupported same-role action cannot make the supported one unique.
    static func currentPotentialConfirmationActor(_ parent:String) -> String? {
        guard let body=currentContextBody(parent),
              let regex=NSRegularExpression.speakItCached("(?i)^\\s*(?:after|before|if|unless|when|once|until)\\s+("+currentContextPerson+")\\s+confirms\\b"),
              let match=regex.firstMatch(in:body,range:NSRange(body.startIndex...,in:body)),
              let range=Range(match.range(at:1),in:body) else { return nil }
        return String(body[range])
    }
    static func currentPotentialReturnOwner(_ original:String) -> String? {
        guard let body=currentContextBody(original),
              let regex=NSRegularExpression.speakItCached("(?i)\\breturn\\s+("+currentContextPerson+#")[’']s\s+"#),
              let match=regex.firstMatch(in:body,range:NSRange(body.startIndex...,in:body)),
              let range=Range(match.range(at:1),in:body) else { return nil }
        return String(body[range])
    }
    static func currentConfirmationParentActor(_ parent:String) -> String? {
        guard QuotedSpeechScope.ranges(in:parent).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(parent),
              let body=currentContextBody(parent),
              let fields=currentContextExact(body,#"(?:after|before|if|unless|when|once|until)\s+("# + currentContextPerson + #")\s+confirms\s+([^,;.!?]+),\s*((?:ask|tell|call|phone|email|text|message)\s+[^;.!?]+)"#),
              RuntimeCommunicationReading.completeRecipient(fields[0],delimiter:" confirms"),
              RuntimeIndependentFramePlan.coherentNarrative("Keep one memory. "+fields[1]) != nil,
              fields[1].range(of:#"(?i)\b(?:and|or|but|then|also|I|we|you|will|shall|must|should|need|want)\b"#,options:.regularExpression) == nil,
              let reading=RuntimeCommunicationReading.read(body),reading.isConditionalCurrentAction else { return nil }
        return fields[0]
    }
    static func currentPendingConfirmationContext(_ context:String,belongsTo parent:String) -> Bool {
        guard QuotedSpeechScope.ranges(in:context).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(context),
              let actor=currentConfirmationParentActor(parent),
              let fields=currentContextExact(context,"("+currentContextPerson+#")\s+has\s+(?:(?:only|already)\s+)?(?:inspected|reviewed|checked|seen)\s+(.+?)\s+but\s+has\s+not\s+(?:yet\s+)?confirmed\s+(.+)"#),
              RuntimeRecipientReplacement.normalize(actor) == RuntimeRecipientReplacement.normalize(fields[0]),
              RuntimeCommunicationReading.completeRecipient(fields[0],delimiter:" has inspected"),
              currentFactualContextNominal(fields[1]),currentFactualContextNominal(fields[2]),
              let reading=RuntimeCommunicationReading.read(parent+" "+context),reading.isConditionalCurrentAction else { return false }
        // The two complements remain literal facts. No stable/stability or
        // other paraphrase equality is inferred; no condition becomes fulfilled.
        return true
    }
    static func currentReturnCustodyOwner(_ original:String) -> String? {
        guard QuotedSpeechScope.ranges(in:original).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(original),
              RuntimeSpokenIntentionLabels.reading(original).map({ !["note","memory"].contains($0.kind) }) ?? true else { return nil }
        guard var body=currentContextBody(original) else { return nil }
        if let routing=body.range(of:#"(?i)^\s*(?:last|finally|first|next),\s+(?=(?:remind\s+me|return)\b)"#,options:.regularExpression) { body=String(body[routing.upperBound...]) }
        let time = #"(?:(?:0?[1-9]|1[0-2])(?::[0-5][0-9])?\s+(?:AM|PM)|(?:[01]?[0-9]|2[0-3])(?::[0-5][0-9])?)"#
        let day = #"(?:(?:on\s+)?(?:january|february|march|april|may|june|july|august|september|october|november|december)\s+(?:0?[1-9]|[12][0-9]|3[01])(?:st|nd|rd|th)?(?:,?\s+[0-9]{4})?|today|tomorrow|tonight|(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday))"#
        if let reminder=currentContextExact(body,"remind\\s+me\\s+(?:"+day+"(?:\\s+at\\s+"+time+")?\\s+)?to\\s+(.+)") { body=reminder[0] }
        guard let fields=currentContextExact(body,"return\\s+("+currentContextPerson+#")[’']s\s+([^;.!?]+?)\s+to\s+("#+currentContextPerson+#")(?:\s+("#+day+"))?"),
              RuntimeCommunicationReading.completeRecipient(fields[0],delimiter:"’s object"),
              RuntimeCommunicationReading.completeRecipient(fields[2],delimiter:"."),
              RuntimeRecipientReplacement.normalize(fields[0]) != RuntimeRecipientReplacement.normalize(fields[2]) else { return nil }
        // The explicit possessive and transfer syntax supply a literal object
        // ROLE, not lexical noun tagging or a saved object. Consume every word;
        // a second predicate, actor, condition, correction or pronoun is unproved.
        let object=fields[1]
        guard object.count <= 120,object.range(of:#"^[\p{L}\p{M}][\p{L}\p{M}-]*(?:\s+[\p{L}\p{M}][\p{L}\p{M}-]*){0,4}$"#,options:.regularExpression) != nil,
              object.range(of:#"(?i)\b(?:I|we|you|he|she|they|it|this|that|these|those|and|or|but|then|also|plus|if|unless|when|once|because|before|after|until|which|who|will|shall|must|should|need|want|not|never|no|saved|actually|instead|correction|cancel|withdraw|"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b"#,options:.regularExpression) == nil else { return nil }
        return fields[0]
    }
    static func currentReturnCustodyContext(_ context:String,belongsTo parent:String) -> Bool {
        guard QuotedSpeechScope.ranges(in:context).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(context),
              let owner=currentReturnCustodyOwner(parent),
              let fields=currentContextExact(context,"("+currentContextPerson+#")\s+(?:still\s+)?owns\s+it"#),
              RuntimeCommunicationReading.completeRecipient(fields[0],delimiter:" owns"),
              RuntimeRecipientReplacement.normalize(owner) == RuntimeRecipientReplacement.normalize(fields[0]) else { return false }
        return true
    }
    static func applyCurrentSourcePurposeProofs(_ atoms:inout [CurrentOwnershipAtom],units:RuntimeIndexedSource) {
        guard currentPurposeProofsCanBind(units.source) else { return }
        let ownUnits=Set(units.units.indices.filter { currentOwnedUnitSpan(units.units[$0],source:units.source) != nil })
        let declarations=units.units.indices.filter { currentLoanRetentionDeclaration(units.units[$0].text) }
        // Competing declarations require the ordinary whole-capture graph.
        // Only one complete cluster can fix this local connected account.
        // Count the original declarations BEFORE later-continuity filtering:
        // declining one competing cluster must never make the other unique.
        if declarations.count == 1,let retention=declarations.first,
           let account=currentLoanUncertaintyAccount(units,retentionUnit:retention) {
            let ids=[account.root]+account.contexts
            let members=ids.map { unit in atoms.indices.filter { atoms[$0].unit == unit } }
            if members.allSatisfy({ $0.count == 1 }),members.flatMap({$0}).allSatisfy({
                atoms[$0].anchor.isEmpty && !atoms[$0].retainedKnowledge && !atoms[$0].allocationPurchase
                    && atoms[$0].roleContextOwnerKey.isEmpty && !atoms[$0].hasBoundRoleContext
                    && atoms[$0].sourcePurposeCode.isEmpty && atoms[$0].sourceContextOwnerKey.isEmpty
            }),let root=members.first?.first {
                atoms[root].sourcePurposeCode="N"
                for member in members.dropFirst().flatMap({$0}) { atoms[member].sourceContextOwnerKey=atoms[root].key }
            }
        }
        // Bind only a complete adjacent factual context to a unique current
        // prerequisite actor or returned-object owner. Never synthesize purpose,
        // state, date, contact identity or permission from these literal roles.
        for unit in units.units.indices.dropFirst() {
            guard ownUnits.contains(unit-1),ownUnits.contains(unit) else { continue }
            let parents=atoms.indices.filter { atoms[$0].unit == unit-1 },children=atoms.indices.filter { atoms[$0].unit == unit }
            guard parents.count == 1,children.count == 1 else { continue }
            let parent=parents[0],child=children[0]
            guard [parent,child].allSatisfy({ atoms[$0].anchor.isEmpty && !atoms[$0].retainedKnowledge && !atoms[$0].allocationPurchase && atoms[$0].roleContextOwnerKey.isEmpty && !atoms[$0].hasBoundRoleContext && atoms[$0].sourceContextOwnerKey.isEmpty }),
                  atoms[child].sourcePurposeCode.isEmpty,
                  atoms[parent].sourcePurposeCode.isEmpty || atoms[parent].sourcePurposeCode == "T" else { continue }
            func unique(_ actor:String,_ reader:(String)->String?) -> Bool {
                units.units.indices.filter { ownUnits.contains($0) && reader(units.units[$0].text).map({ RuntimeRecipientReplacement.normalize($0) == RuntimeRecipientReplacement.normalize(actor) }) == true }.count == 1
            }
            let pending=currentConfirmationParentActor(units.units[unit-1].text).map { actor in
                unique(actor,currentPotentialConfirmationActor) && currentPendingConfirmationContext(units.units[unit].text,belongsTo:units.units[unit-1].text)
            } ?? false
            let custody=currentReturnCustodyOwner(units.units[unit-1].text).map { owner in
                unique(owner,currentPotentialReturnOwner) && currentReturnCustodyContext(units.units[unit].text,belongsTo:units.units[unit-1].text)
            } ?? false
            if pending || custody { atoms[child].sourceContextOwnerKey=atoms[parent].key }
        }
        for index in atoms.indices where ownUnits.contains(atoms[index].unit) && atoms[index].anchor.isEmpty && !atoms[index].retainedKnowledge && !atoms[index].allocationPurchase
            && atoms[index].sourcePurposeCode.isEmpty && atoms[index].sourceContextOwnerKey.isEmpty {
            if let code=currentSourcePurpose(units.units[atoms[index].unit].text) { atoms[index].sourcePurposeCode=code }
        }
        for unit in units.units.indices.dropFirst() {
            guard ownUnits.contains(unit-1),ownUnits.contains(unit) else { continue }
            let parents=atoms.indices.filter { atoms[$0].unit == unit-1 },children=atoms.indices.filter { atoms[$0].unit == unit }
            guard parents.count == 1,children.count == 1 else { continue }
            let parent=parents[0],child=children[0]
            guard atoms[parent].anchor.isEmpty,atoms[child].anchor.isEmpty,
                  !atoms[child].retainedKnowledge,!atoms[child].allocationPurchase,
                  atoms[child].sourcePurposeCode.isEmpty,atoms[child].sourceContextOwnerKey.isEmpty else { continue }
            let purchase=atoms[parent].sourcePurposeCode == "S"
                && currentPurchaseExclusionContext(units.units[unit].text,belongsTo:units.units[unit-1].text)
            let reminder=currentNegativeReminderContext(units.units[unit].text,belongsTo:units.units[unit-1].text)
                && (atoms[parent].sourcePurposeCode.isEmpty || atoms[parent].sourcePurposeCode == "T")
                && atoms[parent].sourceContextOwnerKey.isEmpty && atoms[parent].roleContextOwnerKey.isEmpty
                && !atoms[parent].hasBoundRoleContext && !atoms[parent].retainedKnowledge && !atoms[parent].allocationPurchase
            if reminder {
                // The complete affirmative reminder request owns the negative
                // payload; negating that payload cannot withdraw the request
                // into its own later clarification. Clock/state/delivery are
                // still decided by the unchanged full-source validators.
                atoms[parent].sourcePurposeCode="T"
