            guard ownUnits.contains(unit-1),ownUnits.contains(unit) else { continue }
            let parents=atoms.indices.filter { atoms[$0].unit == unit-1 },children=atoms.indices.filter { atoms[$0].unit == unit }
            guard parents.count == 1,children.count == 1 else { continue }
            let parent=parents[0],child=children[0]
            guard atoms[parent].anchor.isEmpty,atoms[child].anchor.isEmpty,
                  !atoms[parent].retainedKnowledge,!atoms[parent].allocationPurchase,
                  !atoms[child].retainedKnowledge,!atoms[child].allocationPurchase,
                  atoms[parent].sourcePurposeCode.isEmpty,atoms[child].sourcePurposeCode.isEmpty,
