    /// A later finite own statement can retract an earlier other-person
    /// ownership bond. This is a conservative optimization veto, never proof
    /// of adoption or action permission; the complete graph stays unresolved.
    /// Contracted present forms may precede going-to, responsibility or another
    /// finite predicate, including intervening adverbs and negation.
    static func currentLaterOwnRoleMayChange(_ text:String)->Bool {
        // Any later first-person statement requires whole-capture role
        // reconciliation. Word boundaries also include I’m/I’ve/I’ll and
        // we’re/we’ve/we’ll. Explicit let/allow-me/us, take-over and assume-
        // responsibility transfers also require full reconciliation. A bare
        // object pronoun in an independent reminder is not a transfer. This declines
        // early sealing, without pretending a command/denial proves adoption.
        text.range(of:#"(?i)\b(?:I|we)\b|\b(?:let|allow)\s+(?:me|us)\b|\b(?:take|taking|taken)\s+over\b|\b(?:assume|assuming|assumed)\s+(?:the\s+)?responsibility\b"#,options:.regularExpression) != nil
    }
    static func currentRoleContext(_ context:String,belongsTo previous:String) -> Bool {
        guard QuotedSpeechScope.ranges(in:previous + " " + context).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(previous + " " + context) else { return false }
        func exact(_ text:String,_ pattern:String) -> [String]? {
            guard let (range,fields)=RuntimeRecipientReplacement.match(text,from:text.startIndex,pattern:"(?:" + pattern + ")$"),
                  range.upperBound == text.endIndex else { return nil };return fields
        }
        func same(_ a:String,_ b:String) -> Bool {
            RuntimeRecipientReplacement.normalize(a) == RuntimeRecipientReplacement.normalize(b)
        }
        let name = #"\p{L}[\p{L}\p{M}'’-]*(?:\s+\p{L}[\p{L}\p{M}'’-]*)?"#
        let person = "(?:" + PersonMentionResolver.communicationRelationPhrasePattern + "|" + name + ")"
        let relation = PersonMentionResolver.communicationRelationPhrasePattern
        // The entire subject is retained verbatim. Reject executable tails,
        // conditions, replacements and coordination before binding context.
        func boundedSubject(_ text:String) -> Bool {
            !text.isEmpty && text.count <= 160
                && text.range(of:#"^[\p{L}\p{M}0-9 '’,-]+$"#,options:.regularExpression) != nil
                && !text.contains("--")
                && text.range(of:#"(?i)\b(?:and|or|plus|also|but|yet|then|so|if|unless|when|once|since|before|after|until|instead|actually|correction|not|never|saved|existing|remind|alert|notify|i|we|you|he|she|they|will|would|should|must|need|want|to|"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b"#,options:.regularExpression) == nil
        }
        if let action=exact(previous,#"(?:please\s+)?Tell\s+("# + name + #")\s+to\s+ask\s+their\s+("# + relation + #")\s+about\s+([^;.!?]+)[;.!]?"#),
           let clarification=exact(context,#"I\s+am\s+contacting\s+("# + name + #"),\s*not\s+that\s+("# + relation + #")[.!]?"#),
           action.count == 3,clarification.count == 2,
           RuntimeRecipientReplacement.literalRecipient(action[0]),boundedSubject(action[2]),
           same(action[0],clarification[0]),same(action[1],clarification[1]),
           RuntimeCommunicationReading.read(previous).map({ same($0.recipient,action[0]) }) == true {
            return true
        }
        let clock = #"(?:(?:on|by)\s+)?(?:(?:january|february|march|april|may|june|july|august|september|october|november|december)\s+[0-9]{1,2}(?:st|nd|rd|th)?(?:,?\s+[0-9]{4})?|today|tomorrow|tonight)"#
        if let action=exact(previous,#"(?:please\s+)?Return\s+("# + name + #")[’']s\s+([^;.!?]+?)\s+to\s+("# + person + #")(?:\s+("# + clock + #"))?[;.!]?"#),
           let clarification=exact(context,#"("# + name + #")\s+remains\s+owner\s+and\s+("# + person + #")\s+is\s+only\s+recipient[.!]?"#),
           action.count == 4,clarification.count == 2,boundedSubject(action[1]),
           RuntimeRecipientReplacement.literalRecipient(action[0]),RuntimeRecipientReplacement.literalRecipient(action[2]),
           same(action[0],clarification[0]),same(action[2],clarification[1]),!same(action[0],action[2]) {
            return true
        }
        return false
    }
    /// Unlike a local purpose hint, this proves the complete current plan,
    /// every report/refusal boundary, and every source unit before constraining
    /// generation. The small-capture generic constructor gate remains intact.
    private static func applyRecordedCommitmentOwnership(_ atoms:inout [CurrentOwnershipAtom],units:RuntimeIndexedSource,
                                                         referenceDate:Date?,calendar:Calendar?) {
        guard let referenceDate,let calendar,
              let plan=RuntimeRecordedCommitmentCertificate.read(units.source,referenceDate:referenceDate,calendar:calendar),
              atoms.count == units.units.count,
              atoms.allSatisfy({ $0.anchor.isEmpty && !$0.retainedKnowledge && !$0.allocationPurchase
                  && $0.roleContextOwnerKey.isEmpty && !$0.hasBoundRoleContext
                  && $0.sourcePurposeCode.isEmpty && $0.sourceContextOwnerKey.isEmpty }) else { return }
        let assignments=plan.map { frame in frame.evidence.map { unit in atoms.indices.filter { atoms[$0].unit == unit } } }
        guard assignments.flatMap({$0}).allSatisfy({ $0.count == 1 }) else { return }
        for (frame,members) in zip(plan,assignments) {
            guard let root=members.first?.first else { return }
            atoms[root].sourcePurposeCode=frame.adopted ? "T" : "N"
            for index in members.dropFirst().flatMap({$0}) { atoms[index].sourceContextOwnerKey=atoms[root].key }
        }
    }
    static func fixedOutlineAtoms(_ units:RuntimeIndexedSource,referenceDate:Date? = nil,calendar:Calendar? = nil) -> [CurrentOwnershipAtom] {
        if let referenceDate,let calendar,
           let whole=RuntimeDeniedRequestPlan.read(units,referenceDate:referenceDate,calendar:calendar) {
            // All three source-proved frames share complete provenance. Their
            // literal anchors and purposes are derived together before any
            // model call; no example or generated answer supplies a slot.
            return whole.enumerated().map { index,frame in
                var atom=CurrentOwnershipAtom(key:"u0a\(index)",unit:0,anchor:frame.anchor)
                atom.sourcePurposeCode=frame.adopted ? "T" : "N"
                return atom
            }
        }
        var atoms = units.units.enumerated().flatMap { id,unit -> [CurrentOwnershipAtom] in
            let own=currentOwnedUnitSpan(unit,source:units.source) != nil
            let ordinary = [CurrentOwnershipAtom(key:"u\(id)",unit:id,anchor:"",retainedKnowledge:own && independentRetainedKnowledge(unit.text),allocationPurchase:own && independentAllocationPurchase(unit.text))]
            // Complete capture ownership precedes every positive constructor
            // privilege. A quote split at a sentence boundary remains reported
            // evidence with an expressive ordinary atom, never an own task.
            guard own,QuotedSpeechScope.ranges(in:unit.text).isEmpty,
                  !QuotedSpeechScope.hasUnclosedQuote(unit.text),
                  let marker = unit.text.range(of:#"(?i)\bto\s+"#,options:.regularExpression) else { return ordinary }
            let prefix = String(unit.text[..<marker.lowerBound]) + "to "
            let body = String(unit.text[marker.upperBound...]).trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!?")))
            let separated = body.replacingOccurrences(of:#"(?i)\s+and\s+to\s+"#,with:"\n",options:.regularExpression)
            let parts = separated.split(separator:"\n",omittingEmptySubsequences:false).map(String.init)
            guard parts.count > 1,RuntimeDeclaredTaskPartition.prefix(prefix,count:parts.count),
                  parts.allSatisfy({ RuntimeDeclaredTaskPartition.predicate($0) }) else { return ordinary }
            return parts.enumerated().map { CurrentOwnershipAtom(key:"u\(id)a\($0.offset)",unit:id,anchor:$0.element) }
        }
        applyRecordedCommitmentOwnership(&atoms,units:units,referenceDate:referenceDate,calendar:calendar)
        if RuntimeCurrentPurchaseStatus.read(units),atoms.count == 2,
           atoms.enumerated().allSatisfy({ index,atom in atom.unit == index && atom.anchor.isEmpty
               && !atom.retainedKnowledge && !atom.allocationPurchase && atom.roleContextOwnerKey.isEmpty
               && !atom.hasBoundRoleContext && atom.sourcePurposeCode.isEmpty && atom.sourceContextOwnerKey.isEmpty }) {
            atoms[0].sourcePurposeCode="S"
            atoms[1].sourceContextOwnerKey=atoms[0].key
        }
        if atoms.count > 5 { applyCurrentSourcePurposeProofs(&atoms,units:units) }
        // A complete denied agreement has no own action even in a short
        // capture. Bind ONLY this proved status after checking the complete
        // capture for later adoption/correction and whole-source voice scope.
        // The generic >5 purpose optimization and every other atom stay as-is.
        if currentPurposeProofsCanBind(units.source) {
            for unit in units.units.indices where currentOwnedUnitSpan(units.units[unit],source:units.source) != nil
                && currentDeniedAgreementStatus(units.units[unit].text) {
                let indices=atoms.indices.filter { atoms[$0].unit == unit }
                guard indices.count == 1 else { continue }
                let index=indices[0]
                guard atoms[index].anchor.isEmpty,!atoms[index].retainedKnowledge,!atoms[index].allocationPurchase,
                      atoms[index].roleContextOwnerKey.isEmpty,!atoms[index].hasBoundRoleContext,
                      atoms[index].sourceContextOwnerKey.isEmpty,
                      atoms[index].sourcePurposeCode.isEmpty || atoms[index].sourcePurposeCode == "N" else { continue }
                atoms[index].sourcePurposeCode="N"
            }
        }
        // A local role clarification is provisional when any current unit
        // changes or withdraws meaning. Preserve the ordinary whole-capture
        // links so a nonadjacent correction can reconcile its earlier owner.
        let changesCurrentMeaning = units.source.range(of:#"(?i)\b(?:actually|instead|correction|never\s+mind|cancel|withdraw|make\s+that|no|wait|sorry|leave\s+that\s+off|take\s+that\s+back|replace|switch|switched|change|changed|forget|scratch|remove|stop|don['’]?t|do\s+not)\b"#,options:.regularExpression) != nil
        guard !changesCurrentMeaning else { return atoms }
        let unboundAtoms=atoms
        for unit in units.units.indices.dropFirst() {
            let current=atoms.indices.filter { atoms[$0].unit == unit }
            let preceding=atoms.indices.filter { atoms[$0].unit == unit-1 }
            guard current.count == 1,preceding.count == 1,
                  currentOwnedUnitSpan(units.units[unit],source:units.source) != nil,
                  currentOwnedUnitSpan(units.units[unit-1],source:units.source) != nil else { continue }
            let child=current[0],parent=preceding[0]
            guard atoms[child].anchor.isEmpty,atoms[parent].anchor.isEmpty,
                  !atoms[parent].retainedKnowledge,!atoms[parent].allocationPurchase,
                  atoms[parent].roleContextOwnerKey.isEmpty,!atoms[child].retainedKnowledge,!atoms[child].allocationPurchase,
                  currentRoleContext(units.units[unit].text,belongsTo:units.units[unit-1].text) else { continue }
            atoms[child].roleContextOwnerKey=atoms[parent].key
            atoms[parent].hasBoundRoleContext=true
        }
        // Match the COMPLETE capture before fixing a local role bond. An
        // unpaired own role assertion/denial can retract that earlier role
        // without an explicit correction word. Preserve ordinary links so the
        // whole affected intention can become one review row or be revised.
        for (unit,sourceUnit) in units.units.enumerated() {
            let own=QuotedSpeechScope.voiceProjection(in:sourceUnit.text)?.ownVoiceText ?? sourceUnit.text
            // A role word outside a complete paired context declines this
            // compact optimization, including inverted/copular statements.
            // It does not classify a conflict or choose a replacement role.
            let assertsRole=own.range(of:#"(?i)\b(?:contact|contacts|contacting|owner|owners|ownership|recipient|recipients|owns\s+it|not|isn['’]?t|aren['’]?t)\b"#,options:.regularExpression) != nil
            if assertsRole, !atoms.contains(where:{ $0.unit == unit && !$0.roleContextOwnerKey.isEmpty }) { return unboundAtoms }
        }
        return atoms
    }
    /// Unsupported shared source retains the existing expressive outline.
    /// These syntax signals choose a contract, never approve any semantics.
    /// The compact graph cannot absorb multiple unproved acts or donate one
    /// detached collective context atom to only one of its source owners.
    static func fixedOutlineEligible(_ units:RuntimeIndexedSource,atoms:[CurrentOwnershipAtom],
                                     referenceDate:Date? = nil,calendar:Calendar? = nil) -> Bool {
        // The existing complete five-unit conditional reader independently
        // proves its one alternative matrix. Exempt only that exact current
        // occurrence from the inner-predicate syntax gate. Every condition,
        // denial and literal source atom still reaches whole-plan validation.
        var provedConditionalAlternatives:Set<Int>=[]
        if let referenceDate,let calendar,units.units.count >= 5 {
            for start in 0...(units.units.count-5) {
                let group=Array(start..<(start+5))
                guard group.allSatisfy({ id in
                    currentOwnedUnitSpan(units.units[id],source:units.source) != nil
                        && atoms.filter({ $0.unit == id }).count == 1
                }) else { continue }
                let source=group.map { units.units[$0].text }.joined(separator:" ")
                if RuntimeCurrentConditionalWatering.read(source,referenceDate:referenceDate,calendar:calendar) != nil {
                    provedConditionalAlternatives.insert(start+1)
                }
            }
        }
        for (id,unit) in units.units.enumerated() {
            let own=QuotedSpeechScope.voiceProjection(in:unit.text)?.ownVoiceText ?? unit.text
            if own.range(of:#"(?i)\b(?:both|all|each|every|those\s+(?:tasks|jobs))\b"#,options:.regularExpression) != nil {
#if DEBUG
                developmentObserver?("outline contract phase=contract-selection currentUnit=u\(id) reason=unproved-collective-context")
#endif
                return false
            }
            if atoms.filter({ $0.unit == id }).count > 1 { continue }
            // A complete typed allocation already reconciles the replacement
            // and every independent owner. It needs one ownership decision,
            // not a generated echo of all quantities. This only chooses the
            // compact contract; the complete current graph is validated later.
            if let allocations=RuntimeAllocationReading.expected(RuntimeFoundationActionShape.body(unit.text)) {
                guard allocations.allSatisfy({ RuntimeCurrentNominalProof.read($0.object) }) else {
#if DEBUG
                    developmentObserver?("outline contract phase=contract-selection currentUnit=u\(id) reason=unproved-allocation-nominal")
#endif
                    return false
                }
                continue
            }
            let continuation = #"(?i)(?:\b(?:and|otherwise|alternatively|plus|then|also)\s+|\+\s*|[,;:/]\s*(?:(?:and|otherwise|alternatively|plus|then|also)\s+)?)(?:(?:to|(?:i|we)\s+(?:will|must|should|(?:need|have|want)\s+to))\s+)?(?:please\s+)?(?:"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b"#
            // The closed current-position prefix is capture routing, not a
            // first predicate. Read its proved body only for this syntax
            // choice; the prompt, ownership atoms and validator retain every
            // original current unit, including later corrections and context.
            // A leading connective routes this FIRST current predicate.
            // It is not an additional act. Strip only that exact prefix for
            // the syntax gate; all original atoms/source stay in the prompt
            // and complete decoder/validator. Inner coordinated acts still
            // match the unchanged continuation expression below.
            let predicateBody=RuntimeFoundationActionShape.body(own)
                .replacingOccurrences(of:#"(?i)^(?:and|also|then|plus)\s+(?=(?:please\s+)?(?:"#
                    + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b)"#,
                    with:"",options:.regularExpression)
            let predicateMatches=NSRegularExpression.speakItCached(continuation)?.matches(in:predicateBody,range:NSRange(predicateBody.startIndex...,in:predicateBody)) ?? []
            // The existing complete conditional reading retains its condition
            // and matrix recipient. Its sole comma introduces the FIRST
            // action, not another act. Any second predicate still requires
            // the expressive contract. No condition becomes alert permission.
            let singleConditional:Bool = {
                guard predicateMatches.count == 1,
                      let reading=RuntimeCommunicationReading.read(predicateBody),reading.isConditionalCurrentAction,
                      reading.action.filter({ $0 == "," }).count == 1 else { return false }
                // This optimization covers one uncoordinated current matrix.
                // A conjunction/alternative or additional own commitment
                // retains the expressive contract even when it is phrased as
                // "or I'll call", "but we shall...", or a comma continuation.
                // Conditions, delegated subjects and literal relatives stay
                // in the complete original source and validator either way.
                return reading.action.range(of:#"(?i)\b(?:and|or|but|yet|otherwise|alternatively|plus|then|also|i|we)\b"#,options:.regularExpression) == nil
            }()
            if !predicateMatches.isEmpty && !singleConditional && !provedConditionalAlternatives.contains(id) {
#if DEBUG
                developmentObserver?("outline contract phase=contract-selection currentUnit=u\(id) reason=unproved-inner-predicate")
#endif
                return false
            }
            if own.range(of:#"(?i)\bdistinct\s+(?:tasks|jobs)\b"#,options:.regularExpression) != nil {
#if DEBUG
                developmentObserver?("outline contract phase=contract-selection currentUnit=u\(id) reason=unproved-declared-partition")
#endif
                return false
            }
        }
        return true
    }
    static func fixedOutlineSchema(_ atoms:[CurrentOwnershipAtom]) throws -> GenerationSchema? {
        guard !atoms.isEmpty,Set(atoms.map(\.key)).count == atoms.count else { return nil }
        // A free String guide admitted echoed schema descriptions instead
        // of decisions. The installed SDK constrains this shared enum to only
        // purpose codes and links to actual CURRENT keys. Decoding still proves
        // exact membership, direct canonical links and no cycles/orphans.
        let canonicalCodes = ["T","S","P","I","N","D","Q","R"]
        let choices = canonicalCodes + atoms.filter { !$0.retainedKnowledge && !$0.allocationPurchase && $0.roleContextOwnerKey.isEmpty && $0.sourceContextOwnerKey.isEmpty }.flatMap { ["="+$0.key,"!"+$0.key] }
        let decision = DynamicGenerationSchema(name:"CurrentOwnerDecision",anyOf:choices)
        let literalTask = DynamicGenerationSchema(name:"DeclaredCurrentTask",anyOf:["T"])
        let retainedFact = DynamicGenerationSchema(name:"RetainedCurrentFact",anyOf:["N"])
        let allocationPurchase = DynamicGenerationSchema(name:"AllocatedCurrentPurchase",anyOf:["S"])
        let roleOwner = DynamicGenerationSchema(name:"CurrentMatrixOwner",anyOf:canonicalCodes)
        let roleContexts=atoms.filter { !$0.roleContextOwnerKey.isEmpty }.map { atom in
            DynamicGenerationSchema(name:"BoundCurrentRole_" + atom.key,anyOf:["=" + atom.roleContextOwnerKey])
        }
        let sourceProofs=atoms.filter { !$0.sourcePurposeCode.isEmpty || !$0.sourceContextOwnerKey.isEmpty }.map { atom in
            DynamicGenerationSchema(name:"ProvedCurrentSpeechAct_" + atom.key,anyOf:compactAllowedDecisions(atom,atoms:atoms))
        }
        let root = DynamicGenerationSchema(name:"CompleteCurrentOwnership",properties:atoms.map { atom in
            let type = !atom.roleContextOwnerKey.isEmpty ? "BoundCurrentRole_" + atom.key : (!atom.sourcePurposeCode.isEmpty || !atom.sourceContextOwnerKey.isEmpty) ? "ProvedCurrentSpeechAct_" + atom.key : atom.hasBoundRoleContext ? "CurrentMatrixOwner" : atom.retainedKnowledge ? "RetainedCurrentFact" : atom.allocationPurchase ? "AllocatedCurrentPurchase" : atom.anchor.isEmpty ? "CurrentOwnerDecision" : "DeclaredCurrentTask"
            return .init(name:atom.key,schema:.init(referenceTo:type))
        })
        var dependencies=[decision] + roleContexts + sourceProofs
        if atoms.contains(where:{ $0.hasBoundRoleContext }) { dependencies.append(roleOwner) }
        if atoms.contains(where:{ !$0.anchor.isEmpty }) { dependencies.append(literalTask) }
        if atoms.contains(where:{ $0.retainedKnowledge }) { dependencies.append(retainedFact) }
        if atoms.contains(where:{ $0.allocationPurchase }) { dependencies.append(allocationPurchase) }
        return try GenerationSchema(root:root,dependencies:dependencies)
    }
    /// Guided generation serializes each property guide independently. The
    /// old keyed schema repeats its large current-link enum for every atom.
    /// One exact-length ordered array encodes the SAME complete dispositions;
    /// the current-source decoder retains every per-atom proof constraint.
    static func compactAllowedDecisions(_ atom:CurrentOwnershipAtom,atoms:[CurrentOwnershipAtom])->[String] {
        let canonical=["T","S","P","I","N","D","Q","R"]
        if !atom.roleContextOwnerKey.isEmpty { return ["="+atom.roleContextOwnerKey] }
        if !atom.sourceContextOwnerKey.isEmpty { return ["="+atom.sourceContextOwnerKey] }
        if !atom.sourcePurposeCode.isEmpty { return [atom.sourcePurposeCode] }
        if atom.retainedKnowledge { return ["N"] }
        if atom.allocationPurchase { return ["S"] }
        if !atom.anchor.isEmpty { return ["T"] }
        if atom.hasBoundRoleContext { return canonical }
        return canonical + atoms.filter { !$0.retainedKnowledge && !$0.allocationPurchase && $0.roleContextOwnerKey.isEmpty && $0.sourceContextOwnerKey.isEmpty }.flatMap { ["="+$0.key,"!"+$0.key] }
    }
    static func compactOutlineSchema(_ atoms:[CurrentOwnershipAtom]) throws -> GenerationSchema? {
        guard !atoms.isEmpty,Set(atoms.map(\.key)).count == atoms.count else { return nil }
        var choices:[String]=[]
        for atom in atoms { for code in compactAllowedDecisions(atom,atoms:atoms) where !choices.contains(code) { choices.append(code) } }
        let decision=DynamicGenerationSchema(name:"CurrentOrderedDecision",anyOf:choices)
        let root=DynamicGenerationSchema(name:"CompleteCurrentOwnershipArray",properties:[
            .init(name:"decisions",description:"Exactly one decision for every CURRENT slot, in supplied slot order. No omitted or extra decisions.",schema:.init(arrayOf:.init(referenceTo:"CurrentOrderedDecision"),minimumElements:atoms.count,maximumElements:atoms.count))
        ])
        return try GenerationSchema(root:root,dependencies:[decision])
    }
    static func decodeCompactOutline(_ content:GeneratedContent,atoms:[CurrentOwnershipAtom]) throws -> [FirstOutlineRow]? {
        guard !atoms.isEmpty,Set(atoms.map(\.key)).count == atoms.count,
              let raw=content.jsonString.data(using:.utf8),let object=try JSONSerialization.jsonObject(with:raw) as? [String:Any],
              Set(object.keys) == ["decisions"],let decisions=object["decisions"] as? [String],decisions.count == atoms.count else { return nil }
        var current:[String:String]=[:]
        for (atom,code) in zip(atoms,decisions) {
            guard compactAllowedDecisions(atom,atoms:atoms).contains(code) else { return nil }
            current[atom.key]=code
        }
        let data=try JSONSerialization.data(withJSONObject:current,options:[.sortedKeys])
        // Reuse the exact full ownership/link/purpose/role/withdrawal decoder.
        // Array position cannot bypass a forced purpose, orphan, cycle, bound
        // role, missing atom or independent current-source owner constraint.
        return try decodeFixedOutline(GeneratedContent(json:String(decoding:data,as:UTF8.self)),atoms:atoms)
    }
    /// Keyed integers keep each CURRENT atom explicitly named while avoiding
    /// SDK serialization of the full link enum at every property. The numeric
    /// transport has no semantic authority: decode rechecks each current proof
    /// and passes the complete keyed meanings to the unchanged graph decoder.
    static func integerOutlineSchema(_ atoms:[CurrentOwnershipAtom]) throws -> GenerationSchema? {
        guard !atoms.isEmpty,Set(atoms.map(\.key)).count == atoms.count else { return nil }
        let canonical=["T","S","P","I","N","D","Q","R"]
        func integer(_ code:String)->Int? {
            if let i=canonical.firstIndex(of:code) { return i }
            guard let i=atoms.firstIndex(where:{$0.key == String(code.dropFirst())}) else { return nil }
            return 8+i+(code.hasPrefix("!") ? atoms.count : 0)
        }
        let properties=atoms.map { atom -> DynamicGenerationSchema.Property in
            let allowed=compactAllowedDecisions(atom,atoms:atoms)
            let range:ClosedRange<Int>
            if allowed.count == 1,let value=integer(allowed[0]) { range=value...value }
            else if atom.hasBoundRoleContext { range=0...7 }
            else { range=0...(7+2*atoms.count) }
            return .init(name:atom.key,schema:.init(type:Int.self,guides:[.range(range)]))
        }
        // The complete semantic instructions accompany the call once.
        // Repeating them in the schema costs current-context/reference room.
        // Every required key, integer type and per-atom range is unchanged;
        // complete source constraints remain enforced again by the decoder.
        return try GenerationSchema(root:.init(name:"CompleteCurrentKeyedIntegers",properties:properties),dependencies:[])
    }
    static func decodeIntegerOutline(_ content:GeneratedContent,atoms:[CurrentOwnershipAtom]) throws -> [FirstOutlineRow]? {
        guard !atoms.isEmpty,Set(atoms.map(\.key)).count == atoms.count,
              let data=content.jsonString.data(using:.utf8),let raw=try JSONSerialization.jsonObject(with:data) as? [String:Any],
              Set(raw.keys) == Set(atoms.map(\.key)) else { return nil }
        let canonical=["T","S","P","I","N","D","Q","R"]
        var current:[String:String]=[:]
        for atom in atoms {
            guard let number=raw[atom.key] as? NSNumber,CFGetTypeID(number) != CFBooleanGetTypeID(),
                  number.doubleValue.isFinite,number.doubleValue.rounded(.towardZero) == number.doubleValue,
                  number.doubleValue >= 0,number.doubleValue <= Double(7+2*atoms.count) else { return nil }
            let value=number.intValue,code:String
            if value < 8 { code=canonical[value] }
            else {
                let link=value-8,changed=link >= atoms.count,index=link % atoms.count
                code=(changed ? "!" : "=")+atoms[index].key
            }
            guard compactAllowedDecisions(atom,atoms:atoms).contains(code) else { return nil }
            current[atom.key]=code
        }
        let encoded=try JSONSerialization.data(withJSONObject:current,options:[.sortedKeys])
        return try decodeFixedOutline(GeneratedContent(json:String(decoding:encoded,as:UTF8.self)),atoms:atoms)
    }
    /// Speech act and ownership are separate decisions. The model does not
    /// perform arithmetic to encode a purpose or current link. Homogeneous
    /// array guides cannot express per-slot singleton bounds: the complete
    /// decoder therefore re-proves EVERY original per-atom constraint before
    /// invoking the unchanged full graph decoder and source/state validator.
    static func separatedOutlineSchema(_ atoms:[CurrentOwnershipAtom]) throws -> GenerationSchema? {
        guard !atoms.isEmpty,Set(atoms.map(\.key)).count == atoms.count else { return nil }
        let purpose=DynamicGenerationSchema(name:"CurrentSpeechAct",anyOf:["task","shopping","packing","inventory","note","idea","question","review","context","correction"])
        let owner=DynamicGenerationSchema(type:Int.self,guides:[.range(0...(atoms.count-1))])
        let root=DynamicGenerationSchema(name:"CompleteCurrentPurposeAndOwnership",properties:[
            .init(name:"purposes",description:"Exactly one speech act for every current slot, in slot order.",schema:.init(arrayOf:.init(referenceTo:"CurrentSpeechAct"),minimumElements:atoms.count,maximumElements:atoms.count)),
            .init(name:"owners",description:"Same slot order. Canonical purpose owns its own slot position. Context/correction points directly to its canonical current owner position.",schema:.init(arrayOf:owner,minimumElements:atoms.count,maximumElements:atoms.count))
        ])
        return try GenerationSchema(root:root,dependencies:[purpose])
    }
    static func decodeSeparatedOutline(_ content:GeneratedContent,atoms:[CurrentOwnershipAtom]) throws -> [FirstOutlineRow]? {
        guard !atoms.isEmpty,Set(atoms.map(\.key)).count == atoms.count,
              let bytes=content.jsonString.data(using:.utf8),let raw=try JSONSerialization.jsonObject(with:bytes) as? [String:Any],
              Set(raw.keys) == ["purposes","owners"],let purposes=raw["purposes"] as? [String],
              let owners=raw["owners"] as? [NSNumber],purposes.count == atoms.count,owners.count == atoms.count else { return nil }
        let codes=["task":"T","shopping":"S","packing":"P","inventory":"I","note":"N","idea":"D","question":"Q","review":"R"]
        var current:[String:String]=[:]
        for (index,atom) in atoms.enumerated() {
            let number=owners[index]
            guard CFGetTypeID(number) != CFBooleanGetTypeID(),number.doubleValue.isFinite,
                  number.doubleValue.rounded(.towardZero) == number.doubleValue,
                  number.doubleValue >= 0,number.doubleValue < Double(atoms.count) else { return nil }
            let owner=number.intValue,code:String
            if let purpose=codes[purposes[index]] {
                guard owner == index else { return nil }
                code=purpose
            } else if purposes[index] == "context" || purposes[index] == "correction" {
                code=(purposes[index] == "context" ? "=" : "!")+atoms[owner].key
            } else { return nil }
            guard compactAllowedDecisions(atom,atoms:atoms).contains(code) else { return nil }
            current[atom.key]=code
