    static func currentLiteralSharedRows(_ items:[IndexedItem],sharedRows:Set<Int>,units:RuntimeIndexedSource,
                                         referenceDate:Date,calendar:Calendar) -> Set<Int> {
        guard validOwnership(items,units:units),sharedUnitTiming(items,units:units,referenceDate:referenceDate,calendar:calendar) != nil else { return [] }
        if let denied=provedDeniedRows(items,units:units,referenceDate:referenceDate,calendar:calendar),
           !denied.isEmpty,Set(denied.keys) == Set(items.indices),sharedRows == Set(items.indices) {
            // Exact whole-current denial and adopted chores are already
            // reconciled across every row; regenerating names/anchors would
            // increase cost and risk without adding missing meaning.
            return sharedRows
        }
        return Set(sharedRows.filter { index in
            let item=items[index]
            guard item.evidence.count == 1,!item.anchor.isEmpty,!item.needsReview,item.purpose == .task,
                  item.currentMeaning == item.anchor,RuntimeDeclaredTaskPartition.predicate(item.anchor) else { return false }
            let id=item.evidence[0],unit=units.units[id].text,owners=items.filter { $0.evidence.contains(id) }
