    /// no source proof is silently approved or substituted into a first call.
    static func decodeInlineCurrentRevisions(_ completions:[[String]],rowCount:Int,
        requestedRows:Set<Int>,sharedRows:Set<Int>) throws -> [IndexedRevision]? {
        guard completions.count == rowCount,requestedRows.isSubset(of:Set(0..<rowCount)),
              sharedRows.isSubset(of:requestedRows) else { return nil }
        var revisions:[String:Any]=[:]
        for (row,value) in completions.enumerated() {
            guard requestedRows.contains(row) ? value.count == 3 : value.isEmpty else { return nil }
            guard requestedRows.contains(row) else { continue }
