                  let rewrite=row["r"] as? NSNumber,CFGetTypeID(rewrite) == CFBooleanGetTypeID(),
                  let review=row["v"] as? NSNumber,CFGetTypeID(review) == CFBooleanGetTypeID() else { return nil }
