    static func decodeCompactExpressiveOutline(_ content:GeneratedContent,units:RuntimeIndexedSource) throws -> [FirstOutlineRow]? {
        guard let data=content.jsonString.data(using:.utf8),
              let object=try JSONSerialization.jsonObject(with:data) as? [String:Any],Set(object.keys) == ["rows"],
              let strings=object["rows"] as? [String],!strings.isEmpty else { return nil }
