    }

    static func decodeDynamicOutline(_ content: GeneratedContent,units: RuntimeIndexedSource,currentJointCalls:[CurrentJointCallCandidate] = []) throws -> [FirstOutlineRow]? {
        guard currentJointCalls.isEmpty || currentJointCalls == currentJointCallCandidates(units) else { return nil }
        if !currentJointCalls.isEmpty {
            guard let data=content.jsonString.data(using:.utf8),
                  let object=try JSONSerialization.jsonObject(with:data) as? [String:Any],Set(object.keys) == ["items"],
                  let rawRows=object["items"] as? [[String:Any]],rawRows.allSatisfy({ Set($0.keys) == ["evidence","purpose","requiresRewrite","needsReview","currentReconciliation"] }) else { return nil }
        }
        let mapping = Dictionary(uniqueKeysWithValues:units.units.indices.map { ("u\($0)",$0) })
        let rows = try content.value([GeneratedContent].self,forProperty:"items")
        guard !rows.isEmpty else { return nil }
        var result: [FirstOutlineRow] = []
        for row in rows {
            let labels = try row.value([String].self,forProperty:"evidence")
            let ids = labels.compactMap { mapping[$0] }
            guard !ids.isEmpty,ids.count == labels.count,ids == Array(Set(ids)).sorted() else { return nil }
            let purpose: Purpose
            switch try row.value(String.self,forProperty:"purpose") {
            case "task":purpose = .task
            case "shopping":purpose = .shopping
            case "packing":purpose = .packing
            case "inventory":purpose = .inventory
            case "note":purpose = .note
            case "idea":purpose = .idea
            case "question":purpose = .question
            case "review":purpose = .review
            default:return nil
            }
            var key=""
            if !currentJointCalls.isEmpty {
                let value=try row.value(String.self,forProperty:"currentReconciliation")
                guard value == "none" || currentJointCalls.contains(where:{ $0.key == value }) else { return nil }
                if value != "none" { key=value }
            }
            result.append(.init(evidence:ids,purpose:purpose,
                requiresRewrite:try row.value(Bool.self,forProperty:"requiresRewrite"),
                needsReview:try row.value(Bool.self,forProperty:"needsReview"),currentReconciliation:key))
        }
        guard approvedCurrentJointCallRows(result,candidates:currentJointCalls) != nil else { return nil }
        return result
    }
    @Generable struct OutlineItem {
