    struct CurrentRevisionProof {
        let meaning: String
        let directContact: String
    }
    /// Whole current rows with an independent complete correction proof need
    /// a decision, not a regenerated copy of names, allocations or clocks.
    /// This is source reconciliation, never evidence of analogy consumption.
    static func currentRevisionProofs(_ items: [IndexedItem],requestedRows:Set<Int>,sharedRows:Set<Int>,
                                      units:RuntimeIndexedSource) -> [Int:CurrentRevisionProof] {
        var proofs: [Int:CurrentRevisionProof] = [:]
        for row in requestedRows.sorted() {
            guard items.indices.contains(row),!sharedRows.contains(row),!items[row].needsReview,
                  items[row].anchor.isEmpty,!items[row].evidence.isEmpty,
                  items[row].evidence.allSatisfy({ units.units.indices.contains($0) }) else { continue }
            let item = items[row]
            let evidence = item.evidence.map { units.units[$0].text }.joined(separator:" ")
            let body = item.evidence.count == 1 ? RuntimeFoundationActionShape.body(evidence) : evidence
            guard body.range(of:#"(?i)\b(?:actually|instead|correction|no\s+make)\b"#,options:.regularExpression) != nil else { continue }
            if item.purpose == .task,let proof = RuntimeWholePlanReplacement.read(body) {
                proofs[row] = .init(meaning:proof.action,directContact:proof.recipient)
            } else if item.purpose == .task,let proof = RuntimeJointCallReading.read(body) {
                proofs[row] = .init(meaning:proof.action,directContact:"")
            } else if item.purpose == .task,let proof = RuntimeCommunicationReading.read(body) {
                proofs[row] = .init(meaning:proof.action,directContact:proof.recipient)
            } else if item.purpose == .shopping,let entries = RuntimeAllocationReading.expected(body) {
                // Canonical quantities retain each distinct current owner and
                // product. Restore the exact source casing of literal slots.
                func literal(_ slot:String) -> String {
                    body.range(of:slot,options:.caseInsensitive).map { String(body[$0]) } ?? slot
                }
                let meaning = "Buy " + entries.map { "\($0.quantity) \(literal($0.unit)) of \(literal($0.object)) for \(literal($0.owner))" }.joined(separator:" and ")
                guard RuntimeAllocationReading.entries(meaning) == entries else { continue }
                proofs[row] = .init(meaning:meaning,directContact:"")
            }
        }
        return proofs
    }
    struct CurrentJointCallCandidate:Equatable {
        let key:String
        let evidence:[Int]
        let meaning:String
        let topic:String
    }
    /// These are CURRENT proposals for the model, not semantic certificates.
    /// Only an exact original-owned three-unit joint-call structure is offered.
    /// Unknown lexical tags confer no approval. Known current acts/conditions
    /// decline even if a model were to approve the proposed reconciliation.
    static func currentJointCallCandidates(_ units:RuntimeIndexedSource)->[CurrentJointCallCandidate] {
        guard units.units.count >= 3 else { return [] }
        var candidates:[CurrentJointCallCandidate]=[],ranges:[NSRange]=[]
        for first in 0...(units.units.count-3) {
            let ids=Array(first...(first+2))
            guard ids.allSatisfy({ currentOwnedUnitSpan(units.units[$0],source:units.source) != nil }) else { continue }
            let range=units.units[first].range.lowerBound..<units.units[first+2].range.upperBound
            guard let reading=RuntimeJointCallReading.read(String(units.source[range])),
                  !RuntimeAccountOwnership.hasCurrentActForReference(reading.topic),
                  reading.topic.range(of:#"(?i)\b(?:i|we|you|he|she|they|it|them|him|her|is|are|am|was|were|has|have|had|do|does|did|will|shall|must|would|should|can|could|may|might|need|needs|want|wants|provided|providing|assuming|whether|whenever|wherever|which|who|whose|that|when|once|while|because|since|pending|dependent|subject|to)\b"#,options:.regularExpression) == nil else { continue }
            candidates.append(.init(key:"j\(first)",evidence:ids,meaning:reading.action,topic:reading.topic))
            ranges.append(NSRange(range,in:units.source))
        }
        guard !candidates.isEmpty,currentPurposeProofsCanBind(units.source,closedJointCallRanges:ranges) else { return [] }
        return candidates
    }
    /// The legacy expressive contract still receives existing complete owned
    /// retained-knowledge constraints. This repeats no proof or canonical row:
    /// exact original flags are checked, coherent Memory grouping stays open,
    /// and the full current-source validator remains independently required.
    static func currentRetainedKnowledgeData(_ atoms:[CurrentOwnershipAtom],units:RuntimeIndexedSource)->String? {
        let retained=atoms.filter(\.retainedKnowledge)
        guard retained.allSatisfy({ atom in
            units.units.indices.contains(atom.unit) && atom.anchor.isEmpty
                && atoms.filter({ $0.unit == atom.unit }).count == 1
                && currentOwnedUnitSpan(units.units[atom.unit],source:units.source) != nil
                && independentRetainedKnowledge(units.units[atom.unit].text)
        }) else { return nil }
        let ids=retained.map(\.unit).sorted()
        guard !ids.isEmpty else { return "" }
        return "\nCURRENT SOURCE-PROVED RETAINED KNOWLEDGE UNIT IDS: " + ids.map { "u\($0)" }.joined(separator:",")
            + ". These complete own current units retain knowledge, uncertainty and annotations independently of actionable rows. Keep explicitly separate Memory intentions independently accessible; group details of the same coherent intention only when the complete current source supports it. Reconcile every later correction and ownership change across the whole capture."
    }
    static func currentJointCallProposalData(_ candidates:[CurrentJointCallCandidate])->String {
        guard !candidates.isEmpty else { return "" }
        return "\nSOURCE-PROPOSED CURRENT JOINT-CALL RECONCILIATIONS DATA (NOT APP-PROVED):\n"
            + candidates.map { "\($0.key) units=\($0.evidence.map { "u\($0)" }.joined(separator:",")): \($0.meaning)" }.joined(separator:"\n")
    }
    /// Approval belongs to one exact whole current row, never the nearest row
    /// or all corrections. The complete plan still requires shared/ownership,
    /// semantic, temporal and actual saved-state validation before any effect.
    static func approvedCurrentJointCallRows(_ rows:[FirstOutlineRow],candidates:[CurrentJointCallCandidate])->[Int:CurrentJointCallCandidate]? {
        guard Set(candidates.map(\.key)).count == candidates.count else { return nil }
        let lookup=Dictionary(uniqueKeysWithValues:candidates.map { ($0.key,$0) })
        var used=Set<String>(),approved:[Int:CurrentJointCallCandidate]=[:]
        for (index,row) in rows.enumerated() where !row.currentReconciliation.isEmpty {
            guard let candidate=lookup[row.currentReconciliation],used.insert(candidate.key).inserted,
                  row.evidence == candidate.evidence,row.purpose == .task,!row.needsReview,row.literalAnchor.isEmpty else { return nil }
            approved[index]=candidate
        }
        return approved
    }
    /// Close only the existing complete joint-call grammar after a model has
    /// assigned the whole capture. This is not a generic revision-proof bypass:
    /// all requested rows, original ownership and unchanged rows must reconcile
    /// together through the ordinary validator with actual saved context.
    static func currentClosedJointCallPlan(_ items:[IndexedItem],requestedRows:Set<Int>,sharedRows:Set<Int>,
        units:RuntimeIndexedSource,source:String,referenceDate:Date,calendar:Calendar,
        rules:ThoughtExtractionResult,context:RuntimeCaptureContext,
        modelApprovedCandidates:[Int:CurrentJointCallCandidate]? = nil) -> ThoughtExtractionResult? {
        func declined(_ reason:String)->ThoughtExtractionResult? {
#if DEBUG
            developmentObserver?("source reconciliation phase=revision modelCall=none certificate=closed-joint-call validation=declined reason=\(reason)")
#endif
            return nil
        }
        guard !Task.isCancelled,source == units.source,!requestedRows.isEmpty,sharedRows.isEmpty,
              requestedRows.isSubset(of:Set(items.indices)),rules.operations.isEmpty,
              validOwnership(items,units:units) else { return declined("incomplete-current-ownership") }
        var revisions:[IndexedRevision]=[]
        var closedRanges:[NSRange]=[]
        for row in requestedRows.sorted() {
            let item=items[row]
            guard item.purpose == .task,!item.needsReview,item.anchor.isEmpty,
                  let first=item.evidence.first,let last=item.evidence.last,
                  item.evidence == Array(first...last),
                  item.evidence.allSatisfy({ currentOwnedUnitSpan(units.units[$0],source:source) != nil }) else { return declined("not-whole-original-owned-task") }
            let range=units.units[first].range.lowerBound..<units.units[last].range.upperBound
            guard let reading=RuntimeJointCallReading.read(String(source[range])) else { return declined("not-closed-joint-call") }
            if let approved=modelApprovedCandidates {
                let candidate=CurrentJointCallCandidate(key:"j\(first)",evidence:item.evidence,meaning:reading.action,topic:reading.topic)
                guard approved[row] == candidate,currentJointCallCandidates(units).contains(candidate) else { return declined("no-exact-outline-reconciliation-approval") }
            } else {
                guard RuntimeCurrentNominalProof.read(reading.topic) else { return declined("unproved-complete-topic-nominal") }
            }
            revisions.append(.init(row:row,anchor:"",currentMeaning:reading.action,directContact:""))
            closedRanges.append(NSRange(range,in:source))
        }
        guard currentPurposeProofsCanBind(source,closedJointCallRanges:closedRanges) else { return declined("whole-capture-current-change") }
        guard let complete=completingStagedPlan(items,revisions:revisions,requestedRows:requestedRows,sharedRows:[],units:units) else { return declined("incomplete-reconciliation") }
        guard let valid=validateIndexed(.init(items:complete),source:source,units:units,
            referenceDate:referenceDate,calendar:calendar,rules:rules,context:context) else { return declined("complete-validation-rejected") }
        guard valid.operations.isEmpty,valid.items.allSatisfy({ !$0.needsReview }),!Task.isCancelled else { return declined("held-or-cancelled") }
        return valid
    }
    /// Required keys are created by the app from the CURRENT plan. The model
    /// cannot choose a foreign row number, repeat a row, or supply a free
    /// nonshared anchor. Shared rows retain exact literal-anchor validation.
    static func dynamicRevisionSchema(requestedRows:Set<Int>,sharedRows:Set<Int>,proofRows:Set<Int>) throws -> GenerationSchema? {
        guard !requestedRows.isEmpty,requestedRows.allSatisfy({ $0 >= 0 }),sharedRows.isSubset(of:requestedRows),
              proofRows.isSubset(of:requestedRows),proofRows.isDisjoint(with:sharedRows) else { return nil }
        let meaning = DynamicGenerationSchema.Property(name:"currentMeaning",description:"Complete effective CURRENT meaning after corrections; preserve all unchanged roles, objects, quantities, conditions and timing.",schema:.init(type:String.self))
        let contact = DynamicGenerationSchema.Property(name:"directContact",description:"Complete literal CURRENT direct contact of the USER, or empty. Owners and nested recipients are distinct.",schema:.init(type:String.self))
        let whole = DynamicGenerationSchema(name:"CurrentWholeRevision",properties:[meaning,contact])
        let shared = DynamicGenerationSchema(name:"CurrentSharedRevision",properties:[
            .init(name:"anchor",description:"Complete exact CURRENT substring for this independent intention; disjoint from other shared anchors. No unit labels or paraphrases.",schema:.init(type:String.self)),meaning,contact])
        let decision = DynamicGenerationSchema(name:"CurrentReconciliationDecision",anyOf:["useCurrentReconciliation","unresolved"])
        let proved = DynamicGenerationSchema(name:"CurrentProvedRevision",properties:[
            .init(name:"decision",description:"Use the entire CURRENT source reconciliation only if it is the correct complete meaning of this current row; otherwise unresolved.",schema:.init(referenceTo:"CurrentReconciliationDecision"))])
        let root = DynamicGenerationSchema(name:"CurrentCompleteRevisions",properties:requestedRows.sorted().map { row in
            .init(name:"r\(row)",description:"Complete requested CURRENT outline row \(row).",schema:.init(referenceTo:proofRows.contains(row) ? "CurrentProvedRevision" : sharedRows.contains(row) ? "CurrentSharedRevision" : "CurrentWholeRevision"))
        })
        var dependencies: [DynamicGenerationSchema] = []
        if !requestedRows.subtracting(sharedRows).subtracting(proofRows).isEmpty { dependencies.append(whole) }
        if !sharedRows.isEmpty { dependencies.append(shared) }
        if !proofRows.isEmpty { dependencies.append(contentsOf:[decision,proved]) }
        return try GenerationSchema(root:root,dependencies:dependencies)
    }
    static func decodeDynamicRevisions(_ content:GeneratedContent,requestedRows:Set<Int>,sharedRows:Set<Int>,
                                       proofs:[Int:CurrentRevisionProof]) throws -> [IndexedRevision]? {
        guard !requestedRows.isEmpty,requestedRows.allSatisfy({ $0 >= 0 }),sharedRows.isSubset(of:requestedRows),
              Set(proofs.keys).isSubset(of:requestedRows),Set(proofs.keys).isDisjoint(with:sharedRows),
              let raw = content.jsonString.data(using:.utf8),
              let object = try JSONSerialization.jsonObject(with:raw) as? [String:Any],
              Set(object.keys) == Set(requestedRows.map { "r\($0)" }) else { return nil }
        var result: [IndexedRevision] = []
        for row in requestedRows.sorted() {
            guard let fields = object["r\(row)"] as? [String:Any] else { return nil }
            if let proof = proofs[row] {
                guard Set(fields.keys) == ["decision"],fields["decision"] as? String == "useCurrentReconciliation" else { return nil }
                result.append(.init(row:row,anchor:"",currentMeaning:proof.meaning,directContact:proof.directContact))
            } else {
                let shared = sharedRows.contains(row)
                guard Set(fields.keys) == (shared ? ["anchor","currentMeaning","directContact"] : ["currentMeaning","directContact"]),
                      let meaning = fields["currentMeaning"] as? String,let contact = fields["directContact"] as? String else { return nil }
                let anchor: String
                if shared { guard let literal = fields["anchor"] as? String else { return nil };anchor = literal }
                else { anchor = "" }
                result.append(.init(row:row,anchor:anchor,currentMeaning:meaning,directContact:contact))
            }
        }
        return result
    }

