                completion = "generation-completed"
#if DEBUG
                developmentObserver?("call output phase=revision rawJSONTokens=\(try await model.tokenCount(for:revision.rawContent.jsonString)) outputLimit=\(revisionReserve) consumed=\(revisionReferences.map(\.id).joined(separator:","))")
#endif
                guard !Task.isCancelled else {
#if DEBUG
                    developmentObserver?("call end phase=revision completion=generation-completed cancellation=observed reason=cancelled-after-response")
#endif
                    return recoverableReview(source)
                }
#if DEBUG
                developmentObserver?("revision response tokens=\(try await model.tokenCount(for: revision.transcriptEntries)) json=\(revision.rawContent.jsonString)")
#endif
                guard let revisions = try decodeDynamicRevisions(revision.content,requestedRows:requestedRows,sharedRows:requiredSharedRows,proofs:proofs),
                      let completed = completingStagedPlan(items,revisions:revisions,
                    requestedRows:requestedRows,sharedRows:requiredSharedRows,units:units) else {
#if DEBUG
                    developmentObserver?("call end phase=revision completion=generation-completed cancellation=none reason=invalid-complete-revision validation=rejected")
#endif
                    return recoverableReview(source)
                }
#if DEBUG
                developmentObserver?("call end phase=revision completion=generation-completed cancellation=none validation=provisional")
#endif
                items = completed
            }
            let validated = validateIndexed(.init(items: items), source: source, units: units,
                referenceDate: referenceDate, calendar: calendar, rules: rules, context: context)
#if DEBUG
            developmentObserver?("capture validation phase=indexed-validation state=\(validated == nil ? "rejected" : "accepted")")
#endif
            return validated ?? recoverableReview(source)
        } catch {
#if DEBUG
            developmentObserver?("staged failure \(String(describing: type(of: error)))")
            developmentObserver?("call end phase=\(activePhase) completion=\(completion) cancellation=\(Task.isCancelled ? "observed" : "none") reason=\(observedFailureReason(error)) errorType=\(String(describing:type(of:error))) \(observedErrorIdentity(error))")
#endif
            return attempted ? recoverableReview(source) : nil
        }
    }

    static func stagedRewriteRows(_ rows:[FirstOutlineRow],items:[IndexedItem],sharedRows:Set<Int>,
        units:RuntimeIndexedSource,referenceDate:Date,calendar:Calendar)->[Int] {
        let provedLiteralRows = currentLiteralSharedRows(items,sharedRows:sharedRows,units:units,
                referenceDate:referenceDate,calendar:calendar)
        let completeDeniedRows=Set(provedDeniedRows(items,units:units,referenceDate:referenceDate,calendar:calendar)?.keys.map { $0 } ?? [])
        return rows.indices.filter { index in
                let quote = rows[index].evidence.map { units.units[$0].text }.joined(separator: " ")
                let action = rows[index].purpose == .task || rows[index].purpose == .shopping || rows[index].purpose == .packing
                return (sharedRows.contains(index) && !provedLiteralRows.contains(index)) || rows[index].requiresRewrite || (action && !completeDeniedRows.contains(index) && quote.range(of: #"(?i)\b(?:actually|instead|correction|never\s+mind|cancel|withdraw|make\s+that|no\s+(?:wait|make)|leave\s+that\s+off|take\s+that\s+back|replace\s+that\s+whole\s+plan)\b"#,
                                                                             options: .regularExpression) != nil)
            }
    }

    /// This is a provisional assignment of complete current units. Shared
    /// evidence is deferred to complete literal ownership proof, never accepted.
    static func stagedOutlinePlan(_ rows: [FirstOutlineRow],units: RuntimeIndexedSource)
        -> (items:[IndexedItem],sharedRows:Set<Int>)? {
        guard !rows.isEmpty,Set(rows.flatMap(\.evidence)) == Set(units.units.indices),
              rows.allSatisfy({ !$0.evidence.isEmpty && $0.evidence == Array(Set($0.evidence)).sorted()
                && $0.evidence.allSatisfy({ units.units.indices.contains($0) }) }) else { return nil }
        var shared = Set<Int>()
        for i in rows.indices {
            for j in rows.indices where j > i && !Set(rows[i].evidence).isDisjoint(with:rows[j].evidence) {
                shared.insert(i);shared.insert(j)
            }
        }
        let items = rows.map { row in
            let evidence = row.evidence.map { units.units[$0].text }.joined(separator:" ")
            return IndexedItem(evidence:row.evidence,anchor:row.literalAnchor,purpose:row.purpose,currentMeaning:row.literalAnchor,
                directContact:anchoredCommunication(anchor:row.literalAnchor,evidence:evidence)?.recipient ?? "",needsReview:row.needsReview)
        }
        return (items,shared)
    }
    /// Every requested row is completed once; all final ownership, meaning,
    /// date and current saved-state guards remain independently required.
    static func completingStagedPlan(_ original: [IndexedItem],revisions: [IndexedRevision],
        requestedRows:Set<Int>,sharedRows:Set<Int>,units:RuntimeIndexedSource) -> [IndexedItem]? {
        guard requestedRows.isSubset(of:Set(original.indices)),sharedRows.isSubset(of:requestedRows),
              revisions.count == requestedRows.count,Set(revisions.map(\.row)) == requestedRows else { return nil }
        var items = original
        for revised in revisions {
            guard !revised.currentMeaning.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty,
                  sharedRows.contains(revised.row) ? !revised.anchor.isEmpty : revised.anchor.isEmpty else { return nil }
            items[revised.row].anchor = revised.anchor
            items[revised.row].currentMeaning = revised.currentMeaning
            items[revised.row].directContact = revised.directContact
        }
        return validOwnership(items,units:units) ? items : nil
    }

    static func completeAnchor(_ literal: String, in source: String) -> Bool {
        guard let range = source.range(of: literal) else { return false }
        let before = String(source[..<range.lowerBound])
        let after = String(source[range.upperBound...])
        if before.last?.isLetter == true || before.last?.isNumber == true
            || after.first?.isLetter == true || after.first?.isNumber == true { return false }
        let family = "(?:partner|spouse|mother|father|mom|dad|brother|sister|son|daughter|grandmother|grandfather|wife|husband|aunt|uncle|cousin|niece|nephew)"
        if after.range(of: "^[’']s\\s+" + family + "\\b", options: [.regularExpression, .caseInsensitive]) != nil { return false }
        if before.range(of: "\\p{L}[’']s\\s*$", options: .regularExpression) != nil { return false }
        return true
    }

    static func projectedDemonstration(_ row: RuntimeWorkedExample) -> String {
        projectedDemonstration(row,outlineContract:nil)
    }

    enum ReferenceOutlineContract:Equatable { case keyed, ordered, separated, fixed, expressive, compactExpressive, compactGuided, compactComplete, compactMembership, compactDeclarations, compactUnitDeclarations, objectUnitDeclarations }

    /// Only exact independently reviewed adaptations may teach a first-response
    /// contract. The complete original example remains authoritative DATA.
    /// These digests pin the existing input, context, lifecycle and solution,
    /// not the example's mutable approval bookkeeping or a current answer.
    static let reviewedOutlineProjectionDigests = [
        "SIR1-503251":"ce8e8de469a3d360227d80af6bc3277124ec5fb965b5e1e816b7e23be693f251",
        "SIR1-456352":"2a8383266fab491ae0f7a711e083e568a7e011b3137241356e3766cf353a879a"
    ]

    static func projectedDemonstration(_ row:RuntimeWorkedExample,outlineContract:ReferenceOutlineContract?) -> String {
        guard let data = row.payload.data(using: .utf8),
              let record = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let input = record["input"], let solution = record["solution"] else { return "" }
        var demonstration: [String: Any] = ["reference_id": row.id, "input": input, "solution": solution]
        if let lifecycle = record["lifecycle_context"] { demonstration["lifecycle_context"] = lifecycle }
        guard let projected = try? JSONSerialization.data(withJSONObject: demonstration,
                                                          options: [.sortedKeys]) else { return "" }
        // Entire input/context and worked answer remain; hashes, review logs
        // and eligibility bookkeeping are outside inference. Exact source ID
        // ties this projection back to the reviewed record or explicit prototype.
        let original=String(decoding:projected,as:UTF8.self)
        guard let outlineContract,
              reviewedOutlineProjectionDigests[row.id] == SHA256.hash(data:projected).map({String(format:"%02x",$0)}).joined(),
              let example=try? referenceOutlineDemonstration(record,contract:outlineContract,referenceID:row.id) else { return original }
        demonstration["outline_demonstration"]=example
        guard let adapted=try? JSONSerialization.data(withJSONObject:demonstration,options:[.sortedKeys]) else { return original }
        return String(decoding:adapted,as:UTF8.self)
    }

    /// A format adapter, never a new semantic answer. Refuse shared/partial
    /// evidence, operations and corrections instead of inventing ownership.
    /// Evidence offsets are Python Unicode scalar offsets, not UTF16 offsets.
    static func referenceOutlineDemonstration(_ record:[String:Any],contract:ReferenceOutlineContract,referenceID:String? = nil) throws -> [String:Any]? {
        guard let input=record["input"] as? [String:Any],let source=input["utterance"] as? String,
              let context=input["context"] as? [String:Any],let saved=context["saved_items"] as? [Any],saved.isEmpty,
              let solution=record["solution"] as? [String:Any],
              ["mutations","operation_receipts","clarifications"].allSatisfy({ (solution[$0] as? [Any])?.isEmpty == true }),
              let groups=solution["groups"] as? [[String:Any]],let items=solution["new_items"] as? [[String:Any]],
              source.range(of:#"(?i)\b(?:actually|instead|correction|never\s+mind|make\s+that|replace|withdraw|cancel)\b"#,options:.regularExpression) == nil else { return nil }
        let units=RuntimeIndexedSource(source),scalars=Array(source.unicodeScalars)
        guard !units.units.isEmpty else { return nil }
        var owners:[Int:Int]=[:],reviewed:[FirstOutlineRow]=[]
        for object in groups+items {
            let kind=(object["purpose"] as? String) ?? (object["kind"] as? String) ?? ""
            let purpose:Purpose
            switch kind { case "task":purpose = .task;case "shopping":purpose = .shopping;case "packing":purpose = .packing
            case "inventory":purpose = .inventory;case "note":purpose = .note;case "idea":purpose = .idea
            case "question":purpose = .question;default:return nil }
            let destination=[Purpose.task,.shopping,.packing].contains(purpose) ? "Today" : "Memory"
            guard object["destination"] as? String == destination,
                  let evidence=object["evidence"] as? [[String:Any]],!evidence.isEmpty else { return nil }
            var covered=Set<Int>()
            for span in evidence {
                guard let a=span["start"] as? NSNumber,let b=span["end"] as? NSNumber,
                      CFGetTypeID(a) != CFBooleanGetTypeID(),CFGetTypeID(b) != CFBooleanGetTypeID(),
                      a.doubleValue.isFinite,b.doubleValue.isFinite,
                      a.doubleValue.rounded(.towardZero) == a.doubleValue,b.doubleValue.rounded(.towardZero) == b.doubleValue,
                      a.doubleValue >= 0,b.doubleValue <= Double(scalars.count),a.doubleValue < b.doubleValue,
                      let text=span["text"] as? String,
                      String(String.UnicodeScalarView(scalars[a.intValue..<b.intValue])) == text else { return nil }
                covered.formUnion(a.intValue..<b.intValue)
            }
            var ids:[Int]=[]
            for (id,unit) in units.units.enumerated() {
                let start=source[..<unit.range.lowerBound].unicodeScalars.count
                let end=source[..<unit.range.upperBound].unicodeScalars.count
                let meaningful=(start..<end).filter { !CharacterSet.whitespacesAndNewlines.contains(scalars[$0]) }
                let intersection=meaningful.filter { covered.contains($0) }
                if !intersection.isEmpty {
                    guard intersection.count == meaningful.count,owners[id] == nil else { return nil }
                    ids.append(id)
                }
            }
            guard let root=ids.first else { return nil }
            for id in ids { owners[id]=root }
            reviewed.append(.init(evidence:ids,purpose:purpose,requiresRewrite:false,needsReview:false,literalAnchor:""))
        }
        guard Set(owners.keys) == Set(units.units.indices) else { return nil }
        reviewed.sort { $0.evidence[0] < $1.evidence[0] }
        let atoms=fixedOutlineAtoms(units)
        guard atoms.count == units.units.count,atoms.enumerated().allSatisfy({ $0.element.unit == $0.offset && $0.element.key == "u\($0.offset)" && $0.element.anchor.isEmpty }) else { return nil }
        var decisions:[String:String]=[:]
        let codes:[(Purpose,String)]=[(.task,"T"),(.shopping,"S"),(.packing,"P"),(.inventory,"I"),(.note,"N"),(.idea,"D"),(.question,"Q")]
        func code(_ purpose:Purpose)->String? { codes.first { $0.0 == purpose }?.1 }
        for row in reviewed {
            guard let root=row.evidence.first,let code=code(row.purpose) else { return nil }
            for id in row.evidence { decisions["u\(id)"]=id == root ? code : "=u\(root)" }
        }
        let bytes=try JSONSerialization.data(withJSONObject:decisions,options:[.sortedKeys])
        let decoded=try decodeFixedOutline(GeneratedContent(json:String(decoding:bytes,as:UTF8.self)),atoms:atoms)
        guard let decoded,decoded.count == reviewed.count,zip(decoded,reviewed).allSatisfy({ pair in
            pair.0.evidence == pair.1.evidence && pair.0.purpose == pair.1.purpose && !pair.0.requiresRewrite && !pair.0.needsReview && pair.0.literalAnchor.isEmpty
        }) else { return nil }
        // Validate reference-local ownership above before rendering it. CURRENT
        // decoders never strip this namespace or accept these foreign pointers.
        // Only derived structural IDs change; original words are never replaced.
        let namespace:String
        if let referenceID {
            guard referenceID.range(of:#"^SIR1-[0-9]{6}$"#,options:.regularExpression) != nil,
                  atoms.allSatisfy({ $0.sourcePurposeCode.isEmpty && $0.sourceContextOwnerKey.isEmpty
                    && compactAllowedDecisions($0,atoms:atoms).count > 1 }) else { return nil }
            namespace="ref"+referenceID.dropFirst(5)+"/"
        } else { namespace="" }
        func key(_ id:Int)->String { namespace+"u\(id)" }
        func decision(_ value:String)->String {
            guard value.hasPrefix("=") || value.hasPrefix("!") else { return value }
            return String(value.prefix(1))+namespace+value.dropFirst()
        }
        let response:[String:Any]
        switch contract {
        case .keyed:
            response=Dictionary(uniqueKeysWithValues:freeSeparatedPositions(atoms).map { index in
                (key(index),keyedNaturalDecision(decision(decisions[atoms[index].key]!))! as Any)
            })
        case .ordered:
            response=["decisions":freeSeparatedPositions(atoms).map { keyedNaturalDecision(decision(decisions[atoms[$0].key]!))! }]
        case .fixed:response=Dictionary(uniqueKeysWithValues:atoms.indices.map { (key($0),decision(decisions[atoms[$0].key]!)) })
        case .separated:
            response=["purposes":atoms.map { atom in
                let code=decisions[atom.key]!
                return code.hasPrefix("=") ? "context" : keyedNaturalDecision(code)!
            },"owners":atoms.indices.map { owners[$0]! }]
        case .objectUnitDeclarations:
            response=["byUnit":units.units.indices.map { unit in reviewed.indices.filter { reviewed[$0].evidence.contains(unit) }.map { row in
                ["g":String(row),"p":code(reviewed[row].purpose)!]
            } },"edits":[]]
        case .compactUnitDeclarations:
            response=["byUnit":units.units.indices.map { unit in reviewed.indices.filter { reviewed[$0].evidence.contains(unit) }.map { row in
                "\(row):"+code(reviewed[row].purpose)!
            } },"edits":[]]
        case .compactDeclarations:
            response=["byUnit":units.units.indices.map { unit in reviewed.indices.filter { reviewed[$0].evidence.contains(unit) }.map { row in
                ["g":row,"p":keyedNaturalDecision(code(reviewed[row].purpose)!)!] as [String:Any]
            } },"edits":[]]
        case .compactMembership:
            response=["rows":reviewed.map { row in ["p":keyedNaturalDecision(code(row.purpose)!)!,"r":false,"v":false,"x":[]] as [String:Any] },
                "byUnit":units.units.indices.map { unit in reviewed.indices.filter { reviewed[$0].evidence.contains(unit) } }]
        case .compactComplete:
            response=["rows":reviewed.map { row in ["p":keyedNaturalDecision(code(row.purpose)!)!,"e":row.evidence.map { key($0) },"r":false,"v":false,"x":[]] as [String:Any] }]
        case .compactGuided:
            response=["rows":reviewed.map { row in ["p":keyedNaturalDecision(code(row.purpose)!)!,"e":row.evidence.map { key($0) },"r":false,"v":false] as [String:Any] }]
        case .compactExpressive:
            response=["rows":reviewed.map { row in
                keyedNaturalDecision(code(row.purpose)!)!+"|0|0|"+row.evidence.map { key($0) }.joined(separator:",")
            }]
        case .expressive:
            response=["items":reviewed.map { row in ["evidence":row.evidence.map { key($0) },"purpose":keyedNaturalDecision(code(row.purpose)!)!,"requiresRewrite":false,"needsReview":false] as [String:Any] }]
        }
        let ownership:String
        if namespace.isEmpty {
            ownership=contract == .keyed || contract == .ordered ? keyedOwnershipPrompt(atoms) : ownershipPrompt(atoms,separated:contract == .separated,unresolvedOnly:false)
        } else {
            ownership=atoms.indices.map { id in
                // Every admitted atom above is exactly one whole original
                // unit with key==unit. Repeating its foreign ID adds no fact.
                (contract == .separated ? "slot \(id) key " : "")+key(id)+": whole"
                    + (contract == .keyed || contract == .ordered ? " UNRESOLVED" : "")
            }.joined(separator:"\n")
        }
        var packet:[String:Any]=["scope":"OTHER capture only; its keys and facts never identify CURRENT source",
                "indexed_source":units.units.enumerated().map { "\(key($0.offset)): \($0.element.text)" }.joined(separator:"\n"),
                "ownership_atoms":ownership,
                "first_response":response]
        if contract == .ordered { packet["decision_order"]=freeSeparatedPositions(atoms).map { key($0) } }
        // Positional contracts retain their declared numeric type. This table
        // binds those positions to this reference's keys, never CURRENT units.
        // Canonical purpose-only outputs carry no foreign IDs and still need
        // unchanged complete CURRENT semantic validation if a model echoes them.
        if (contract == .separated || contract == .compactMembership || contract == .compactDeclarations || contract == .compactUnitDeclarations || contract == .objectUnitDeclarations) && referenceID != nil { packet["reference_slot_order"]=atoms.indices.map { key($0) } }
        // The complete outer demonstration already carries reference_id.
        return packet
    }

    /// Coverage is checked over the exact original indexed source. Evidence
    /// dependencies can overlap; independently usable intention anchors cannot.
    static func validOwnership(_ items: [IndexedItem], units: RuntimeIndexedSource) -> Bool {
        guard !items.isEmpty, Set(items.flatMap(\.evidence)) == Set(units.units.indices) else { return false }
        var anchors: [Range<String.Index>?] = []
        for item in items {
            guard !item.evidence.isEmpty, item.evidence == Array(Set(item.evidence)).sorted(),
                  item.evidence.allSatisfy({ units.units.indices.contains($0) }) else { return false }
            if item.anchor.isEmpty { anchors.append(nil) }
            else {
                let matches = units.units.enumerated().compactMap { index, unit -> Range<String.Index>? in
                    guard item.evidence.contains(index) else { return nil }
                    return units.source.range(of: item.anchor, range: unit.range)
                }
                guard matches.count == 1, completeAnchor(item.anchor, in: units.source) else { return false }
                anchors.append(matches[0])
            }
        }
        for i in items.indices {
            for j in items.indices where j > i && !Set(items[i].evidence).isDisjoint(with: items[j].evidence) {
                guard let a = anchors[i], let b = anchors[j], !a.overlaps(b) else { return false }
                // Identical normalized intentions are duplicates, even when
                // they point at different words in one broad context sentence.
                let left = items[i].currentMeaning.trimmingCharacters(in: .whitespacesAndNewlines)
                let right = items[j].currentMeaning.trimmingCharacters(in: .whitespacesAndNewlines)
                if !left.isEmpty && left.caseInsensitiveCompare(right) == .orderedSame { return false }
            }
        }
        return true
    }

    static func anchoredCommunication(anchor: String, evidence: String) -> RuntimeCommunicationReading.Reading? {
        guard !anchor.isEmpty else {
            if let frames = RuntimeRecipientReplacement.currentFrames(evidence),frames.count == 1,
               frames[0].kind.isActionable,let recipient = frames[0].person {
                return .init(action:frames[0].action,recipient:recipient)
            }
            return RuntimeCommunicationReading.read(evidence)
        }
        guard ActionabilityReader.read(evidence).belongsOnToday,
              let range = evidence.range(of: anchor), !QuotedSpeechScope.protects(range,in: evidence) else { return nil }
        if evidence.range(of: #"(?i)\b(?:actually|instead|correction|not\s+\p{L}|no\s+wait)\b"#,options: .regularExpression) != nil {
            return RuntimeCommunicationReading.read(evidence)
        }
        if let explicit = RuntimeCommunicationReading.read(anchor) { return explicit }
        // A coordinated recipient clause can inherit one explicitly adopted
        // contact verb. Its recipient and object stay in the exact anchor.
        let pattern = #"(?i)^\s*(?:i\s+(?:need|have|want)\s+to\s+|i\s+(?:will|must|should)\s+)?(ask|tell|call|phone|email|text|message)\b"#
        guard ActionabilityReader.read(evidence).belongsOnToday,
              let regex = NSRegularExpression.speakItCached(pattern),
              let match = regex.firstMatch(in: evidence, range: NSRange(evidence.startIndex..., in: evidence)),
              let verb = Range(match.range(at: 1), in: evidence),
              anchor.range(of: #"(?i)^(?:my|our|your|their|his|her)\s+"#, options: .regularExpression) != nil else { return nil }
        return RuntimeCommunicationReading.read(String(evidence[verb]) + " " + anchor)
    }

    /// An evidence-ID union is structural coverage, not intention coverage.
    /// For each shared unit, the literal anchors and closed coordination must
    /// partition its entire proposition. Only an exact common clock or a typed
    /// recipient distinction may be shared without an intention of its own.
    struct CurrentPurchasePartition {
        /// Every member has a complete CURRENT quantity/package/physical
        /// nominal. Neither a model anchor nor reference supplies a member.
        let anchors:[String]
        let actions:[String]
    }
    static func currentPurchasePartition(_ unit:String,minimumMembers:Int = 2)->CurrentPurchasePartition? {
        guard QuotedSpeechScope.ranges(in:unit).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(unit) else { return nil }
        let body=RuntimeFoundationActionShape.body(unit).trimmingCharacters(in:.whitespacesAndNewlines)
        guard body.range(of:#"(?i)^buy\s+"#,options:.regularExpression) != nil,
              let entries=RuntimeQuantityAnalogy.initialEntries(body),[1,2].contains(minimumMembers),(minimumMembers...30).contains(entries.count),
              entries.allSatisfy({ !$0.unit.isEmpty && $0.recipient.isEmpty
                  && (RuntimeCurrentNominalProof.read($0.object)
                      || (minimumMembers == 1 && RuntimeShortSourceCertificate.purpose("Buy " + $0.object) == .shopping)) }),
              let wholeGraph=RuntimeQuantityAnalogy.graph(body),wholeGraph.corrections.isEmpty,
              wholeGraph.entries.count == entries.count else { return nil }
        // The whole quantity graph checks temporal/location/condition scope.
        // A lexical noun tag for a weekday cannot donate clock authority to
        // this untimed purchase partition.
        let expectedAnchors=entries.enumerated().map { index,entry in index == 0 ? "buy " + entry.literal : entry.literal }
        var anchors:[String]=[]
        var previous=body.startIndex
        for (index,anchor) in expectedAnchors.enumerated() {
            // Exact current spelling is required. A repeated anchor or an
            // unowned predicate anywhere between members declines the proof.
            guard let range=body.range(of:anchor,options:.caseInsensitive,range:previous..<body.endIndex),
                  body.range(of:anchor,options:.caseInsensitive,range:range.upperBound..<body.endIndex) == nil else { return nil }
            let gap=String(body[previous..<range.lowerBound]).trimmingCharacters(in:.whitespacesAndNewlines)
            if index == 0 { guard gap.isEmpty else { return nil } }
            else { guard gap.range(of:#"^(?:,|,?\s*and)$"#,options:[.regularExpression,.caseInsensitive]) != nil else { return nil } }
            previous=range.upperBound
            anchors.append(String(body[range]))
        }
        guard String(body[previous...]).trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!"))).isEmpty else { return nil }
        return .init(anchors:anchors,actions:anchors.enumerated().map { $0.offset == 0 ? $0.element : "buy " + $0.element })
    }
    /// Reconcile ALL owners of a shared purchase unit together. Only the
    /// complete immediately following current exclusion may be shared. It
    /// cannot introduce a clock, condition, correction or another action.
    static func provedPurchaseRows(_ items:[IndexedItem],units:RuntimeIndexedSource)->[Int:String]? {
        func clean(_ text:String)->String { text.trimmingCharacters(in:.whitespacesAndNewlines.union(CharacterSet(charactersIn:".!"))) }
        var actions:[Int:String]=[:]
        for id in units.units.indices {
            let indices=items.indices.filter { items[$0].evidence.contains(id) }
            let body=RuntimeFoundationActionShape.body(units.units[id].text)
            guard body.range(of:#"(?i)^\s*(?:buy|purchase)\s+"#,options:.regularExpression) != nil else { continue }
            // A complete own-voice withdrawal cannot remain detached in a
            // review row beside an active purchase, including ordinary whole
            // groups and failed typed partitions. Hold the affected capture;
            // this does not choose a saved target or guess what "both" means.
            // Current Buy/Purchase owns effective purpose even when the model
            // supplies another tag, so a proposed tag cannot bypass the guard.
            if indices.contains(where:{ !items[$0].needsReview }) {
                let withdrawal = #"(?i)^\s*(?:(?:actually|correction|no\s+wait)[,:]?\s+)?(?:(?:cancel|withdraw|drop|remove|scratch|forget|skip)\s+(?:(?:those|these|the)\s+(?:purchases|shopping(?:\s+items)?|purchase\s+items)|(?:both|all)\s+(?:purchases|shopping\s+items))|leave\s+(?:both|all|them|those|these)\s+off)[.!]?\s*$"#
                for later in units.units.indices where later > id {
                    let own=QuotedSpeechScope.voiceProjection(in:units.units[later].text)?.ownVoiceText ?? units.units[later].text
                    guard own.range(of:withdrawal,options:.regularExpression) == nil else { return nil }
                }
            }
            // A single anchored row can still drop a member while claiming
            // the complete unit. Reconcile it too; ordinary unanchored whole
            // shopping groups retain their existing complete-source path.
            guard indices.contains(where:{ !items[$0].anchor.isEmpty }) else { continue }
            guard let partition=currentPurchasePartition(units.units[id].text) else {
                // A failed complete proof must not approve a partial member.
                // Preserve an ordinary exact WHOLE single action or the old
                // independently executable shared-action contract, which
                // still passes its original complete shared-unit guards.
                let whole=indices.count == 1 && items[indices[0]].evidence == [id]
                    && clean(items[indices[0]].anchor) == clean(body)
                let oldShared=indices.count > 1 && indices.allSatisfy {
                    RuntimeFoundationActionShape.executable(items[$0].anchor)
                }
                guard whole || oldShared else { return nil }
                continue
            }
            guard indices.count == partition.anchors.count,
                  Set(indices.map { items[$0].anchor }) == Set(partition.anchors) else { return nil }
            var exclusion:String?=nil
            if id+1 < units.units.count {
                let next=clean(units.units[id+1].text)
                if let marker=next.range(of:#"(?i)^do\s+not\s+buy\s+the\s+existing\s+"#,options:.regularExpression),
                   RuntimeCurrentNominalProof.read(String(next[marker.upperBound...])) { exclusion=next }
            }
            let evidence=exclusion == nil ? [id] : [id,id+1]
            for later in units.units.indices where later > id && !(exclusion != nil && later == id+1) {
                let own=QuotedSpeechScope.voiceProjection(in:units.units[later].text)?.ownVoiceText ?? units.units[later].text
                let changes = #"(?i)\b(?:actually|instead|correction|never\s+mind|cancel|withdraw|make\s+that|no\s+wait|leave\s+(?:that|both|them|those|these)|take\s+that\s+back|replace|switch|switched|change|changed|forget|scratch|remove|stop|skip|don['’]?t|do\s+not)\b"#
                guard own.range(of:changes,options:.regularExpression) == nil else { return nil }
            }
            for index in indices {
                let row=items[index]
                guard row.evidence == evidence,row.purpose == .shopping,!row.needsReview,row.directContact.isEmpty,
                      let member=partition.anchors.firstIndex(of:row.anchor) else { return nil }
                let action=partition.actions[member]
                let expected=action+(exclusion.map { ". " + $0 } ?? "")
                guard clean(row.currentMeaning).caseInsensitiveCompare(expected) == .orderedSame else { return nil }
                actions[index]=action
            }
            if exclusion != nil {
                guard Set(items.indices.filter { items[$0].evidence.contains(id+1) }) == Set(indices) else { return nil }
            }
        }
        return actions
    }
    /// Admission requires the complete independently derived current graph,
    /// not one plausible anchor. Generated rewrites and omitted siblings fail.
    static func provedDeniedRows(_ items:[IndexedItem],units:RuntimeIndexedSource,
                                 referenceDate:Date,calendar:Calendar)->[Int:RuntimeDeniedRequestPlan.Frame]? {
        guard let plan=RuntimeDeniedRequestPlan.read(units,referenceDate:referenceDate,calendar:calendar) else { return [:] }
        guard items.count == plan.count,Set(items.map(\.anchor)) == Set(plan.map(\.anchor)) else { return nil }
        var proved:[Int:RuntimeDeniedRequestPlan.Frame]=[:]
        for (index,row) in items.enumerated() {
            guard let frame=plan.first(where:{$0.anchor == row.anchor}),row.evidence == [0],
                  row.currentMeaning == frame.anchor,row.purpose == (frame.adopted ? .task : .note),
                  row.directContact.isEmpty,!row.needsReview else { return nil }
            proved[index]=frame
        }
        return proved
    }
    /// Exact original factual root of one Note. Complete-plan membership
    /// and source ownership are checked independently before final lowering.
    /// Broad provenance cannot change this row into an action or absorb an
    /// independently declared sibling root.
    static func provedRetainedMemoryRoot(_ row:IndexedItem,units:RuntimeIndexedSource)->Int? {
        guard row.purpose == .note,row.directContact.isEmpty,!row.needsReview,
              !row.anchor.isEmpty,row.currentMeaning.trimmingCharacters(in:.whitespacesAndNewlines) == row.anchor,
              row.evidence.allSatisfy({ id in
                  units.units.indices.contains(id)
                  && currentOwnedUnitSpan(units.units[id],source:units.source) != nil
                  && independentRetainedKnowledge(units.units[id].text)
              }) else { return nil }
        let matches=row.evidence.filter { units.units[$0].text == row.anchor }
        return matches.count == 1 ? matches[0] : nil
    }
    /// Shared Memory provenance supplies no shared clock. Every cited unit
    /// and distinct owner must be a complete original own retained root; a
    /// global membership Bool or one matching anchor is insufficient.
    static func provedSharedRetainedMemoryContextIDs(_ items:[IndexedItem],units:RuntimeIndexedSource)->Set<Int> {
        guard validOwnership(items,units:units),validDeclaredRetainedMemoryMembership(items,units:units) else { return [] }
        var proved=Set<Int>()
        for id in units.units.indices {
            let owners=items.filter { $0.evidence.contains(id) }
            guard owners.count > 1 else { continue }
            let roots=owners.compactMap { provedRetainedMemoryRoot($0,units:units) }
            guard roots.count == owners.count,Set(roots).count == owners.count,roots.contains(id) else { continue }
            proved.insert(id)
        }
        return proved
    }
    static func sharedUnitTiming(_ items: [IndexedItem],units: RuntimeIndexedSource,
                                 referenceDate: Date,calendar: Calendar,
                                 provedPackageContextIDs:Set<Int> = [],
                                 provedPurchases:[Int:String] = [:]) -> [Int:String]? {
        func exact(_ text: String,_ pattern: String) -> Bool {
            text.range(of:"^(?:" + pattern + ")$",options:[.regularExpression,.caseInsensitive]) != nil
        }
        func trim(_ text: Substring) -> String { String(text).trimmingCharacters(in:.whitespacesAndNewlines) }
        guard let deniedRows=provedDeniedRows(items,units:units,referenceDate:referenceDate,calendar:calendar) else { return nil }
        let retainedMemoryContextIDs=provedSharedRetainedMemoryContextIDs(items,units:units)
        var timings: [Int:String] = [:]
        for id in units.units.indices {
            let unit = units.units[id].text
            let ownerIndices = Set(items.indices.filter { items[$0].evidence.contains(id) })
            let owners = ownerIndices.sorted().map { items[$0] }
            let context = unit.trimmingCharacters(in:.whitespacesAndNewlines.union(.punctuationCharacters))
            if retainedMemoryContextIDs.contains(id) {
                // Exact distinct complete factual owners are already proved.
                // Continue all later meaning checks; donate no timing string.
                continue
            }
            if owners.count > 1,ownerIndices.allSatisfy({ deniedRows[$0] != nil }) {
                // Whole denial + explicit first-person adoption was reconciled
                // across every exact owner. It supplies no shared clock.
                continue
            }
            if owners.count > 1,ownerIndices.allSatisfy({ provedPurchases[$0] != nil }) {
                // The complete cross-row purchase proof already reconciled
                // this exact command and exclusion. It supplies no timing.
                continue
            }
            // Only a complete CURRENT quantity reconciliation can prove this
            // package predicate. It is not a detached clock, and cannot be
            // donated to multiple intentions by a model ownership claim.
            if provedPackageContextIDs.contains(id) {
                guard owners.count == 1 else { return nil };continue
            }
            if let marker = context.range(of:#"(?i)^(?:both|all|each|every)\s+"#,options:.regularExpression) {
                let clock = String(context[marker.upperBound...])
                guard RuntimeIndependentFramePlan.clock(clock,referenceDate:referenceDate,calendar:calendar,source:unit) != nil else { return nil }
                // A detached collective governs the independently current
                // earlier acts, not whichever subset a model happens to cite.
                let currentPriorIDs = Set((0..<id).filter { prior in
                    guard let voice = QuotedSpeechScope.voiceProjection(in:units.units[prior].text) else { return false }
                    return ActionabilityReader.read(voice.ownVoiceText).belongsOnToday
                })
                let expected = Set(items.indices.filter { !currentPriorIDs.isDisjoint(with:items[$0].evidence) })
                guard !expected.isEmpty,ownerIndices == expected,
                      !context.lowercased().hasPrefix("both ") || expected.count == 2 else { return nil }
                timings[id] = clock;continue
            }
            guard owners.count > 1 else { continue }
            let ranges = owners.compactMap { row -> Range<String.Index>? in
                guard !row.anchor.isEmpty else { return nil }; return unit.range(of:row.anchor)
            }.sorted { $0.lowerBound < $1.lowerBound }
            if ranges.isEmpty {
                if exact(context,#"(?:they|these|those)\s+are\s+(?:two\s+)?(?:different|distinct|separate)\s+people"#),owners.count == 2,
                   owners.allSatisfy({ anchoredCommunication(anchor:$0.anchor,evidence:$0.evidence.map { units.units[$0].text }.joined(separator:" ")) != nil }) {
                    continue
                }
                return nil
            }
            guard ranges.count == owners.count,let first = ranges.first,let last = ranges.last,
                  ranges.allSatisfy({ !QuotedSpeechScope.protects($0,in:unit) }),
                  owners.allSatisfy({ row in
                      guard let voice = QuotedSpeechScope.voiceProjection(in:row.anchor) else { return false }
                      let independentPredicate = #"(?i)(?:,\s*(?:and\s+)?|\s+and\s+)(?:(?:then|also|next)\s+)?(?:please\s+)?(?:"#
                          + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b"#
                      return voice.ownVoiceText.range(of:independentPredicate,options:.regularExpression) == nil
                  }) else { return nil }
            let prefix = trim(unit[..<first.lowerBound])
            let declaredTasks = RuntimeDeclaredTaskPartition.prefix(prefix,count:owners.count)
            if declaredTasks,!owners.allSatisfy({ RuntimeDeclaredTaskPartition.predicate($0.anchor) }) { return nil }
            guard prefix.isEmpty || declaredTasks || exact(prefix,#"(?:I|we)\s+(?:(?:need|have|want)\s+to|will|must|should)"#) else { return nil }
            for pair in zip(ranges,ranges.dropFirst()) {
                guard pair.0.upperBound <= pair.1.lowerBound,
                      exact(trim(unit[pair.0.upperBound..<pair.1.lowerBound]),declaredTasks ? #",|,?\s*and\s+to"# : #",|,?\s*and"#) else { return nil }
            }
            let suffix = trim(unit[last.upperBound...]).trimmingCharacters(in:.punctuationCharacters.union(.whitespacesAndNewlines))
            if suffix.isEmpty { continue }
            guard let marker = suffix.range(of:#"(?i)^(?:both|all|each|every)\s+"#,options:.regularExpression),
                  !suffix.lowercased().hasPrefix("both ") || owners.count == 2 else { return nil }
            let clock = String(suffix[marker.upperBound...])
            guard RuntimeIndependentFramePlan.clock(clock,referenceDate:referenceDate,calendar:calendar,source:unit) != nil else { return nil }
            timings[id] = clock
        }
        return timings
    }

    /// A later unresolved deictic change cannot authorize stale earlier acts.
    /// Hold the source-linked earlier proposals while independent later acts
    /// remain eligible. Bounded allocation/recipient/withdrawal proofs have
    /// their own exact graphs and do not pass through this unproved frame.
    static func unresolvedCurrentDependencyRows(_ items: [IndexedItem],units: RuntimeIndexedSource) -> Set<Int> {
        var held = Set<Int>()
        for id in units.units.indices {
            guard let voice = QuotedSpeechScope.voiceProjection(in:units.units[id].text),
                  voice.ownVoiceText.range(of:#"(?i)^\s*(?:actually|correction|no\s+wait)[,\s]+(?:move|reschedule|change|shift|make|cancel|withdraw|remove|drop|replace)\s+(?:them|both|all|these\s+(?:tasks|jobs|items)|those\s+(?:tasks|jobs|items)|that\s+(?:task|job|item))\b"#,options:.regularExpression) != nil else { continue }
            for index in items.indices where items[index].evidence.contains(where: { prior in
                guard prior < id,let own = QuotedSpeechScope.voiceProjection(in:units.units[prior].text) else { return false }
                return ActionabilityReader.read(own.ownVoiceText).belongsOnToday
            }) { held.insert(index) }
        }
        return held
    }

    /// Complete source text does not justify attaching the first clock to a
    /// merged row. Independently current command units must have compatible
    /// typed timing before a single actionable row can own them together.
    /// Reported/history/context units cannot contribute a current action clock.
    static func conflictingCurrentClockRows(_ items: [IndexedItem], units: RuntimeIndexedSource,
                                            referenceDate: Date, calendar: Calendar) -> Set<Int> {
        var held = Set<Int>()
        for (index, row) in items.enumerated() where row.anchor.isEmpty
            && [.task, .shopping, .packing].contains(row.purpose) {
            let whole = row.evidence.map { units.units[$0].text }.joined(separator:" ")
            // A complete unchanged current physical task owns its one event
            // deadline. Its modifier and same-object participle continuation
            // are not competing independently timed commands. The full proof
            // refuses extra acts, actual competing clocks and alert permission.
            if row.purpose == .task,row.currentMeaning.isEmpty,row.directContact.isEmpty,!row.needsReview,
               let first = row.evidence.first,let last = row.evidence.last,row.evidence == Array(first...last) {
                let span = String(units.source[units.units[first].range.lowerBound..<units.units[last].range.upperBound])
                if let proof = RuntimeDiscourseCertificate.interpretPhysicalTaskGroup(span,referenceDate:referenceDate,calendar:calendar),
                   proof.items.first?.organization.temporalIntent.kind == .dateOnly,
                   proof.items.first?.organization.temporalIntent.day != nil { continue }
            }
            // This complete source proof replaces a recipient and explicitly
            // inherits the same current object/clock. Its correction fragment
            // is not a second independently timed command.
            if RuntimeCommunicationReading.read(whole)?.inheritsCurrentClock == true || RuntimeWholePlanReplacement.read(whole) != nil { continue }
            let clocks = row.evidence.compactMap { id -> OrganizedThought? in
                guard let voice = QuotedSpeechScope.voiceProjection(in: units.units[id].text) else { return nil }
                let own = RuntimeFoundationActionShape.body(voice.ownVoiceText)
                guard RuntimeFoundationActionShape.executable(own) else { return nil }
                return ThoughtOrganizer.organize(own, referenceDate: referenceDate, calendar: calendar)
            }
            guard let first = clocks.first else { continue }
            let sameClock: (OrganizedThought) -> Bool = { other in
                var a = first.temporalIntent; var b = other.temporalIntent
                // Source strings are provenance, not a difference of clocks.
                a.sourceText = nil; b.sourceText = nil
                return first.dueDate == other.dueDate && first.reminderDate == other.reminderDate
                    && first.reminderDelivery == other.reminderDelivery && a == b
                    && first.recurrenceRule == other.recurrenceRule && first.locationIntent == other.locationIntent
            }
            if !clocks.allSatisfy(sameClock) { held.insert(index) }
        }
        return held
    }

    /// One independently owned current action can carry literal reported
    /// context. The report cannot supply its recipient, clock or permission.
    /// Every other unit must be an explicitly quoted report; a later own-voice
    /// refusal, adoption, correction or unknown clause cannot borrow this proof.
    static func currentActionWithQuotedContext(_ ids: [Int], units: RuntimeIndexedSource) -> String? {
        guard ids.count > 1 else { return nil }
        let current = ids.filter { id in
            let text = units.units[id].text
            return QuotedSpeechScope.ranges(in: text).isEmpty
                && RuntimeFoundationActionShape.executable(RuntimeFoundationActionShape.body(text))
        }
        guard current.count == 1, let action = current.first,
              ids.filter({ $0 != action }).allSatisfy({ id in
                  let text = units.units[id].text
                  let quotes = QuotedSpeechScope.ranges(in: text)
                  guard quotes.count == 1, let quote = quotes.first,
                        QuotedSpeechScope.matrixVoice(in: text) == .reported,
                        String(text[quote.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines.union(.punctuationCharacters)).isEmpty else { return false }
                  let prefix = String(text[..<quote.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines.union(.punctuationCharacters))
                  let pattern = #"^(.*?)\s+(?:"# + ClauseScope.reportingVerb + #")\s*[:,]?\s*$"#
                  guard let regex = NSRegularExpression.speakItCached(pattern, options: .caseInsensitive),
                        let match = regex.firstMatch(in: prefix, range: NSRange(prefix.startIndex..., in: prefix)),
                        let range = Range(match.range(at: 1), in: prefix) else { return false }
                  let speaker = String(prefix[range]).trimmingCharacters(in: .whitespacesAndNewlines)
                  return speaker.range(of: #"^(?:I|we|you|he|she|they)$"#, options: [.regularExpression, .caseInsensitive]) != nil
                      || RuntimeCommunicationReading.read("Ask " + speaker + " about the quotation")?.recipient == speaker
              }) else { return nil }
        return RuntimeFoundationActionShape.body(units.units[action].text)
    }

    /// A modeled note still needs a positive CURRENT knowledge scope. A
    /// recording instruction is distinct from its descriptive object; a
    /// cognitive topic question owns no contact request by itself.
    /// Positive whole CURRENT knowledge framing. The source graph owns
    /// corrections/roles; an old generic action heuristic cannot undo it.
    /// Existing custody and exclusion describe a different retained object,
    /// not another purchase. Prove the whole current finite statement, every
    /// physical nominal word and literal custodian before assigning Memory.
    /// Quotes, conditions, clocks, new commands and unknown tails decline.
    static func currentExcludedOwnershipFact(_ text:String) -> Bool {
        guard QuotedSpeechScope.ranges(in:text).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(text),
              let regex=NSRegularExpression.speakItCached(#"(?is)^\s*the\s+existing\s+(.+?)\s+stays\s+with\s+(.+?)\s+and\s+is\s+not\s+on\s+that\s+list[.!]?\s*$"#),
              let match=regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)),
              let object=Range(match.range(at:1),in:text),let owner=Range(match.range(at:2),in:text),
              RuntimeCurrentNominalProof.read(String(text[object])),
              RuntimeRecipientReplacement.literalRecipient(String(text[owner])) else { return false }
        let custodian=String(text[owner])
        // The generic literal-recipient helper is not a full named-slot
        // grammar. Bound this local finite fact's ENTIRE current custodian.
        let named=custodian.range(of:#"^\p{Lu}[\p{L}\p{M}'’-]*(?:\s+\p{Lu}[\p{L}\p{M}'’-]*)?$"#,options:.regularExpression) != nil
        let related=custodian.range(of:"^(?:" + PersonMentionResolver.communicationRelationPhrasePattern + ")$",options:[.regularExpression,.caseInsensitive]) != nil
        guard named || related,
              custodian.range(of:#"(?i)\b(?:today|tomorrow|tonight|monday|tuesday|wednesday|thursday|friday|saturday|sunday|january|february|march|april|may|june|july|august|september|october|november|december|and|or|but|then|also|if|unless|when|once|before|after|until|not|never|actually|instead|"# + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b"#,options:.regularExpression) == nil else { return false }
        return true
    }
    /// An explicitly retained location fact can explain why it must be
    /// findable later while declining a generated physical task. Prove every
    /// complete unit; that cognitive clause cannot hide another adopted act.
    static func currentRetainedReferenceGroup(_ text: String) -> Bool {
        let units = RuntimeIndexedSource(text).units.map(\.text)
        guard units.count >= 3, !QuotedSpeechScope.hasUnclosedQuote(text) else { return false }
        let locationFact = #"(?is)^\s*(?:the|my|our|this|that|these|those)\s+[^.!?;]+\s+(?:is|are)\s+(?:in|inside|on|under|at|with|beside|behind|near)\s+[^.!?;]+[.!?]*\s*$"#
        let finiteFact = #"(?is)^\s*(?:the|my|our|his|her|their|this|that|these|those)\s+[^.!?;]+\s+(?:is|are|was|were|has|have|had|belongs|belong|stays|stay|contains|contain)\b[^.!?;]*[.!?]*\s*$"#
        let pointer = #"(?i)^\s*(?:remember\s+(?:that|this)|(?:keep|save|retain)\s+(?:that|this|it)\s+as\s+(?:a\s+)?(?:note|memory|reference))[.!?]*\s*$"#
        func ownsCurrentAct(_ unit: String) -> Bool {
            RuntimeAccountOwnership.hasCurrentActForReference(unit)
                || RuleBasedThoughtExtractor.splitIndependentConjuncts(unit).contains { child in
                    RuntimeAccountOwnership.hasCurrentActForReference(child)
                        || ActionabilityReader.read(child).belongsOnToday
                }
        }
        guard units[0].range(of:locationFact,options:.regularExpression) != nil,
              !ActionabilityReader.read(units[0]).belongsOnToday,
              !ownsCurrentAct(units[0]),
              units[1].range(of:pointer,options:.regularExpression) != nil else { return false }
        let lookup = #"(?i)^\s*(?:I|we)\s+(?:do\s+not|don't)\s+(?:want|need)\s+(?:a|an|another|any)\s+(?:task|reminder|job|alarm|to-?do)\s+to\s+\p{L}+\s+(it|them|this|that)\s*,\s*(?:I|we)\s+(?:just|only)\s+need\s+to\s+(?:find|locate)\s+\1\s+when\s+(?:I|we)\s+(?:"#
            + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")[.!?]*\s*$"#
        // A complete past search/expenditure frame is history even when
        // lexical assets cannot classify its past verb. Bound every residual
        // word; new finite clauses, conditions and commands cannot enter it.
        let historyWord = #"(?!(?:I|we|you|he|she|they|is|are|was|were|has|have|had|will|shall|must|should|need|needs|want|wants|and|but|or|then|also|so|because|if|unless|when|once|before|after|until|"#
            + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b)[\p{L}\p{M}'’-]+"#
        let pastSearch = #"(?i)^\s*(?:I|we)\s+(?:wasted|spent|lost)\s+(?:"# + historyWord
            + #"\s+){0,8}(?:time|hours|minutes)\s+(?:looking|searching)\s+(?:in|inside|through|around|under|behind|for)\s+(?:"#
            + historyWord + #"\s+){1,12}(?:last\s+(?:time|week|month|year)|previously)[.!?]*\s*$"#
        var hasBoundLookup = false
        for unit in units.dropFirst(2) {
            if unit.range(of:lookup,options:.regularExpression) != nil,
               QuotedSpeechScope.ranges(in:unit).isEmpty {
                hasBoundLookup = true
                continue
            }
            guard !ownsCurrentAct(unit),
                  !ActionabilityReader.read(unit).belongsOnToday,
                  ThoughtOrganizer.organize(unit).itemType != .idea else { return false }
            // Positive complete finite reference facts may be ambiguous to
            // the legacy taxonomy. Whole-unit and independent-current-act
            // vetoes run first; that old confidence cannot erase the fact.
            if unit.range(of:finiteFact,options:.regularExpression) != nil { continue }
            // The existing reader must agree this is history. A past cue
            // cannot override a present command, promise or adoption.
            let history = unit.range(of:#"(?i)^\s*(?:I|we)\s+"#,options:.regularExpression) != nil
                && unit.range(of:#"(?i)\b(?:last\s+(?:time|week|month|year)|previously|in\s+the\s+past|the\s+other\s+day)\b"#,options:.regularExpression) != nil
                && ActionabilityReader.read(unit) == .knowledge
            guard history || unit.range(of:pastSearch,options:.regularExpression) != nil
                || unit.range(of:pointer,options:.regularExpression) != nil else { return false }
        }
        return hasBoundLookup
    }

    private static func currentKnowledgeScope(_ text: String) -> Bool {
        if currentExcludedOwnershipFact(text) || currentRetainedReferenceGroup(text) { return true }
        if let frames = RuntimeRecipientReplacement.currentFrames(text),!frames.isEmpty,
           frames.allSatisfy({ $0.kind == .note }) { return true }
        let units = RuntimeIndexedSource(text)
        guard !units.units.isEmpty,RuntimeAccountOwnership.scoped(text),
              !QuotedSpeechScope.hasUnclosedQuote(text) else { return false }
        return units.units.allSatisfy { !RuntimeAccountOwnership.hasCurrentIntent($0.text) }
    }

    /// An explicit possible project may deny adoption in a relative clause.
    /// Prove its complete descriptive nominal before scoping that denial; an
    /// idea label alone cannot hide an independent act or an unknown tail.
    private static func currentUnadoptedIdeaStatus(_ text: String) -> Bool {
        guard QuotedSpeechScope.ranges(in: text).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(text),
              let fields = currentContextExact(text,
                #"(?:an?\s+)?idea\s+for\s+later\s+is\s+([^,;.!?\n\r]{1,256}),\s*not\s+something\s+(?:I|we)\s+have\s+agreed\s+to\s+(?:build|make|do|create|start|buy)"#),
              fields.count == 1 else { return false }
        let description = fields[0]
        func nominal(_ value: String, requiresDeterminer: Bool) -> Bool {
            guard value.count <= 120,
                  value.range(of: #"^[\p{L}\p{M} -]+$"#, options: .regularExpression) != nil,
                  !value.contains("--") else { return false }
            var words = value.lowercased().split(whereSeparator: \.isWhitespace).map(String.init)
            let determined = ["a", "an", "the"].contains(words.first ?? "")
            if determined { words.removeFirst() }
            guard !requiresDeterminer || determined,
                  (1...5).contains(words.count) else { return false }
            let finiteOrContinuation: Set<String> = ["i", "we", "you", "he", "she", "they", "it",
                "me", "us", "them", "him", "her", "is", "are", "was", "were", "am", "has",
                "have", "had", "will", "shall", "must", "should", "can", "could", "may", "might",
                "would", "need", "needs", "want", "wants", "and", "or", "but", "then", "also",
                "plus", "so", "if", "unless", "when", "once", "because", "before", "after", "until",
                "while", "who", "whom", "whose", "that", "which", "not", "never", "no", "actually",
                "instead", "correction", "saved", "said", "wrote", "agreed", "decided", "committed"]
            guard words.allSatisfy({ !finiteOrContinuation.contains($0) }) else { return false }
            if RuntimeCurrentNominalProof.read(value) { return true }
            // Local portable noun evidence keeps this nonexecuting status
            // usable without lexical assets. It does not broaden object proof
            // for actions, contacts, purchases or saved-item matching.
            let heads: Set<String> = ["mural", "murals", "painting", "paintings", "drawing", "drawings",
                "sketch", "sketches", "design", "designs", "collage", "collages", "sculpture", "sculptures",
                "model", "models", "garden", "gardens", "pattern", "patterns", "picture", "pictures", "image", "images",
                "silhouette", "silhouettes", "star", "stars", "leaf", "leaves", "flower", "flowers",
                "tree", "trees", "branch", "branches", "shell", "shells", "stone", "stones", "tile", "tiles",
                "paper", "cloth", "wood", "metal", "glass", "bookstand", "bookstands", "stand", "stands"]
            let modifiers: Set<String> = ["small", "large", "new", "old", "portable", "red", "blue", "green",
                "white", "black", "simple", "abstract", "geometric", "colored", "colourful", "colorful",
                "wooden", "floral", "winter", "summer"]
            guard let head = words.last, heads.contains(head) else { return false }
            return words.dropLast().allSatisfy { heads.contains($0) || modifiers.contains($0) }
        }
        if let composition = currentContextExact(description,
            #"(.+?)\s+(?:made\s+(?:entirely\s+)?)?(?:of|from)\s+(.+)"#) {
            guard composition.count == 2,
                  nominal(composition[0], requiresDeterminer: true),
                  nominal(composition[1], requiresDeterminer: false) else { return false }
        } else if !nominal(description, requiresDeterminer: true) { return false }
        // Inspect all descriptive source words. Only the positively proved
        // terminal nonadoption is scoped out of this veto projection.
        return !RuntimeAccountOwnership.hasCurrentActForReference(description)
    }

    /// These complete current clauses describe retention, nonadoption or an
    /// unanswered reference slot. None can absorb a later finite continuation.
    /// They supply no purpose, target, date or saved-operation authority.
    private static func currentReferenceOnlyStatus(_ text: String) -> Bool {
        if ActionabilityReader.explicitCaptureRetentionKind(text) != nil { return true }
        guard QuotedSpeechScope.ranges(in: text).isEmpty,
              !QuotedSpeechScope.hasUnclosedQuote(text) else { return false }
        if currentUnadoptedIdeaStatus(text) { return true }
        if ActionabilityReader.retainedReportSpeaker(text) != nil {
            // The report's broad optional reason is not a complete no-action
            // proof. Peel only its exact cognitive retention wrapper, then
            // inspect the entire remaining matrix/reason/continuations.
            var retained = text.replacingOccurrences(of:
                #"(?i)^\s*(?:I|we)\s+(?:(?:want|need)\s+to|would\s+like\s+to)\s+(?=(?:keep|save|retain|record|store)\s+what\b)"#,
                with: "", options: .regularExpression)
            if let reason = retained.range(of: #"(?i)\s+because\s+"#, options: .regularExpression) {
                let explanation = String(retained[reason.upperBound...])
                if let cognitive = explanation.range(of:
                    #"(?i)^\s*(?:I|we)\s+(?:still\s+)?need\s+to\s+decide\s+whether\s+"#,
                    options: .regularExpression) {
                    let proposition = String(explanation[cognitive.upperBound...])
                    // A complete descriptive uncertainty may explain retained
                    // speech. An extra command or unknown continuation cannot
                    // pass this existing positive finite-source proof.
                    if let fact = currentContextExact(proposition,
                        #"((?:the|a|an|my|our|this|that)\s+[^,;.!?]+?)\s+(?:has|have)\s+(?:(?:enough|any|no|some)\s+)?([^,;.!?]+)"#),
                       fact.count == 2, currentFactualContextNominal(fact[0]),
                       currentFactualContextNominal(fact[1]),
                       RuntimeIndependentFramePlan.coherentNarrative("Keep one memory. " + proposition) != nil {
                        retained = String(retained[..<reason.upperBound]) + proposition
                    }
                }
            }
            return !RuntimeAccountOwnership.hasCurrentActForReference(retained)
        }
        if ActionabilityReader.isUnadoptedAction(text),
           !RuntimeAccountOwnership.hasCurrentActForReference(text) { return true }
        if currentDeniedCommitment(text) != nil
            || currentDeniedAgreementStatus(text) { return true }
        let pointer = #"(?:remember\s+(?:that|this)|(?:keep|save|retain|preserve)\s+(?:that|this|it)\s+as\s+(?:(?:a|an)\s+)?(?:(?:separate|useful|reference|connected|coherent)\s+){0,3}(?:note|memory|fact|idea|reference|account))"#
        let noExtraJob = #"(?:\s+rather\s+than\s+(?:adding|creating|making)\s+(?:another|a|any)\s+(?:job|task|reminder)(?:\s+for\s+(?:today|tomorrow|tonight|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday))?)?"#
        if currentContextExact(text, pointer + noExtraJob) != nil { return true }
        let action = "(?:" + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + ")"
        if let fields = currentContextExact(text,
            #"(?:also[,]?\s+)?(?:I|we)\s+(?:have\s+)?(?:decided|chosen|agreed|committed)\s+(?:not|never)\s+to\s+"#
                + action + #"\s+(?:(?:any\s+more|any|more)\s+)?(.+)"#),
           fields.count == 1, currentFactualContextNominal(fields[0]) { return true }
        // A cognitive matrix owns the missing interlocutor. A named recipient,
        // action object, clock, condition or another clause cannot fit this
        // complete question, and therefore cannot inherit this exemption.
        var question = text
        if let fields = currentContextExact(text, #"about\s+([^,;.!?]+),\s*(.+)"#), fields.count == 2 {
            // A topical nominal is opaque reference text, never an executable
            // object. This complete bounded slot remains usable without lexical
            // assets; a new actor, finite predicate or action cannot enter it.
            let excluded = #"(?:I|we|you|he|she|they|it|me|us|them|him|her|is|are|was|were|am|has|have|had|will|shall|must|should|need|want|and|or|but|then|also|plus|if|unless|when|once|because|before|after|until|not|never|no|actually|instead|correction|saved|withdraw|"#
                + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + ")"
            let word = "(?!(?:" + excluded + #")\b)[\p{L}\p{M}][\p{L}\p{M}'’-]*"#
            let opaqueTopic = fields[0].count <= 120 && fields[0].range(of:
                #"(?i)^(?:the|a|an|my|our|this|that)\s+"# + word + "(?:\\s+" + word + "){0,4}$",
                options: .regularExpression) != nil
            if RuntimeCurrentNominalProof.read(fields[0]) || opaqueTopic { question = fields[1] }
        }
        let cognition = #"(?:I\s+(?:keep\s+(?:mixing\s+up|confusing|forgetting)|am\s+(?:unsure|uncertain))|we\s+(?:keep\s+(?:mixing\s+up|confusing|forgetting)|are\s+(?:unsure|uncertain)))"#
        return currentContextExact(question, cognition
            + #"\s+(?:about\s+)?who\s+(?:I|we)\s+(?:need|have|want)\s+to\s+(?:(?:speak|talk)\s+(?:to|with)|contact)"#) != nil
    }

    /// Inspect independent acts without destroying the source grammar which
    /// establishes a quoted report, a retained account or a negative decision.
    /// Existing positive proofs cover only their exact units. Every remaining
    /// owned unit still faces the current-action veto, in either source order.
    private static func hasIndependentCurrentActionCoverage(_ evidence: [Int],
        units: RuntimeIndexedSource, literalBody: String) -> Bool {
        guard evidence.allSatisfy({ units.units.indices.contains($0) }),
              let voice = QuotedSpeechScope.voiceProjection(in: units.source) else { return true }
        if currentRetainedReferenceGroup(literalBody)
            || RuntimeRetainedUncommittedIdea.read(literalBody) { return false }
        let selected = Set(evidence)
        var covered = Set<Int>()
        for id in evidence where currentLoanRetentionDeclaration(units.units[id].text) {
            if let proof = currentLoanUncertaintyAccount(units, retentionUnit: id) {
                let account = Set([proof.root] + proof.contexts)
                if account.isSubset(of: selected) { covered.formUnion(account) }
            }
        }
        for id in evidence where !covered.contains(id) {
            let unit = units.units[id]
            if currentExcludedOwnershipFact(unit.text) || currentReferenceOnlyStatus(unit.text) { continue }
            // Project through the ORIGINAL whole-capture quote spans. A unit
            // boundary inside a balanced single-quoted report cannot turn its
            // fragment into unclosed own speech or a newly adopted command.
            let own = voice.ownVoiceRanges.compactMap { range -> String? in
                let lower = max(range.lowerBound, unit.range.lowerBound)
                let upper = min(range.upperBound, unit.range.upperBound)
                return lower < upper ? String(units.source[lower..<upper]) : nil
            }.joined(separator: " ")
            if RuntimeAccountOwnership.hasCurrentActForReference(own) { return true }
        }
        return false
    }

    /// A declared request to retain an independently factual unit owns
    /// Memory. It cannot disappear inside an adjacent current task merely
    /// because all literal words remain in that task's source quote.
    static func independentRetainedKnowledge(_ text:String) -> Bool {
        guard QuotedSpeechScope.ranges(in:text).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(text) else { return false }
        if currentExcludedOwnershipFact(text) { return true }
        if let frame=text.range(of:#"(?i)^\s*(?:keep|save|retain|record)\s+the\s+fact\s+that\s+"#,options:.regularExpression) {
            let fact=String(text[frame.upperBound...])
            return RuntimeIndependentFramePlan.coherentNarrative("Keep one memory. " + fact) != nil
        }
        guard let label=RuntimeSpokenIntentionLabels.reading(text),["note","memory"].contains(label.kind),
              !RuntimeAccountOwnership.hasCurrentIntent(label.body),
              label.body.range(of:#"(?i)\b(?:actually|instead|correction|never\s+mind|cancel|withdraw|make\s+that|no\s+(?:wait|make)|leave\s+that\s+off|take\s+that\s+back|replace\s+that\s+whole\s+plan|if|unless|until|when|after|before|once|since|by|via)\b"#,options:.regularExpression) == nil else { return false }
        // This exact terminal instruction describes how to interpret a
        // literal identifier, not a second task. Prove the complete preceding
        // finite fact independently; retain the entire annotation as source.
        // Other directives, corrections and continuations have no exception.
        let subject = #"(?:the|a|an|my|our|their|his|her|its)\s+[\p{L}\p{M}'’-]+(?:\s+(?!(?:I|we|you|am|are|is|was|were|will|shall|must|should|to|and|or|but|then|also|because|if|unless)\b)[\p{L}\p{M}'’-]+){0,6}"#
        let identifierFact = #"(?is)^\s*((?:"# + subject + #")\s+(?:is|was)\s+(?:coded|marked|labelled|labeled|identified)(?:\s+as)?\s+[A-Za-z]{1,32}-[0-9]{1,12})\s+do\s+not\s+turn\s+it\s+into\s+a\s+date[.!]?\s*$"#
        guard let regex=NSRegularExpression.speakItCached(identifierFact),
              let match=regex.firstMatch(in:label.body,range:NSRange(label.body.startIndex...,in:label.body)),
              let range=Range(match.range(at:1),in:label.body) else { return false }
        let fact=String(label.body[range])
        return RuntimeIndependentFramePlan.coherentNarrative("Keep one memory. " + fact) != nil
    }
    /// Original complete owned retained facts may share one coherent Memory,
    /// but a later ordinal note/memory declaration starts another intention.
    /// Literal retention alone cannot make those roots independently accessible
    /// inside one saved row. This grants no grouping or correction authority.
    static func crossesDeclaredRetainedMemoryBoundary(_ evidence:[Int],units:RuntimeIndexedSource,anchor:String = "")->Bool {
        guard evidence.allSatisfy({ units.units.indices.contains($0) }) else { return true }
        let roots=evidence.sorted().filter { id in
            currentOwnedUnitSpan(units.units[id],source:units.source) != nil
                && independentRetainedKnowledge(units.units[id].text)
        }
        guard roots.count > 1 else { return false }
        // Broad shared provenance can still own one exact complete factual
        // root. Existing ownership/meaning validation checks disjoint rows;
        // a partial anchor cannot waive independent membership.
        if !anchor.isEmpty,roots.contains(where:{ units.units[$0].text == anchor }) { return false }
        return roots.dropFirst().contains { id in
            guard let declaration=RuntimeSpokenIntentionLabels.reading(units.units[id].text) else { return false }
            return ["note","memory"].contains(declaration.kind)
        }
    }
    /// A complete anchor is only a candidate owner. At the complete-plan
    /// boundary, every retained root crossing a declared Memory boundary must
    /// have exactly one distinct complete literal owner; no second root can be
    /// covered only as broad provenance. All existing meaning checks still run.
    static func validDeclaredRetainedMemoryMembership(_ items:[IndexedItem],units:RuntimeIndexedSource)->Bool {
        for (index,item) in items.enumerated() where crossesDeclaredRetainedMemoryBoundary(item.evidence,units:units) {
            let roots=item.evidence.filter { id in
                units.units.indices.contains(id)
                    && currentOwnedUnitSpan(units.units[id],source:units.source) != nil
                    && independentRetainedKnowledge(units.units[id].text)
            }
            var ownerIDs=Set<Int>()
            for root in roots {
                let literal=units.units[root].text
                let owners=items.indices.filter { position in
                    let candidate=items[position]
                    return candidate.evidence.contains(root) && candidate.purpose == .note
                        && candidate.directContact.isEmpty && candidate.anchor == literal
                        && candidate.currentMeaning.trimmingCharacters(in:.whitespacesAndNewlines) == literal
                }
                guard owners.count == 1,ownerIDs.insert(owners[0]).inserted else { return false }
            }
            guard ownerIDs.contains(index) else { return false }
        }
        return true
    }
    static func independentAllocationPurchase(_ text:String) -> Bool {
        guard QuotedSpeechScope.ranges(in:text).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(text),
              let entries=RuntimeAllocationReading.expected(RuntimeFoundationActionShape.body(text)),
              entries.allSatisfy({ RuntimeCurrentNominalProof.read($0.object) }) else { return false }
        return true
    }
    /// This is a complete CURRENT graph comparison, not reference approval.
    /// Every allocation, owner, product, package amount and content predicate
    /// must match. Unsupported clocks, conditions, new acts or missing members
    /// decline in the existing bounded graph readers before any lowering.
    static func currentQuantityReconciliation(_ source:String,meaning:String) -> RuntimeQuantityAnalogy.Graph? {
        guard let current=RuntimeQuantityAnalogy.graph(source),!current.corrections.isEmpty,
              let proposed=RuntimeQuantityAnalogy.graph(meaning),proposed.corrections.isEmpty,
              current.entries.count == proposed.entries.count else { return nil }
        let same=zip(current.entries,proposed.entries).allSatisfy { a,b in
            a.quantity == b.quantity && RuntimeAllocationReading.normalized(a.unit) == RuntimeAllocationReading.normalized(b.unit)
                && RuntimeQuantityAnalogy.identity(a.object) == RuntimeQuantityAnalogy.identity(b.object)
                && RuntimeQuantityAnalogy.identity(a.recipient) == RuntimeQuantityAnalogy.identity(b.recipient)
                && a.contents.map(RuntimeAllocationReading.normalized) == b.contents.map(RuntimeAllocationReading.normalized)
        }
        return same ? current : nil
    }

    private static func currentPersonalFactSubject(_ item:IndexedItem,literalBody:String,sourceReading:OrganizedThought) -> String? {
        guard item.purpose == .note,item.evidence.count == 1,item.anchor.isEmpty,item.currentMeaning.isEmpty,
              QuotedSpeechScope.ranges(in:literalBody).isEmpty,!QuotedSpeechScope.hasUnclosedQuote(literalBody),
              !ActionabilityReader.read(literalBody).belongsOnToday else { return nil }
        let subjects=PersonMentionResolver.mentions(in:literalBody).filter { $0.role == .subject }
        guard subjects.count == 1,let subject=subjects.first,sourceReading.personName == subject.label else { return nil }
        return subject.label
    }
    /// A complete retained project stays visible to validation even when a
    /// proposed row has absorbed unrelated surrounding actions. These are
    /// original source spans, not approved purposes or a forced partition:
    /// a later adoption still needs complete current reconciliation.
    static func retainedUncommittedIdeaComponents(_ units:RuntimeIndexedSource)->[[Int]] {
        guard !Task.isCancelled,!QuotedSpeechScope.hasUnclosedQuote(units.source) else { return [] }
        return units.units.indices.compactMap { start in
            guard start+3 <= units.units.count,
                  units.units[start].text.range(of:#"(?i)^\s*(?:I\s+was\s+thinking\s+of|There\s+is\s+an\s+idea)\b"#,options:.regularExpression) != nil else { return nil }
            let ids=Array(start..<(start+3))
            guard ids.allSatisfy({ currentOwnedUnitSpan(units.units[$0],source:units.source) != nil }),
                  RuntimeRetainedUncommittedIdea.read(ids.map { units.units[$0].text }.joined(separator:" ")) else { return nil }
            return ids
        }
    }
    /// Packing requires its own affirmative packing matrix. Event membership
    /// in Today and an arbitrary actionable head do not prove packing. Shared
    /// rows use their already validated complete literal anchor.
    static func hasCurrentPackingMatrix(_ text:String)->Bool {
        guard !QuotedSpeechScope.hasUnclosedQuote(text),
              QuotedSpeechScope.ranges(in:text).isEmpty
                || QuotedSpeechScope.matrixVoice(in:text) == .direct else { return false }
        let own=QuotedSpeechScope.voiceProjection(in:text)?.ownVoiceText ?? text
        let routed=RuntimeFoundationActionShape.body(own)
            .replacingOccurrences(of:#"(?i)^\s*(?:and|also|then|plus)\s+"#,with:"",options:.regularExpression)
        let body=ActionabilityReader.actionBody(routed).trimmingCharacters(in:.whitespacesAndNewlines)
        return body.range(of:#"(?i)^pack\b\s+\S"#,options:.regularExpression) != nil
            && RuntimeFoundationActionShape.executable(routed)
    }
    private static func indexedRejection(_ stage: String) -> ThoughtExtractionResult? {
#if DEBUG
        developmentObserver?("validation rejected phase=indexed stage=\(stage)")
#endif
        return nil
    }

    static func validateIndexed(_ proposal: IndexedProposal, source: String, units: RuntimeIndexedSource,
                                referenceDate: Date, calendar: Calendar, rules: ThoughtExtractionResult,
                                context: RuntimeCaptureContext) -> ThoughtExtractionResult? {
        guard !proposal.items.isEmpty, rules.operations.isEmpty else { return indexedRejection("indexed-guard-1") }
        let allocations = RuntimeAllocationReading.expected(source)
        // Ignore a model's unowned reference artifact only when a typed graph
        // proves the entire current purchase and its correction. No artifact
        // acquires an item, alert or source ownership.
        let substantiveItems = proposal.items.filter { !($0.evidence.isEmpty
            && $0.currentMeaning.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && $0.directContact.isEmpty && !$0.needsReview) }
        let plannedItems = allocations == nil ? substantiveItems : substantiveItems.filter { !$0.evidence.isEmpty }
        if RuntimeCurrentPurchaseStatus.read(units) {
            guard plannedItems.count == 1,plannedItems[0].evidence == Array(units.units.indices),
                  plannedItems[0].anchor.isEmpty,plannedItems[0].purpose == .shopping,
                  plannedItems[0].currentMeaning.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty,
                  plannedItems[0].directContact.isEmpty else { return indexedRejection("current-purchase-status-ownership") }
        }
        guard let deniedRows=provedDeniedRows(plannedItems,units:units,referenceDate:referenceDate,calendar:calendar) else { return indexedRejection("current-denied-whole-ownership") }
        let quantityReconciliation = plannedItems.count == 1 && plannedItems[0].purpose == .shopping
            && plannedItems[0].anchor.isEmpty && !plannedItems[0].needsReview
            && Set(plannedItems[0].evidence) == Set(units.units.indices)
            ? currentQuantityReconciliation(source,meaning:plannedItems[0].currentMeaning) : nil
        let packageStatements=Set(quantityReconciliation?.entries.flatMap(\.contents).map(RuntimeAllocationReading.normalized) ?? [])
        let packageIDs=Set(units.units.indices.filter { packageStatements.contains(RuntimeAllocationReading.normalized(units.units[$0].text)) })
        guard let purchaseRows=provedPurchaseRows(plannedItems,units:units) else { return indexedRejection("current-purchase-partition") }
        guard validOwnership(plannedItems, units: units),
              let sharedTiming = sharedUnitTiming(plannedItems,units:units,referenceDate:referenceDate,calendar:calendar,provedPackageContextIDs:packageIDs,provedPurchases:purchaseRows) else { return indexedRejection("indexed-guard-2") }
        guard validDeclaredRetainedMemoryMembership(plannedItems,units:units) else {
            return indexedRejection("independent-current-memory-membership")
        }
        let dependencyHeldRows = unresolvedCurrentDependencyRows(plannedItems,units:units)
        let clockHeldRows = conflictingCurrentClockRows(plannedItems, units: units,
            referenceDate: referenceDate, calendar: calendar)
        let recordedPlan = RuntimeRecordedCommitmentCertificate.read(source,referenceDate:referenceDate,calendar:calendar)
        let retainedIdeaComponents = retainedUncommittedIdeaComponents(units)
        var output: [ExtractedThought] = []
        let ledger = SourceUnitLedger(source)
        let withdrawalDependencies = RuntimeCurrentWithdrawal.dependencies(units)
        let cancelledUnits = Set(withdrawalDependencies.map(\.creation))
        let cancelledContextUnits = cancelledUnits.union(withdrawalDependencies.map(\.withdrawal))
        let referencePairs = RuntimeExplicitReferenceScope.pairs(units)
        let referenceOnlyUnits = Set(referencePairs.flatMap { [$0.fact, $0.directive] })
        let nonCreationUnits = Set(units.units.indices.filter {
            RuntimeCurrentWithdrawal.hasNonCreationDirective(units.units[$0].text)
                && !QuotedSpeechScope.protects(units.units[$0].range, in: source)
        })
        for (itemIndex,item) in plannedItems.enumerated() {
            guard let first = item.evidence.first, let last = item.evidence.last else { return indexedRejection("indexed-guard-3") }
            let range = units.units[first].range.lowerBound..<units.units[last].range.upperBound
            let quote = String(source[range]).trimmingCharacters(in: .whitespacesAndNewlines)
            let evidence = item.evidence.map { units.units[$0].text }.joined(separator: " ")
            // The enclosing span is audit provenance, not this row's body.
            // Nonadjacent ownership must not persist another intention's
            // action, person, date or list members inside the current item.
            let ownedQuote = item.evidence == Array(first...last) ? quote : evidence
            let literalBody = RuntimeFoundationActionShape.body(evidence)
            let explicitRetentionKind = ActionabilityReader.explicitCaptureRetentionKind(literalBody)
            if let explicitRetentionKind, item.purpose != .review,
               (explicitRetentionKind == .idea ? item.purpose != .idea : item.purpose != .note) {
                return indexedRejection("current-capture-retention-purpose")
            }
            // The complete CURRENT speech act owns purpose independently of
            // a model tag. An explicitly uncommitted retained idea cannot
            // acquire a task, purchase, packing or factual-note destination.
            // An exact sub-unit anchor cannot adopt a merely possible
            // project when its complete owned CURRENT evidence explicitly
            // retains that project as an idea. Purpose is proved before
            // generated wording or an anchor narrows the speech act.
            if RuntimeRetainedUncommittedIdea.read(literalBody),
               item.purpose != .idea && item.purpose != .review {
                return indexedRejection("current-retained-idea-purpose")
            }
            if item.evidence.count == 1,
               let label = RuntimeSpokenIntentionLabels.reading(evidence), label.kind == "idea",
               !item.needsReview {
                // An idea heading owns the possibility, not an additional
                // independently commanded or adopted act in its continuation.
                let own = QuotedSpeechScope.voiceProjection(in:label.body)?.ownVoiceText ?? label.body
                let continuation = #"(?i)(?:[,;:]|\s+(?:and|but|then|also|plus)\s+)\s*(?:please\s+)?(?:"#
                    + ActionabilityReader.actionVerb + "|" + ActionabilityReader.headOnlyImperativeVerb + #")\b|\b(?:i|we)\s+(?:will|must|should|need\s+to|have\s+to|have\s+agreed|agree\s+to)\b"#
                guard own.range(of:continuation,options:.regularExpression) == nil else { return indexedRejection("indexed-guard-4") }
            }
            let proposedMeaning = item.currentMeaning.trimmingCharacters(in:.whitespacesAndNewlines)
            let correctionSource = QuotedSpeechScope.voiceProjection(in:literalBody)?.ownVoiceText ?? literalBody
            let denied=deniedRows[itemIndex]
            let correction = denied == nil && correctionSource.range(of:#"(?i)\b(?:actually|instead|correction|never\s+mind|cancel|withdraw|make\s+that|no\s+(?:wait|make)|leave\s+that\s+off|take\s+that\s+back|replace\s+that\s+whole\s+plan)\b"#,options:.regularExpression) != nil
            // A whole unchanged intention retains its exact owned source.
            // Optional generated wording cannot remove an action, swap its
            // object or drop a qualifier when there is no current correction.
            let normalized = item.anchor.isEmpty && !correction ? "" : proposedMeaning
            if normalized.isEmpty, item.purpose == .task || item.purpose == .shopping || item.purpose == .packing {
                // A held literal correction cannot execute, and need not hide
                // unrelated, independently proved intentions in the same plan.
                guard !correction || item.needsReview else { return indexedRejection("indexed-guard-5") }
            }
            // A shared/sub-unit anchor must be reconciled into complete
            // effective meaning; preserving its broad quote alone would merge
            // the separate intentions again.
            guard item.anchor.isEmpty || !normalized.isEmpty else { return indexedRejection("indexed-guard-6") }
            let meaning = normalized.isEmpty ? literalBody : normalized
            let recorded = item.anchor.isEmpty && normalized.isEmpty
                ? recordedPlan?.first(where: { $0.evidence == item.evidence }) : nil
            if let recorded,item.purpose != (recorded.adopted ? .task : .note) {
                return indexedRejection("current-recorded-commitment-purpose")
            }
            let quotedContextAction = item.anchor.isEmpty
                ? currentActionWithQuotedContext(item.evidence, units: units) : nil
            if !item.anchor.isEmpty {
                // Disjoint evidence anchors alone do not bind predicate and
                // object. An unchanged anchored action must survive as the
                // same complete phrase, rather than swapping objects between
                // two equally source-present actions.
                let canonical: (String) -> String = { text in
                    text.lowercased().replacingOccurrences(of: "’",with: "'")
                        .split(whereSeparator: { !$0.isLetter && !$0.isNumber && $0 != "'" })
                        .joined(separator: " ")
                }
                guard (" " + canonical(meaning) + " ").contains(" " + canonical(item.anchor) + " ") else { return indexedRejection("indexed-guard-7") }
                let own = RuntimeExampleLibrary.words(item.anchor)
                let foreign = plannedItems.filter { $0.anchor != item.anchor }.reduce(into: Set<String>()) {
                    $0.formUnion(RuntimeExampleLibrary.words($1.anchor).subtracting(own))
                }
