    static func recoverableReview(_ source: String) -> ThoughtExtractionResult {
        let organized = OrganizedThought(itemType: .unclear, category: .general, priority: .normal,
            personName: nil, dueDate: nil, reminderDate: nil, reminderDelivery: .none,
            recurrenceRule: nil, needsClarification: true,
            state: .contested(.uncertainClauseBoundary))
        let item = ExtractedThought(sourceQuote: source, rawQuote: source, wasRepaired: false,
            analysisText: source, suggestedTitle: nil, organization: organized,
            confidence: 0, needsReview: true)
        return ThoughtExtractionResult(items: [item], method: .appleIntelligence)
    }

    static func validate(_ proposal: Proposal, source: String, referenceDate: Date,
                         calendar: Calendar, rules: ThoughtExtractionResult,
                         context: RuntimeCaptureContext = .empty) -> ThoughtExtractionResult? {
        guard !proposal.items.isEmpty,
              RuntimeProposalGuard.covers(source, quotes: proposal.items.map(\.quote)),
              proposal.items.allSatisfy({ item in
                  item.sourceContext.allSatisfy { source.contains($0) }
                    && item.roles.allSatisfy { anchor in
                        !anchor.literal.isEmpty && (([.actor, .requester].contains(anchor.role) && anchor.literal == "user"
                            && ActionabilityReader.read(item.quote).belongsOnToday)
                        || ([item.quote] + item.sourceContext).contains { completeAnchor(anchor.literal, in: $0) })
                    }
              }) else { return nil }
        // The existing operation interpreter and repository own identity/version
        // validation and mutation. A model may not bypass or replace that boundary.
        guard rules.operations.isEmpty else { return nil }
        let items = proposal.items.map { item in
            let analysis = (Array(Set(item.sourceContext).subtracting([item.quote])).sorted() + [item.quote]).joined(separator: " ")
            let organized = ThoughtOrganizer.organize(analysis, referenceDate: referenceDate, calendar: calendar)
            let kind: ItemType
            switch item.purpose {
            case .task, .packing: kind = .task
            case .shopping: kind = .shopping
            case .idea: kind = .idea
            case .review: kind = .unclear
            case .inventory, .note, .question: kind = .note
            }
            let missingRequestedTrigger = ReminderPhrasing.requestsReminder(analysis)
                && organized.reminderDate == nil && organized.locationIntent == nil
                && organized.recurrenceRule == nil
            let missingPlace: Bool
            switch organized.locationIntent?.place {
            case .named: missingPlace = true
            case .home: missingPlace = !context.hasHome
            case .work: missingPlace = !context.hasWork
            case .currentLocation, nil: missingPlace = false // Repository resolves the actual snapshot/permission.
            }
            let held = item.needsReview || item.purpose == .review || organized.needsClarification
                || missingRequestedTrigger || missingPlace
                || (kind.isActionable && !ActionabilityReader.read(analysis).belongsOnToday)
            let recipients = item.roles.filter { $0.role == .recipient }.map(\.literal)
            let person = recipients.count == 1 ? recipients[0] : organized.personName
            let organization = OrganizedThought(itemType: kind, category: kind == .shopping ? .shopping : organized.category,
                priority: organized.priority, personName: person,
                dueDate: kind.isActionable ? organized.dueDate : nil,
                reminderDate: !held && kind.isActionable ? organized.reminderDate : nil,
                reminderDelivery: !held && kind.isActionable ? organized.reminderDelivery : .none,
                recurrenceRule: kind.isActionable ? organized.recurrenceRule : nil,
                needsClarification: held, temporalIntent: organized.temporalIntent,
                locationIntent: kind.isActionable ? organized.locationIntent : nil,
                state: held && organized.state == .resolved ? .underspecified(.uncertainClauseBoundary) : organized.state)
            return ExtractedThought(sourceQuote: item.quote, rawQuote: item.quote, wasRepaired: false,
                analysisText: analysis, suggestedTitle: nil, organization: organization,
                confidence: held ? 0 : 1, needsReview: held)
        }
        return ThoughtExtractionResult(items: items, method: .appleIntelligence)
    }
